#!/usr/bin/env ruby
# frozen_string_literal: false
#
# convert_mrbgem.rb [--name GEM] <cext_dir> <out_dir>
#
# Text-only converter: a CRuby C extension directory (ext/<name>/ with *.c, *.h)
# -> an mruby mrbgem directory (mrbgem.rake, src/*.c, src/gem_init.c, include/*.h).
#
# The input is only read as text. It is never compiled, loaded or executed.
# Mappings come from api_map.json next to this script. Any CRuby-looking API
# identifier without a map entry is REFUSED: a marker comment
# `/* BC2CPP-MRBGEM REFUSED: <api> */` is left in the output, the item is listed
# in REFUSALS.txt, and the output is marked not buildable (NOT_BUILDABLE file,
# #error in gem_init.c, raise in mrbgem.rake).
#
# Exit status: 0 converted with no refusals; 2 refusals present (output written,
# marked not buildable); 1 usage or input error.
#
# This is the Ruby port of the former Python converter. Python's Unicode \w, \s and
# str.isspace() are reproduced with explicit character classes (WC, WSP), and Python's
# `$` (which also matches before a final newline) is written as \z.

require 'json'
require 'fileutils'
require 'open3'
require 'set'
require_relative 'decl_scan'

NFCX_SYNC_THREAD_H = <<'EOS'
/* nfcx_uv_thread.h (--thread-sync): models CRuby's rb_thread_call_without_gvl by a direct call on the calling thread. mruby
 * has no GVL, so there is nothing to release; the call is synchronous, as CRuby's is for the caller. ubf is ignored. */
#ifndef NFCX_UV_THREAD_H
#define NFCX_UV_THREAD_H
#include <mruby.h>

static inline void *
nfcx_thread_call_without_gvl(mrb_state *mrb, void *(*fn)(void *), void *data, void *ubf, void *data2)
{
  (void)mrb;
  (void)ubf;
  (void)data2;
  return fn(data);
}
#endif
EOS

NFCX_UV_THREAD_H = <<'EOS'
/* nfcx_uv_thread.h: models CRuby's rb_thread_call_without_gvl on mruby-uv (generated by convert_mrbgem.rb).
 * func runs on libuv's thread pool; the calling Ruby-side C code runs the loop until the work is done, so
 * the call stays synchronous as in CRuby. func must not touch mrb_state (no GVL section rules apply here).
 * ubf (the unblock function) is ignored: a blocked worker cannot be interrupted. NOT COMPILED. */
#ifndef NFCX_UV_THREAD_H
#define NFCX_UV_THREAD_H
#include <uv.h>
#include <mruby.h>
#include "mrb_uv.h"   /* mruby-uv: mrb_uv_current_loop */

typedef struct {
  void *(*fn)(void *);
  void *data;
  void *result;
  int done;
} nfcx_uv_work_t;

static void nfcx_uv_work_cb(uv_work_t *w) {
  nfcx_uv_work_t *n = (nfcx_uv_work_t *)w->data;
  n->result = n->fn(n->data);
}

static void nfcx_uv_after_cb(uv_work_t *w, int status) {
  nfcx_uv_work_t *n = (nfcx_uv_work_t *)w->data;
  (void)status;
  n->done = 1;
}

static inline void *
nfcx_thread_call_without_gvl(mrb_state *mrb, void *(*fn)(void *), void *data, void *ubf, void *data2)
{
  uv_loop_t *loop = mrb_uv_current_loop(mrb);
  uv_work_t w;
  nfcx_uv_work_t n = { fn, data, NULL, 0 };
  (void)ubf;
  (void)data2;
  w.data = &n;
  if (uv_queue_work(loop, &w, nfcx_uv_work_cb, nfcx_uv_after_cb) != 0)
    return NULL;
  while (!n.done)
    uv_run(loop, UV_RUN_ONCE);
  return n.result;
}
#endif
EOS

# CRuby headers whose only use is a compatibility redefinition that the target libc does not need.
DROP_INCLUDES = {
  'ruby/util.h' => 'only redefines strdup as ruby_strdup for libcs without it; mruby targets provide strdup',
  'ruby/internal/has/builtin.h' => 'CRuby internal feature tests (__has_builtin); the code that uses them is in branches the build undefines (corpus flags: RBIMPL_STATIC_ASSERT, RUBY_ATOMIC_PTR_CAS)',
  'ruby/internal/static_assert.h' => 'CRuby internal static assertions (RBIMPL_STATIC_ASSERT); the build undefines it (corpus flags), so its uses are not compiled',
  'ruby/atomic.h' => 'CRuby internal atomics (RUBY_ATOMIC_PTR_CAS); the build undefines it (corpus flags), so its uses are not compiled',
  'ruby/version.h' => 'the CRuby version the gem emulates is a build define (RUBY_API_VERSION_CODE, set by --define in the corpus flags); the header only declares it',
}

HERE = File.dirname(File.absolute_path(__FILE__))
MAP_PATH = File.join(HERE, 'api_map.json')

# Python's \w (str patterns: Unicode letters, numbers and underscore), for use inside [...]
WC = '\p{L}\p{N}_'
# Python's \s and str.isspace() (Unicode whitespace plus the \x1c-\x1f separators), for use inside [...]
WSP = '\p{Space}\x1c-\x1f'
SS = "[#{WSP}]*"   # Python \s*
SS1 = "[#{WSP}]+"  # Python \s+
SPACE_RE = /[#{WSP}]/     # Python str.isspace()
ALNUM_RE = /[\p{L}\p{N}]/ # Python str.isalnum()

IDENT_RE = /(?<![#{WC}$])[A-Za-z_][#{WC}]*/
# A definition starts at a line start (Ruby's ^ is a line anchor, as Python's re.M). Return-type words may be split
# across lines (`static VALUE` then `name(...)` on the next line, as bigdecimal and date write them).
C_STATEMENT_KEYWORDS = %w[if while for switch return sizeof else do].freeze
DEF_RE = /^[ \t]*((?:(?:static|inline|extern)[ \t\n]+)*)((?:[A-Za-z_][#{WC}]*(?:[ \t\n]+|[ \t\n]*\*[ \t\n\*]*))+?)([A-Za-z_][#{WC}]*)[ \t\n]*\(((?:[^()]|\([^()]*\))*)\)#{SS}(\{|;)/
INC_RE = /#[ \t]*include[ \t]*[<"](ruby(?:\/[#{WC}.\/-]*)?\.h)[>"]/
REG_RE = /(?<![#{WC}$.>])(rb_define_method|rb_define_private_method|rb_define_singleton_method|rb_define_module_function|rb_define_global_function)#{SS}\(/
ALLOC_REG_RE = /(?<![#{WC}$.>])(rb_define_alloc_func)#{SS}\(/
# a right side that yields a class (a definition or a lookup of a class): not a non-class assignment to a class variable
# a class expression of the fork (an RClass *): mrb->x_class, mrb_class_get / mrb_exc_get / mrb_module_get, or an E_*_ERROR class macro
CLASS_EXPR_RE = /\A(?:mrb->(?:\w+_class|kernel_module)|mrb_class_get\(|mrb_exc_get\(|mrb_module_get\(|E_[A-Z][A-Z0-9_]*\z)/
CLASS_RHS_RE = '(?:rb_define_(?:class|module)(?:_under)?|rb_const_get(?:_at)?|rb_path2class|rb_class_new|mrb_const_get|mrb_define_(?:class|module)(?:_under)?|mrb_class_get|rb_class_get)'
CLASS_ASSIGN_RE = /(?<![#{WC}$.>])([#{WC}]+)#{SS}=#{SS}rb_define_(?:class|module)(?:_under)?#{SS}\(/
# an ID variable's only write in the gem: NAME = rb_intern("lit"); (matched on the masked text, the literal read from the source)
ID_LIT_ASSIGN_RE = /(?<![#{WC}$.>])([#{WC}]+)#{SS}=(?!=)#{SS}rb_intern(?:_const)?#{SS}\(#{SS}"[^"]*"#{SS}\)#{SS}[;,]/
ID_ZERO_ASSIGN_RE = /(?<![#{WC}$.>])([#{WC}]+)#{SS}=(?!=)#{SS}0#{SS}[;,]/
ANY_WRITE_RE = /(?<![#{WC}$.>])([#{WC}]+)#{SS}(?:[-+*\/%&|^]|<<|>>)?=(?!=)/
NON_FUNC_WORDS = Set.new(%w[if while for switch return sizeof else do case goto])

# CRuby-looking identifiers that are not in api_map.json are refused.
UNKNOWN_RE = /\A(?:rb_[#{WC}]+|st_[#{WC}]+|ruby_[#{WC}]+|x(?:malloc|calloc|realloc|free)|[A-Z][A-Z0-9_]*2[A-Z][A-Z0-9_]*|RB_[#{WC}]+|RUBY_[#{WC}]+|R[A-Z]{2,}_[#{WC}]+|RTEST|RBASIC[#{WC}]*|Q(?:nil|true|false|undef)|(?:NUM2|INT2|LONG2|ULONG2|UINT2|DBL2|FIX2|FIXNUM_|ID2|SYM2|CHR2|LL2|ULL2)[#{WC}]*|SYMBOL_P|NIL_P|NIL_OR_UNDEF_P|Check_[#{WC}]+|StringValue[#{WC}]*|T_[A-Z]+|ANYARGS|PRIsVALUE|CLASS_OF|SPECIAL_CONST_P|FL_[#{WC}]+|OBJ_[#{WC}]+|TypedData_[#{WC}]+|Data_[#{WC}]+|rb_data_[#{WC}]*)\z/

GEM_NAME_RE = /\A[A-Za-z][A-Za-z0-9_-]*\n?\z/

# ---- Python-compatible helpers -------------------------------------------------

# Python str.strip() (Unicode whitespace)
def py_strip(s)
  s.sub(/\A[#{WSP}]+/, '').sub(/[#{WSP}]+\z/, '')
end

# Python str.split() with no argument (whitespace runs, no empty items)
def py_split_ws(s)
  s.split(/[#{WSP}]+/).reject(&:empty?)
end

# Python slice s[a:b] (negative and out-of-range indices clamp, as in Python)
def psl(s, a, b = nil)
  n = s.length
  a += n if a < 0
  b = n if b.nil?
  b += n if b < 0
  a = 0 if a < 0
  a = n if a > n
  b = n if b > n
  return '' if b <= a
  s[a, b - a]
end

# Python str.find(sub, start): index or -1
def pyfind(s, sub, start = 0)
  s.index(sub, start) || -1
end

# Python re.finditer: MatchData objects, with character offsets (begin/end)
def finditer(re, s)
  out = []
  s.scan(re) { out << Regexp.last_match }
  out
end

# Python repr() of a str
def py_repr(s)
  quote = (s.include?("'") && !s.include?('"')) ? '"' : "'"
  out = String.new(quote) # a copy: appending to quote itself would change the closing quote
  s.each_codepoint do |cp|
    ch = [cp].pack('U')
    piece =
      if ch == quote || ch == '\\' then '\\' + ch
      elsif cp == 9 then '\\t'
      elsif cp == 10 then '\\n'
      elsif cp == 13 then '\\r'
      elsif cp < 0x20 || cp == 0x7f then format('\\x%02x', cp)
      elsif cp < 0x7f then ch
      elsif ch.match?(/[\p{C}\p{Z}]/) then (cp <= 0xff ? format('\\x%02x', cp) : (cp <= 0xffff ? format('\\u%04x', cp) : format('\\U%08x', cp)))
      else ch
      end
    out << piece
  end
  out << quote
end

# json.dump(obj, fh, indent=1) as Python writes it: ensure_ascii escapes, ": " and ",\n" separators
def py_json_str(s)
  out = +'"'
  s.each_codepoint do |cp|
    out << case cp
           when 0x22 then '\\"'
           when 0x5c then '\\\\'
           when 0x0a then '\\n'
           when 0x0d then '\\r'
           when 0x09 then '\\t'
           when 0x08 then '\\b'
           when 0x0c then '\\f'
           when 0x20..0x7e then cp.chr
           when 0..0xffff then format('\\u%04x', cp)
           else
             v = cp - 0x10000
             format('\\u%04x\\u%04x', 0xd800 | (v >> 10), 0xdc00 | (v & 0x3ff))
           end
  end
  out << '"'
end

def py_json(v, level = 0)
  case v
  when nil then 'null'
  when true then 'true'
  when false then 'false'
  when Integer then v.to_s
  when String then py_json_str(v)
  when Array
    return '[]' if v.empty?
    "[\n" + v.map { |x| ' ' * (level + 1) + py_json(x, level + 1) }.join(",\n") + "\n" + ' ' * level + ']'
  when Hash
    return '{}' if v.empty?
    "{\n" + v.map { |k, x| ' ' * (level + 1) + py_json_str(k.to_s) + ': ' + py_json(x, level + 1) }.join(",\n") +
      "\n" + ' ' * level + '}'
  else
    raise TypeError, "cannot serialise #{v.class}"
  end
end

# Input is read as text as Python did: UTF-8 with bad bytes replaced, and universal newlines (CRLF and CR become LF).
def read_text(path)
  File.binread(path).force_encoding(Encoding::UTF_8).scrub.gsub(/\r\n?/, "\n")
end

def write_bytes(path, text)
  FileUtils.mkdir_p(File.dirname(path))
  File.binwrite(path, text)
end

def line_of(text, pos)
  psl(text, 0, pos).count("\n") + 1
end

# Function-defining macros. A function-like macro whose body defines functions (ffi's NUM_OP(name, type, ...) defines
# memory_put_##name and its siblings) is expanded at each of its file-scope statement invocations, so the functions it
# defines are ordinary definitions to the scanners. Per file: the macro has one unconditional #define, its body has no
# string literal and no stringification, the invocation is `NAME(args);` at the start of a line outside any braces and
# outside another macro body, and the expansion defines a function (DEF_RE). Each top-level item of the expansion goes
# on its own line, so the lines after an expansion move (refusals there name the expanded text). The #define is left as
# it is: with no use left it is an unused macro, which the converter wraps in #if 0 as it does any other.
def expand_function_macros(text)
  masked = mask_c(text)
  starts = Hash.new { |h, k| h[k] = [] }
  masked.to_enum(:scan, /^[ \t]*#[ \t]*define[ \t]+([A-Za-z_]\w*)\(/).each { starts[Regexp.last_match(1)] << Regexp.last_match.begin(0) }
  cands = {}
  starts.each do |name, at|
    next unless at.length == 1
    st = at[0]
    # a #define under a conditional may be one of several alternatives: such a macro is not expanded
    depth = 0
    masked[0...st].scan(/^[ \t]*#[ \t]*(if|ifdef|ifndef|endif)\b/) { depth += Regexp.last_match(1) == 'endif' ? -1 : 1 }
    next unless depth == 0
    open = masked.index('(', st)
    close = match_close(masked, open)
    next if close < 0
    params = psl(text, open + 1, close).split(',').map(&:strip).reject(&:empty?)
    # the logical line of the #define: a line ending in a backslash continues
    pos = close + 1
    eol = nil
    while eol.nil?
      nl = text.index("\n", pos) || text.length
      if nl > 0 && text[nl - 1] == '\\'
        pos = nl + 1
      else
        eol = nl
      end
    end
    body = psl(text, close + 1, eol).gsub(/\\\n/, ' ').gsub(%r{/\*.*?\*/}m, ' ').sub(%r{//.*\z}, '')
    next if body.match?(/["']/) || body.gsub('##', '').include?('#')
    cands[name] = { params: params, body: body }
  end
  return text if cands.empty?
  edits = []
  cands.each do |name, c|
    masked.to_enum(:scan, /^([ \t]*)#{Regexp.escape(name)}[ \t]*\(/).each do
      m = Regexp.last_match
      name_pos = m.begin(0) + m[1].length
      open = m.end(0) - 1
      prev = m.begin(0) > 0 ? masked[0...m.begin(0)] : ''
      next if prev.end_with?("\\\n")
      close = match_close(masked, open)
      next if close < 0
      j = close + 1
      j += 1 while j < masked.length && masked[j].match?(/[ \t]/)
      next unless masked[j] == ';'
      before = masked[0...name_pos]
      next unless before.count('{') == before.count('}')
      args = split_args(masked, open, close).map { |a, b| psl(text, a, b) }
      next unless args.length == c[:params].length
      expansion = format_expansion(c[:body], c[:params], args)
      next unless DEF_RE.match?(expansion)
      edits << [name_pos, j + 1, expansion]
    end
  end
  edits.sort_by { |a, _b, _t| -a }.each { |a, b, t| text = psl(text, 0, a) + t + psl(text, b) }
  text
end

# The body with its parameters replaced by the arguments (## pastes the adjacent pieces), with each top-level item on its
# own line and the runs of blanks collapsed.
def format_expansion(body, params, args)
  map = params.zip(args).to_h
  pieces = body.split(/\s*##\s*/, -1).map { |pc| pc.gsub(/\b[A-Za-z_]\w*\b/) { |id| map.fetch(id, id) } }
  depth = 0
  lines = []
  cur = +''
  pieces.join.each_char do |ch|
    depth += 1 if ch == '{'
    depth -= 1 if ch == '}'
    cur << ch
    next unless depth == 0 && (ch == ';' || ch == '}')
    lines << cur.strip.gsub(/[ \t]+/, ' ')
    cur = +''
  end
  lines << cur.strip.gsub(/[ \t]+/, ' ') unless cur.strip.empty?
  lines.reject(&:empty?).join("\n")
end

def blank(s)
  s.gsub(/[^\n]/, ' ')
end

def mask_c(src)
  out = []
  i = 0
  n = src.length
  while i < n
    c = src[i]
    if src[i, 2] == '//'
      j = pyfind(src, "\n", i)
      j = n if j < 0
      out << blank(psl(src, i, j))
      i = j
    elsif src[i, 2] == '/*'
      j = pyfind(src, '*/', i + 2)
      j = j < 0 ? n : j + 2
      out << blank(psl(src, i, j))
      i = j
    elsif c == '"' || c == "'"
      j = i + 1
      while j < n && src[j] != c && src[j] != "\n"
        j += src[j] == '\\' ? 2 : 1
      end
      j = n if j > n
      out << c << blank(psl(src, i + 1, j))
      if j < n && src[j] == c
        out << c
        i = j + 1
      else
        i = j
      end
    else
      out << c
      i += 1
    end
  end
  out.join
end

def match_close(masked, open_pos)
  depth = 0
  k = open_pos
  while k < masked.length
    ch = masked[k]
    if '([{'.include?(ch)
      depth += 1
    elsif ')]}'.include?(ch)
      depth -= 1
      return k if depth == 0
    end
    k += 1
  end
  -1
end

def trim(masked, s, e)
  s += 1 while s < e && SPACE_RE.match?(masked[s])
  e -= 1 while e > s && SPACE_RE.match?(masked[e - 1])
  [s, e]
end

def split_args(masked, open_pos, close_pos)
  return [] if py_strip(psl(masked, open_pos + 1, close_pos)).empty?
  spans = []
  depth = 0
  start = open_pos + 1
  (open_pos + 1...close_pos).each do |k|
    ch = masked[k]
    if '([{'.include?(ch)
      depth += 1
    elsif ')]}'.include?(ch)
      depth -= 1
    elsif ch == ',' && depth == 0
      spans << [start, k]
      start = k + 1
    end
  end
  spans << [start, close_pos]
  spans.map { |s, e| trim(masked, s, e) }
end

def next_nonspace(masked, pos)
  k = pos
  k += 1 while k < masked.length && SPACE_RE.match?(masked[k])
  k < masked.length ? k : -1
end

GC_ROOT_ADDR_PRELUDE = <<~'C'.chomp
  /* BC2CPP-MRBGEM: a GC root given by address (rb_gc_register_address, rb_global_variable) on a class variable (struct RClass *)
     or on a value (mrb_value). A class is rooted by its class value once it is set; a value while it is not nil. */
  static void
  nfcx_gc_root_addr(mrb_state *mrb, void *p, size_t n)
  {
    if (n == sizeof(struct RClass *)) {
      struct RClass *c = *(struct RClass **)p;
      if (c) mrb_gc_register(mrb, mrb_obj_value(c));
    }
    else {
      mrb_value v = *(mrb_value *)p;
      if (!mrb_nil_p(v)) mrb_gc_register(mrb, v);
    }
  }
C

# the span of a call rb_gc_register_address(&NAME) or rb_global_variable(&NAME) whose only argument is the address of a class
# variable (pv: the '&', e: the end of NAME): from the callee's name to the closing parenthesis, or nil
def gc_root_call_span(masked, pv, e)
  nx = next_nonspace(masked, e)
  return nil unless nx >= 0 && masked[nx] == ')'
  o = prev_nonspace(masked, pv - 1)
  return nil unless o >= 0 && masked[o] == '('
  m = masked[0...o].match(/\b(rb_gc_register_address|rb_global_variable)[#{WSP}]*\z/)
  return nil unless m
  cp = match_close(masked, o)
  return nil unless cp == nx
  [m.begin(1), cp + 1]
end

def prev_nonspace(masked, pos)
  k = pos
  k -= 1 while k >= 0 && SPACE_RE.match?(masked[k])
  k
end

def is_member(masked, s)
  j = prev_nonspace(masked, s - 1)
  return false if j < 0
  masked[j] == '.' || (masked[j] == '>' && j > 0 && masked[j - 1] == '-')
end

# (callee name, top-level argument index) of the call enclosing pos, or [nil, nil]
def call_context(masked, pos)
  depth = 0
  commas = 0
  k = pos - 1
  while k >= 0
    ch = masked[k]
    if ')]}'.include?(ch)
      depth += 1
    elsif '([{'.include?(ch)
      if depth == 0
        return [nil, nil] if ch != '('
        j = prev_nonspace(masked, k - 1)
        e = j + 1
        while j >= 0 && (ALNUM_RE.match?(masked[j]) || masked[j] == '_')
          j -= 1
        end
        name = psl(masked, j + 1, e)
        return [(name.empty? ? nil : name), commas]
      end
      depth -= 1
    elsif ch == ',' && depth == 0
      commas += 1
    elsif ch == ';' && depth == 0
      return [nil, nil]
    end
    k -= 1
  end
  [nil, nil]
end

# (opening character, callee name) of the innermost unclosed bracket before pos in the same statement; the
# callee is the identifier before a '(' (nil when there is none). [nil, nil] at the statement start.
def innermost_open(masked, pos)
  depth = 0
  k = pos - 1
  while k >= 0
    ch = masked[k]
    if ')]}'.include?(ch)
      depth += 1
    elsif '([{'.include?(ch)
      if depth == 0
        return [ch, nil] if ch != '('
        j = prev_nonspace(masked, k - 1)
        e = j + 1
        j -= 1 while j >= 0 && (ALNUM_RE.match?(masked[j]) || masked[j] == '_')
        name = psl(masked, j + 1, e)
        return ['(', (name.empty? ? nil : name)]
      end
      depth -= 1
    elsif ch == ';' && depth == 0
      return [nil, nil]
    end
    k -= 1
  end
  [nil, nil]
end

# a use of a global-state helper in a function that has no mruby state (see global_use)
CTX_REASON = 'helper needs mruby state, and a use is in a function with no mruby state in scope (not a method, Init or threaded helper)'.freeze

# calls that may keep a pointer they are given (registration, storage, threads, data objects): a helper passed to one
# of them is not a use that stays inside the method call
# rb_thread_* runs its function on another thread (rb_thread_call_without_gvl): the state must not be used there.
STORE_CALL_RE = /\A(?:rb_define|mrb_define|rb_gc_register|rb_global|rb_set_end|rb_iv_set|rb_ivar_set|rb_const_set|
  rb_hash_aset|rb_ary_store|rb_ary_push|rb_thread_|nfcx_thread_|rb_obj_call_init|rb_data_|st_|Data_|TypedData_)/x

# the end of the logical line (a backslash-newline continues it) that starts before k
def logical_line_end(masked, k)
  while k < masked.length
    return k if masked[k] == "\n" && (k == 0 || masked[k - 1] != '\\')
    k += 1
  end
  masked.length
end

def map_types(s, types)
  types.each do |ctype, mtype|
    if ctype == 'ID'
      # ID as a declared type: followed by a name, or alone (a return type before the name is written separately)
      s = s.gsub(/(?<![#{WC}])ID(?![#{WC}])(?=[#{WSP}]+[A-Za-z_]|\z)/) { mtype }
    else
      s = s.gsub(/(?<![#{WC}])#{Regexp.escape(ctype)}(?![#{WC}])/) { mtype }
    end
  end
  s
end

class Edits
  def initialize
    @items = []
  end

  def add(s, e, text)
    @items << [s, e, text]
  end

  def overlaps(s, e)
    @items.any? { |a, b, _| a < e && s < b }
  end

  # an edit that starts, ends or spans the position p (a zero-width insertion there would conflict with it)
  def touches?(p)
    @items.any? { |a, b, _| a <= p && p <= b }
  end

  # an edit that strictly contains the position p (a->p->b with a < p < b): an insertion there would conflict with it
  def touches_strictly?(p)
    @items.any? { |a, b, _| a < p && p < b }
  end

  # the edits that overlap [s, e), as [start, end, text]
  def overlapping(s, e)
    @items.select { |a, b, _| a < e && s < b }
  end

  def drop(items)
    @items -= items
  end

  # the edits at exactly the point p (a zero-width insertion, such as a refusal marker, or any edit that starts there)
  def at_point(p)
    @items.select { |a, _b, _| a == p }
  end

  def apply(text)
    # stable sort: edits at the same position keep their insertion order, as Python's sorted() does
    items = @items.each_with_index.sort_by { |(s, e, _), i| [s, e, i] }.map(&:first)
    items.each_cons(2) do |p, q|
      raise "internal: overlapping edits at #{q[0]}" if q[0] < p[1]
    end
    # the text between the edits is copied once, in order (the same result as Python's reversed splices)
    chars = text.chars
    out = +''
    pos = 0
    items.each do |s, e, t|
      out << chars[pos...s].join << t
      pos = e
    end
    out << chars[pos..].join
  end
end

# K&R-style prototypes with the old compatibility macro: name _((params)) and name _(params). The macro _ is a space,
# and the outer parentheses of the double form are spaces (name  (params) ), so every position stays the same and the
# declaration is an ordinary prototype for the scanners. Only a standalone _ followed by ( is changed.
def kr_normalize(src)
  s = src.dup
  starts = []
  s.to_enum(:scan, /(?<![\w$])_[ \t]*\(/).each { starts << Regexp.last_match.begin(0) }
  starts.reverse_each do |st|
    m = /_[ \t]*\(/.match(s, st)
    op = m.end(0) - 1
    if s[op + 1] == '('
      depth = 0
      close = nil
      i = op
      while i < s.length
        if s[i] == '(' then depth += 1
        elsif s[i] == ')'
          depth -= 1
          if depth.zero?
            close = i
            break
          end
        end
        i += 1
      end
      next if close.nil?
      s[st] = ' '
      s[op] = ' '
      s[close] = ' '
    else
      s[st] = ' '
    end
  end
  s
end

class Converter
  def initialize(cext_dir, out_dir, name = nil, scanner_mode = 'auto', defines = [], undefines = [])
    @scanner_mode = scanner_mode  # auto, libclang or regex
    @scanner = 'regex'            # the scanner used: libclang or regex (choose_scanner)
    @scanner_reason = nil
    @scanner_fallback = []        # files the regex scan read although libclang was used
    @excluded_defs = Set.new      # names defined in text the libclang scan does not list (see libclang_declarations)
    @undefines = undefines        # names this build leaves undefined (--undefine): their #ifdef branches are inactive
    @defines = defines            # -D options for the libclang front end (NAME or NAME=VALUE), as extconf would set
    @cext_dir = File.absolute_path(cext_dir)
    @out_dir = File.absolute_path(out_dir)
    base = @cext_dir.sub(%r{/+\z}, '')
    base = base.include?('/') ? base[(base.rindex('/') + 1)..] : base
    @name = (name.nil? || name.empty?) ? base : name
    @funcname = @name.tr('-', '_')
    amap = JSON.parse(File.read(MAP_PATH, encoding: 'UTF-8'))
    @entries = amap['entries']
    @types = amap['types']
    @includes = amap['includes']
    @special_pos = amap['special_arg_positions_class_only']
    @type_check_refused = amap['type_check_refused'] || {}
    @require_gems = amap['require_gems'] || {}
    @unmapped_reasons = amap['unmapped_reasons'] || {}
    @files = {}   # rel -> {'text','masked','kind'}
    @edits = {}   # rel -> Edits
    @ignored = []
    @warnings = []
    @refusals = []
    @rewrites = []
    @class_vars = Set.new
    @id_literals = {}  # ID variable name -> its rb_intern string literal (gem-wide, assigned exactly once)
    @decl_name_pos = Set.new
    @regs = []
    @reg_by_call = {}
    @reg_names = Set.new
    @valid_reg_names = Set.new  # registered functions whose registration survived check_refs
    @block_arg_files = Set.new  # files that have the nfcx_block_arg definition (rb_yield in a helper)
    @yield_cb_files = Set.new   # files that have the nfcx_yield_cb wrapper (rb_yield as the rb_protect callback)
    @q_helpers = {}            # per file: the nil/true/false test helpers defined (nfcx_is_nil, ...)
    @decls = []   # dicts for function prototypes and definitions
    @defs = {}    # name -> [def dicts]
    @init_defs = []
    @occ = {}     # identifier -> [[rel, start, end]]
    @needs = Set.new
    @helper_names = Set.new
    @init_rel = nil
    @dead_inits = []
    @variadic = {}
    @local_macros = Set.new
  end

  # ---- reporting ---------------------------------------------------------
  def extconf_entry
    path = File.join(@cext_dir, 'extconf.rb')
    return nil unless File.file?(path)
    # create_makefile takes its name with or without parentheses (create_makefile "x" and create_makefile("x"))
    m = /create_makefile(?:#{SS}\(|#{SS1})#{SS}['"]([#{WC}\/.-]+)['"]/.match(read_text(path))
    m ? m[1] : nil
  end

  def in_dead_init(rel, pos)
    @dead_inits.any? { |d| d['file'] == rel && d['hstart'] <= pos && pos <= d['body_end'] }
  end

  def enclosing_func(rel, pos)
    @defs.each_value do |lst|
      lst.each do |d|
        return d if d['file'] == rel && d.key?('brace') && d['brace'] < pos && pos < d['body_end']
      end
    end
    nil
  end

  # A header included by exactly one converted source file: its function bodies are compiled as part of that source, so a use in
  # it is a use in the including file's text (the same rules apply).
  def single_src_header?(rel)
    base = File.basename(rel)
    srcs = @files.select { |r, f| f['kind'] == 'src' && f['text'] =~ /^[ \t]*#[ \t]*include[ \t]*"#{Regexp.escape(base)}"/ }
    srcs.size == 1
  end

  # the tree path a quoted include names from file rel: the includer's directory joined with the path, '.' and '..' resolved
  # (a path that leaves the tree starts with '..')
  def include_key(rel, inc)
    parts = []
    (File.dirname(rel).split('/') + inc.split('/')).each do |seg|
      next if seg.empty? || seg == '.'
      if seg == '..' && !parts.empty? && parts.last != '..'
        parts.pop
      else
        parts << seg
      end
    end
    parts.join('/')
  end

  # a quoted include resolves in the output tree when the path from the includer's directory, or from the tree root, is a file of it
  def include_in_tree?(rel, inc)
    @files.key?(include_key(rel, inc)) || @files.key?(include_key('', inc))
  end

  def refuse(rel, pos, api, reason)
    if rel.nil?
      @refusals << { 'file' => '(gem)', 'line' => 0, 'api' => api, 'reason' => reason }
      return
    end
    return if in_dead_init(rel, pos)
    text = @files[rel]['text']
    @refusals << { 'file' => rel, 'line' => line_of(text, pos), 'api' => api, 'reason' => reason, 'pos' => pos }
    # a marker strictly inside a declaration's header would overlap the header rewrite (process step 2); the
    # refusal is still recorded and the output is still marked not buildable
    return if @decls.any? { |d| d['file'] == rel && d['hstart'] < pos && pos < d['hend'] }
    @edits[rel].add(pos, pos, "/* BC2CPP-MRBGEM REFUSED: #{api} */ ")
  end

  def uses_uv_thread?
    @rewrites.any? { |r| r['to'] == 'nfcx_thread_call_without_gvl' }
  end

  # the position of the innermost '{' that is still open at pos, or nil
  def enclosing_open_brace(masked, pos)
    depth = 0
    k = pos - 1
    while k >= 0
      c = masked[k]
      if c == '}'
        depth += 1
      elsif c == '{'
        return k if depth == 0
        depth -= 1
      end
      k -= 1
    end
    nil
  end

  def rewrite(rel, pos, src, dst, caveat = nil)
    text = @files[rel]['text']
    rec = { 'file' => rel, 'line' => line_of(text, pos), 'from' => src, 'to' => dst }
    rec['caveat'] = caveat if caveat
    @rewrites << rec
  end

  # ---- stage 1: load -----------------------------------------------------
  # A static function defined in more than one file is file-local: each file's copy gets a unique name (NAME__STEM) in
  # that file only, so the converter's name-keyed analysis sees one definition per name. A member name (x.NAME, a struct
  # member NAME; or an array NAME[]) is not a use of the function and is not renamed.
  def static_rename(texts)
    defs = {}
    texts.each do |base, t|
      next unless base.end_with?('.c')
      mask_c(t).scan(/^[ \t]*(?:(?:inline|static)[ \t]+)*static\b[^;{}()]*?\b([A-Za-z_]\w*)[ \t\n]*\([^;{}]*\)[ \t\n]*\{/) do
        (defs[Regexp.last_match(1)] ||= Set.new) << base
      end
    end
    dups = defs.select { |_, fs| fs.size > 1 }
    return texts if dups.empty?
    out = {}
    texts.each do |base, t|
      mine = dups.keys.select { |n| defs[n].include?(base) }
      if mine.empty?
        out[base] = t
        next
      end
      stem = base.sub(/\.[ch]\z/, '').gsub(/\W/, '_')
      masked = mask_c(t)
      reps = []
      mine.each do |n|
        masked.to_enum(:scan, /(?<![\w.>$])#{n}(?!\w)/).each do
          m = Regexp.last_match
          nxt = masked[m.end(0)..][/\A\s*(.)/, 1]
          # a name followed by ';' is a value use (a prototype is followed by '('); an array declaration is followed by '['
          next if nxt == '['
          reps << [m.begin(0), m.end(0), "#{n}__#{stem}"]
        end
      end
      s = t.dup
      reps.sort_by { |a, _, _| -a }.each { |a, b, r| s[a...b] = r }
      out[base] = s
    end
    out
  end

  # C++ inputs (the extension's .cc/.cpp/.cxx sources and their .hh/.hpp/.hxx headers) are read as the C ones are: the mruby build
  # compiles a gem's .cc sources as C++, and the C API they use is the fork's (extern "C" headers)
  def c_input?(name)
    name.match?(/\.(?:c|h|cc|cpp|cxx|hh|hpp|hxx)\z/)
  end

  def cxx_or_c_source?(name)
    name.match?(/\.(?:c|cc|cpp|cxx)\z/)
  end

  def load
    abort "error: not a directory: #{@cext_dir}" unless File.directory?(@cext_dir)
    abort "error: cannot derive a gem name from #{@cext_dir}" unless GEM_NAME_RE.match?(@name)
texts = {}
Dir.children(@cext_dir).reject { |n| n.start_with?('.') }.sort.each do |tb|
  tp = File.join(@cext_dir, tb)
  next if File.directory?(tp)
  texts[tb] = read_text(tp) if c_input?(tb)
end
# the headers of an immediate subdirectory (yajl's api/ holds its public headers, which the sources include as "api/x.h")
# are inputs at their relative path; the subdirectory's sources are not compiled (only the gem's own C files are)
sub_headers = Dir.children(@cext_dir).reject { |n| n.start_with?('.') }.sort.select { |n| File.directory?(File.join(@cext_dir, n)) }
                  .flat_map { |d| (Dir.glob(File.join(@cext_dir, d, '*.{h,c}')) + Dir.glob(File.join(@cext_dir, d, '**', '*.{hh,hpp,hxx}'))).sort.map { |p| p.sub(File.join(@cext_dir, '') , '') } }
sub_headers.each { |rel| texts[rel] = read_text(File.join(@cext_dir, rel)) }
texts.each_key { |k| texts[k] = kr_normalize(texts[k]) }
texts = static_rename(texts)
# --rename OLD=NEW: the gem's own identifier OLD is NEW in every source and header (a name the system headers declare, e.g. crypt_r)
($renames || []).each do |old, new|
  re = /(?<![\w$])#{Regexp.escape(old)}(?![\w])/
  texts.each_key { |k| texts[k] = texts[k].gsub(re, new) }
end
# --replace OLD=NEW: the literal text OLD is NEW in every source and header (a signature the gem's own header and definition disagree on)
($replaces || []).each do |old, new|
  texts.each_key { |k| texts[k] = texts[k].gsub(old, new) }
end
# function-defining macros (NUM_OP(...) at file scope) are expanded in their own file, so the functions they define are found
texts.each_key { |k| texts[k] = expand_function_macros(texts[k]) }
    Dir.children(@cext_dir).reject { |n| n.start_with?('.') }.sort.each do |base|
      path = File.join(@cext_dir, base)
      if File.directory?(path)
        @ignored << [base, 'subdirectory not converted']
        next
      end
      if ($excluded_files || Set.new).include?(base)
        @ignored << [base, 'excluded (--exclude): not built in this configuration']
        next
      end
      unless c_input?(base)
        @ignored << [base, 'not a C source or header (read by nothing; extconf.rb is never run)']
        next
      end
      text = texts.fetch(base)
      kind = cxx_or_c_source?(base) ? 'src' : 'hdr'
      @files[base] = { 'text' => text, 'masked' => mask_c(text), 'kind' => kind }
      noreturn_mask(base)
      @edits[base] = Edits.new
      # gem_init.c is the generated file; the input's own copy is refused (set up before the refusal is recorded)
      refuse(base, 0, 'gem_init.c', 'name collides with the generated gem_init.c') if base == 'gem_init.c'
    end
    sub_headers.each do |rel|
      @files[rel] = { 'text' => texts.fetch(rel), 'masked' => mask_c(texts.fetch(rel)), 'kind' => 'hdr' }
      noreturn_mask(rel)
      @edits[rel] = Edits.new
    end
  end

  # ---- local macros: names the input defines itself -----------------------
  # A name is local when every #define of it in the input is unconditional, apart from the include guard of a
  # header. A #define under any other conditional (or #if 0) may be a compatibility fallback for a CRuby name
  # (e.g. #if !defined(HAVE_...) #define rb_x ...), so the name stays refused. An #undef must be unconditional and
  # no use may follow it in its file. A name whose first use in its own file precedes the #define is not local
  # either: that use is the CRuby name. A local name is kept as it is (it is not a CRuby API); the body of its
  # macro is still scanned like any other text, so a CRuby API used there is checked.
  GUARD_RE = /(?:_h_*|_included)\z/i

  def scan_local_macros
    defined = {}     # name -> [[rel, directive position, tainted]]
    undefined = {}   # name -> [[rel, directive position, tainted]]
    @files.each do |rel, f|
      stack = []     # one frame per open conditional: [guard?, condition texts]
      f['masked'].scan(/^[ \t]*#[ \t]*(\w+)([^\n]*(?:\\\n[^\n]*)*)/) do
        kw, rest, pos = $1, $2.strip, $~.begin(0)
        case kw
        when 'if', 'ifdef', 'ifndef'
          gname = rest[/\A\w+\z/] if kw == 'ifndef'
          gname ||= rest[/\A!\s*defined\s*\(?\s*(\w+)\s*\)?\z/, 1] if kw == 'if'
          guard = stack.empty? && f['kind'] == 'hdr' && !gname.nil? && GUARD_RE.match?(gname)
          stack.push([guard, [rest], false])
        when 'elif', 'else'
          if stack.any?
            stack.last[1] << rest
            stack.last[0] = false   # an include guard has no other branch
          end
        when 'endif' then stack.pop
        when 'define'
          name = rest[/\A(\w+)/, 1]
          next if name.nil?
          tainted = stack.any? { |g, _, _| !g }
          (defined[name] ||= []) << [rel, pos, tainted]
        when 'undef'
          name = rest[/\A(\w+)/, 1]
          (undefined[name] ||= []) << [rel, pos, stack.any? { |g, _, _| !g }] if name
        end
      end
    end
    @local_macros = Set.new
    defined.each do |name, defs|
      next if defs.any? { |_, _, t| t }
      use_re = /(?<![#{WC}$])#{Regexp.escape(name)}(?![#{WC}])/
      # an #undef ends the gem's meaning: it must be unconditional, and no use of the name may follow it
      undone = (undefined[name] || []).any? do |rel, pos, t|
        masked = @files[rel]['masked']
        t || !masked.index(use_re, masked.index("\n", pos) || masked.length).nil?
      end
      next if undone
      early = defs.any? do |rel, pos, _|
        first = @files[rel]['masked'].index(use_re)
        !first.nil? && first < pos
      end
      @local_macros << name unless early
    end
  end

  # ---- local variables and struct tags the input declares ----------------
  # A parameter or top-level local of a function definition is local when every occurrence of its name in the input
  # lies inside a function that declares it, from the declaration on: within that function it shadows any CRuby name
  # of the same spelling, and no other occurrence can refer to it. A class variable is never local this way. A
  # struct, union or enum tag the input defines (with a body) is in the tag namespace, so `struct NAME` with that tag
  # is local; a forward declaration is not enough, since the definition may be CRuby's.
  NOT_A_TYPE = %w[return goto else case typedef sizeof break continue do].freeze

  def scan_local_names
    @local_tags = Set.new
    @files.each_value do |f|
      f['masked'].scan(/\b(?:struct|union|enum)[ \t\n]+([A-Za-z_][#{WC}]*)[ \t\n]*\{/) { @local_tags << $1 }
    end
    cands = Hash.new { |h, k| h[k] = [] }   # name -> [[rel, lo, hi, declaration position]]
    @defs.values.flatten.each do |d|
      next unless d.key?('body_end')
      span = [d['file'], d['hstart'], d['body_end']]
      param_names(d).each { |n| cands[n] << [*span, d['hstart']] }
      body_top_declarations(d).each { |n, pos| cands[n] << [*span, pos] }
    end
    @local_var_occ = Set.new
    cands.each do |name, list|
      next if @class_vars.include?(name) || !@occ.key?(name)
      occs = @occ[name]
      covered = occs.all? do |orel, s, _|
        list.any? { |rel, lo, hi, dpos| rel == orel && lo <= s && s < hi && s >= dpos }
      end
      occs.each { |orel, s, _| @local_var_occ << [orel, s] } if covered
    end
  end

  # [name, declaration position] for the declarators of the top-level declarations in a function body
  def body_top_declarations(d)
    masked = @files[d['file']]['masked']
    out = []
    depth = 0
    seg = d['brace'] + 1
    i = seg
    while i < d['body_end']
      c = masked[i]
      if c == '{'
        depth += 1
      elsif c == '}'
        depth -= 1
        seg = i + 1 if depth.zero?
      elsif c == ';' && depth.zero?
        text = masked[seg...i]
        head = /\A\s*(?:(?:static|const|volatile|unsigned|signed|struct|union|enum)\s+)*([A-Za-z_]\w*)\s+(?=[*A-Za-z_])/.match(text)
        if head && !NOT_A_TYPE.include?(head[1])
          rest = text[head.end(0)..]
          parts, cur, pd = [], +'', 0
          rest.each_char do |ch|
            pd += 1 if ch == '('
            pd -= 1 if ch == ')'
            if ch == ',' && pd.zero?
              parts << cur
              cur = +''
            else
              cur << ch
            end
          end
          parts << cur
          parts.each do |part|
            nm = part.sub(/=.*\z/m, '')[/([A-Za-z_]\w*)\s*(?:\[[^\]]*\]\s*)*\z/, 1]
            out << [nm, seg] if nm
          end
        end
        seg = i + 1
      end
      i += 1
    end
    out
  end

  # An ID variable whose one write in the whole gem is NAME = rb_intern("lit"); and that is never address-taken, never
  # declared inside a function and never written otherwise always names the literal. A call that passes it can then
  # use mrb_intern_cstr with the literal (the same symbol the variable holds after the Init function runs).
  def compute_id_literals
    lits = Hash.new { |h, k| h[k] = Set.new }   # name -> the literals it is set from (rb_intern("lit"))
    lit_writes = Hash.new(0)                    # name -> number of rb_intern writes
    zero_writes = Hash.new(0)                   # name -> number of writes of 0 (the unset value of a lazily set ID)
    writes = Hash.new(0)                        # name -> every write
    address = Set.new
    local_decl = Set.new
    @files.each_value do |f|
      next unless f['kind'] == 'src'
      masked, text = f['masked'], f['text']
      finditer(ID_LIT_ASSIGN_RE, masked).each do |m|
        lit = /"([^"\\]+)"/.match(text[m.begin(0)...m.end(0)])
        next unless lit
        lits[m[1]] << lit[1]
        lit_writes[m[1]] += 1
      end
      finditer(ID_ZERO_ASSIGN_RE, masked).each { |m| zero_writes[m[1]] += 1 }
      finditer(ANY_WRITE_RE, masked).each { |m| writes[m[1]] += 1 }
      masked.scan(/&\s*([#{WC}]+)\b/) { address << Regexp.last_match(1) }
      finditer(/(?<![#{WC}])ID\s+([#{WC}]+)\b/, masked).each do |m|
        nl = masked.rindex("\n", m.begin(0) - 1)
        pre = masked[(nl ? nl + 1 : 0)...m.begin(0)]
        local_decl << m[1] unless pre.match?(/\A(?:extern\s+|static\s+)?\z/)
      end
    end
    lits.each do |name, set|
      # every write is rb_intern of the one literal, or 0 (the unset value); nothing else writes it
      next unless set.size == 1 && writes[name] == lit_writes[name] + zero_writes[name]
      next if address.include?(name) || local_decl.include?(name) || @class_vars.include?(name)
      @id_literals[name] = set.first
    end
  end

  # ---- stage 2: classes, registrations, definitions -----------------------
  def scan
    @files.each_value do |f|
      finditer(CLASS_ASSIGN_RE, f['masked']).each { |m| @class_vars << m[1] }
    end
    compute_id_literals
    @files.each do |rel, f|
      next unless f['kind'] == 'src'
      text, masked = f['text'], f['masked']
      finditer(REG_RE, masked).each do |m|
        cs = m.begin(1)
        op = m.end(0) - 1
        cp = match_close(masked, op)
        rec = { 'file' => rel, 'call' => cs, 'open' => op, 'close' => cp, 'api' => m[1],
                'error' => nil, 'func' => nil, 'argc' => nil, 'target' => nil,
                'func_span' => nil, 'argc_span' => nil }
        if cp < 0
          rec['error'] = 'unbalanced parentheses in registration call'
        else
          args = split_args(masked, op, cp)
          # rb_define_global_function(name, func, argc) has no target: it defines a Kernel method
          global = m[1] == 'rb_define_global_function'
          if args.size != (global ? 3 : 4)
            rec['error'] = "registration call has #{args.size} arguments, expected #{global ? 3 : 4}"
          else
            if global
              (ns, ne), (fs, fe), (as_, ae) = args
              rec['target'] = 'rb_mKernel'
            else
              (ts, te), (ns, ne), (fs, fe), (as_, ae) = args
              rec['target'] = py_strip(psl(text, ts, te))
              rec['target_span'] = [ts, te]
            end
            rec['name_span'] = [ns, ne]
            nm = /\A"([^"\\\n]*)"\z/.match(py_strip(psl(text, ns, ne)))
            fm = /\A(?:\(#{SS}VALUE#{SS}\(#{SS}\*#{SS}\)#{SS}\(#{SS}(?:ANYARGS|\.\.\.)#{SS}\)#{SS}\)#{SS})?([A-Za-z_][#{WC}]*)\z/
                 .match(py_strip(psl(text, fs, fe)))
            am = /\A-?[0-9]+\z/.match(py_strip(psl(text, as_, ae)))
            rec['func_span'] = [fs, fe]
            rec['argc_span'] = [as_, ae]
            if am.nil?
              rec['error'] = 'argc is not an integer literal'
            elsif am[0].to_i < -1
              # -1 is the variadic form (int argc, VALUE *argv, VALUE self); -2 takes an array
              rec['error'] = "argc #{am[0]} (array form) is not in the supported subset"
            elsif fm.nil?
              rec['error'] = 'method function argument is not a plain function name ' \
                             '(only the VALUE (*)(ANYARGS) and VALUE (*)(...) casts are handled)'
            elsif nm.nil?
              rec['error'] = 'method name is not a plain string literal'
            else
              rec['func'] = fm[1]
              rec['argc'] = am[0].to_i
              rec['name'] = nm[1]
            end
          end
        end
        @regs << rec
        @reg_by_call[[rel, cs]] = rec
      end
      # rb_define_alloc_func(klass, func): the allocator is a registered function of arity 0 (its VALUE parameter is the class)
      finditer(ALLOC_REG_RE, masked).each do |m|
        cs = m.begin(1)
        op = m.end(0) - 1
        cp = match_close(masked, op)
        rec = { 'file' => rel, 'call' => cs, 'open' => op, 'close' => cp, 'api' => m[1],
                'error' => nil, 'func' => nil, 'argc' => 0, 'target' => nil,
                'func_span' => nil, 'argc_span' => nil }
        args = cp < 0 ? [] : split_args(masked, op, cp)
        if cp < 0
          rec['error'] = 'unbalanced parentheses in registration call'
        elsif args.size != 2
          rec['error'] = "registration call has #{args.size} arguments, expected 2"
        else
          (ts, te), (fs, fe) = args
          rec['target'] = py_strip(psl(text, ts, te))
          rec['target_span'] = [ts, te]
          fm = /\A([A-Za-z_][#{WC}]*)\z/.match(py_strip(psl(text, fs, fe)))
          if fm.nil?
            rec['error'] = 'allocator argument is not a plain function name'
          else
            rec['func'] = fm[1]
            rec['func_span'] = [fs, fe]
          end
        end
        @regs << rec
        @reg_by_call[[rel, cs]] = rec
      end
    end
    # one arity per registered function
    arities = {}
    @regs.each do |r|
      (arities[r['func']] ||= Set.new) << r['argc'] if r['error'].nil?
    end
    @regs.each do |r|
      r['error'] = "function #{r['func']} is registered with conflicting arities" if r['error'].nil? && arities[r['func']].size > 1
    end
    @regs.each { |r| @reg_names << r['func'] if r['error'].nil? }
    # declarations and definitions, from the scanner chosen at start (see declarations_by_file)
    declarations_by_file.each do |rel, decls|
      f = @files[rel]
      decls.each do |d|
        next if f['kind'] != 'src' && !d['proto'] && !d['storage'].split.include?('static') # a header body is converted only when it is static (inline or not): it is local to each includer
        next if NON_FUNC_WORDS.include?(d['name']) || NON_FUNC_WORDS.include?(py_split_ws(d['ret']).last)
        unless d['proto']
          (@defs[d['name']] ||= []) << d
          @init_defs << d if d['name'].start_with?('Init_')
        end
        @decls << d
      end
    end
    # class variables declared as VALUE (decl name positions are skipped later)
    @files.each do |rel, f|
      @class_vars.each do |c|
        finditer(/(?<![#{WC}])VALUE(?![#{WC}])#{SS1}#{Regexp.escape(c)}(?![#{WC}])(?=#{SS}[=;,\[])/, f['masked'])
          .each { |m| @decl_name_pos << [rel, m.end(0) - c.length] }
      end
      # every declarator of a VALUE declaration list (static VALUE a, cParseError, cEncoder;): a list has no call or braces
      finditer(/(?<![#{WC}])VALUE(?![#{WC}])([^;{}()]*);/, f['masked']).each do |m|
        m[1].scan(/(?<![#{WC}])([A-Za-z_]\w*)(?![#{WC}])/) do
          next unless @class_vars.include?($1)
          @decl_name_pos << [rel, m.begin(1) + $~.begin(0)]
        end
      end
    end
  end

  # ---- declaration scanners ----------------------------------------------
  # The scanner is chosen once, before the scan. auto uses libclang-edg when it loads and the regex scan otherwise;
  # libclang forces it (an unavailable library stops the conversion); regex never loads it.
  def choose_scanner
    if @scanner_mode == 'regex'
      @scanner = 'regex'
      return
    end
    ok, why = DeclScan.available?
    if ok
      @scanner = 'libclang'
    elsif @scanner_mode == 'libclang'
      abort "error: libclang scanner unavailable: #{why}"
    else
      @scanner = 'regex'
      @scanner_reason = "libclang-edg not used: #{why}"
    end
  end

  # {rel => [declaration dicts]} for every input file. With libclang, a file the front end cannot parse (a header that
  # needs its includer's types, or a configuration that needs extconf's defines) is read by the regex scan and is
  # listed in scanner_fallback. The fallback is per file: the other files keep the libclang records.
  def declarations_by_file
    result = {}
    @scanner_fallback = []
    @files.each do |rel, f|
      if @scanner == 'libclang'
        begin
          decls, skipped = libclang_declarations(rel, f)
          skipped.each { |line, why| @warnings << { 'file' => rel, 'line' => line, 'api' => 'declaration scan', 'reason' => why } }
          result[rel] = decls
          next
        rescue DeclScan::Error => e
          @scanner_fallback << { 'file' => rel, 'reason' => e.message }
        end
      end
      result[rel] = regex_declarations(rel, f)
    end
    @scanner = 'regex' if @scanner == 'libclang' && @scanner_fallback.size == @files.size
    result
  end

  # [records, skipped] from libclang-edg: the function declarations of the main file (decl_scan.rb). libclang-edg
  # lists one record per function entity, so a prototype with a definition in the same file is not listed; the
  # prototypes of the names it lists are taken from the text, as the regex scan finds them.
  # The inactive branches of conditionals whose condition is known in this build: #if 0, and #ifdef / #ifndef of a name that
  # this build does not define (no -D option) and the gem never #defines. Other conditions are unknown and stay active.
  # Returns [start, end] spans of inactive text (the directive lines themselves are kept).
  # the HAVE_OPENSSL* / HAVE_SSL* guard (mkmf defines it when OpenSSL is in the build) of the definition of name, or nil
  def openssl_guarded_definition?(name)
    @files.each_value do |f|
      masked = f['masked']
      m = /^[ \t]*(?:[A-Za-z_][\w \t\*]*?\b)?#{Regexp.escape(name)}[ \t]*\(/.match(masked)
      next unless m
      pos = m.begin(0)
      # the conditionals still open at the definition (a stack of #if/#ifdef/#ifndef, popped by #endif): an OpenSSL one guards it
      stack = []
      masked[0...pos].each_line do |line|
        if (d = /\A[ \t]*#[ \t]*(if|ifdef|ifndef|endif)\b[ \t]*(.*?)[ \t\r\n]*\z/.match(line))
          if d[1] == 'endif'
            stack.pop
          else
            stack << d[2].to_s
          end
        end
      end
      open_ssl = stack.find { |g| g =~ /HAVE_(?:OPENSSL|SSL)/ }
      return open_ssl[/\b(HAVE_(?:OPENSSL|SSL)\w*)\b/, 1] if open_ssl
    end
    nil
  end

  # the value of a #if condition made of defined(NAME) / !defined(NAME) atoms joined by && or || (no grouping):
  # true, false, or nil when an atom is not decided (a name no build or target setting defines or undefines)
  def pred_value(arg, build, undefined)
    atom = lambda do |t|
      t = t.strip
      neg = t.start_with?('!')
      t = t.sub(/\A!\s*/, '') if neg
      t = t.sub(/\A\(\s*/, '').sub(/\s*\)\z/, '') while t.start_with?('(') && t.end_with?(')')
      m = t.match(/\Adefined\s*\(?\s*([A-Za-z_]\w*)\s*\)?\z/)
      return nil unless m
      v = if build.include?(m[1]) then true
          elsif undefined.include?(m[1]) then false
          end
      return nil if v.nil?
      neg ? !v : v
    end
    return nil if arg.include?('(') && !arg.match?(/\A\s*!?\s*\(?\s*defined/)
    ors = arg.split('||').map(&:strip)
    ors.map do |o|
      ands = o.split('&&').map { |a| atom.call(a) }
      if ands.include?(false) then false
      elsif ands.all? { |x| x == true } then true
      end
    end.then do |vals|
      if vals.include?(true) then true
      elsif vals.all? { |x| x == false } then false
      end
    end
  end

  def text_inactive_spans(rel)
    f = @files[rel]
    masked = f['masked']
    build = Set.new((@defines || []).map { |d| d.split('=', 2)[0] })
    # The target is a non-Windows mruby build: these names are undefined in it, so their #ifdef branches are inactive
    # (oj's rb_w32_* calls sit under #ifdef _WIN32). A Windows target would need this set changed.
    # _LIBC is defined only while glibc itself is compiled (bcrypt's crypt_r is under defined(__GLIBC__) && defined(_LIBC))
    target_undefined = Set.new(%w[_WIN32 _MSC_VER __MINGW32__ _LIBC]) | Set.new(@undefines || [])
    gem_defined = Set.new
    @files.each_value { |g| g['masked'].scan(/^[ \t]*#[ \t]*define[ \t]+([A-Za-z_]\w*)/) { gem_defined << $1 } }
    out = []
    stack = []   # frames: {value: true/false/nil, branch_start: pos}
    pos = 0
    masked.each_line do |line|
      lstart = pos
      pos += line.length
      if (m = /\A[ \t]*#[ \t]*(if|ifdef|ifndef|else|elif|endif)\b[ \t]*(.*?)[ \t\r\n]*\z/.match(line))
        kw, arg = m[1], m[2].to_s.strip
        case kw
        when 'if', 'ifdef', 'ifndef'
          # only #if 0, a name this build defines (-D), and the names the target leaves undefined are decided: a name the gem
          # #defines is not decided (an include guard #defines its own name inside its #ifndef), and a name no -D option
          # sets may come from mkmf (HAVE_*, extconf.h), so its branch stays active
          value = if kw == 'if' && arg == '0' then false
                  elsif kw == 'if' && arg =~ /\A(\d+)[ \t]*(==|!=)[ \t]*(\d+)\z/
                    # a comparison of two integer literals is decided (#if 0 == 1)
                    (($1.to_i == $3.to_i) == ($2 == '==')) ? true : false
                  elsif kw != 'if' && arg =~ /\A([A-Za-z_]\w*)\z/ && build.include?($1)
                    kw == 'ifdef'
                  elsif kw != 'if' && arg =~ /\A([A-Za-z_]\w*)\z/ && target_undefined.include?($1)
                    kw == 'ifndef'
                  elsif kw == 'if' && arg.match?(/defined|&&|\|\|/)
                    # a condition of defined(NAME) atoms joined by && and || (no grouping): decided when the atoms decide it
                    pred_value(arg, build, target_undefined)
                  end
          frame = { value: value, inactive_from: nil }
          frame[:inactive_from] = pos if value == false
          stack << frame
        when 'else'
          fr = stack.last
          next unless fr
          if fr[:inactive_from]
            out << [fr[:inactive_from], lstart]
            fr[:inactive_from] = nil
          end
          fr[:inactive_from] = pos if fr[:value] == true
        when 'endif'
          fr = stack.pop
          next unless fr
          out << [fr[:inactive_from], lstart] if fr[:inactive_from]
        end
      end
    end
    out
  end

  def libclang_declarations(rel, f)
    dirs = [@cext_dir]
    dirs += DeclScan.ruby_include_dirs if INC_RE.match?(f['text'])
    recs, skipped = DeclScan.scan_file(File.join(@cext_dir, rel), rel, f['text'], f['masked'],
                                       f['kind'] != 'src', dirs, @defines)
    names = recs.map { |d| d['name'] }.to_set
    listed = recs.map { |d| d['po'] }.to_set
    text_decls = regex_declarations(rel, f)
    # a prototype of a decl_drop name is added even when the front end lists it only as a header declaration (the libclang
    # records are for this file's own declarations): its declaration is removed (see the decl_drop loop)
    extra = text_decls.select do |d|
      d['proto'] && (names.include?(d['name']) || (@entries[d['name']] || {})['decl_drop']) && !listed.include?(d['po'])
    end
    # a definition the text has and the front end does not list is excluded by its #if (or is not a definition)
    # per definition: a text definition the front end does not list (its #if is false in this build), even when another
    # definition of the same name is listed (#if A ... #else ... #endif)
    text_decls.each { |d| @excluded_defs << d['name'] if !d['proto'] && !listed.include?(d['po']) }
    # the body of such a definition is not compiled (its #if is false in this build): its spans are kept, so a use inside
    # them is dead code, not a file-scope use (see the identifier pass)
    text_decls.each do |d|
      next if d['proto'] || listed.include?(d['po']) || d['brace'].nil? || d['body_end'].nil?
      (@excluded_spans ||= {})[rel] ||= []
      @excluded_spans[rel] << [d['brace'], d['body_end']]
    end
    [(recs + extra).sort_by { |d| d['hstart'] }, skipped]
  end

  # The declaration records of one file from DEF_RE (the regex scan)
  def regex_declarations(rel, f)
    text, masked = f['text'], f['masked']
    out = []
    finditer(DEF_RE, masked).each do |m|
      storage, name, term = m[1], m[3], m[5]
      # `else if (c) {` and `while (x) {` match the header shape with a keyword as the name: not a definition
      next if C_STATEMENT_KEYWORDS.include?(name)
      ret = m[2].sub(/[#{WSP}]+\z/, '') # the pointer star of a return type (Real *) stays
      po = pyfind(masked, '(', m.begin(3))
      pc = match_close(masked, po)
      d = { 'file' => rel, 'name' => name, 'storage' => storage, 'ret' => ret,
            'hstart' => m.begin(0), 'po' => po, 'pc' => pc,
            'params' => psl(text, po + 1, pc), 'proto' => term == ';', 'hdr' => f['kind'] != 'src' }
      if term == '{'
        d['brace'] = m.end(0) - 1
        d['body_end'] = match_close(masked, d['brace'])
        d['hend'] = d['brace']
      else
        d['hend'] = pc + 1
      end
      out << d
    end
    out
  end

  def build_occurrences
    @files.each do |rel, f|
      f['masked'].scan(IDENT_RE) do
        m = Regexp.last_match
        next if is_member(f['masked'], m.begin(0))
        (@occ[m[0]] ||= []) << [rel, m.begin(0), m.end(0)]
      end
    end
  end

  def body_idents(d)
    masked = @files[d['file']]['masked']
    Set.new(psl(masked, d['brace'], d['body_end'] + 1).scan(IDENT_RE))
  end

  # A registered method that is also called directly from C is split: its body becomes <name>_impl with the original
  # C parameters, direct calls go to the impl, and the registration keeps <name> for a generated wrapper with the
  # mruby signature (wrapper_def). The split needs the arity and argument types (registered_header), a single
  # definition in a source file, and only direct calls (no address, no header body, no rb_scan_args in a variadic
  # body: its arguments would come from the mruby call frame). The impl takes mrb when check_refs threads it into
  # the body's direct callers; a method that fails there is unsplit and keeps its refusal. @split_reason records why.
  def compute_splits
    @split_names = Set.new
    @split_reason = {}
    @regs.select { |r| r['error'].nil? }.map { |r| r['func'] }.uniq.sort.each do |name|
      next unless @defs.key?(name)
      uses = (@occ[name] || []).reject do |rel, s, _e|
        @regs.any? { |r| r['error'].nil? && r['file'] == rel && r['open'] <= s && s <= r['close'] } ||
          @decls.any? { |d| d['name'] == name && d['file'] == rel && d['hstart'] <= s && s < d['hend'] }
      end
      next if uses.empty?
      why = split_problem(name, uses)
      if why
        @split_reason[name] = why
      else
        @split_names << name
      end
    end
  end

  # the refusal of the direct calls of a registered method that is not split, with the reason recorded for it
  def refuse_direct_uses(name)
    msg = 'registered method function is also called directly (not supported)'
    msg += " (#{@split_reason[name]})" if @split_reason[name]
    uses = (@occ[name] || []).reject do |rel, s, _e|
      @regs.any? { |r| r['error'].nil? && r['file'] == rel && r['open'] <= s && s <= r['close'] } ||
        @decls.any? { |d| d['name'] == name && rel == d['file'] && d['hstart'] <= s && s < d['hend'] }
    end
    # A method whose body reads its arguments from the call frame (rb_scan_args) cannot be called directly: the direct
    # call F(n, NULL, self) would read the caller's frame. Called through its name (mrb_funcall_argv) it runs in its own
    # frame with the same arguments; the calls of that form are rewritten, and any other direct use still refuses.
    if @split_reason[name].to_s.include?('rb_scan_args') && !uses.empty?
      reg = @regs.find { |r| r['error'].nil? && r['func'] == name }
      rewrites = uses.map do |rel, s, _e|
        masked = @files[rel]['masked']
        m = /#{Regexp.escape(name)}[ \t\n]*\([ \t\n]*(\d+)[ \t\n]*,[ \t\n]*(?:\([ \t\n]*VALUE[ \t\n]*\*[ \t\n]*\)[ \t\n]*)?(?:NULL|0)[ \t\n]*,[ \t\n]*([A-Za-z_][#{WC}]*)[ \t\n]*\)/.match(masked[s..].to_s)
        fn = enclosing_func(rel, s)
        ok = m && m.begin(0) == 0 && reg && fn && (@valid_reg_names.include?(fn['name']) || (@needs || Set.new).include?(fn['name']))
        [rel, s, m, ok]
      end
      if rewrites.all? { |_r, _s, _m, ok| ok }
        rewrites.each do |rel, s, m, _ok|
          tok = mrb_tok(rel, s)
          # a tracked class variable is a struct RClass *: its VALUE is mrb_obj_value (the receiver of mrb_funcall_argv)
          recv = @class_vars.include?(m[2]) ? "mrb_obj_value(#{m[2]})" : m[2]
          new = "mrb_funcall_argv(#{tok}, #{recv}, mrb_intern_cstr(#{tok}, \"#{reg['name']}\"), #{m[1]}, NULL)"
          @edits[rel].add(s, s + m[0].length, new)
          rewrite(rel, s, name, new, 'a direct call of a method whose arguments are read from the call frame is a call through the method name: the method runs in its own frame (Ruby method dispatch, so a redefinition of the method is seen)')
        end
        return
      end
    end
    uses.each do |rel, s, _e|
      refuse(rel, s, name, msg)
    end
  end

  # a parameter or local of the enclosing function fn with the name hides a function of that name there
  # true when a declaration of name in fn is a local or a parameter, not the declaration of a class variable of that name
  # (a class variable's own VALUE declaration is in @decl_name_pos, and it is not a shadow)
  # true when the class variable NAME is owned at pos: a file-scope variable, or a variable of a function that assigns it a
  # class (NAME = rb_define_class...). A VALUE local of another function with the same name is an ordinary value.
  # A class variable is owned (struct RClass *) across the whole input when some function assigns it a class definition and
  # no function assigns it a non-class value: a use in another file (or in a function without the definition) is the same
  # object. The per-function test (below) decides the rest.
  # an assignment (not a declaration with an initializer: VALUE x = Qnil declares x) of a non-class value
  def nondef_assignment?(text, re)
    text.to_enum(:scan, re).any? do
      m = Regexp.last_match
      pre = text[[m.begin(0) - 24, 0].max...m.begin(0)].to_s
      !pre.match?(/\b(?:VALUE|mrb_value)\s*\*?\s*\z/)
    end
  end

  def global_owned_cvar?(name)
    @gcv_owned ||= {}
    return @gcv_owned[name] if @gcv_owned.key?(name)
    en = Regexp.escape(name)
    define_re = /(?<![#{WC}$.>])#{en}#{SS}=#{SS}rb_define_(?:class|module)(?:_under)?#{SS}\(/
    # a class constant (rb_eEncodingError, rb_cObject: an RClass * expression in the api_map) is a class value too
    nondef_re = /(?<![#{WC}$.>])#{en}#{SS}=(?!=)(?>#{SS})(?!#{CLASS_RHS_RE}#{SS}\(|rb_[cem][A-Z]\w*#{SS};)/
    defined = @files.values.any? { |f| f['masked'].match?(define_re) }
    mixed = @files.values.any? { |f| nondef_assignment?(f['masked'], nondef_re) }
    @gcv_owned[name] = defined && !mixed
  end

  def owns_class_var?(rel, pos, name)
    fn = enclosing_func(rel, pos)
    # a function that declares a local of this name shadows the class variable: its own (local) test decides
    return true if global_owned_cvar?(name) && !(fn && value_names_of(fn).include?(name))
    if fn.nil?
      # a struct or union member is a field of that type, not a class variable (a field may share a class variable's name)
      open = enclosing_open_brace(@files[rel]['masked'], pos)
      return false if open && @files[rel]['masked'][[open - 60, 0].max...open].to_s.match?(/\b(?:struct|union)[ \t\n]*[A-Za-z_]?\w*[ \t\n]*\z/)
      # a file-scope class variable is owned unless some function assigns it a non-class value (then it is an mrb_value)
      return global_owned_cvar?(name)
    end
    masked = @files[fn['file']]['masked']
    text = psl(masked, fn['brace'], fn['body_end'] + 1)
    return false unless text.match?(/(?<![#{WC}$.>])#{Regexp.escape(name)}#{SS}=#{SS}rb_define_(?:class|module)(?:_under)?#{SS}\(/)
    # a function that also assigns the name a value that is not a class definition (Qundef, a lookup) holds an mrb_value:
    # an RClass * cannot take it
    !nondef_assignment?(text, /(?<![#{WC}$.>])#{Regexp.escape(name)}#{SS}=(?!=)(?>#{SS})(?!#{CLASS_RHS_RE}#{SS}\()/)
  end

  # for a Q constant at s that is the right operand of == or !=: [operator position, left operand start, negated?] when the
  # left operand is a call (NAME(...)); nil otherwise (an identifier or a member is the value pass's comparison)
  def q_comparison(rel, s, masked)
    pre = prev_nonspace(masked, s - 1)
    return nil if pre < 1
    op = masked[(pre - 1)..pre]
    return nil unless op == '==' || op == '!='
    ops = pre - 1
    lhs_end = prev_nonspace(masked, ops - 1)
    return nil if lhs_end < 0
    if masked[lhs_end] == ')'
      depth = 0
      i = lhs_end
      while i >= 0
        c = masked[i]
        if c == ')' then depth += 1
        elsif c == '('
          depth -= 1
          break if depth.zero?
        end
        i -= 1
      end
      return nil if i < 0
      head = masked[0...i]
      m = head.match(/([A-Za-z_]\w*(?:\s*(?:->|\.)\s*[A-Za-z_]\w*)*)\s*\z/)
      return nil unless m
    else
      # an identifier or a member path is a VALUE comparison, which value_equality_pass handles (mrb_obj_equal)
      return nil
    end
    return nil if %w[if while for switch return sizeof].include?(m[1])
    [ops, m.begin(1), op == '!=']
  end

  # true when the declaration of ID variables at e (ID a, b, c;) names only variables that are assigned ID2SYM(...) somewhere
  # in the input (their value is a symbol VALUE), with no other declarator and no initializer that is not ID2SYM
  def symbol_value_decl?(rel, e)
    @symbol_vars ||= begin
      sv = Set.new
      @files.each_value { |f| f['masked'].scan(/(?<![#{WC}$.>])([A-Za-z_]\w*)[ \t\n]*=[ \t\n]*ID2SYM\(/) { sv << $1 } }
      sv
    end
    masked = @files[rel]['masked']
    stop = masked.index(';', e)
    return false if stop.nil?
    decl = masked[e...stop]
    return false if decl.include?('(') || decl.include?('{')
    names = decl.split(',').map { |x| x.strip[/\A[A-Za-z_]\w*/] }
    !names.empty? && names.all? { |n| n && @symbol_vars.include?(n) }
  end

  # the first argument of a statement-level call of a local macro, when it is an all-caps name the input's macro pastes into a
  # declaration (DEF_MAX_LENGTH(REQUEST_URI, 1024) declares MAX_REQUEST_URI_LENGTH): not a CRuby name (no api_map entry, no
  # CRuby prefix), so it is not an unknown name to refuse
  def local_macro_arg_names
    @local_macro_arg_names ||= begin
      out = Set.new
      @files.each_value do |f|
        f['masked'].scan(/^[ \t]*([A-Za-z_]\w*)[ \t]*\(([^()\n;]*)\)[ \t]*;/) do
          next unless @local_macros.include?($1)
          first = $2.split(',').first.to_s.strip
          next unless first.match?(/\A[A-Z][A-Z0-9_]*\z/)
          next if @entries.key?(first) || first.match?(/\A(?:RUBY_|RB_|RSTRING|RARRAY|RHASH|RTYPEDDATA|RBASIC|RDATA|Q[a-z]|T_|ID2|SYM2|FIX|INT2|NUM2|LONG2|CLASS_OF)/)
          out << first
        end
      end
      out
    end
  end

  # for a Q constant at s followed by == or != and a call NAME(...): [operator position, call end, negated?]; nil otherwise
  def q_left_call(masked, e)
    op_p = next_nonspace(masked, e)
    return nil if op_p < 0
    op = masked[op_p..op_p + 1]
    return nil unless op == '==' || op == '!='
    rs = next_nonspace(masked, op_p + 2)
    m = masked[rs..].match(/\A[A-Za-z_]\w*[ \t\n]*\(/)
    return nil unless m
    open_p = rs + m[0].length - 1
    cl = match_close(masked, open_p)
    return nil if cl < 0
    [op_p, cl + 1, op == '!=']
  end

  # a class variable's name that a local of the enclosing function shadows, at position pos
  def shadowed_local?(rel, name, pos)
    fn = enclosing_func(rel, pos)
    fn && local_shadows_class_var?(name, fn)
  end

  def local_shadows_class_var?(name, fn)
    return true if param_names(fn).include?(name)
    masked = @files[fn['file']]['masked']
    start = fn['brace']
    stop = fn['body_end'] + 1
    re = /(?<![#{WC}])(?!return(?![#{WC}])|else(?![#{WC}])|case(?![#{WC}])|goto(?![#{WC}]))[A-Za-z_][#{WC}]*[ \t\n\*]+(#{Regexp.escape(name)})#{SS}[=;,\[)]/
    masked[start...stop].to_s.to_enum(:scan, re).map { Regexp.last_match }.any? do |m|
      !owns_class_var?(fn['file'], start + m.begin(1), name)
    end
  end

  def shadowed_in?(name, fn)
    return true if param_names(fn).include?(name)
    n = Regexp.escape(name)
    body = psl(@files[fn['file']]['masked'], fn['brace'], fn['body_end'] + 1)
    !(body =~ /(?<![#{WC}])(?!return(?![#{WC}])|else(?![#{WC}])|case(?![#{WC}])|goto(?![#{WC}]))[A-Za-z_][#{WC}]*[ \t\n\*]+#{n}#{SS}[=;,\[)]|\(#{SS}\*#{SS}#{n}#{SS}\)/).nil?
  end

  def split_problem(name, uses)
    return 'it has more than one definition' if @defs[name].size != 1
    return "the names #{name}_impl and #{name}_nfcx_impl are already used in the input" if @occ.key?("#{name}_impl") && @occ.key?("#{name}_nfcx_impl")
    d0 = @defs[name][0]
    _hdr, _pro, err = registered_header(d0)
    return "its arguments are not known to the converter: #{err}" if err
    return 'a parameter is named mrb, which the wrapper uses' if param_names(d0).include?('mrb')
    if split_arity(name) == -1
      masked = @files[d0['file']]['masked']
      if psl(masked, d0['brace'], d0['body_end'] + 1) =~ /(?<![#{WC}])rb_scan_args(?![#{WC}])/
        # the impl reads its arguments from the argv array: lead, optional, keyword and block parts (no rest)
        fmts = []
        psl(@files[d0['file']]['text'], d0['brace'], d0['body_end'] + 1)
          .scan(/rb_scan_args[ \t\n]*\([ \t\n]*\w+[ \t\n]*,[ \t\n]*\w+[ \t\n]*,[ \t\n]*("[^"]*")/) { fmts << $1 }
        unless !fmts.empty? && fmts.all? { |f| f.match?(/\A"[0-9][0-9]?:?&?"\z/) }
          return 'its body calls rb_scan_args with a rest, keyword or block part, which would read the arguments from the mruby call frame'
        end
      end
    end
    uses.each do |rel, s, e|
      next if in_dead_init(rel, s)
      masked = @files[rel]['masked']
      # a member access (x.name, p->name) or a struct or union field declaration named like the function is not a use of it
      next if is_member(masked, s)
      ob = enclosing_open_brace(masked, s)
      next if ob && masked[[ob - 60, 0].max...ob].to_s.match?(/\b(?:struct|union)[ \t\n]*[A-Za-z_]?\w*[ \t\n]*\z/)
      if @files[rel]['kind'] != 'src' && !single_src_header?(rel)
        return "it is used in #{rel}, a header, whose function bodies are not converted (it is not included by exactly one source)"
      end
      nx = next_nonspace(masked, e)
      return 'its address is taken, so a pointer would reach the wrapper' unless nx >= 0 && masked[nx] == '('
      fn = enclosing_func(rel, s)
      return 'its name is shadowed in a function that calls it' if fn && shadowed_in?(name, fn)
    end
    nil
  end

  def split_arity(name)
    @regs.find { |r| r['error'].nil? && r['func'] == name }['argc']
  end

  def split_fixed_names(d0)
    d0['params'].split(',', -1).map { |p| py_strip(p)[/\AVALUE#{SS1}([A-Za-z_][#{WC}]*)\z/, 1] }
  end

  # the name of a split method's impl: <name>_impl, or <name>_nfcx_impl when the input already has <name>_impl (msgpack's
  # Unpacker_each has its own Unpacker_each_impl helper)
  def split_impl_name(name)
    @occ.key?("#{name}_impl") ? "#{name}_nfcx_impl" : "#{name}_impl"
  end

  # the impl: the original C parameters (mapped), with mrb first when check_refs threaded it
  def split_impl_hdr(d0)
    mrb_arg = @helper_names.include?(d0['name']) ? 'mrb_state *mrb, ' : ''
    params = map_types(py_strip(d0['params']), @types)
    "#{d0['storage']}#{map_types(d0['ret'], @types)} #{split_impl_name(d0['name'])}(#{mrb_arg}#{params})"
  end

  def split_self(d0)
    split_arity(d0['name']) == -1 ? variadic_params(d0)[2] : split_fixed_names(d0)[0]
  end

  def split_wrapper_hdr(d0)
    "#{d0['storage']}mrb_value #{d0['name']}(mrb_state *mrb, mrb_value #{split_self(d0)})"
  end

  # the wrapper: the mruby signature, the arguments read as registered_header reads them, then the impl call
  def split_wrapper_def(d0)
    name = d0['name']
    argc = split_arity(name)
    lines = ['(void)mrb;']
    if argc == -1
      _ac, av, sv = variadic_params(d0)
      lines << "mrb_int nfcx_argc;" << "mrb_value *#{av};" << "mrb_get_args(mrb, \"*\", &#{av}, &nfcx_argc);"
      args = ['(int)nfcx_argc', av, sv]
    else
      names = split_fixed_names(d0)
      locals = names[1..]
      if argc > 0
        lines << "mrb_value #{locals.join(', ')};"
        lines << "mrb_get_args(mrb, \"#{'o' * argc}\", #{locals.map { |x| '&' + x }.join(', ')});"
      end
      args = [names[0]] + locals
    end
    args.unshift('mrb') if @helper_names.include?(name)
    call = "#{split_impl_name(name)}(#{args.join(', ')})"
    if @global_wrap
      # as a registered method: the global state is set on entry and restored on return (wrap_returns)
      g = @global_name
      lines.unshift("mrb_state *nfcx_bc2_old = #{g};", "if (nfcx_bc2_old != NULL && nfcx_bc2_old != mrb) abort(); /* nested mruby state */", "#{g} = mrb;")
      lines += ["mrb_value nfcx_bc2_ret = #{call};", "#{g} = nfcx_bc2_old;", 'return nfcx_bc2_ret;']
    else
      lines << "return #{call};"
    end
    "#{split_wrapper_hdr(d0)} {\n" + lines.map { |l| "  #{l}" }.join("\n") + "\n}"
  end

  # The declarations of a split method: a prototype gets the impl and wrapper prototypes (the original ';' ends the
  # last one); the definition becomes the impl, and the wrapper follows its body.
  def split_decl(rel, d)
    ed = @edits[rel]
    d0 = @defs[d['name']][0]
    if d['proto']
      ed.add(d['hstart'], d['hend'], "#{split_impl_hdr(d0)};\n#{split_wrapper_hdr(d0)}")
      return
    end
    ed.add(d['hstart'], d['hend'], split_impl_hdr(d0) + ' ')
    ed.add(d['body_end'] + 1, d['body_end'] + 1, "\n\n#{split_wrapper_def(d0)}\n")
    rewrite(rel, d['hstart'], "#{d['name']}(...)", split_impl_hdr(d0),
            'registered method also called directly: the body is the impl, and the registration uses the wrapper after it')
    return if d0['storage'].split.include?('static')
    rewrite(rel, d['hstart'], d['name'], "wrapper #{d['name']}",
            'non-static registered method: the name now names the mruby wrapper, so a caller outside the input would need the impl')
  end

# A rb_data_type_t declaration: its initializer's open and close braces, the five top-level element spans, the nested
# {mark, free, size} spans, and the callback names. Returns a hash with 'error' when the shape is not CRuby's.
def dtype_parse(rel, m)
  # the masked text with its preprocessor lines blanked (same positions): an #ifdef inside the initializer is not an element
  mk = @files[rel]['masked'].gsub(/^[ \t]*#[^\n]*/) { |x| ' ' * x.length }
  tx = @files[rel]['text']
  open = m.end(0) - 1
  close = match_close(mk, open)
  els = split_args(mk, open, close).map { |a, b| [a, b, psl(tx, a, b)] }.reject { |_a, _b, t| t.strip.empty? }
    if !els.empty? && els.all? { |e| e[2].start_with?('.') }
      return dtype_designated(rel, m, open, close, els)
    end
  # flags may be left out (CRuby's initializer ends after data): 4 or 5 top-level members
  return { 'error' => 'the initializer is not CRuby\'s {name, {mark, free, size}, parent, data, flags}' } unless (els.size == 4 || els.size == 5) && els[1][2].start_with?('{') && els[1][2].end_with?('}')
  nested = split_args(mk, els[1][0], els[1][1] - 1).map { |a, b| [a, b, psl(tx, a, b)] }.reject { |_a, _b, t| t.strip.empty? }
  # a null function pointer with a cast, (RUBY_DATA_FUNC) NULL, is NULL (pg's data types write their mark this way)
  nested.each { |e| e[2] = e[2].sub(/\A\(\s*[A-Za-z_][\w\s*]*\)\s*(NULL|0)\z/, '\\1') }
  ok_fn = ->(t) { t.match?(/\A[A-Za-z_][#{WC}]*\z/) || t == 'NULL' || t == '0' }
  # RUBY_TYPED_DEFAULT_FREE frees with CRuby's allocator: mruby's dfree takes (mrb, data), and mrb_free has that shape
  nested_free = nested[1] && %w[RUBY_TYPED_DEFAULT_FREE RUBY_DEFAULT_FREE].include?(nested[1][2]) ? 'mrb_free' : (nested[1] && nested[1][2])
  # the members after free (dsize, and dcompact when the input has one) are dropped: mruby does not move objects, so
  # compaction is never needed; dsize is the memory report, which mruby does not use
  unless (nested.size >= 2 && nested.size <= 5) && ok_fn.call(nested[0][2]) && ok_fn.call(nested_free || 'NULL') && %w[0 NULL].include?(els[2][2]) && %w[0 NULL].include?(els[3][2])
    return { 'error' => 'the mark or free function, the parent or the data slot is not a plain name or 0/NULL' }
  end
  return { 'error' => 'the name is not a string literal' } unless els[0][2].start_with?('"')
  { 'error' => nil, 'open' => open, 'close' => close, 'name' => els[0][2], 'mark' => nested[0][2], 'free' => nested_free,
    'mark_pos' => nested[0][0], 'free_pos' => nested[1][0] }
end

  # A macro call that is a compaction member of a data type's .function, such as ffi's ffi_compact_callback(f): every #define
  # of the macro in the input is empty or a .dcompact designator (mruby never compacts). Such a call is dropped.
  def compaction_macro_call?(t)
    nm = t[/\A([A-Za-z_]\w*)\s*\(/, 1]
    return false unless nm
    bodies = []
    @files.each_value do |f|
      f['text'].scan(/^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(nm)}\([^)\n]*\)[ \t]*(.*)$/) { bodies << $1.strip }
    end
    !bodies.empty? && bodies.all? { |body| body.empty? || body.start_with?('.dcompact') }
  end

  # A designated initializer: .wrap_struct_name, .function = {.dmark, .dfree, .dsize}, .parent, .data, .flags (fields in
  # any order; a field may be left out). The same result as the positional form.
  def dtype_designated(rel, m, open, close, els)
    mk = @files[rel]['masked']
    tx = @files[rel]['text']
    fields = {}
    els.each do |a, b, t|
      mm = t.match(/\A\.\s*([A-Za-z_]\w*)\s*=\s*(.*)\z/m)
      return { 'error' => 'an initializer element is not a designated field' } unless mm
      return { 'error' => "the designated field .#{mm[1]} is repeated" } if fields.key?(mm[1])
      fields[mm[1]] = [a, b, mm[2].strip, a + t.index('=') + 1]
    end
    return { 'error' => 'the name is not a string literal' } unless fields['wrap_struct_name'] && fields['wrap_struct_name'][2].start_with?('"')
    fn = fields['function']
    return { 'error' => 'no .function field' } unless fn
    return { 'error' => '.function is not a braced group' } unless fn[2].start_with?('{') && fn[2].end_with?('}')
    brace = fn[0] + tx[fn[0]...fn[1]].index('{')
    # the elements of .function: a preprocessor line before an element (#ifdef HAVE_RB_GC_LOCATION) is not part of it, and an
    # element in inactive text (its branch is not in this build) is not an element (mruby's data type has no compaction hook)
    inactive = (@excluded_spans || {})[rel] || []
    sub = split_args(mk, brace, fn[1] - 1).map { |a, b| [a, b, psl(tx, a, b)] }
    sub = sub.reject { |a, _b, _t| inactive.any? { |x, z| x < a && a < z } }
    sub = sub.map { |a, b, t| [a, b, t.gsub(/^[ \t]*#[^\n]*\n?/, '').strip] }.reject { |_a, _b, t| t.empty? }
    sf = {}
    sub.each do |a, b, t|
      mm = t.match(/\A\.\s*([A-Za-z_]\w*)\s*=\s*(.*)\z/m)
      # a compaction member written as a macro call (ffi's ffi_compact_callback(f)) is dropped, as the positional form drops dcompact
      next if mm.nil? && compaction_macro_call?(t)
      return { 'error' => '.function holds a non-designated element' } unless mm
      # the position of the value's first character (after the '=' and its spaces): the identifier's own position
      eq = t.index('=')
      lead = t[(eq + 1)..][/\A\s*/].length
      sf[mm[1]] = [a, b, mm[2].strip, a + eq + 1 + lead]
    end
    ok_fn = ->(t) { t.match?(/\A[A-Za-z_][#{WC}]*\z/) || t == 'NULL' || t == '0' }
    mark = sf['dmark'] ? sf['dmark'][2] : 'NULL'
    free = sf['dfree'] ? sf['dfree'][2] : 'NULL'
    free = 'mrb_free' if %w[RUBY_TYPED_DEFAULT_FREE RUBY_DEFAULT_FREE].include?(free)
    unless ok_fn.call(mark) && ok_fn.call(free)
      return { 'error' => 'the mark or free function is not a plain name or 0/NULL (a macro such as RUBY_TYPED_DEFAULT_FREE is not mapped)' }
    end
    parent = fields['parent'] ? fields['parent'][2] : '0'
    data = fields['data'] ? fields['data'][2] : '0'
    return { 'error' => 'the parent or the data slot is not 0/NULL' } unless %w[0 NULL].include?(parent) && %w[0 NULL].include?(data)
    { 'error' => nil, 'open' => open, 'close' => close, 'name' => fields['wrap_struct_name'][2], 'mark' => mark, 'free' => free,
      'mark_pos' => sf['dmark'] ? sf['dmark'][3] : nil, 'free_pos' => sf['dfree'] ? sf['dfree'][3] : nil }
  end

# the data type declarations of the input, and the callback positions (the mark and free names) they use
def dtype_decls
  out = []
  @files.each do |rel, f|
    finditer(/\brb_data_type_t[ \t\n]+[A-Za-z_][#{WC}]*[ \t\n]*=[ \t\n]*\{/, f['masked']).each do |m|
      out << [rel, m, dtype_parse(rel, m)]
    end
  end
  out
end

  # rb_hash_foreach(h, cb, (VALUE)ptr): the callback is a synchronous callback of mrb_hash_foreach, so it is threaded with
  # mrb, and its third (VALUE) parameter becomes void * (the pointer it is given). Only a call whose callback is defined in
  # the input and used only here, and whose argument is an address or a (VALUE) cast of a plain name, is converted.
# An argument of a template that is a plain expression: identifiers (which are not renamed by the converter), member
# access, indexing, &, ?:, parentheses and integer literals. A call or any name the converter would rewrite (an API
# name, a macro, a class variable, mrb) makes it not plain, so it is refused.
def plain_expr?(t, rel)
  return false unless t.match?(/\A[\w\s&*.\->\[\]?:()]+\z/)
  return false if t.match?(/\w\s*\(/) # a call
  t.scan(/[A-Za-z_]\w*/).all? do |w|
    next false if w == 'mrb' || @class_vars.include?(w) || @entries.key?(w) || @types.key?(w) || UNKNOWN_RE.match?(w)
    true
  end
end

# NORETURN(decl); is CRuby's no-return prototype wrapper. mruby has no NORETURN, so the wrapper's two tokens are removed
# from the output, and the masked text (used to scan declarations) has them blanked, so the declaration is a plain prototype.
# the opening NORETURN( token lies in a prototype that is rewritten as a whole (a helper or a registered method)
def noreturn_in_rewritten_decl?(rel, start)
  @decls.any? do |d|
    d['file'] == rel && d['hstart'] <= start && start < d['hend'] &&
      ((@helper_names || Set.new).include?(d['name']) || (@valid_reg_names || Set.new).include?(d['name']))
  end
end

def noreturn_mask(rel)
  f = @files[rel]
  f['noreturn'] = []
  # MAYBE_UNUSED(decl) is the same kind of wrapper: CRuby's identity macro (an unused-variable attribute) around a declaration
  f['text'].to_enum(:scan, /^[ \t]*(?:NORETURN|MAYBE_UNUSED)\(/).each do
    m = Regexp.last_match
    open = m.end(0) - 1
    close = match_close(f['masked'], open)
    next if close < 0
    start = m.begin(0) + m[0][/\A[ \t]*/].length
    f['noreturn'] << [start, open, close]
    (start...open + 1).each { |k| f['masked'][k] = ' ' }
    f['masked'][close] = ' '
  end
end

  def pp_conditional_at?(masked, pos)
    ls = (masked.rindex("\n", pos - 1) || -1) + 1 if pos > 0
    ls ||= 0
    le = masked.index("\n", pos) || masked.length
    line = masked[ls...le]
    line.match?(/\A[ \t]*#[ \t]*(?:if|ifdef|ifndef|elif)\b/) || line.match?(/\bdefined\b/)
  end

  # rb_ensure(body, data1, ensure, data2): both callbacks are static functions of this file, each used only by this call
  # and each VALUE f(VALUE); they are threaded (mrb, mrb_value) for mrb_ensure. The data arguments are VALUE names or Q constants.
  # The functions a per-class allocator (rb_define_alloc_func) reaches, directly or through calls and macro bodies:
  # an allocator is called by the VM with no mruby state argument, so a helper it reaches cannot take the state.
  def alloc_reach
    @alloc_reach ||= begin
      seeds = Set.new
      # no seeds: an allocator is a registered function of the state (rb_define_alloc_func is a template with a prelude)
      # every #define body in the gem, by macro name (a macro may be defined in several conditional branches)
      macro_bodies = Hash.new { |h, k| h[k] = [] }
      @files.each do |rel, f|
        define_spans(rel).each do |mname, a, b|
          macro_bodies[mname] << psl(f['masked'], a, b)
        end
      end
      reach = Set.new(seeds)
      todo = seeds.to_a
      until todo.empty?
        f = todo.shift
        bodies = []
        (@defs[f] || []).each do |d|
          next unless d['brace'] && d['body_end']
          bodies << @files[d['file']]['masked'][d['brace']..d['body_end']].to_s
        end
        bodies.concat(macro_bodies[f]) if macro_bodies.key?(f)
        bodies.each do |b|
          b.scan(IDENT_RE).each do |i|
            next if reach.include?(i) || !(@defs.key?(i) || macro_bodies.key?(i))
            reach << i
            todo << i
          end
        end
      end
      reach
    end
  end

  # rb_rescue(body, data1, rescue, data2) with static callbacks defined here and used only here. The body takes (VALUE) and
  # the rescue callback (VALUE data, VALUE exc): mruby's rescue takes (mrb, data) and reads the exception from mrb->exc, so
  # a wrapper after the rescue callback passes mrb->exc as its exc argument.
  def rescue_calls
    cands = []
    raw_refs = Hash.new(0)
    ident = /\A[A-Za-z_][#{WC}]*\z/
    @files.each do |rel, f|
      masked = f['masked']
      text = f['text']
      finditer(/(?<![#{WC}$.>])(rb_rescue2?)#{SS}\(/, masked).each do |m|
        fname = m[1]
        s0 = m.begin(0)
        open = m.end(0) - 1
        close = match_close(masked, open)
        next if close < 0
        spans = split_args(masked, open, close)
        args = spans.map { |a, b| psl(text, a, b).strip }
        # rb_rescue2(body, data1, rescue, data2, class..., 0): the classes are mapped to RClass * in a compound array
        if fname == 'rb_rescue2'
          next unless args.size >= 6 && args.last.match?(/\A(?:\(VALUE\)\s*)?0\z|\ANULL\z/)
          cls = args[4...-1]
          next unless cls.all? { |x| x.match?(/\Arb_e[A-Za-z]\w*\z/) && (@entries[x] || {})['kind'] == 'expr' }
          cls_text = cls.map { |x| @entries[x]['mruby'] }
        else
          next unless args.size == 4
          cls_text = []
        end
        b_cb, d1, r_cb, d2 = args
        next unless b_cb.match?(ident) && r_cb.match?(ident)
        data_ok = ->(d) { d.match?(ident) && (!@entries.key?(d) || d.match?(/\AQ(?:nil|undef|true|false)\z/)) }
        # a pointer passed as data: (VALUE)name, whose callback uses the parameter only in pointer casts
        # (VALUE)name, or the converter's nfcx_ptr_value(name): a pointer carried in a VALUE
        ptr_data = ->(d) { d.match?(/\A\(VALUE\)\s*[A-Za-z_][#{WC}]*\z/) || d.match?(/\Anfcx_ptr_value\(\s*&?[A-Za-z_][#{WC}]*\s*\)\z/) }
        next unless [d1, d2].all? { |d| data_ok.call(d) || ptr_data.call(d) }
        raw_refs[[rel, b_cb]] += 1
        raw_refs[[rel, r_cb]] += 1
        cands << { rel: rel, s: s0, e: close + 1, b: b_cb, d1: d1, r: r_cb, d2: d2, cls: cls_text,
                   bpos: spans[0][0], rpos: spans[2][0] }
      end
    end
    out = []
    cands.each do |c|
      rel = c[:rel]
      text = @files[rel]['text']
      masked = @files[rel]['masked']
      ok = [[c[:b], /\A\(?\s*VALUE\s+[A-Za-z_]\w*\s*\)?\z/], [c[:r], /\A\(?\s*VALUE\s+[A-Za-z_]\w*\s*,\s*VALUE\s+[A-Za-z_]\w*\s*\)?\z/]].all? do |cb, pat|
        d = (@defs[cb] || []).select { |x| x['file'] == rel }
        d.size == 1 && d[0]['storage'].split.include?('static') && d[0]['ret'].to_s.strip == 'VALUE' &&
          psl(text, d[0]['po'], d[0]['pc']).match?(pat) &&
          ((@occ[cb] || []).count { |r0, _, _| r0 == rel } -
           @decls.count { |x| x['name'] == cb && x['file'] == rel && x['proto'] }) >= 1 + raw_refs[[rel, cb]]
      end
      next unless ok
      rdef = (@defs[c[:r]] || []).find { |x| x['file'] == rel }
      bdef = (@defs[c[:b]] || []).find { |x| x['file'] == rel }
      casts = []
      cast_ok = [[c[:d1], bdef], [c[:d2], rdef]].all? do |dd, dfn|
        next true unless dd.match?(/\A\(VALUE\)/)
        pos = ptr_cast_uses(rel, dfn, text, masked, 0)
        casts.concat(pos) unless pos.nil?
        !pos.nil?
      end
      next unless cast_ok
      out << c.merge(rend: rdef['body_end'] + 1, cast_pos: casts.uniq)
    end
    out
  end

  def ensure_calls
    cands = []
    raw_refs = Hash.new(0)   # every rb_ensure call's callbacks, candidate or not: a callback is referenced by all of them
    @files.each do |rel, f|
      masked = f['masked']
      text = f['text']
      finditer(/(?<![#{WC}$.>])rb_ensure#{SS}\(/, masked).each do |m|
        s = m.begin(0)
        open = m.end(0) - 1
        close = match_close(masked, open)
        next if close < 0
        args_pos = split_args(masked, open, close).map { |a, _b| a }
        args = split_args(masked, open, close).map { |a, b| psl(text, a, b).strip }
        next unless args.size == 4
        b_cb, d1, e_cb, d2 = args
        next unless b_cb.match?(/\A[A-Za-z_][#{WC}]*\z/) && e_cb.match?(/\A[A-Za-z_][#{WC}]*\z/)
        raw_refs[[rel, b_cb]] += 1
        raw_refs[[rel, e_cb]] += 1
        # a data argument is a VALUE name or Q constant, or a pointer to a local: (VALUE)&x (carried as mrb_cptr_value;
        # the callbacks must use it only in pointer casts, checked below)
        data_ok = ->(d) { d.match?(/\A[A-Za-z_][#{WC}]*\z/) && (!@entries.key?(d) || d.match?(/\AQ(?:nil|undef|true|false)\z/)) }
        # (VALUE)p where p is a pointer declared in this file (oj's (VALUE)out): the pointer is carried in the VALUE
        ptr_name = ->(d) { (pm = /\A\(VALUE\)\s*([A-Za-z_]\w*)\z/.match(d)) && masked.match?(/\*\s*#{Regexp.escape(pm[1])}\b/) }
        ptr_data = ->(d) { d.match?(/\A\(VALUE\)\s*&[A-Za-z_][#{WC}]*\z/) || ptr_name.call(d) }
        next unless [d1, d2].all? { |d| data_ok.call(d) || ptr_data.call(d) }
        cands << { rel: rel, s: s, e: close + 1, b: b_cb, d1: d1, ecb: e_cb, d2: d2,
                   bpos: args_pos[0], epos: args_pos[2] }
      end
    end
    # a callback is used only by rb_ensure calls: its definition plus one reference per call (a callback may serve two calls)
    refs = raw_refs
    out = []
    cands.each do |c|
      rel = c[:rel]
      f = @files[rel]
      text = f['text']
      masked = f['masked']
      cb_ok = [c[:b], c[:ecb]].all? do |cb|
        d = (@defs[cb] || []).select { |x| x['file'] == rel }
        d.size == 1 && d[0]['storage'].split.include?('static') && d[0]['ret'].to_s.strip == 'VALUE' &&
          psl(text, d[0]['po'], d[0]['pc']).match?(/\A\(?\s*VALUE\s+[A-Za-z_][#{WC}]*\s*\)?\z/) &&
          (@occ[cb] || []).count { |r, _, _| r == rel } == 1 + refs[[rel, cb]]
      end
      next unless cb_ok
      cast_pos = []
      ptr_ok = [[c[:b], c[:d1]], [c[:ecb], c[:d2]]].all? do |cb, dd|
        next true unless /\A\(VALUE\)\s*&/.match?(dd)
        d = (@defs[cb] || []).find { |x| x['file'] == rel }
        pos = ptr_cast_uses(rel, d, text, masked)
        cast_pos.concat(pos) unless pos.nil?
        !pos.nil?
      end
      next unless ptr_ok
      out << c.merge(cast_pos: cast_pos.uniq)
    end
    out
  end

  # a typedef of a pointer type in the gem: typedef ... *NAME;
  def pointer_typedef?(name)
    @pointer_typedefs ||= begin
      set = Set.new
      @files.each_value do |f|
        masked = f['masked']
        masked.to_enum(:scan, /\btypedef\b/).map { Regexp.last_match.end(0) }.each do |pos|
          # the declarator follows the type: past a braced body (typedef struct X {...} *P;) if there is one
          # the first '{' or ';' after the keyword: a braced body (struct tag {...}) comes before the declarator
          jb = masked.index(/[{;]/, pos)
          if jb && masked[jb] == '{'
            close = match_close(masked, jb)
            next if close < 0
            tail = masked[(close + 1)..(close + 80)].to_s
          else
            tail = masked[pos...(pos + 200)].to_s
          end
          m = /\A[^;{}]*?\*[ \t\n]*([A-Za-z_]\w*)[ \t\n]*;/.match(tail)
          set << m[1] if m
        end
      end
      set
    end
    @pointer_typedefs.include?(name)
  end

  def ptr_cast_uses(rel, d, text, masked, idx = nil)
    return nil if d.nil? || !d.key?('brace')
    pars = split_args(masked, d['po'], d['pc']).map { |a2, b2| psl(text, a2, b2).strip }
    return nil unless idx.nil? ? pars.size == 1 : (idx < pars.size)
    pname = pars[idx || 0][/([A-Za-z_]\w*)\z/, 1]
    return nil if pname.nil?
    body = masked[d['brace']...d['body_end']].to_s
    uses = []
    body.to_enum(:scan, /(?<![#{WC}$.>])#{Regexp.escape(pname)}(?![#{WC}])/).map { Regexp.last_match }.each do |m|
      pre = body[0...m.begin(0)]
      # a cast to a pointer type: (T *), or (P) where P is a typedef of a pointer type in this gem
      ptr_cast = pre.match?(/\(\s*(?:const\s+|volatile\s+)*(?:void|struct\s+[A-Za-z_]\w*|[A-Za-z_]\w*)\s*\*+\s*\)\s*\z/) ||
                 ((tn = pre[/\(\s*([A-Za-z_]\w*)\s*\)\s*\z/, 1]) && pointer_typedef?(tn))
      # UNUSED(name) discards the parameter (msgpack's sysdep.h: ((void)var)): not a use of the pointer
      next if pre.match?(/\bUNUSED\(\s*\z/)
      return nil unless ptr_cast
      uses << (d['brace'] + m.begin(0))
    end
    uses.map { |u| [rel, u, u + pname.size] }
  end

  # onig_foreach_name(reg, cb, arg): the callback cb (a static function of this file, with no other use but the call) is threaded
  # with the mruby state as its first argument; the call passes it through a trampoline (see onig_foreach_special)
  def onig_foreach_calls
    out = []
    @files.each do |rel, f|
      masked = f['masked']
      text = f['text']
      finditer(/(?<![#{WC}$.>])onig_foreach_name#{SS}\(/, masked).each do |m|
        s0 = m.begin(0)
        open = m.end(0) - 1
        close = match_close(masked, open)
        next if close < 0
        args = split_args(masked, open, close)
        next unless args.size == 3
        cb_a, cb_b = args[1]
        cb = psl(text, cb_a, cb_b).strip
        next unless cb.match?(/\A[A-Za-z_][#{WC}]*\z/)
        d = (@defs[cb] || []).select { |x| x['file'] == rel }
        next unless d.size == 1 && d[0]['storage'].to_s.split.include?('static') && d[0]['po']
        out << { rel: rel, cb: cb, cb_pos: cb_a + text[cb_a...cb_b].to_s.index(cb).to_i, call: s0, open: open, close: close, def: d[0] }
      end
    end
    out
  end

  def hash_foreach_calls
    out = []
    @files.each do |rel, f|
      masked = f['masked']
      text = f['text']
      finditer(/(?<![#{WC}$.>])(?:rb_hash_foreach|rb_ivar_foreach)#{SS}\(/, masked).each do |m|
        fe_name = m[0].sub(/#{SS}\(\z/, '')
        s = m.begin(0)
        open = m.end(0) - 1
        close = match_close(masked, open)
        next if close < 0
        args = split_args(masked, open, close).map { |a, b| [a, b, psl(text, a, b)] }
        next unless args.size == 3
        h = args[0][2]
        cb = args[1][2]
        arg = args[2][2]
        next unless h.match?(/\A[A-Za-z_][#{WC}]*(?:(?:->|\.)[A-Za-z_][#{WC}]*)*\z/) && cb.match?(/\A&?[A-Za-z_][#{WC}]*\z/)
        raw_cb = cb
        cb = cb.delete('&')
        # the callback's position is its identifier's (after a & address-of), where its occurrence is recorded
        cb_ident_pos = args[1][0] + raw_cb.index(cb)
        next unless arg.match?(/\A(?:\(VALUE\)\s*)?&?[A-Za-z_][#{WC}]*\z/)
        # a static callback defined in this file, with no other use in the file (its definition and this call)
        d = (@defs[cb] || []).select { |x| x['file'] == rel }
        next unless d.size == 1 && d[0]['storage'].split.include?('static')
        # a VALUE data argument (a VALUE name, not a pointer cast): the data is passed by address, and the callback may also be
        # called directly (each such call passes its VALUE data by address too)
        fn_h = enclosing_func(rel, s)
        value_data = !arg.start_with?('(VALUE)') && !arg.start_with?('&') && fn_h &&
                     (value_names_of(fn_h).include?(arg) || file_scope_value_names(rel).include?(arg))
        cb_occ = (@occ[cb] || []).select { |r, _, _| r == rel }
        if value_data
          direct = cb_occ.reject { |_r, p, _e| p == cb_ident_pos || p == d[0]['hstart'] || p == d[0]['hstart'] + (text[d[0]['hstart']..].index(cb) || 0) }
          direct = direct.reject do |_r, p, _e|
            nx = next_nonspace(masked, p + cb.length)
            nx >= 0 && masked[nx] == '(' && (dc = match_close(masked, nx)) > 0 && next_nonspace(masked, dc + 1) >= 0 && masked[next_nonspace(masked, dc + 1)] == '{'
          end
          # every other use is a plain call of the callback (not an address taken or stored), or the callback of another
          # rb_hash_foreach / rb_ivar_foreach call (that call is a record of its own)
          direct = direct.reject { |_r, p, _e| masked[[p - 80, 0].max...p].to_s.match?(/(?:rb_hash_foreach|rb_ivar_foreach)#{SS}\([^,()]*,#{SS}\z/) }
          next unless direct.all? do |_r, p, _e|
            nx = next_nonspace(masked, p + cb.length)
            nx >= 0 && masked[nx] == '(' && (dc = match_close(masked, nx)) > 0 && split_args(masked, nx, dc).size == 3
          end
        else
          calls_here = cb_occ.count { |_r, p, _e| masked[[p - 80, 0].max...p].to_s.match?(/(?:rb_hash_foreach|rb_ivar_foreach)#{SS}\([^,()]*,#{SS}&?#{SS}\z/) }
          next unless calls_here >= 1 && cb_occ.count == 1 + calls_here
        end
        pars = split_args(masked, d[0]['po'], d[0]['pc']).map { |a2, b2| [a2, b2, psl(text, a2, b2)] }
        out << { rel: rel, s: s, e: close + 1, h: h, cb: cb, fe: fe_name,
                 arg: arg.sub(/\Anfcx_ptr_value\(\s*(&?[A-Za-z_][#{WC}]*)\s*\)\z/) { "mrb_cptr_value(mrb, #{$1})" }.sub(/\A\(VALUE\)\s*(?:\(void\s*\*\)\s*)?/, ''),
                 cb_pos: cb_ident_pos, cb_file: d[0]['file'], param_edit: [pars[2][0], pars[2][0] + 5],
                 value_data: value_data }
      end
    end
    out
  end

  # A struct field of function-pointer type, RET (*NAME)(PARAMS), in a struct body of this file. Returns the field's
  # declaration; its assignments and calls are found across the whole input by fnptr_global.
  # the '{' that opens the innermost struct body containing pos (struct TAG { or struct {), or nil
  def struct_body_open(masked, pos)
    depth = 0
    k = pos - 1
    while k >= 0
      c = masked[k]
      if c == '}'
        depth += 1
      elsif c == '{'
        if depth == 0
          return psl(masked, [k - 40, 0].max, k) =~ /struct\s*\w*\s*\z/ ? k : nil
        end
        depth -= 1
      end
      k -= 1
    end
    nil
  end

  def fnptr_decls(rel)
    masked = @files[rel]['masked']
    out = []
    masked.to_enum(:scan, /\(\s*\*\s*([A-Za-z_]\w*)\s*\)\s*\(/).each do
      m = Regexp.last_match
      open = m.end(0) - 1
      close = match_close(masked, open)
      next if close < 0
      next unless struct_body_before?(masked, m.begin(0))
      params = psl(masked, open + 1, close).strip
      next if params.empty? || params == 'void'
      # the member index and the struct tag, for a positional initializer (struct TAG var = { h1, h2, ... })
      bo = struct_body_open(masked, m.begin(0))
      tag = bo && psl(masked, [bo - 60, 0].max, bo)[/struct\s+(\w+)\s*\z/, 1]
      index = bo ? masked[(bo + 1)...m.begin(0)].to_s.count(';') : nil
      out << { rel: rel, name: m[1], params_start: open + 1, tag: tag, index: index }
    end
    # Fields whose type is a typedef of a function pointer, typedef RET (*T)(PARAMS): each field of type T in a struct body of
    # this file is a callback field, and its parameter list is the typedef's (retyped once for all of them: see edit_fnptr_fields)
    typedefs = {}
    masked.to_enum(:scan, /\btypedef[ \t\n]+[^;{}()]*?\(\s*\*\s*([A-Za-z_]\w*)\s*\)\s*\(/).each do
      tm = Regexp.last_match
      topen = tm.end(0) - 1
      tclose = match_close(masked, topen)
      next if tclose < 0
      next if struct_body_before?(masked, tm.begin(0))
      typedefs[tm[1]] = topen + 1 unless psl(masked, topen + 1, tclose).strip.empty? || psl(masked, topen + 1, tclose).strip == 'void'
    end
    typedefs.each do |tname, pstart|
      masked.to_enum(:scan, /(?<![#{WC}.>])#{Regexp.escape(tname)}[ \t\n]+([A-Za-z_]\w*)[ \t\n]*(?:\[[^\]\n]*\][ \t\n]*)?;/).each do
        fm = Regexp.last_match
        next unless struct_body_before?(masked, fm.begin(0))
        bo = struct_body_open(masked, fm.begin(0))
        tag = bo && psl(masked, [bo - 60, 0].max, bo)[/struct\s+(\w+)\s*\z/, 1]
        index = bo ? masked[(bo + 1)...fm.begin(0)].to_s.count(';') : nil
        out << { rel: rel, name: fm[1], params_start: pstart, tag: tag, index: index, typedef: tname }
      end
    end
    out
  end

  # The assignments (x.NAME = helper;) and calls (x.NAME(...)) of a field, across every file of the input.
  # Parameters of function-pointer type, RET (*NAME)(PARAMS), of a helper H defined here. H calls them with the mruby
  # state, so H takes mrb, and the callbacks passed for the parameter are threaded (like a struct function-pointer
  # field, fnptr_global). The assigns are the helper names passed as that argument at H's call sites; the calls are the
  # direct NAME( calls in H's body. A call site that does not pass a plain helper name makes the record invalid.
  # the index of parameter text t in the parameter list of the function-like macro name defined in rel, or nil
  def macro_param_index(name, rel, t)
    masked = @files[rel]['masked']
    m = /^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(name)}\(([^)]*)\)/.match(masked)
    return nil unless m
    m[1].split(',').map(&:strip).index(t)
  end

  # true when the name at [s, e) is the only argument of a call M(name) to a one-parameter function-like macro M
  # whose body uses its parameter as a member (M(x) (p->x) or p.x): the name is a field, not a use of a helper
  def member_macro_arg?(rel, s, e)
    masked = @files[rel]['masked']
    open = prev_nonspace(masked, s - 1)
    return false if open < 0 || masked[open] != '('
    callee = masked[[open - 60, 0].max...open].to_s[/([A-Za-z_]\w*)[ \t\n]*\z/, 1]
    return false unless callee
    close = next_nonspace(masked, e)
    return false if close < 0 || masked[close] != ')'
    d = /^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(callee)}\(([A-Za-z_]\w*)\)/.match(masked)
    return false unless d
    param = d[1]
    body_end = logical_line_end(masked, d.end(0))
    masked[d.end(0)...body_end].to_s.match?(/(?:\.|->)[ \t\n]*#{Regexp.escape(param)}\b/)
  end

  # for each invocation of macro name (outside any #define), its k-th argument when that is a plain helper name:
  # [helper, rel, position], or nil when some invocation's argument is not one
  # The name an object-like macro stands for when the macro's body is a single identifier (#define cb real_cb): real_cb.
  def object_macro_name(name)
    @files.each_value do |f|
      m = /^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(name)}[ \t]+([A-Za-z_][#{WC}]*)[ \t]*$/.match(f['masked'])
      return m[1] if m
    end
    nil
  end

  def macro_invocation_helpers(name, k)
    out = []
    (@occ[name] || []).each do |irel, is, ie|
      next if define_at(irel, is)
      mk = @files[irel]['masked']
      nx = next_nonspace(mk, ie)
      return nil if nx < 0 || mk[nx] != '('
      close = match_close(mk, nx)
      args = close > 0 ? split_args(mk, nx, close) : []
      a = args[k]
      return nil if a.nil?
      # an invocation in an inactive definition (its #if is false in this build) is dead code: it passes nothing
      next if ((@excluded_spans || {})[irel] || []).any? { |x, z| x < is && is < z }
      t = psl(@files[irel]['text'], a[0], a[1]).strip
      t = object_macro_name(t) || t
      return nil unless t.match?(/\A[A-Za-z_]\w*\z/) && @defs.key?(t)
      lead = psl(@files[irel]['text'], a[0], a[1])[/\A\s*/].length
      out << [t, irel, a[0] + lead]
    end
    out
  end

  # A name with one definition, or with definitions that are the alternatives of one conditional (#if A ... #else/#elif ...
  # #endif, in one file): only one of them is compiled, so each is converted the same way and the name is one helper.
  def single_or_exclusive?(name)
    defs = (@defs[name] || []).reject { |x| x['proto'] }
    return true if defs.size == 1
    return false if defs.empty?
    return false unless defs.map { |x| x['file'] }.uniq.size == 1
    sorted = defs.sort_by { |x| x['hstart'] }
    sorted.each_cons(2).all? do |a, b|
      between = @files[a['file']]['masked'][a['hend']...b['hstart']].to_s
      between.match?(/^[ \t]*#[ \t]*(?:else|elif)\b/) && !between.match?(/^[ \t]*#[ \t]*endif\b/)
    end
  end

  # The Data_Make_Struct calls of the input: [rel, start, mark name, free name, mark position, free position] (names nil
  # when they are not plain identifiers; 'NULL'/'0' for none).
  def data_make_calls_all
    out = []
    @files.each do |rel, f|
      next unless f['kind'] == 'src'
      masked = f['masked']
      text = f['text']
      masked.to_enum(:scan, /(?<![#{WC}$.>])Data_Make_Struct#{SS}\(/).each do
        m = Regexp.last_match
        open = m.end(0) - 1
        close = match_close(masked, open)
        next if close <= 0
        args = split_args(masked, open, close)
        next unless args.size == 5
        names = args.map { |a, b| psl(text, a, b).strip }
        mk_pos = args[2][0] + (psl(text, args[2][0], args[2][1])[/\A\s*/].length)
        fr_pos = args[3][0] + (psl(text, args[3][0], args[3][1])[/\A\s*/].length)
        mk = names[2].match?(/\A[A-Za-z_][#{WC}]*\z/) || names[2] == 'NULL' || names[2] == '0' ? names[2] : nil
        fr = names[3].match?(/\A[A-Za-z_][#{WC}]*\z/) || names[3] == 'NULL' || names[3] == '0' ? names[3] : nil
        out << [rel, m.begin(0), mk, fr, mk_pos, fr_pos]
      end
    end
    out
  end

  def fnptr_param_recs
    recs = []
    @defs.each do |hname, lst|
      bodies = lst.reject { |x| x['proto'] }
      next unless bodies.size == 1
      d = bodies[0]
      next unless d['po'] && d['pc'] && d['brace'] && d['body_end'] && d['file']
      rel = d['file']
      masked = @files[rel]['masked']
      psub = masked[(d['po'] + 1)...d['pc']].to_s
      # every function-pointer parameter of the definition has its own record (a callee may take two callbacks)
      psub.to_enum(:scan, /\(\s*\*\s*([A-Za-z_]\w*)\s*\)\s*\(/).map { Regexp.last_match }.each do |m|
      cname = m[1]
      pidx = psub[0...m.begin(0)].count(',')
      rec = { name: cname, owner: hname, rel: rel, params_start: d['po'] + 1 + m.end(0), assigns: [], calls: [], bad: false, pidx: pidx }
      body = masked[d['brace']..d['body_end']].to_s
      # a call is cname(...) or, through the parameter's own dereference, (*cname)(...)
      body.to_enum(:scan, /(?:\(\s*\*\s*#{cname}\s*\)|(?<![#{WC}.>])#{cname})\s*\(/).each do
        cm = Regexp.last_match
        rec[:calls] << [d['brace'] + cm.end(0) - 1, hname, rel]
      end
      (@occ[hname] || []).each do |crel, cs, ce|
        next if @decls.any? { |dd| dd['name'] == hname && dd['file'] == crel && dd['hstart'] <= cs && cs < dd['hend'] }
        next if crel == rel && cs >= d['hstart'] && cs < d['hend']
        mk = @files[crel]['masked']
        nx = next_nonspace(mk, ce)
        if nx < 0 || mk[nx] != '('
          rec[:bad] = true
          break
        end
        close = match_close(mk, nx)
        # a prototype (name(...);) is a declaration, not a call
        ns = next_nonspace(mk, close + 1)
        before = psl(mk, [ce - 0 - 80, 0].max, cs)[/(\w+)[ \t\n*]*\z/, 1]
        next if close > 0 && ns >= 0 && mk[ns] == ';' && before && before != 'return' && before != 'else'
        args = close > 0 ? split_args(mk, nx, close) : []
        a = args[pidx]
        if a.nil?
          rec[:bad] = true
          break
        end
        t = psl(@files[crel]['text'], a[0], a[1]).strip
        lead = psl(@files[crel]['text'], a[0], a[1])[/\A\s*/].length
        if t.match?(/\A[A-Za-z_]\w*\z/) && @defs.key?(t)
          rec[:assigns] << [t, crel, a[0] + lead]
        elsif (dm = define_at(crel, cs)) && (k = macro_param_index(dm[0], crel, t))
          # the call is in a macro body and passes the macro's k-th parameter: each invocation's k-th argument is the helper
          inv = macro_invocation_helpers(dm[0], k)
          if inv.nil?
            rec[:bad] = true
            break
          end
          inv.each { |h, irel, ipos| rec[:assigns] << [h, irel, ipos] }
        elsif (en = enclosing_func(crel, cs)) && (j = fn_param_names(en).index(t))
          # forwarded: the call passes the enclosing function's own callback parameter j (its record gives the callbacks)
          rec[:assigns] << [:fwd, en['name'], j]
        else
          rec[:bad] = true
          break
        end
      end
      # the callback is threaded (it takes mrb): only a parameter that calls the callback, and does not keep it, can take it
      rec[:bad] = true unless non_retaining?(hname, pidx)
      rec[:stores] = ((@store_fields || {})[[hname, pidx]] || []).uniq
      next if rec[:bad] || rec[:assigns].empty?
      recs << rec
      end
    end
    # resolve forwarded assigns through the records of the enclosing functions' parameters (bounded depth)
    by_key = {}
    recs.each { |r| by_key[[r[:owner], r[:pidx]]] = r }
    resolve = lambda do |r, depth|
      return nil if depth > 8
      out = []
      r[:assigns].each do |x|
        if x[0] == :fwd
          src = by_key[[x[1], x[2]]]
          sub = src && resolve.call(src, depth + 1)
          return nil if sub.nil?
          out.concat(sub)
        else
          out << x
        end
      end
      out
    end
    recs.each do |r|
      res = resolve.call(r, 0)
      if res.nil?
        r[:bad] = true
      else
        r[:assigns] = res
      end
    end
    recs.reject { |r| r[:bad] || r[:assigns].empty? }
  end

  # the parameter names of a function definition (a callback parameter's name is the one in (*NAME))
  def fn_param_names(en)
    en['params'].to_s.split(',').map do |p|
      p.strip[/\(\s*\*\s*(\w+)\s*\)/, 1] || p.strip[/([A-Za-z_]\w*)\s*\z/, 1]
    end
  end

  def fnptr_global(rec)
    rec[:assigns] = []
    rec[:calls] = []
    @files.each do |frel, f|
      masked = f['masked']
      # the field may also be stored as an address (x.NAME = &helper;)
      masked.to_enum(:scan, /(?:\.|->)\s*#{rec[:name]}\s*=\s*&?\s*([A-Za-z_]\w*)\s*;/).each do
        am = Regexp.last_match
        # a parameter of the enclosing function: the callback it receives (its parameter record gives the helpers)
        en = enclosing_func(frel, am.begin(1))
        j = en && fn_param_names(en).index(am[1])
        rec[:assigns] << (j ? [:fwd, en['name'], j] : [am[1], frel, am.begin(1)])
      end
      # a conditional assignment (obj->NAME = cond ? helper_a : helper_b;): both helpers are assigned
      masked.to_enum(:scan, /(?:\.|->)\s*#{rec[:name]}\s*=\s*[^;{}]*?\?\s*([A-Za-z_]\w*)\s*:\s*([A-Za-z_]\w*)\s*;/).each do
        cm = Regexp.last_match
        [1, 2].each { |g| rec[:assigns] << [cm[g], frel, cm.begin(g)] }
      end
      # a designated initializer of the field (.NAME = helper inside a braced initializer) is an assignment too
      masked.to_enum(:scan, /\.\s*#{rec[:name]}\s*=\s*([A-Za-z_]\w*)\s*(?=[,}])/).each do
        am = Regexp.last_match
        rec[:assigns] << [am[1], frel, am.begin(1)]
      end
      # a positional initializer of a struct of the tag: struct TAG var = { h1, h2, ... }: the member at index is the helper
      if rec[:tag] && rec[:index]
        masked.to_enum(:scan, /\bstruct\s+#{rec[:tag]}\s+\w+\s*(?:\[[^\]]*\])?\s*=\s*\{/).each do
          im = Regexp.last_match
          bo = im.end(0) - 1
          bc = match_close(masked, bo)
          next if bc < 0
          text = @files[frel]['text']
          # an array of structs (struct TAG arr[] = { {...}, {...} }): the field is inside each braced element
          elems = split_args(masked, bo, bc)
          groups = elems.select { |a, _b| masked[a + (masked[a..].to_s[/\A\s*/].length)] == '{' }
          fields = if !groups.empty?
                     groups.map do |ga, gb|
                       ob = ga + masked[ga..].to_s[/\A\s*/].length
                       cb = match_close(masked, ob)
                       cb < 0 ? nil : split_args(masked, ob, cb)[rec[:index]]
                     end
                   else
                     [elems[rec[:index]]]
                   end
          fields.compact.each do |a|
            t = psl(text, a[0], a[1]).strip
            lead = psl(text, a[0], a[1])[/\A\s*/].length
            # NULL is no callback: the entry leaves the field unset, so it is not an assign
            rec[:assigns] << [t, frel, a[0] + lead] if t.match?(/\A[A-Za-z_]\w*\z/) && t != 'NULL'
          end
        end
      end
      masked.to_enum(:scan, /(?:\.|->)\s*#{rec[:name]}\s*\(/).each do
        cm = Regexp.last_match
        rec[:calls] << [cm.end(0) - 1, enclosing_func(frel, cm.begin(0))&.fetch('name', nil), frel]
      end
    end
    rec
  end

  # whether the innermost unclosed brace before pos opens a struct body (struct TAG { or struct {)
  def struct_body_before?(masked, pos)
    depth = 0
    k = pos - 1
    while k >= 0
      c = masked[k]
      if c == '}'
        depth += 1
      elsif c == '{'
        if depth == 0
          return psl(masked, [k - 40, 0].max, k) =~ /struct\s*\w*\s*\z/ ? true : false
        end
        depth -= 1
      end
      k -= 1
    end
    false
  end

  # The field type and the calls through a threaded field take mrb (see compute_needs). The decision was made once for
  # the whole input: every assigned callback is threaded, and every call is in a function with the mruby state.
  # The parameter text of helper name with the mruby state added to each active function-pointer parameter (see
  # fnptr_param_recs): the callback type takes mrb first, as its threaded callbacks do. The same predicate as
  # edit_fnptr_fields decides the call sites, so the header and the calls agree.
  def fnptr_param_text(name, ptxt)
    cands = @threaded_cands || Set.new
    regs = @valid_reg_names || Set.new
    (@fnptr_recs || []).each do |r|
      next unless r[:owner] == name && r[:ok] && r[:assigns].all? { |h, _, _| cands.include?(h) }
      next unless r[:calls].all? { |_, fn, _| fn && (cands.include?(fn) || regs.include?(fn)) }
      ptxt = ptxt.sub(/\(\s*\*\s*#{Regexp.escape(r[:name])}\s*\)\s*\(/) { |m| m + 'mrb_state *mrb, ' }
    end
    # a prototype declares the callback without its name ((*)(VALUE, ...)): the threaded callback type takes mrb the same way
    if (@fnptr_recs || []).any? { |r| r[:owner] == name && r[:ok] && r[:assigns].all? { |h, _, _| cands.include?(h) } &&
                                      r[:calls].all? { |_, fn, _| fn && (cands.include?(fn) || regs.include?(fn)) } }
      ptxt = ptxt.gsub(/\(\s*\*\s*\)\s*\(/) { |m| m + 'mrb_state *mrb, ' }
    end
    ptxt
  end

  def edit_fnptr_fields(rel)
    cands = @threaded_cands || Set.new
    regs = @valid_reg_names || Set.new
    ed = @edits[rel]
    applied_pstart = nil
    applied_copen = nil
    (@fnptr_recs || []).each do |r|
      next unless r[:ok] && r[:assigns].all? { |h, _, _| cands.include?(h) }
      next unless r[:calls].all? { |_, fn, _| fn && (cands.include?(fn) || regs.include?(fn)) }
      # the callback's parameter list gains mrb once (a typedef shared by several fields has one parameter list)
      if r[:rel] == rel && r[:owner].nil? && !(applied_pstart ||= Set.new).include?(r[:params_start])
        applied_pstart << r[:params_start]
        ed.add(r[:params_start], r[:params_start], 'mrb_state *mrb, ')
      end
      r[:calls].each do |copen, _, crel|
        next unless crel == rel
        # a call is passed mrb once, however many records name its field
        next if (applied_copen ||= Set.new).include?(copen)
        applied_copen << copen
        masked = @files[rel]['masked']
        nxt = next_nonspace(masked, copen + 1)
        ed.add(copen + 1, copen + 1, masked[nxt] == ')' ? 'mrb' : 'mrb, ')
      end
    end
  end

  # A typedef of a function-pointer type, typedef RET (*T)(PARAMS);, declared in this file. Its variables (T v; or
  # T v[] = {helpers};) hold the callbacks, and their calls are v(...) or v[i](...). fnptr_typed_global collects them.
  def fnptr_typedefs(rel)
    masked = @files[rel]['masked']
    out = []
    masked.to_enum(:scan, /\btypedef\b[^;{}]*?\(\s*\*\s*([A-Za-z_]\w*)\s*\)\s*\(/).each do
      m = Regexp.last_match
      open = m.end(0) - 1
      close = match_close(masked, open)
      next if close < 0
      params = psl(masked, open + 1, close).strip
      next if params.empty? || params == 'void'
      out << { rel: rel, name: m[1], params_start: open + 1 }
    end
    out
  end

  # The variables of typedef T and their callbacks and calls, across every file of the input. A variable declared in a
  # struct body is a member: its calls are member accesses (x.v(...) / x->v(...)), so a function of the same name is not
  # a call of it. A member name declared with another type anywhere in the input makes the rule refuse.
  def fnptr_typed_global(rec)
    rec[:assigns] = []
    rec[:calls] = []
    vars = []
    mvars = []
    @files.each do |frel, f|
      masked = f['masked']
      masked.to_enum(:scan, /\b#{rec[:name]}\s+([A-Za-z_]\w*)\s*(?:\[[^\]]*\]\s*)*(=|;|,)/).each do
        dm = Regexp.last_match
        (struct_body_before?(masked, dm.begin(0)) ? mvars : vars) << dm[1]
        next unless dm[2] == '='
        after = next_nonspace(masked, dm.end(0))
        if masked[after] == '{'
          close = match_close(masked, after)
          next if close < 0
          split_args(masked, after, close).each do |a, b|
            t = psl(f['text'], a, b).strip
            rec[:assigns] << [t, frel, a] if t.match?(/\A[A-Za-z_]\w*\z/) && t != 'NULL'
          end
        elsif (am = masked[after..].match(/\A([A-Za-z_]\w*)\s*;/))
          rec[:assigns] << [am[1], frel, after]
        end
      end
    end
    mvars.uniq.each do |v|
      # any struct member of this name with another type makes the member calls ambiguous: refuse
      @files.each do |frel, f|
        f['masked'].to_enum(:scan, /([A-Za-z_]\w*)[ \t*]+#{v}\s*(?:\[[^\]]*\]\s*)*;/).each do
          tm = Regexp.last_match
          next if tm[1] == rec[:name]
          rec[:calls] << [-1, nil, frel]
        end
      end
      @files.each do |frel, f|
        f['masked'].to_enum(:scan, /(?:\.|->)\s*#{v}\s*(?:\[[^\]]*\]\s*)*\(/).each do
          cm = Regexp.last_match
          rec[:calls] << [cm.end(0) - 1, enclosing_func(frel, cm.begin(0))&.fetch('name', nil), frel]
        end
      end
    end
    vars.uniq.each do |v|
      @files.each do |frel, f|
        f['masked'].to_enum(:scan, /(?<![\w.>])#{v}\s*(?:\[[^\]]*\]\s*)*\(/).each do
          cm = Regexp.last_match
          rec[:calls] << [cm.end(0) - 1, enclosing_func(frel, cm.begin(0))&.fetch('name', nil), frel]
        end
      end
    end
    # Members of this typedef's type (struct TAG { T NAME; }): their assigns are the members' positional initializer entries
    # (struct TAG var = { ..., helper, ... }) and statement assigns (x.NAME = helper;), as for a function-pointer field
    # (fnptr_global). The member's struct tag and index come from the declaration.
    @files.each do |frel, f|
      f['masked'].to_enum(:scan, /\b#{rec[:name]}\s+([A-Za-z_]\w*)\s*(?:\[[^\]]*\]\s*)*;/).each do
        md = Regexp.last_match
        next unless struct_body_before?(f['masked'], md.begin(0))
        bo = struct_body_open(f['masked'], md.begin(0))
        next unless bo
        tag = psl(f['masked'], [bo - 60, 0].max, bo)[/struct\s+(\w+)\s*\z/, 1]
        next unless tag
        pseudo = { name: md[1], tag: tag, index: f['masked'][(bo + 1)...md.begin(0)].to_s.count(';'), assigns: [], calls: [] }
        fnptr_global(pseudo)
        rec[:assigns].concat(pseudo[:assigns])
      end
    end
    rec
  end

  def compute_needs
    ids = {}
    @defs.each do |name, lst|
      lst.each { |d| (ids[name] ||= Set.new).merge(body_idents(d)) }
    end
    # a split registered method (compute_splits) is forced only through its body: its impl gets mrb when the body needs it
forced = (@reg_names - @split_names) | Set.new(@init_defs.map { |d| d['name'] })
    # the first argument of rb_protect is called as mruby's mrb_func_t (mrb, data): a callback defined here takes mrb
    prot_names = Set.new
    @files.each_value { |f| f['masked'].to_enum(:scan, /rb_protect\s*\(\s*([A-Za-z_]\w*)/).each { prot_names << Regexp.last_match(1) } }
    forced |= prot_names.select { |n| @defs.key?(n) }
    # struct function-pointer fields (fnptr_decls): the callbacks assigned to a field are threaded with mrb, as the field's
    # type takes mrb (fnptr_global; the edits are in edit_fnptr_fields)
    @fnptr_recs = []
    @files.keys.each { |frel| fnptr_decls(frel).each { |d| @fnptr_recs << fnptr_global(d) } }
    @files.keys.each { |frel| fnptr_typedefs(frel).each { |d| @fnptr_recs << fnptr_typed_global(d) } }
    @fnptr_recs.concat(fnptr_param_recs)
    # a field assigned a parameter takes the helpers of that parameter's record (forwarding), and a parameter record that
    # stores into a field is refused when the field cannot take mrb: iterated until both sides agree
    @fnptr_recs.each { |r| r[:assigns_raw] ||= r[:assigns].dup }
    10.times do
      byk = {}
      @fnptr_recs.each { |r| byk[[r[:owner], r[:pidx]]] = r if r[:owner] && !r[:bad] }
      @fnptr_recs.each do |r|
        next if r[:owner] || r[:bad]
        next unless r[:assigns_raw].any? { |x| x[0] == :fwd }
        out = []
        okf = true
        r[:assigns_raw].each do |x|
          if x[0] == :fwd
            src = byk[[x[1], x[2]]]
            if src.nil?
              okf = false
              break
            end
            out.concat(src[:assigns])
          else
            out << x
          end
        end
        r[:assigns] = okf ? out : []
      end
      changed = false
      @fnptr_recs.each do |p|
        next if p[:bad] || p[:owner].nil? || (p[:stores] || []).empty?
        unusable = p[:stores].any? do |f|
          @fnptr_recs.any? { |q| q[:owner].nil? && q[:name] == f && !q[:bad] && (q[:assigns_raw].any? { |x| x[0] == :fwd } && q[:assigns].empty?) }
        end
        next unless unusable
        p[:bad] = true
        changed = true
      end
      break unless changed
    end
    # a function whose address is taken other than by a direct call (a dispatch table: &char_escape) keeps its C signature
    # (its table's type has no state), so a call from it cannot pass the state to a threaded callback field
    # (a callback stored in a field, and a registered method or Init function, are address-taken by design: they are threaded
    # with their field or registration, so they stay usable)
    @fnptr_addr_taken = {}
    stored_cbs = Set.new(@fnptr_recs.flat_map { |r| r[:assigns].map { |h, _, _| h } })
    registered = Set.new((@reg_names || []).to_a) | Set.new((@init_defs || []).map { |d| d['name'] })
    fn_addr_taken = lambda do |fn|
      next false if stored_cbs.include?(fn) || registered.include?(fn)
      @fnptr_addr_taken.fetch(fn) do
        @fnptr_addr_taken[fn] = @files.values.any? { |f| f['masked'].match?(/\b#{Regexp.escape(fn)}\b(?!\s*\()/) }
      end
    end
    @fnptr_recs.each do |r|
      next if r[:assigns].empty?
      r[:ok] = r[:assigns].all? { |h, _, _| @defs.key?(h) } && r[:calls].all? { |_, fn, _| fn && !fn_addr_taken.call(fn) }
      # only a record that is ok forces its callbacks: a refused field must not make its callbacks need the state
      r[:assigns].each { |h, _, _| forced << h if @defs.key?(h) && r[:ok] }
      forced << r[:owner] if r[:ok] && r[:owner]
      # the function that calls an ok field passes it the state (edit_fnptr_fields): it needs the state too
      r[:calls].each { |_, cfn, _| forced << cfn if r[:ok] && cfn && @defs.key?(cfn) }
    end
    @fnptr_assign_pos = Set.new(@fnptr_recs.select { |r| r[:ok] }.flat_map { |r| r[:assigns].map { |_, frel, hp| [frel, hp] } })
# a data type's mark and free functions are called by the runtime with (mrb, data): they are threaded like helpers
@dtype_cb_pos = Set.new
dtype_decls.each do |rel, _m, info|
  next if info['error']
  [[info['mark'], info['mark_pos']], [info['free'], info['free_pos']]].each do |nm, pos|
    next if nm == 'NULL' || nm == '0' || !@defs.key?(nm)
    forced << nm
    @dtype_cb_pos << [rel, pos]
    # the mark function is a mark-context name from the start: mark_context_names is memoized on its first use
    (@dtype_mark_names ||= Set.new) << nm if nm == info['mark']
  end
end
# Data_Make_Struct(klass, type, mark, free, ptr): the mark and free callbacks go into a static mrb_data_type, so they are
# threaded like a data type's callbacks (the same positions and mark-context names)
data_make_calls_all.each do |rel, pos, mk_name, fr_name, mk_pos, fr_pos|
  [[mk_name, mk_pos], [fr_name, fr_pos]].each do |nm, p2|
    next if nm.nil? || nm == 'NULL' || nm == '0' || !@defs.key?(nm)
    forced << nm
    @dtype_cb_pos << [rel, p2]
  end
  (@dtype_mark_names ||= Set.new) << mk_name if mk_name && @defs.key?(mk_name)
end
# a mark function stored in a struct's mark field (p->mark = mark) is a mark callback when the gem calls it through that field
# (p->mark(p) in the data type's mark, as oj's parser does): the registration is the assignment, the call is the mark. Both
# must be in this gem, so a field nothing marks through is not seeded.
if @files.each_value.any? { |f| f['masked'].match?(/(?:->|\.)mark\s*\(/) }
  @files.each_value do |f|
    f['masked'].scan(/(?:->|\.)mark\s*=\s*([A-Za-z_]\w*)\s*;/) do |(nm)|
      (@dtype_mark_names ||= Set.new) << nm if @defs.key?(nm)
    end
  end
end
    # rb_hash_foreach callbacks are threaded (see hash_foreach_calls): forced into the needs set, with their call positions
    @hash_calls = hash_foreach_calls
    @onig_calls = onig_foreach_calls
    @onig_calls.each { |c| forced << c[:cb] }
    @onig_cb_pos = Set.new(@onig_calls.map { |c| [c[:rel], c[:cb_pos]] })
    @ensure_calls = ensure_calls
    @ensure_calls.each { |c| forced << c[:b] << c[:ecb] }
    @ensure_cb_pos = Set.new(@ensure_calls.flat_map { |c| [[c[:rel], c[:bpos]], [c[:rel], c[:epos]]] })
    @rescue_calls = rescue_calls
    @rescue_calls.each { |c| forced << c[:b] << c[:r] }
    @rescue_cb_pos = Set.new(@rescue_calls.flat_map { |c| [[c[:rel], c[:bpos]], [c[:rel], c[:rpos]]] })
    @hash_calls.each { |c| forced << c[:cb] }
    @hash_cb_pos = Set.new(@hash_calls.map { |c| [c[:rel], c[:cb_pos]] })
    @hash_cb_names = Set.new(@hash_calls.map { |c| c[:cb] })
    # a VALUE-data callback: its third parameter is a void * named nfcx_data_<name>, and its body starts with the VALUE copy
    @hash_value_cbs = {}
    @hash_calls.each { |c| @hash_value_cbs[c[:cb]] = c[:arg] if c[:value_data] }
    # a local macro whose body uses a name that needs the state needs it too: a use of the macro expands that use
    macro_needs = Set.new
    macro_idents = {}   # macro name -> the identifiers of its body (a macro that calls a needed helper needs the state too)
    @files.each do |_rel, f|
      f['masked'].to_enum(:scan, /^[ \t]*#[ \t]*define[ \t]+([A-Za-z_][#{WC}]*)/).map { Regexp.last_match }.each do |m|
        body = psl(f['masked'], m.end(0), logical_line_end(f['masked'], m.end(0)))
        macro_idents[m[1]] = body.scan(IDENT_RE)
        macro_needs << m[1] if body.scan(IDENT_RE).any? { |i| (@entries[i] || {})['needs_mrb'] }
      end
    end
    @macro_needs = macro_needs
    # a helper that reads rb_scan_args on its argc and argv needs the mruby state for its argc check (mrb_argnum_error)
    forced.merge(argv_scan_helpers.keys)
    # a --method-scope-fn helper needs the state (its stored pointer runs inside a method call that sets it)
    forced.merge($method_scope_fns || [])
    needs = Set.new(forced)
    ids.each do |name, s|
      # a class-test type tag (RB_TYPE_P(x, T_RATIONAL) and the like) is a class lookup, which needs the mruby state
      needs << name if s.any? { |i| (@entries[i] || {})['needs_mrb'] || macro_needs.include?(i) || %w[T_RATIONAL T_COMPLEX T_STRUCT RB_ALLOCV_N RB_ALLOCV_END].include?(i) }
    end
    changed = true
    while changed
      changed = false
      macro_idents.each do |mn, idents|
        next if macro_needs.include?(mn)
        # a macro whose body uses a needing helper or a needing macro needs the state too
        if idents.any? { |c| (needs.include?(c) && @defs.key?(c)) || macro_needs.include?(c) }
          macro_needs << mn
          changed = true
        end
      end
      ids.each do |name, s|
        next if needs.include?(name)
        if s.any? { |c| (needs.include?(c) && @defs.key?(c)) || macro_needs.include?(c) }
          needs << name
          changed = true
        end
      end
    end
    @needs = needs
  end

  def check_refs
    # Init functions: CRuby calls only Init_<entry>, where <entry> is the name extconf.rb passes to
    # create_makefile. Other Init_ functions are dead code in the extension: they are kept under #if 0.
    @dead_inits = []
    entry = extconf_entry
    if entry && !@init_defs.empty?
      want = "Init_#{entry.split('/', -1).last}"
      chosen = @init_defs.select { |d| d['name'] == want }
      if !chosen.empty?
        # an Init_ function that the entry (or a live function) calls is a helper, not dead code: it stays in the
        # output as an ordinary function. Only the others are kept under #if 0.
        others = @init_defs.reject { |d| d.equal?(chosen[0]) }
        live_names = Set[chosen[0]['name']]
        changed = true
        while changed
          changed = false
          others.each do |d|
            next if live_names.include?(d['name'])
            called = (@occ[d['name']] || []).any? do |orel, os, _oe|
              f = enclosing_func(orel, os)
              f && live_names.include?(f['name'])
            end
            if called
              live_names << d['name']
              changed = true
            end
          end
        end
        @dead_inits = others.reject { |d| live_names.include?(d['name']) }
        @init_defs = chosen
        @dead_inits.each do |d|
          @ignored << [d['file'], "Init_ function #{d['name']} is not the entry (create_makefile names #{entry}): kept under #if 0"]
        end
      else
        refuse(nil, 0, want, "create_makefile names #{entry} but no #{want} is defined in the input")
      end
    end
    @init_defs[1..].to_a.each do |extra|
      refuse(extra['file'], extra['hstart'], extra['name'], 'multiple Init_ functions in one extension are not supported')
    end
    if !@init_defs.empty?
      @init_rel = @init_defs[0]['file']
    else
      cxx = Dir.glob(File.join(@cext_dir, '*.{cc,cpp,cxx}'))
      if cxx.any?
        refuse(nil, 0, "Init_#{@name}", "stuck point (C++): the extension is C++ (#{cxx.map { |f| File.basename(f) }.sort.join(', ')}), and the converter reads C sources only; C++ classes, templates and exceptions are not translated (accepted stuck point)")
      else
        refuse(nil, 0, "Init_#{@name}", 'no Init_<name> function found')
      end
    end
    init_first = @init_defs.empty? ? nil : @init_defs[0]['name']
    # registered functions: must be defined; must not be called directly
    @regs.each do |r|
      next unless r['error'].nil?
      next if @defs.key?(r['func'])
      # a registration in inactive text (an #if 0 or an undefined #ifdef branch) is dead code: it is not refused, and the
      # text stays as written
      if text_inactive_spans(r['file']).any? { |a, z| a < r['call'] && r['call'] < z }
        r['error'] = 'dead: the registration is in inactive text'
        next
      end
      why = if @excluded_defs.include?(r['func'])
              ssl = openssl_guarded_definition?(r['func'])
              if ssl
                "stuck point (OpenSSL): the function is compiled only when the build has OpenSSL (#ifdef #{ssl}), and it uses " \
                "OpenSSL, which mruby has no binding for (accepted stuck point)"
              else
                'registered function has no active definition: its only definition is in text the front end excludes'
              end
            else
              'registered function has no definition in the input'
            end
      refuse(r['file'], r['call'], r['func'], why)
      r['error'] = why
    end
    valid_reg = @regs.select { |r| r['error'].nil? }
    @valid_reg_names = Set.new(valid_reg.map { |r| r['func'] })
    # variadic methods (argc -1): (argc, argv, self) parameter names, used by rb_scan_args
    @variadic = {}
    valid_reg.each do |r|
      next unless r['argc'] == -1 && @defs.key?(r['func'])
      p = variadic_params(@defs[r['func']][0])
      @variadic[r['func']] = p if p
    end
    # Python iterated a set here; sorted, so the refusals come out in the same order on every run
    # A split method (compute_splits) is not refused here: its direct calls are renamed to its impl (process). A method
    # that is not split keeps the refusal, with the reason compute_splits or the threading check recorded.
    @reg_names.to_a.sort.each do |name|
      # only a registration that is active (no error) makes the function a mruby method; an excluded one leaves it plain C
      next unless @regs.any? { |r| r['error'].nil? && r['func'] == name }
      refuse_direct_uses(name) unless @split_names.include?(name)
    end
    # helper functions that need the mruby state are threaded: the mrb argument is added to the definition, to
    # every prototype (in the .c and .h files, which are scanned) and to every call site. A use is safe when it
    # is a direct call inside a function body; a use anywhere else is refused. A static helper cannot be called
    # from another file, so its uses are all in its own file; a non-static one is threaded with a caveat (its
    # signature changes, so callers outside the input would need the argument too). Every caller of a helper is
    # itself in needs, so it either gets mrb (a threaded helper, a registered method or Init) or has a refusal of
    # its own; the check after the loop makes that explicit.
    cands = Set.new
    @needs.to_a.sort.each do |name|
      next if (@reg_names - @split_names).include?(name) || name == init_first || !@defs.key?(name)
      cands << name if single_or_exclusive?(name)
    end

    helper_uses = lambda do |name|
      out = []
      (@occ[name] || []).each do |rel, s, e|
        # a file-scope array of this name in this file is a variable, not a use of a helper of the same name elsewhere
        next if @files[rel]['masked'].match?(/^[ \t]*(?:static[ \t]+|const[ \t]+)*[A-Za-z_][\w \t\*]*?\b#{Regexp.escape(name)}[ \t]*\[[^\]\n]*\][ \t]*(?:=|;)/)
        next if @decls.any? { |d| d['name'] == name && rel == d['file'] && d['hstart'] <= s && s < d['hend'] }
        # the body of an object-like alias (#define alias real_name): its invocations are the uses, resolved by object_macro_name
        lstart = @files[rel]['masked'].rindex("\n", s - 1) || -1
        dline = @files[rel]['masked'][(lstart + 1)...s].to_s
        next if dline.match?(/\A[ \t]*#[ \t]*define[ \t]+[#{WC}]+[ \t]+\z/)
        # a definition header in the text (also one the front end excludes, as in an inactive #if branch): name (params) {
        next if @files[rel]['masked'][e..].to_s.match?(/\A[ \t\n]*\([^()]*\)[ \t\n]*\{/)
        # a definition's own header (a name that has several definitions: each is a header, not a use)
        next if (@defs[name] || []).any? { |d| d['file'] == rel && d['hstart'] && d['brace'] && d['hstart'] <= s && s < d['brace'] }
        # a split method's registration names it as the wrapper, which is not a use of the impl
        next if valid_reg.any? { |r| rel == r['file'] && r['open'] <= s && s <= r['close'] }
        next if in_dead_init(rel, s)
        # a use in inactive code (an #if 0 or another excluded conditional branch) cannot run: it is not a use
        next if ((@excluded_spans || {})[rel] || []).any? { |a, z| a < s && s < z }
        masked = @files[rel]['masked']
        # a struct member of the same name (obj.name, obj->name) is a field, not a use of the helper
        next if masked[[s - 40, 0].max...s].to_s.match?(/(?:\.|->)[ \t\n]*\z/)
        # a field declared in a struct body (type name;) is a member, not a use of the helper of the same name
        nxd = next_nonspace(masked, e)
        pvd = prev_nonspace(masked, s - 1)
        if nxd >= 0 && (masked[nxd] == ';' || masked[nxd] == '[') && pvd >= 0 && masked[pvd].match?(/[A-Za-z_0-9*]/) &&
           struct_body_before?(masked, s)
          next
        end
        # a function-pointer field declaration of the same name, as in a struct body: type (*name)(params);
        next if masked[[s - 40, 0].max...s].to_s.match?(/\(\*[ \t\n]*\z/) && masked[e..].to_s.match?(/\A[ \t\n]*\)[ \t\n]*\(/)
        # the only argument of a one-parameter macro whose body uses the parameter as a member (#define M(x) (p->x)): a field
        next if member_macro_arg?(rel, s, e)
        nx = next_nonspace(masked, e)
        direct = nx >= 0 && masked[nx] == '('
        out << [rel, s, direct, enclosing_func(rel, s)]
      end
      out
    end

shadowed = lambda { |name, fn| shadowed_in?(name, fn) }

# true when the use is the first argument of a call to rb_protect
protect_callback_use = lambda do |rel, s|
  masked = @files[rel]['masked']
  open, callee = innermost_open(masked, s)
  prev = prev_nonspace(masked, s - 1)
  open == '(' && callee == 'rb_protect' && prev >= 0 && masked[prev] == '('
end

    # why a use of a helper through its address (not a direct call) cannot take mrb, or nil (see value_problem below)
    value_problem = lambda do |rel, s, name|
      masked = @files[rel]['masked']
      # the helper is assigned to a callback field (its assignment is a field assign, in fnptr_global) or compared with one: once the
      # field's type takes mrb, both sides have the same type, so the comparison is not a use that escapes
      fields = (@fnptr_recs || []).map { |r| r[:name] }.to_set
      if masked[[s - 80, 0].max...s].to_s =~ /(?:\.|->)[ \t\n]*(\w+)[ \t\n]*(?:==|!=)[ \t\n]*\z/ && fields.include?($1)
        next nil
      end
      if masked[[s - 80, 0].max...s].to_s =~ /(?:\.|->)[ \t\n]*(\w+)[ \t\n]*=[ \t\n]*\z/ && fields.include?($1)
        next nil
      end
      if masked[(s + name.length)..(s + name.length + 80)].to_s =~ /\A[ \t\n]*(?:==|!=)[ \t\n]*[A-Za-z_][\w\t\n .>\[\]-]*?\.(\w+)/ && fields.include?($1)
        next nil
      end
      open, callee = innermost_open(masked, s)
      before = prev_nonspace(masked, s - 1)
      after = next_nonspace(masked, s + name.length)
      if open != '(' || callee.nil?
        'its address is assigned or stored, so the pointer may escape the method context'
      elsif !(before >= 0 && '(,'.include?(masked[before])) || after < 0 || !')'.include?(masked[after]) && masked[after] != ','
        'the pointer is part of an expression, not a plain argument'
      elsif macro_arg_nonretaining?(rel, s, callee)
        nil
      elsif callee == 'rb_define_alloc_func'
        # the registration template takes the allocator as a registered function (see the scan of registrations)
        nil
      elsif @entries[callee].nil? && (ur = @unmapped_reasons[callee]).is_a?(String) && ur.start_with?('stuck point')
        # a callee that is a stuck point (its reason is recorded): the pointer's refusal carries that reason
        "#{ur}; the pointer is passed to #{callee}"
      elsif STORE_CALL_RE.match?(callee) || @defs.key?(callee) || !@entries.key?(callee)
        "the pointer is passed to #{callee}, which may keep it"
      end
    end

use_problem = lambda do |name, use|
  rel, s, direct, fn = use
  # a name that a local shadows in this function, used without a call, is that local (not the helper): no use
  next nil if fn && !direct && shadowed.call(name, fn)
  next nil if !direct && (@fnptr_assign_pos || Set.new).include?([rel, s])
  next nil if !direct && @dtype_cb_pos.include?([rel, s])
  next nil if !direct && (@hash_cb_pos || Set.new).include?([rel, s])
  next nil if !direct && (@onig_cb_pos || Set.new).include?([rel, s])
  next nil if !direct && ((@ensure_cb_pos || Set.new).include?([rel, s]) || (@rescue_cb_pos || Set.new).include?([rel, s]))
  # the first argument of rb_protect is called synchronously with the mrb_func_t shape (mrb, data), which a
  # threaded helper has; it is a value use that may take mrb (api_map.json rb_protect)
  next nil if !direct && protect_callback_use.call(rel, s)
  # a value use passed to a defined function that only calls it (or forwards it to one that does): not a keep
  next nil if !direct && non_retaining_use?(rel, s)
  if !direct
        # the address is kept or passed on, so the helper's signature cannot gain mrb; the reason says how
        why = value_problem.call(rel, s, name) || 'the pointer is passed as a value, and the helper would gain an argument'
        next "helper needs the mruby state threaded in, but is used outside a direct call (not supported): #{why}"
      end
      if fn.nil? && direct && in_global_macro?(rel, s)
        next nil # a macro that expands in a function with the state
      end
      # a threaded helper called from a macro body: the macro's expansions are all in functions with the state, so the
      # expansion passes the mrb of its function (mrb_tok gives mrb outside the global macros)
      # a macro expanded in a global-state helper expands with the global name, consistent with the threaded helper it calls
      if fn.nil? && direct && (dm = define_at(rel, s)) && macro_expansions_ok(dm, cands | (@valid_reg_names || Set.new) | (init_first ? Set[init_first] : Set.new) | (@global_helpers || Set.new))
        next nil
      end
      if fn.nil?
        # a macro body that a per-class allocator reaches: the allocator has no state argument (accepted stuck point)
        if (dm = define_at(rel, s)) && alloc_reach.include?(dm[0])
          next 'stuck point (per-class allocator): the macro that calls the helper is expanded in an allocator, which has no state argument in the fork'
        end
        next ('helper needs the mruby state threaded in, but the call is not in a function definition the ' \
              'converter recognises (a macro-decorated definition, or file scope) (not supported)')
      end
      if shadowed.call(name, fn)
        next 'helper needs the mruby state threaded in, but its name is shadowed in the calling function (not supported)'
      end
      nil
    end

    uses = {}
    cands.each { |name| uses[name] = helper_uses.call(name) }
    # A function-pointer field or parameter is rewritten (its type takes mrb, its calls pass it) only when every call of it
    # is in a function that has the state (edit_fnptr_fields). Its callbacks must then be threaded too, so a record whose
    # calls fail is dropped: its callbacks leave the threaded set and each one is refused where it is stored.
    fn_regs = @valid_reg_names || Set.new
    (@fnptr_recs || []).each do |r|
      next unless r[:ok] && r[:assigns].any? { |h, _, _| cands.include?(h) }
      next if r[:calls].all? { |_, fn, _| fn && (cands.include?(fn) || fn_regs.include?(fn)) }
      r[:assigns].each do |h, frel, pos|
        next unless cands.include?(h)
        cands.delete(h)
        refuse(frel, pos, h, 'a function-pointer field or parameter it is stored in is called from a function without the mruby state (not supported)')
      end
      r[:ok] = false
    end
    # The macro decision needs the threaded set, and the threaded set needs the macro decision (a direct call from a
    # macro body is a use only when the macro expands in a function with the state). Greatest fixpoint: start from the
    # set of candidates, record which macros expand in it, prune the candidates whose uses fail, and repeat. The spans
    # only grow with the context, so the final macro decision keeps every position this pass allowed.
    loop do
      compute_global_macros(@valid_reg_names | (init_first ? Set[init_first] : Set.new) | cands, false)
      changed = false
      cands.to_a.sort.each do |name|
        why = uses[name].map { |u| use_problem.call(name, u) }.compact.first
        next unless why
        changed = true
        cands.delete(name)
        next unless @split_names.include?(name)
        # the impl cannot take mrb from every direct caller: the method is not split, and its calls keep the refusal
        @split_names.delete(name)
        @split_reason[name] = why
        refuse_direct_uses(name)
      end
      break unless changed
    end
    # A split method that takes mrb needs every direct caller to have the mruby state in scope: a method or Init, or a
    # threaded helper. A caller without it (a refused helper, or a function with no state) would pass a state that is
    # not there, so the method is not split. Removing one method can leave another's caller without state: repeat.
    loop do
      mrb_fn = cands | @valid_reg_names | (init_first ? Set[init_first] : Set.new)
      bad = @split_names.to_a.sort.filter_map do |name|
        next unless cands.include?(name)
        _rel, _s, _d, fn = uses[name].find { |u| u[3] && !mrb_fn.include?(u[3]['name']) }
        [name, fn['name']] if fn
      end
      break if bad.empty?
      bad.each do |name, caller|
        @split_names.delete(name)
        cands.delete(name)
        stuck_callee = (@occ[caller] || []).map { |crel, cs, _ce| [crel, cs] }.filter_map do |crel, cs|
          cm = @files[crel]['masked']
          op, callee_n = innermost_open(cm, cs)
          callee_n if op == '(' && callee_n && (ur = @unmapped_reasons[callee_n]).is_a?(String) && ur.start_with?('stuck point')
        end.first
        @split_reason[name] = if stuck_callee
                                "stuck point (#{stuck_callee}): the caller #{caller} is passed to #{stuck_callee}, which has no mruby form (its reason is recorded)"
                              else
                                "its direct caller #{caller} has no mruby state in scope (not a method, Init or threaded helper)"
                              end
        refuse_direct_uses(name)
      end
    end
    @helper_names = cands
    cands.to_a.sort.each do |name|
      next if @split_names.include?(name)
      d0 = @defs[name][0]
      next if d0['storage'].split.include?('static')
      rewrite(d0['file'], d0['hstart'], name, "mrb-threaded #{name}",
              'non-static helper: its signature gains the mrb argument; callers outside the input would need it too')
    end
    # Global state path (the design in the comment at @global_name). A needs-helper the threading path refused is not
    # threaded: it uses the file-scope state @global_name, which the registered methods and Init set on entry and
    # restore on exit (process, wrap_returns). Its uses must be direct calls, or a function pointer passed as an
    # argument to a call that does not keep it, inside a function with the mruby state: a registered method, Init, a
    # threaded helper or another helper of this set. The set is the greatest fixpoint: a helper leaves it when one of
    # its uses fails, and its callers are then checked again.
    @global_name = "#{@funcname}_bc2_mrb"
    # a --method-scope-fn helper keeps its signature and takes the state from the global (a stored pointer's type is unchanged)
    ($method_scope_fns || []).each { |n| cands.delete(n) }
    gcands = Set.new
    @needs.to_a.sort.each do |name|
      next if @reg_names.include?(name) || name == init_first || !@defs.key?(name) || cands.include?(name)
      gcands << name if single_or_exclusive?(name)
    end
    with_state = cands | @valid_reg_names | (init_first ? Set[init_first] : Set.new)
    global_use = lambda do |name, use, members|
      rel, s, direct, fn = use
      # --method-scope-fn NAME: the helper's address is stored only inside a parser or table that lives for one registered method
      # call (the caller asserts it), so the helper runs in that method's dynamic extent, where the global state is set
      next nil if ($method_scope_fns || Set.new).include?(name)
      # a callback passed to rb_hash_foreach / rb_ivar_foreach is converted by that call (the callback takes mrb)
      next nil if !direct && (@hash_cb_pos || Set.new).include?([rel, s])
      next nil if !direct && (@onig_cb_pos || Set.new).include?([rel, s])
      macro = fn.nil? && direct ? define_at(rel, s) : nil
      if fn.nil?
        # a function address in a file-scope table (an initializer of a variable of this file) runs only when the table is
        # used: when every use of the table is in a registered method or Init, the call runs in a method's dynamic extent,
        # where the global state is set (the same state the method's own helpers use)
        # Init sets the global state too (and every method restores it on return), so once the gem's Init has run the state is
        # valid wherever the table's entries run: a table used from any function is accepted when there is an Init
        if !direct && (tbl = file_scope_table_at(rel, s)) && (init_first || table_used_in_methods?(tbl, rel, s))
          nil
        elsif direct && macro && macro_expansions_ok(macro, with_state | members)
          nil
        elsif direct && macro && alloc_reach.include?(macro[0])
          'stuck point (per-class allocator): the macro that calls the helper is expanded in an allocator, which has no state argument in the fork'
        elsif direct
          'helper needs the mruby state threaded in, but the call is not in a function definition the converter ' \
          'recognises (a macro-decorated definition, or file scope) (not supported)'
        else
          'helper needs the mruby state threaded in, but is used outside a direct call (not supported): ' \
          'its address is in a file-scope initializer, so it may run with no method context'
        end
      elsif !direct && fn && shadowed.call(name, fn)
        nil # a local of this name, not a use of the helper
      elsif shadowed.call(name, fn)
        'helper needs the mruby state threaded in, but its name is shadowed in the calling function (not supported)'
      elsif !(init_first || with_state.include?(fn['name']) || members.include?(fn['name']))
        CTX_REASON
      elsif !direct
        why = value_problem.call(rel, s, name)
        why && "helper needs the mruby state threaded in, but is used outside a direct call (not supported): #{why}"
      end
    end
    gset = gcands.dup
    changed = true
    while changed
      changed = false
      gset.to_a.sort.each do |name|
        next unless helper_uses.call(name).any? { |u| global_use.call(name, u, gset) }
        gset.delete(name)
        changed = true
      end
    end
    @global_helpers = gset
    gset.to_a.sort.each do |name|
      d0 = @defs[name][0]
      rewrite(d0['file'], d0['hstart'], name, "global-state #{name}",
              "uses #{@global_name} (set by the registered method or Init it runs under), not an mrb argument")
    end
    refused_defs = Set.new
    @needs.to_a.sort.each do |name|
      next if @reg_names.include?(name) || name == init_first || !@defs.key?(name) || cands.include?(name) || gset.include?(name)
      ctx_why = nil
      stuck_why = nil
      if gcands.include?(name)
        # a use in a function with no state (a callback path) is reported once, on the helper's definition
        helper_uses.call(name).each do |u|
          why = global_use.call(name, u, gset)
          ctx_why ||= why if why == CTX_REASON
          stuck_why ||= why if why && why.include?('stuck point')
          refuse(u[0], u[1], name, why) if why && why != CTX_REASON
        end
      else
        helper_uses.call(name).each do |u|
          why = use_problem.call(name, u)
          # a use that is a stuck point (its reason is recorded) makes the helper's refusal that stuck point
          stuck_why ||= why if why && why.start_with?('stuck point')
          refuse(u[0], u[1], name, why) if why
        end
      end
      @defs[name].each do |d0|
        if alloc_reach.include?(name)
          refuse(d0['file'], d0['hstart'], name, 'stuck point (per-class allocator): the helper needs the mruby state and is reached from a ' \
                                                  'per-class allocator (rb_define_alloc_func), which has no state argument in the fork (accepted stuck point)')
        else
          if stuck_why
            refuse(d0['file'], d0['hstart'], name, "#{stuck_why}; the helper is refused with it")
          else
            refuse(d0['file'], d0['hstart'], name, ctx_why ? "helper needs mruby state; threading refused: #{ctx_why}" :
                                                   'helper needs mruby state; threading refused')
          end
        end
      end
      refused_defs << name
    end
    # fail-safe: a call of a threaded helper from a function that gets no mrb and has no refusal of its own
    # would not compile, so it is refused. A global-state helper has the state in scope through the global.
    @threaded_cands = cands.dup
    mrb_bearing = with_state | gset
    cands.to_a.sort.each do |name|
      uses[name].each do |rel, s, _direct, fn|
        # a refused definition is still emitted: its calls of threaded helpers would pass an mrb that is not in scope
        # with the gem's Init, a caller without the state reads the global (set by Init, restored by each method)
        next unless fn && !init_first && !mrb_bearing.include?(fn['name'])
        # a caller reached from a per-class allocator is part of that accepted stuck point (the allocator has no state)
        if alloc_reach.include?(fn['name'])
          refuse(rel, s, name, 'stuck point (per-class allocator): the caller is reached from a per-class allocator ' \
                               '(rb_define_alloc_func), which has no state argument in the fork (accepted stuck point)')
        else
          refuse(rel, s, name, 'caller has no mruby state and no refusal of its own (not supported)')
        end
      end
    end
    compute_global_macros(with_state | gset)
    # a macro that returns in a registered method or Init restores the global state before its return (see compute_global_macros)
    (@macro_return_plan || {}).each do |(prel, ps), plan|
      next unless ((@global_macro_spans || {})[prel] || []).any? { |a, _z| a == ps }
      ed = @edits[prel]
      ed.add(plan[:ret], plan[:ret] + 6, "{ mrb_value nfcx_bc2_ret = (")
      ed.add(plan[:end], plan[:end], "); #{@global_name} = nfcx_bc2_old; return nfcx_bc2_ret; }")
    end
    @global_wrap = !gset.empty? || @global_macro_spans.any? { |_r, l| !l.empty? }
    if @global_wrap
      # a macro that expands a return skips the restore of a registered method or Init that expands it (wrap_returns
      # only sees return statements written in the body). Such a use is refused; the macro's own body is not changed.
      wrapped = @valid_reg_names | (init_first ? Set[init_first] : Set.new)
      @files.each do |rel, f|
        define_spans(rel).each do |mname, a, b|
          next unless psl(f['masked'], a, b) =~ /(?<![#{WC}])return(?![#{WC}])/
          # a macro whose body restores the state before its return (the plan applied above) is not refused
          next if (@macro_return_plan || {}).key?([rel, a]) && ((@global_macro_spans || {})[rel] || []).any? { |x, _z| x == a }
          (@occ[mname] || []).each do |orel, os, _oe|
            next if orel == rel && a <= os && os < b
            fn = enclosing_func(orel, os)
            next unless fn && wrapped.include?(fn['name'])
            refuse(orel, os, mname, 'macro expands a return, which would skip the restore of the mruby global state in ' \
                                    'this registered method or Init (not supported)')
          end
        end
      end
    end
  end

  # Macros whose body calls an api that needs the mruby state. At file scope such a body is refused unless every
  # expansion is in a function with the state (a with_state or global-state function, mrb_tok) and the body has no
  # return (a return would skip the restore). Their mrb argument is then the global. A use in a preprocessor line
  # or in a file-scope initializer keeps the macro refused. Conservative: a macro that calls a helper is not handled.
  def compute_global_macros(ctx, record = true)
    # A use of a macro is fine in a function with the state, or inside another macro body accepted in an earlier round
    # (the outer macro's expansions are checked the same way). Rounds repeat until no macro is added.
    accepted = {}   # rel -> [[start, end]] of the accepted macros
    names = {}      # rel -> { start => macro name }
    loop do
      added = false
      # a macro body that calls a macro accepted in an earlier round is a candidate too (its expansions are checked)
      accepted_names = Set.new(names.values.flat_map { |h| h.values })
      @files.each do |rel, f|
        masked = f['masked']
        masked.to_enum(:scan, /^[ \t]*#[ \t]*define[ \t]+([A-Za-z_][#{WC}]*)/).map { Regexp.last_match }.each do |m|
          name = m[1]
          s = m.begin(0)
          e = logical_line_end(masked, m.end(0))
          next if (accepted[rel] || []).include?([s, e])
          body = psl(masked, m.end(0), e)
          # a body that calls a helper which needs the state is handled the same way: its call takes the global
          # a macro is a global macro only when its body calls the global state: a macro that calls only threaded helpers
          # expands with the mrb of its function (mrb_tok), so it is not on the global path
          threaded = @threaded_cands || Set.new
          # a --method-scope-fn macro (its expansions are stored callbacks that run in a method's call) is a candidate
          next unless ($method_scope_fns || Set.new).include?(name) || body.scan(IDENT_RE).any? { |i| (@entries[i] || {})['needs_mrb'] || (@defs.key?(i) && @needs.include?(i) && !threaded.include?(i)) || accepted_names.include?(i) || (@macro_needs || Set.new).include?(i) }
          # a return in the body skips the state restore of a registered method or Init that expands it: refused there
          if body =~ /(?<![#{WC}])return(?![#{WC}])/
            wrapped_use = lambda do |orel, os|
              fnx = enclosing_func(orel, os)
              fnx && (@valid_reg_names.include?(fnx['name']) || (@init_defs || []).any? { |x| x['name'] == fnx['name'] })
            end
            uses_out = (@occ[name] || []).reject { |orel, os, _oe| orel == rel && s <= os && os < e }
            wrapped = uses_out.any? { |orel, os, _oe| wrapped_use.call(orel, os) }
            if wrapped
              # every use is in a registered method or Init (each restores the global state before it returns), and the body is
              # `if (C) return E` with one return: the macro restores the state itself, before its return (the plan below)
              plan = nil
              mm = /(if[ \t]*\(.*\)[ \t]*)return([ \t]+[^;]*)\z/m.match(body)
              # the final statement form: `... return E;` (the macro's last statement; its ';' ends the return)
              mf = /(?<![#{WC}])return([ \t]+[^;]*);[ \t\\\n]*\z/m.match(body) unless mm
              if (mm || mf) && body.scan(/(?<![#{WC}])return(?![#{WC}])/).size == 1 && !uses_out.empty? &&
                 uses_out.all? { |orel, os, _oe| wrapped_use.call(orel, os) }
                if mm
                  plan = { ret: m.end(0) + mm.begin(0) + mm[1].length, end: e }
                else
                  plan = { ret: m.end(0) + mf.begin(0), end: m.end(0) + mf.begin(0) + mf[0].rindex(';') }
                end
              end
              next unless plan
              (@macro_return_plan ||= {})[[rel, s]] = plan if record
            end
          end
          ok = (@occ[name] || []).all? do |orel, os, _oe|
            inside = orel == rel && s <= os && os < e
            next true if inside
            # an expansion in an inactive definition (its #if is false in this build) is dead code
            next true if ((@excluded_spans || {})[orel] || []).any? { |x, z| x < os && os < z }
            # another #define of the same macro (an alternative branch) is a definition, not an expansion
            next true if (dd = define_at(orel, os)) && dd[0] == name
            # a macro is local to its file: a same-named macro of another file is another definition, not a use
            next true if orel != rel
            fn = enclosing_func(orel, os)
            # a --method-scope-fn macro: its file-scope expansions are stored callbacks (run in a method's call)
            next true if fn.nil? && ($method_scope_fns || Set.new).include?(name)
            if fn.nil?
              (accepted[orel] || []).any? { |a, z| a < os && os < z }
            else
              ctx.include?(fn['name'])
            end
          end
          next unless ok
          (accepted[rel] ||= []) << [s, e]
          (names[rel] ||= {})[s] = name
          added = true
        end
      end
      break unless added
    end
    @global_macro_spans = accepted
    return unless record
    accepted.each do |rel, spans|
      f = @files[rel]
      spans.each do |s, _e|
        name = names[rel][s]
        @rewrites << { 'file' => rel, 'line' => line_of(f['text'], s), 'from' => name, 'to' => "#{name} (mrb = #{@global_name})" }
      end
    end
  end

  # [name, start, end, rel] of the #define that holds pos, or nil
  def define_at(rel, pos)
    d = define_spans(rel).find { |_n, a, b| a < pos && pos < b }
    d && [d[0], d[1], d[2], rel]
  end

  def define_spans(rel)
    @define_spans ||= {}
    @define_spans[rel] ||= begin
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /^[ \t]*#[ \t]*define[ \t]+([A-Za-z_][#{WC}]*)/).map { Regexp.last_match }.map do |m|
        [m[1], m.begin(0), logical_line_end(masked, m.end(0))]
      end
    end
  end

  # A macro whose body calls a global-state helper: safe when the body has no return and every expansion is in a
  # function with the state (ctx). Checked again as the set of global-state helpers changes (its fixpoint).
  def macro_expansions_ok(macro, ctx, seen = nil)
    name, a, b, rel = macro
    (@occ[name] || []).all? do |orel, os, _oe|
      next true if rel == orel && a <= os && os < b
      # a same-named macro of another file is another definition
      next true if orel != rel
      # an expansion in an inactive definition (its #if is false in this build) is dead code
      next true if ((@excluded_spans || {})[orel] || []).any? { |x, z| x < os && os < z }
      # another #define of the same macro (an alternative branch) is a definition, not an expansion
      next true if (dd = define_at(orel, os)) && dd[0] == name
      fn = enclosing_func(orel, os)
      if fn.nil?
        # an expansion inside another macro's body is ok when that macro's own expansions are (the nesting is followed)
        outer = define_at(orel, os)
        next false if outer.nil? || outer[0] == name || (seen ||= Set.new).include?(outer[0])
        next macro_expansions_ok(outer, ctx, seen | [name])
      end
      ctx.include?(fn['name'])
    end
  end

  # The call that the position pos is an argument of: [open, close, callee name, argument index], or nil when pos is not
  # inside a call (a parenthesized expression or a statement has no callee name before its '(')
  def enclosing_call(masked, pos)
    depth = 0
    k = pos - 1
    while k >= 0
      ch = masked[k]
      if ')]}'.include?(ch)
        depth += 1
      elsif '([{'.include?(ch)
        if depth == 0
          return nil unless ch == '('
          j = prev_nonspace(masked, k - 1)
          return nil if j < 0
          m = /([A-Za-z_]\w*)\z/.match(masked[[j - 120, 0].max..j].to_s)
          return nil unless m
          close = match_close(masked, k)
          return nil if close <= 0
          args = split_args(masked, k, close)
          idx = args.index { |a, b| a <= pos && pos <= b }
          return nil if idx.nil?
          return [k, close, m[1], idx]
        end
        depth -= 1
      end
      k -= 1
    end
    nil
  end

  # true when the parameter at index k of the defined function fname never keeps the function pointer it receives: every
  # use in its body is a call of it (NAME(...) or (*NAME)(...)) or an argument of a call of another such function. The
  # depth bounds the forwarding chain.
  def fnptr_field_names
    @fnptr_field_names ||= Set.new(@files.keys.flat_map { |f| fnptr_decls(f).map { |d| d[:name] } })
  end

  def non_retaining?(fname, k, depth = 0)
    return false if depth > 6
    defs = (@defs[fname] || []).reject { |x| x['proto'] }
    return false unless defs.size == 1
    d = defs[0]
    return false unless d['po'] && d['pc'] && d['brace'] && d['body_end'] && d['file']
    pname = fn_param_names(d)[k]
    return false unless pname && pname.match?(/\A[A-Za-z_]\w*\z/)
    rel = d['file']
    masked = @files[rel]['masked']
    body = psl(masked, d['brace'], d['body_end'] + 1)
    body.to_enum(:scan, /(?<![#{WC}.>])#{Regexp.escape(pname)}(?![#{WC}])/).each do
      q = d['brace'] + Regexp.last_match.begin(0)
      nx = next_nonspace(masked, q + pname.length)
      next if nx >= 0 && masked[nx] == '('
      pv = prev_nonspace(masked, q - 1)
      # stored into a callback field of the gem (obj->field = param): the field takes mrb too (see the field forwarding)
      if pv >= 0 && masked[pv] == '=' && (fm = masked[[q - 80, 0].max...q].to_s[/(?:\.|->)[ \t\n]*([A-Za-z_]\w*)[ \t\n]*=[ \t\n]*\z/, 1]) &&
         fnptr_field_names.include?(fm)
        (@store_fields ||= Hash.new { |h, kk| h[kk] = [] })[[fname, k]] << fm
        next
      end
      if pv >= 0 && masked[pv] == '*'
        pv2 = prev_nonspace(masked, pv - 1)
        if pv2 >= 0 && masked[pv2] == '('
          cl = next_nonspace(masked, q + pname.length)
          next if cl >= 0 && masked[cl] == ')' && (nn = next_nonspace(masked, cl + 1)) >= 0 && masked[nn] == '('
        end
      end
      ec = enclosing_call(masked, q)
      return false if ec.nil?
      open_pos, close_pos, g, idx = ec
      return false unless @defs.key?(g) && g != fname
      return false unless pv >= 0 && '(,'.include?(masked[pv]) && nx >= 0 && ',)'.include?(masked[nx])
      return false unless non_retaining?(g, idx, depth + 1)
    end
    true
  end

  # true when the use at position s is a condition: the operand of if/while, of ! or of && / ||
  def condition_context?(rel, s)
    masked = @files[rel]['masked']
    p = prev_nonspace(masked, s - 1)
    return false if p < 0
    if masked[p] == '('
      j = prev_nonspace(masked, p - 1)
      return false if j < 0
      return !!(/(?:\bif|\bwhile)\z/.match(psl(masked, [j - 6, 0].max, j + 1)))
    end
    return true if masked[p] == '!'
    return true if masked[p] == '&' || masked[p] == '|'
    false
  end

  # an identifier the map turns into an RClass * expression (rb_cHash -> mrb->hash_class, rb_cNumeric -> mrb_class_get)
  def class_expr_ok
    lambda do |t|
      e = @entries[t]
      next false unless e.is_a?(Hash) && e['kind'] == 'expr' && e['mruby'].is_a?(String)
      e['mruby'].match?(/\Amrb->\w+_class\z/) || e['mruby'].match?(/\Amrb_class_get\(mrb, "[^"]+"\)\z/) ||
        e['mruby'].match?(/\Amrb_exc_get\(mrb, "[^"]+"\)\z/) || e['mruby'].match?(/\Amrb_module_get\(mrb, "[^"]+"\)\z/)
    end
  end

  # a helper name used as an argument of a defined function whose parameter does not keep it (see non_retaining?)
  def non_retaining_use?(rel, pos)
    ec = enclosing_call(@files[rel]['masked'], pos)
    return false if ec.nil?
    _o, _c, g, idx = ec
    # the callee's callback record must exist and be ok (the callback is threaded for it): without it the callee's
    # parameter keeps its C type while the helper gains mrb
    ok_rec = (@fnptr_recs || []).any? { |r| r[:ok] && r[:owner] == g && r[:pidx] == idx }
    ok_rec && @defs.key?(g) && non_retaining?(g, idx)
  end

  # The functions the runtime calls while it marks: the data type mark callbacks, and the helpers every call of which is
  # in such a function (transitively). rb_gc_mark is valid in these. A definition header or a prototype is not a call.
  def mark_context_names
    return @mark_ctx_names if @mark_ctx_names
    ctx = (@dtype_mark_names || Set.new).dup
    in_header = lambda do |name, orel, os|
      (@defs[name] || []).any? { |dd| dd['file'] == orel && dd['hstart'] && dd['hend'] && dd['hstart'] <= os && os < dd['hend'] } ||
        (@decls || []).any? { |dd| dd['name'] == name && dd['file'] == orel && dd['hstart'] && dd['hend'] && dd['hstart'] <= os && os < dd['hend'] }
    end
    changed = true
    while changed
      changed = false
      @defs.each_key do |name|
        next if ctx.include?(name)
        # a function's own recursive calls do not count: a helper is mark context when every outside call is in one
        occs = (@occ[name] || []).reject do |orel, os, _oe|
          in_header.call(name, orel, os) || (f0 = enclosing_func(orel, os)) && f0['name'] == name
        end
        next if occs.empty?
        if occs.all? { |orel, os, _oe| (f = enclosing_func(orel, os)) && ctx.include?(f['name']) }
          ctx << name
          changed = true
        end
      end
    end
    @mark_ctx_names = ctx
  end

  # CRuby converts a C integer to a VALUE implicitly (return f(x) in a VALUE function, where f returns int): mruby's mrb_value
  # is a struct, so the output does not compile. A return whose expression is a call of a defined function that returns a
  # C integer type is refused (the compile check finds the rest when it runs).
  INT_RET_RE = /\b(?:u?int(?:\d+_t)?|u?long|short|char|size_t|ssize_t|off_t|time_t|_Bool|bool|double|float)\b/
  def integer_return_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /(?<![#{WC}.>])return[ \t\n]+([A-Za-z_]\w*)[ \t\n]*\(/).each do
        m = Regexp.last_match
        callee = m[1]
        # return f(x) ? Qtrue : Qfalse is a truth test of the int, not the int returned (puma's HttpParser_is_finished)
        close_p = match_close(masked, m.end(0) - 1)
        next if close_p >= 0 && (nxc = next_nonspace(masked, close_p + 1)) >= 0 && masked[nxc] == '?'
        defs = (@defs[callee] || []).reject { |x| x['proto'] }
        next unless defs.size == 1 && defs[0]['ret']
        ret = defs[0]['ret'].to_s
        next if ret.include?('*')
        next unless ret.match?(INT_RET_RE) && !ret.match?(/\bVALUE\b/)
        fn = enclosing_func(rel, m.begin(0))
        if fn.nil? && define_at(rel, m.begin(0))
          # a return in a macro body: the functions that expand the macro return it
          name = define_at(rel, m.begin(0))[0]
          expanders = (@occ[name] || []).reject { |orel, os, _e| define_at(orel, os) }.map { |orel, os, _e| enclosing_func(orel, os) }
          next unless expanders.any? { |f| f && f['ret'].to_s.strip == 'VALUE' }
        else
          next if fn.nil? || fn['ret'].to_s.strip != 'VALUE'
        end
        refuse(rel, m.begin(0), callee, "stuck point (source bug): returns #{callee}'s #{ret} from a function that returns VALUE; CRuby converts the int implicitly to a bit pattern that is not a Ruby value (the source does not define the result), and mruby's mrb_value is a struct (accepted stuck point)")
      end
    end
  end

  # CRuby compares VALUEs with ==, which is identity. mruby's mrb_value is a struct here, so a == b is mrb_obj_equal(mrb, a, b)
  # (identity too). Both operands must be VALUE names of a function with the mruby state, or a Qnil/Qtrue/Qfalse/Qundef
  # constant; any other comparison is left as it is (the compile check refuses it when it does not compile).
  # the VALUE names declared in a macro body (VALUE a, b;) of a define span [name, start, end]
  def macro_value_names(rel, mac)
    body = psl(@files[rel]['masked'], mac[1], mac[2])
    names = Set.new
    body.scan(/(?<![#{WC}])VALUE(?![#{WC}])([^;{}()]*);/) do
      $1.split(',').each { |d| n = d.strip[/\A[A-Za-z_]\w*/]; names << n if n }
    end
    names
  end

  # assert(E) with E a VALUE member (p->stream) or a VALUE name: CRuby's assert tests that the word is nonzero, which has no
  # mruby equivalent (mrb_value is a struct). The argument is still evaluated, and the check is not made: the value is ((void)(E), 1).
  # The caveat is recorded in the refusal list's conversion notes (the rewrite line).
  # the VALUE variables declared at file scope in a file (static VALUE x = ...;)
  # a position in text the build leaves out (an inactive #if branch): its declarations are not file-scope names
  # An object-like alias of rb_gc_mark, #define NAME rb_gc_mark (the mark of an active #define: date's rb_gc_mark_movable, oj's mark).
  # When NAME is itself a mapped mark call (api_map gc_mark_context, e.g. rb_gc_mark_movable), the alias is dead: its uses convert
  # through NAME's entry, so the define goes. Otherwise NAME becomes the function-like macro NAME(x) mrb_gc_mark_value(mrb, x), when
  # every use of NAME is in a mark callback (the same test as a call in a macro body). Returns false when neither applies.
  def gc_mark_alias_fix(rel, s)
    dl = define_at(rel, s)
    return false unless dl
    name, a, b = dl[0], dl[1], dl[2]
    text = @files[rel]['text']
    body = text[a...b].to_s
    return false unless body.match?(/\A[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(name)}[ \t]+rb_gc_mark[ \t]*(\/\*.*\*\/[ \t]*)?\z/m)
    return false if inactive_text_at?(rel, a)
    ent = @entries[name]
    # the uses the macro changes: this file's text after the define (a #define is file-local and applies from its line on)
    uses = (@occ[name] || []).select { |orel, os, _oe| orel == rel && b <= os }
    if ent.is_a?(Hash) && ent['gc_mark_context']
      ed = @edits[rel]
      ed.drop(ed.overlapping(a, b))
      @refusals.reject! { |r| r['file'] == rel && r['api'] == 'rb_gc_mark' && r['pos'] == s }
      ed.add(a, b, '')
      rewrite(rel, a, 'rb_gc_mark', name, "the alias #define #{name} rb_gc_mark is dropped: #{name} is a mapped mark call (its uses convert through its entry)")
      return true
    end
    return false unless !uses.empty? && uses.all? { |orel, os, _oe| (uf = enclosing_func(orel, os)) && mark_context_names.include?(uf['name']) }
    ed = @edits[rel]
    ed.drop(ed.overlapping(a, b))
    @refusals.reject! { |r| r['file'] == rel && r['api'] == 'rb_gc_mark' && r['pos'] == s }
    ed.add(a, b, "#define #{name}(x) mrb_gc_mark_value(mrb, x)")
    rewrite(rel, a, 'rb_gc_mark', "#{name}(x) mrb_gc_mark_value(mrb, x)", "the alias #define #{name} rb_gc_mark is a function-like mark macro: every use is in a mark callback, which has the state")
    true
  end

  def inactive_text_at?(rel, pos)
    (@excluded_spans&.[](rel) || []).any? { |a, z| a <= pos && pos <= z }
  end

  def file_scope_value_names(rel)
    @fs_value_names ||= {}
    @fs_value_names[rel] ||= begin
      out = Set.new
      value_decl_statements(@files[rel]['masked']).each do |_st, _kw, decls|
        decls.each do |d|
          next if inactive_text_at?(rel, d[:start])
          out << d[:name] if d[:name] && !d[:ptr] && enclosing_func(rel, d[:start]).nil?
        end
      end
      out
    end
  end

  # X = 0; where X is a VALUE struct member: CRuby's Qfalse is the zero word, so the 0 is mrb_false_value()
  def value_zero_assign_pass
    vfields = value_field_names
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /((?:->|\.)[A-Za-z_]\w*)[ \t\n]*(?<![=!<>+\-*\/%&|^])=(?!=)[ \t\n]*0(?![\w.])[ \t\n]*;/).each do
        m = Regexp.last_match
        field = m[1][/[A-Za-z_]\w*\z/]
        next unless vfields.include?(field) && enclosing_func(rel, m.begin(0))
        zpos = m.begin(0) + m[0].rindex('0')
        @edits[rel].add(zpos, zpos + 1, 'mrb_false_value()')
        rewrite(rel, zpos, field, "#{field} = mrb_false_value()", 'a literal 0 stored in a VALUE member is Qfalse (the zero word)')
      end
    end
  end

  # A prototype in a header that is copied (not converted, since several sources include it) still has CRuby types: its type
  # names are mapped with the same type map (ID -> mrb_sym, VALUE -> mrb_value, ...), unless another pass edits it.
  def header_prototype_types_pass
    @files.each do |rel, f|
      next if f['kind'] == 'src'
      text = f['text']
      @decls.each do |d|
        next unless d['file'] == rel && d['proto'] && d['hstart'] && d['hend']
        a = d['hstart']
        b = d['hend']
        next if @edits[rel].overlaps(a, b)
        decl = psl(text, a, b)
        mapped = map_types(decl, @types)
        @edits[rel].add(a, b, mapped) if mapped != decl
      end
    end
  end

  # A == or != between two VALUE expressions that the other passes do not rewrite whole (a call, a dereference, an assignment in
  # parentheses, a function result): CRuby compares VALUEs by identity, which is mrb_value_identical (stateless, in the fork). The
  # operands keep their own rewrites; only the operator and the two ends of the comparison are edited (insertions).
  # the file-scope VALUE names of every file (a global VALUE, declared extern in a header, is a VALUE in each file)
  def all_file_scope_value_names
    @all_fs_values ||= @files.keys.inject(Set.new) { |acc, fr| acc | file_scope_value_names(fr) }
  end

  # the names declared as a VALUE pointer (VALUE *p, mrb_value *p) in a function's parameters and body
  def value_pointer_names(fn)
    text = @files[fn['file']]['text']
    body = psl(text, fn['brace'], fn['body_end'] + 1).to_s
    params = fn['params'].to_s
    # an array of VALUEs (VALUE args[3]) decays to a VALUE pointer
    (body + ' ' + params).scan(/\b(?:VALUE|mrb_value)\s*\*\s*([A-Za-z_]\w*)|\b(?:VALUE|mrb_value)\s+([A-Za-z_]\w*)\s*\[/).map { |a, b| a || b }.to_set
  end

  # a call name whose result is a VALUE: a converted function returning VALUE, or a mapped API call whose mruby form or
  # template yields a VALUE (mrb_const_get*, mrb_obj_value(...)) (the rb_const_get_at family)
  def value_call_name?(name)
    defs = (@defs[name] || []).reject { |x| x['proto'] }
    return true if defs.any? && defs.all? { |x| x['ret'].to_s.strip == 'VALUE' }
    ent = @entries[name]
    return false unless ent.is_a?(Hash)
    return true if %w[const_get funcall].include?(ent['handler'])
    ent['template'].to_s.match?(/\Amrb_(?:obj_value\(|const_get)/) || ent['mruby'].to_s.match?(/\Amrb_const_get|_value\z/)
  end

  # a call whose result is a class pointer (struct RClass *): the mruby definitions and lookups of a class or module
  def class_result_call?(name)
    ent = @entries[name]
    return false unless ent.is_a?(Hash)
    ent['mruby'].to_s.match?(/\Amrb_(?:define_(?:class|module)(?:_under)?|class_get|module_get|exc_get)(?:\z|\()/)
  end

  # An owned class variable (struct RClass *) assigned the result of a VALUE-returning call: the class pointer of that result
  # (mrb_class_ptr around the call; the call's own rewrites stay).
  def owned_class_assign_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /(?<![#{WC}$.>])([A-Za-z_]\w*)[ \t\n]*=(?![=])[ \t\n]*(?=[A-Za-z_])/).each do
        m = Regexp.last_match
        name = m[1]
        next unless @class_vars.include?(name)
        rs = m.end(0)
        unless owns_class_var?(rel, m.begin(1), name)
          # an unowned class variable (a VALUE) assigned a class pointer result: the VALUE is the class's object. A local VALUE
          # is wrapped where it is converted, so this is for a file-scope variable
          fl = enclosing_func(rel, m.begin(1))
          next if fl && value_names_of(fl).include?(name)
          cm = masked[rs..].to_s.match(/\A([A-Za-z_]\w*)[ \t\n]*\(/)
          next unless cm && class_result_call?(cm[1])
          open = rs + cm[0].length - 1
          close = match_close(masked, open)
          next if close < 0
          after = next_nonspace(masked, close + 1)
          next unless after >= 0 && masked[after] == ';'
          # a class expression in a value position is already wrapped where it is converted
          next if @edits[rel].overlapping(rs, close + 1).any? { |_, _, t| t.to_s.include?('mrb_obj_value(') }
          next if @edits[rel].touches_strictly?(rs) || @edits[rel].touches_strictly?(close + 1)
          @edits[rel].add(rs, rs, 'mrb_obj_value(')
          @edits[rel].add(close + 1, close + 1, ')')
          next
        end
        # an owned class variable assigned a nil, undef or false constant is the null class pointer (as its declaration's Q
        # initializer is): the constant becomes 0
        qm = masked[rs..].to_s.match(/\A(Qnil|Qundef|Qfalse)[ \t\n]*;/)
        if qm
          next if @edits[rel].overlaps(rs, rs + qm[1].length)
          @edits[rel].add(rs, rs + qm[1].length, '0')
          next
        end
        cm = masked[rs..].to_s.match(/\A([A-Za-z_]\w*)[ \t\n]*\(/)
        next unless cm && value_call_name?(cm[1])
        open = rs + cm[0].length - 1
        close = match_close(masked, open)
        next if close < 0
        after = next_nonspace(masked, close + 1)
        next unless after >= 0 && masked[after] == ';'
        next if @edits[rel].touches_strictly?(rs) || @edits[rel].touches_strictly?(close + 1)
        @edits[rel].add(rs, rs, 'mrb_class_ptr(')
        @edits[rel].add(close + 1, close + 1, ')')
      end
    end
  end

  # the body of each function definition whose parameter list has no mrb_state *mrb: mrb-> becomes the global state's ->
  def global_mrb_arrows(text, gname)
    out = text.dup
    spans = []
    text.to_enum(:scan, /^[A-Za-z_][^\n;{}()]*\([^;{}]*\)[ \t]*\{/).each do
      m = Regexp.last_match
      next if m[0].include?('mrb_state')
      open = m.end(0) - 1
      depth = 0
      k = open
      while k < text.length
        c = text[k]
        if c == '{' then depth += 1
        elsif c == '}'
          depth -= 1
          break if depth.zero?
        end
        k += 1
      end
      spans << [open, k] if k < text.length
    end
    spans.reverse_each do |a, b|
      body = out[a..b]
      # mrb-> and the state passed as an argument (mrb_class_get(mrb, ...), a call's first argument) name the global
      out[a..b] = body.gsub(/(?<![\w$.>])mrb->/, "#{gname}->").gsub(/(?<=[(,\s])mrb(?=\s*[,)])/, gname)
    end
    out
  end

  # CRuby stores an ID in a VALUE (the cast (VALUE)rb_intern(...)) and reads it back with (ID)v. The fork's symbol is an
  # mrb_sym, carried in a value by mrb_symbol_value and read back by mrb_symbol: the two casts become those calls.
  def id_value_casts(text)
    out = text.dup
    loop do
      m = /\(mrb_value\)\s*mrb_intern\(/.match(out)
      break unless m
      start = m.begin(0)
      name_at = start + m[0].index('mrb_intern')
      close = match_close(out, m.end(0) - 1)
      break if close < 0
      out = out[0...start] + 'mrb_symbol_value(' + out[name_at..close] + ')' + out[(close + 1)..]
    end
    loop do
      m = /\(mrb_sym\)\s*([A-Za-z_]\w*)\(/.match(out)
      break unless m && value_call_name?(m[1])
      start = m.begin(0)
      name_at = start + m[0].index(m[1])
      close = match_close(out, m.end(0) - 1)
      break if close < 0
      out = out[0...start] + 'mrb_symbol(' + out[name_at..close] + ')' + out[(close + 1)..]
    end
    out
  end

  # A macro calls a helper by a pasted name (s##_trunc(v##s, &fr), with s = d giving d_trunc); when the converted helper takes the
  # state (@needs), the macro's call passes mrb, which is in scope where the macro is used
  def macro_paste_mrb(text)
    text.gsub(/^#define(?:[^\n]*\\\n)*[^\n]*/) do |blk|
      blk.gsub(/##([A-Za-z_]\w*)\(/) do
        m = Regexp.last_match
        # a function head (static ... name##_key(ojParser p)) is a definition, not a call
        next m[0] if m.pre_match.match?(/\bstatic\b[^(;{}]*\z/)
        suffix = m[1]
        needs = (@needs || Set.new).any? { |n| n.end_with?(suffix) }
        needs ? '##' + suffix + '(mrb, ' : m[0]
      end
    end
  end

  # a #define that generates a static function without the state parameter (DEFINE_DELEGATED_FUNCTION) names the global in
  # its expansion: the generated function is a stored callback, run inside a method call
  def global_macro_arrows(text, gname)
    text.gsub(/^#define(?:[^\n]*\\\n)*[^\n]*/) do |blk|
      next blk if blk.include?('mrb_state') || !blk.match?(/\bstatic\s+\w+\s+[\w#]+\s*\(/) || !blk.include?('{')
      blk.gsub(/(?<![\w$.>])mrb->/, "#{gname}->").gsub(/(?<=[(,\s])mrb(?=\s*[,)])/, gname)
    end
  end

  # A VALUE array (VALUE *args, the data of rb_protect) whose elements carry struct pointers, (T *)args[i], or which is itself
  # carried in a VALUE, (VALUE)args: the fork's VALUE is a struct, so neither has a form
  def value_pointer_array_stuck_pass
    @files.each_key do |rel|
      mv = @files[rel]['masked']
      mv.to_enum(:scan, /\(\s*(?!VALUE\b|mrb_value\b)(?:struct\s+[A-Za-z_]\w*|[A-Za-z_]\w*)\s*\*+\s*\)\s*([A-Za-z_]\w*)\s*\[/).each do
        m = Regexp.last_match
        nm = m[1]
        fn = enclosing_func(rel, m.begin(1))
        next unless fn && value_pointer_names(fn).include?(nm)
        next if @edits[rel].overlaps(m.begin(1), m.begin(1) + 1)
        # an element (args[i]) carrying a pointer is read with mrb_cptr: the element is the VALUE, its pointer is the CPTR value
        close_b = mv.index(']', m.end(1))
        if close_b && mv[m.end(1)...close_b].match?(/\A\s*\[[^\[\]\n]*\z/) && !@edits[rel].overlaps(m.begin(1), close_b + 1)
          @edits[rel].add(m.begin(1), m.begin(1), 'mrb_cptr(')
          @edits[rel].add(close_b + 1, close_b + 1, ')')
          next
        end
        refuse(rel, m.begin(1), nm, "stuck point (VALUE as pointer): #{nm} is a VALUE array (mrb_value *, the data of rb_protect), and an element cast to a struct pointer has no mruby form (the fork's VALUE is a struct, include/mruby/boxing_no.h)")
      end
      mv.to_enum(:scan, /\(\s*(?:VALUE|mrb_value)\s*\)\s*([A-Za-z_]\w*)(?![\w\[(])/).each do
        m = Regexp.last_match
        nm = m[1]
        fn = enclosing_func(rel, m.begin(1))
        next unless fn && value_pointer_names(fn).include?(nm)
        # the array's address carried in a VALUE (rb_protect's data): mrb_cptr_value of the array; the VALUE token is renamed
        items = @edits[rel].overlapping(m.begin(0), m.end(1))
        if items.all? { |a, b, t| t == 'mrb_value' && a >= m.begin(0) && b <= m.begin(1) } && !@edits[rel].overlaps(m.end(1), m.end(1) + 1)
          @edits[rel].drop(items)
          @edits[rel].add(m.begin(0), m.end(1), "mrb_cptr_value(#{mrb_tok(rel, m.begin(0))}, #{nm})")
          next
        end
        next if @edits[rel].overlaps(m.begin(1), m.begin(1) + 1)
        refuse(rel, m.begin(1), nm, "stuck point (VALUE as pointer): #{nm} is a VALUE array (mrb_value *), and a pointer cast to VALUE is a struct in the fork (include/mruby/boxing_no.h), which cannot hold an address")
      end
    end
  end

  # rb_enc_get gives a VALUE (the encoding name, mruby-encoding), but a field or variable declared rb_encoding * takes the
  # encoding pointer: an assignment of it to such a field is the Encoding stuck point (the fork has no rb_encoding)
  def encoding_pointer_assign_pass
    # the fork has rb_encoding (mrbgems/mruby-encoding), so an rb_encoding * is a real pointer: nothing to refuse
    return
    names = Set.new
    @files.each_value do |f|
      f['masked'].to_enum(:scan, /\brb_encoding\s*\*\s*([A-Za-z_]\w*)\s*[;,\[=)]/).each { names << Regexp.last_match(1) }
    end
    return if names.empty?
    @files.each_key do |rel|
      mv = @files[rel]['masked']
      # every use of an rb_encoding * variable as a value (passed to an encoding call, or stored in a VALUE array such as
      # (mrb_value[]){enc}) is the Encoding stuck point; its declaration (rb_encoding *enc;) is not a use
      names.each do |nm|
        mv.to_enum(:scan, /(?<![#{WC}.>$])#{Regexp.escape(nm)}(?![#{WC}])/).each do
          m = Regexp.last_match
          pre = mv[0...m.begin(0)]
          next if pre.match?(/\brb_encoding\s*\*\s*\z/) && mv[m.end(0)..].to_s.match?(/\A\s*[;,\[=)]/)
          refuse(rel, m.begin(0), nm, "stuck point (Encoding): #{nm} is an rb_encoding * (the encoding pointer of CRuby), used as a value; the fork has no Encoding (accepted stuck point)")
        end
      end
      mv.to_enum(:scan, /(?<![#{WC}])([A-Za-z_]\w*(?:\s*(?:->|\.)\s*[A-Za-z_]\w*)*)\s*=(?!=)\s*(rb_enc_get)\s*\(/).each do
        m = Regexp.last_match
        field = m[1].split(/\s*(?:->|\.)\s*/).last
        next unless names.include?(field)
        # refused at the assigned field: the rb_enc_get call itself is mapped (its template covers that text)
        next if @edits[rel].overlaps(m.begin(1), m.end(1))
        refuse(rel, m.begin(1), field, "stuck point (Encoding): rb_enc_get's result is assigned to #{field}, an rb_encoding * (the encoding pointer of CRuby); the fork has no Encoding (accepted stuck point)")
      end
      # rb_enc_get(...) as an argument of a function that takes an rb_encoding * (strscan's name_to_backref_number)
      mv.to_enum(:scan, /(?<![#{WC}])rb_enc_get\s*\(/).each do
        m = Regexp.last_match
        s0 = m.begin(0)
        callee = nil
        cpos = nil
        k = s0 - 1
        while k >= [s0 - 400, 0].max && callee.nil?
          if mv[k] == '(' && (c = match_close(mv, k)) > s0
            pre = mv[0...k].match(/([A-Za-z_]\w*)\s*\z/)
            if pre
              callee = pre[1]
              cpos = pre.begin(1)
            end
          end
          k -= 1
        end
        next unless callee
        defs = (@defs[callee] || [])
        next unless defs.any? { |d| d['params'].to_s.include?('rb_encoding') }
        # refused at the callee's name: the rb_enc_get call itself is covered by its template's edit
        next if @edits[rel].overlaps(cpos, cpos + callee.length)
        refuse(rel, cpos, callee, "stuck point (Encoding): rb_enc_get's result is passed to #{callee}, which takes an rb_encoding * (the encoding pointer of CRuby); the fork has no Encoding (accepted stuck point)")
      end
    end
  end

  # the caveat of a VALUE-returning call used as a truth value: mrb_test is false for nil, where CRuby's word test is true
  TRUTH_TEST_CAVEAT = 'mrb_test of a VALUE-returning call: nil and false are false (CRuby\'s word test takes nil as true); the helpers this converts return true or false'

  # !v on a VALUE, or !f(...) of a VALUE-returning function (date's f_nonzero_p is (!f_zero_p(x))): CRuby's ! tests the word (Qfalse is
  # zero); the fork's VALUE is a struct, and no exact test of it is expressed (the VALUE truth test)
  def value_not_stuck_pass
    @files.each_key do |rel|
      mv = @files[rel]['masked']
      fs_values = file_scope_value_names(rel)
      mv.to_enum(:scan, /(?<![!=<>\w$.>])!(?!=)\s*([A-Za-z_]\w*)\s*(\()?/).each do
        m = Regexp.last_match
        nm = m[1]
        if m[2]
          defs = (@defs[nm] || []).reject { |x| x['proto'] }
          next unless (defs.any? && defs.all? { |x| x['ret'].to_s.strip == 'VALUE' }) || value_call_name?(nm)
        else
          next unless (local_value_at?(rel, m.begin(1), nm) || fs_values.include?(nm)) && !@class_vars.include?(nm)
        end
        next if @edits[rel].overlaps(m.begin(0), m.begin(0) + 1)
        if m[2]
          # !f(...) of a VALUE-returning call: mrb_test of the result (nil and false are false)
          close = match_close(mv, m.end(0) - 1)
          # an earlier pass may have wrapped this call already (value_condition_operand_pass: the call next to !): one wrap
          already = @edits[rel].at_point(m.begin(1)).any? { |_a, _b, t| t.to_s.start_with?('mrb_test(') }
          next if already
          if close >= 0 && !@edits[rel].overlaps(m.begin(1), m.begin(1) + 1) && !@edits[rel].overlaps(close + 1, close + 2)
            @edits[rel].add(m.begin(1), m.begin(1), 'mrb_test(')
            @edits[rel].add(close + 1, close + 1, ')')
            rewrite(rel, m.begin(0), nm, "!mrb_test(#{nm}(...))", TRUTH_TEST_CAVEAT)
            next
          end
        end
        refuse(rel, m.begin(0), nm, "stuck point (VALUE truth test): !#{nm}#{m[2] ? '(...)' : ''} tests a VALUE, a struct in the fork (include/mruby/boxing_no.h); CRuby's ! tests the word (Qfalse is zero), which has no exact struct test")
      end
    end
  end

  # if (v) on a VALUE tests its word: CRuby's Qnil is a nonzero word, so the test is true for nil, which the fork's struct has no
  # exact test of (the same reason as the assert case); a VALUE struct cannot be a condition
  def value_if_truth_stuck_pass
    vfields = value_field_names
    @files.each_key do |rel|
      mv = @files[rel]['masked']
      fs_values = file_scope_value_names(rel)
      mv.to_enum(:scan, /(?<![#{WC}])if\s*\(\s*([A-Za-z_]\w*(?:\s*(?:->|\.)\s*[A-Za-z_]\w*)*)\s*\)/).each do
        m = Regexp.last_match
        path = m[1].split(/\s*(?:->|\.)\s*/)
        base = path.first
        field = path.length > 1 ? path.last : nil
        is_value = field ? if_field_value?(rel, m.begin(1), path, vfields) : (local_value_at?(rel, m.begin(1), base) || fs_values.include?(base)) && !@class_vars.include?(base)
        next unless is_value
        next if in_dead_init(rel, m.begin(1))
        next if @edits[rel].overlaps(m.begin(1), m.begin(1) + 1)
        # CRuby's if (v) is true for every word but Qfalse (0), so nil is true: mrb_false_p is the same test on the struct (false only)
        @edits[rel].add(m.begin(1), m.begin(1), '!mrb_false_p(')
        @edits[rel].add(m.end(1), m.end(1), ')')
        rewrite(rel, m.begin(1), field ? "#{base}->#{field}" : base, "!mrb_false_p(...)", 'if (v) on a VALUE: CRuby is true for every word but Qfalse, so nil is true; !mrb_false_p is that test (false only)')
      end
      # if (f(...)) of a VALUE-returning function: the whole condition is that VALUE
      mv.to_enum(:scan, /(?<![#{WC}])if\s*\(\s*([A-Za-z_]\w*)\s*\(/).each do
        m = Regexp.last_match
        nm = m[1]
        defs = (@defs[nm] || []).reject { |x| x['proto'] }
        next unless (defs.any? && defs.all? { |x| x['ret'].to_s.strip == 'VALUE' }) || value_call_name?(nm) || funcall_macro?(rel, nm)
        open = m.end(0) - 1
        close = match_close(mv, open)
        next if close < 0
        outer = match_close(mv, mv.index('(', m.begin(0)))
        next if outer < 0 || next_nonspace(mv, close + 1) != outer
        next if @edits[rel].overlaps(m.begin(1), m.begin(1) + 1)
        # if (f(...)) of a VALUE-returning call: the condition is mrb_test of the result (nil and false are false)
        next if @edits[rel].overlaps(close + 1, close + 2)
        # an earlier pass (value_truth_call_pass: a macro funcall in an if) may have wrapped it: one wrap
        next if @edits[rel].at_point(m.begin(1)).any? { |_a, _b, t| t.to_s.start_with?('mrb_test(') }
        @edits[rel].add(m.begin(1), m.begin(1), 'mrb_test(')
        @edits[rel].add(close + 1, close + 1, ')')
        rewrite(rel, m.begin(1), nm, "mrb_test(#{nm}(...))", TRUTH_TEST_CAVEAT)
      end
    end
  end

  # CRuby returns an ID where a VALUE is returned, and a VALUE where an ID is: the fork's symbol is an mrb_sym carried in a value by
  # mrb_symbol_value, read back by mrb_symbol. In a function returning VALUE, return NAME of an ID NAME is mrb_symbol_value(NAME);
  # in a function returning ID, return f(...) of a VALUE-returning call f is mrb_symbol(f(...)).
  def id_return_pass
    @defs.values.flatten.each do |d|
      next if d['proto'] || !d['brace'] || !d['body_end']
      rel = d['file']
      masked = @files[rel]['masked']
      ret = d['ret'].to_s.strip
      next unless ret == 'VALUE' || ret == 'ID'
      bstart = d['brace'] + 1
      body = masked[bstart...d['body_end']].to_s
      header_ids = (d['params'].to_s + ' ' + body).scan(/\bID\s+([A-Za-z_]\w*)/).flatten.to_set
      if ret == 'VALUE'
        body.to_enum(:scan, /\breturn\s+([A-Za-z_]\w*)\s*;/).each do
          m = Regexp.last_match
          nm = m[1]
          next unless header_ids.include?(nm)
          s = bstart + m.begin(1)
          e = bstart + m.end(1)
          next if @edits[rel].overlaps(s, e)
          @edits[rel].add(s, e, "mrb_symbol_value(#{nm})")
        end
      else
        body.to_enum(:scan, /\breturn\s+([A-Za-z_]\w*)\s*\(/).each do
          m = Regexp.last_match
          cn = m[1]
          next unless value_call_name?(cn)
          cs = bstart + m.begin(1)
          open = bstart + m.end(0) - 1
          close = match_close(masked, open)
          next if close < 0
          next if @edits[rel].touches_strictly?(cs) || @edits[rel].touches_strictly?(close + 1)
          @edits[rel].add(cs, cs, 'mrb_symbol(')
          @edits[rel].add(close + 1, close + 1, ')')
        end
      end
    end
  end

  # rb_id2name(v) of a VALUE symbol v (CRuby takes the ID; a symbol VALUE is passed where it is wanted): the fork's symbol is read
  # from the value with mrb_symbol, so the argument becomes mrb_symbol(v)
  def id_arg_of_value_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /\brb_id2name\s*\(\s*([A-Za-z_]\w*)\s*\)/).each do
        m = Regexp.last_match
        fn = enclosing_func(rel, m.begin(0))
        next unless fn && value_names_of(fn).include?(m[1])
        s = m.begin(1)
        e = m.end(1)
        next if @edits[rel].overlaps(s, e) || @edits[rel].touches_strictly?(s) || @edits[rel].touches_strictly?(e)
        @edits[rel].add(s, s, 'mrb_symbol(')
        @edits[rel].add(e, e, ')')
      end
    end
  end

  # The Onigmo regexp engine of CRuby (its types, its match region and regex, its functions and constants): the fork has no
  # regexp engine, so each use of its names is a stuck point, marked where it is used (the functions that hold them are not
  # buildable without it)
  ONIG_STUCK_TYPES_PRELUDE = <<~C
    #ifndef NFCX_STUCK_TYPES_H
    #define NFCX_STUCK_TYPES_H
    /* BC2CPP-MRBGEM: placeholder types for CRuby's Onigmo and Encoding declarations (the fork has neither). Only stubs use them. */
    typedef unsigned char UChar;
    typedef unsigned char OnigUChar;
    typedef long OnigPosition;
    typedef void *OnigRegex;
    typedef void *regex_t;
    typedef struct nfcx_onig_regs { int allocated; int num_regs; OnigPosition *beg; OnigPosition *end; } OnigRegion;
    struct re_registers { int allocated; int num_regs; OnigPosition *beg; OnigPosition *end; };
    #endif
  C
  PLACEHOLDER_APIS = %w[UChar OnigUChar OnigPosition OnigRegex regex_t OnigRegion re_registers].freeze

  # a file whose declarations name a stuck type gets the placeholder prelude (see ONIG_STUCK_TYPES_PRELUDE)
  def needs_placeholder_prelude?(f)
    # the Onigmo names are declared by the fork's mruby/onigmo.h (ruby/re.h maps there), and rb_encoding and ruby/encoding.h by
    # the fork's mruby/encoding.h: no placeholder is needed for them. The prelude stays for a name the fork declares nowhere.
    false
  end
  ONIG_NAME_RE = /(?<![#{WC}.>])(OnigUChar|OnigRegion|OnigRegex|OnigPosition|OnigEncoding|OnigOptionType|OnigCaptureTreeNode|regex_t|re_registers|UChar|ONIG_[A-Z0-9_]+|onig_[a-z0-9_]+)(?![#{WC}])/
  def onig_engine_stuck_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, ONIG_NAME_RE).each do
        m = Regexp.last_match
        name = m[1]
        next if @defs[name] || @entries[name] || @types.key?(name)
        s, e = m.begin(1), m.end(1)
        next if @edits[rel].overlaps(s, e)
        refuse(rel, s, name, "stuck point (regexp engine): #{name} is CRuby's Onigmo regexp engine (its match region, regex and functions); the fork has no regexp engine (no regexp mrbgem in mrbgems/), so it has no mruby form")
      end
    end
  end

  # (T *)v where v is a VALUE that carries a pointer (CRuby's rb_protect and rb_ensure data: msgpack's
  # msgpack_packer_try_calling_proc casts its VALUE to a struct pointer): the pointer is read with mrb_cptr, as the ensure
  # data of the callbacks is (api_ensure_ptr). Runs last, so a cast the passes above convert is left alone.
  def value_to_pointer_cast_pass
    @files.each_key do |rel|
      mv = @files[rel]['masked']
      fs_values = file_scope_value_names(rel)
      tp = pointer_typedef_names.to_a
      pats = [/\(\s*(?:struct\s+[A-Za-z_]\w*|[A-Za-z_]\w*)\s*\*+\s*\)\s*([A-Za-z_]\w*)(?![\w(\[])/]
      pats << /\(\s*(?:#{tp.map { |t| Regexp.escape(t) }.join('|')})\s*\)\s*([A-Za-z_]\w*)(?![\w(\[])/ unless tp.empty?
      pats.each do |pat|
      mv.to_enum(:scan, pat).each do
        m = Regexp.last_match
        nm = m[1]
        next unless local_value_at?(rel, m.begin(1), nm) || fs_values.include?(nm)
        next if in_dead_init(rel, m.begin(1)) || @edits[rel].overlaps(m.begin(1), m.end(1))
        # the third parameter of a rb_hash_foreach callback is already the void * it was given (the threading above): no mrb_cptr
        fnv = enclosing_func(rel, m.begin(1))
        next if fnv && (@hash_cb_names || Set.new).include?(fnv['name']) &&
                (fnv['params'] || '').split(',')[2].to_s.split.last.to_s.delete('*') == nm
        @edits[rel].add(m.begin(1), m.begin(1), 'mrb_cptr(')
        @edits[rel].add(m.end(1), m.end(1), ')')
      end
      end
    end
  end

  # (VALUE)0 is CRuby's Qfalse as a cast (a macro body such as msgpack's NO_MAPPED_STRING): the fork's VALUE is a struct, so the
  # cast of 0 is not valid; it becomes mrb_false_value(), in function bodies and in macro bodies alike
  def value_cast_zero_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /\(\s*VALUE\s*\)\s*0\b/).each do
        m = Regexp.last_match
        s0, e0 = m.begin(0), m.end(0)
        # only in a macro body: a (VALUE)0 in a call is a sentinel of the call (rb_rescue2's argument list ends with one)
        next unless define_at(rel, s0)
        next if in_dead_init(rel, s0)
        # the cast's VALUE token may carry the type rename: the whole cast is replaced, so those edits go
        @edits[rel].drop(@edits[rel].overlapping(s0, e0))
        @edits[rel].add(s0, e0, 'mrb_false_value()')
      end
    end
  end

  # VALUE x = 0 (CRuby's Qfalse is the zero word): the local is initialized with mrb_false_value(), the fork's false
  def value_zero_init_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /\b(?:VALUE|mrb_value)[ \t\n]+[A-Za-z_]\w*[ \t\n]*=[ \t\n]*(0)[ \t\n]*[;,]/).each do
        m = Regexp.last_match
        s0 = m.begin(1)
        next unless enclosing_func(rel, s0)
        next if in_dead_init(rel, s0) || @edits[rel].overlaps(s0, s0 + 1)
        @edits[rel].add(s0, s0 + 1, 'mrb_false_value()')
      end
    end
  end

  # the body of an if whose condition is FIXNUM_P(nm) holds pos (the cast is in the fixnum branch of nm)
  def fixnum_guarded?(masked, nm, pos)
    masked.to_enum(:scan, /(?<![#{WC}])if[ \t]*\(/).any? do
      m = Regexp.last_match
      op = m.end(0) - 1
      cl = match_close(masked, op)
      next false if cl < 0 || cl > pos
      next false unless masked[(op + 1)...cl].to_s.match?(/\bFIXNUM_P[ \t]*\([ \t]*#{Regexp.escape(nm)}[ \t]*\)/)
      br = next_nonspace(masked, cl + 1)
      next false unless br >= 0 && masked[br] == '{' && br < pos
      match_close(masked, br) > pos
    end
  end

  # the function hashes the array (rb_memhash or st_hash* of arr, in its body)
  def hashed_array?(masked, fn, arr)
    body = masked[fn['brace'].to_i...fn['body_end'].to_i].to_s
    body.match?(/\b(?:rb_memhash|st_hash\w*)[ \t\n]*\([ \t\n]*#{Regexp.escape(arr)}\b/)
  end

  # (uintptr_t)v of a VALUE: CRuby's word as an integer (the fork's VALUE is a struct, with no integer form of the word)
  def value_cast_integer_stuck_pass
    @files.each_key do |rel|
      mv = @files[rel]['masked']
      fs_values = file_scope_value_names(rel)
      mv.to_enum(:scan, /\(\s*(?:uintptr_t|intptr_t|unsigned\s+long|long|unsigned\s+int|int|size_t|ID|st_index_t|st_data_t)\s*\)\s*([A-Za-z_]\w*)(?![\w(\[])/).each do
        m = Regexp.last_match
        nm = m[1]
        next unless (local_value_at?(rel, m.begin(1), nm) || fs_values.include?(nm)) && !@class_vars.include?(nm)
        next if in_dead_init(rel, m.begin(1)) || @edits[rel].overlaps(m.begin(0), m.begin(0) + 1)
        if fixnum_guarded?(mv, nm, m.begin(0))
          # inside if (FIXNUM_P(v)) { ... }: the integer the fixnum holds (CRuby's FIX2LONG). The hash of a fixnum is the same for
          # equal fixnums; the bits CRuby would cast are its tagged word, which nothing outside the process sees
          ed = @edits[rel]
          ed.drop(ed.overlapping(m.begin(0), m.end(0)))
          ed.add(m.begin(0), m.end(0), "mrb_fixnum(#{nm})")
          rewrite(rel, m.begin(0), "(#{m[0][/\(\s*([^)]*)\)/, 1].to_s.strip}) #{nm}", "mrb_fixnum(#{nm})",
                  'a fixnum-guarded cast: the integer the fixnum holds (FIX2LONG), inside if (FIXNUM_P(v)); CRuby casts the tagged word')
          next
        end
        refuse(rel, m.begin(0), nm, "stuck point (VALUE as integer): #{nm} is a VALUE, a struct in the fork (include/mruby/boxing_no.h), and its word is read as an integer in CRuby; the fork has no integer form of it")
      end
      # an element of an integer hash array (st_index_t h[5]) assigned a VALUE-returning call: the word is stored as an integer
      # the array declarators of an st_index_t declaration, also after another declarator (st_index_t v, h[5];)
      int_arrays = Set.new
      mv.to_enum(:scan, /\bst_index_t\s+([^;{}]+);/).each do
        Regexp.last_match(1).split(',').each do |d|
          dm = d.match(/\A\s*\*?\s*([A-Za-z_]\w*)\s*\[/)
          int_arrays << dm[1] if dm
        end
      end
      int_arrays.each do |arr|
        mv.to_enum(:scan, /(?<![#{WC}])#{Regexp.escape(arr)}\s*\[[^\]\n]*\]\s*=\s*([A-Za-z_]\w*)\s*\(/).each do
          m = Regexp.last_match
          next unless value_call_name?(m[1]) || ((@defs[m[1]] || []).reject { |x| x['proto'] }.any? && (@defs[m[1]] || []).reject { |x| x['proto'] }.all? { |x| x['ret'].to_s.strip == 'VALUE' })
          next if in_dead_init(rel, m.begin(0)) || @edits[rel].overlaps(m.begin(0), m.begin(0) + 1)
          # an array that the function hashes (rb_memhash(arr, ...)): the VALUE is hashed, not stored as its word. A fixnum is its
          # integer, anything else its hash method (the value meaning of the hash, as d_lite_hash's nth branch takes it)
          fnh = enclosing_func(rel, m.begin(0))
          cl = match_close(mv, m.end(0) - 1)
          if fnh && cl > 0 && hashed_array?(mv, fnh, arr)
            ed = @edits[rel]
            rs = m.begin(1)
            ed.add(rs, rs, "nfcx_value_hash(#{mrb_tok(rel, rs)}, ")
            ed.add(cl + 1, cl + 1, ')')
            rewrite(rel, rs, m[1], 'nfcx_value_hash(mrb, call)',
                    "#{arr} is hashed (rb_memhash): #{m[1]}'s VALUE is hashed by value (its integer if a fixnum, else its hash method), not stored as its word")
            @prelude_done ||= Set.new
            at = define_at(rel, rs) ? define_at(rel, rs)[1] : (fnh['hstart'] || nil)
            if at && !@prelude_done.include?([rel, 'nfcx_value_hash'])
              @prelude_done << [rel, 'nfcx_value_hash']
              ed.add(at, at, "static long nfcx_value_hash(mrb_state *mrb, mrb_value v) {\n" \
                             "  if (mrb_fixnum_p(v)) return mrb_fixnum(v);\n" \
                             "  return mrb_fixnum(mrb_funcall_argv(mrb, v, mrb_intern_cstr(mrb, \"hash\"), 0, NULL));\n}\n")
            end
            next
          end
          refuse(rel, m.begin(0), arr, "stuck point (VALUE as integer): #{arr} is an integer array (st_index_t), and #{m[1]} returns a VALUE, a struct in the fork (include/mruby/boxing_no.h); the word has no integer form here")
        end
      end
    end
  end

  # A VALUE cast to a struct pointer (CRuby carries a struct pointer in a VALUE: (OO)ov, (ParseInfo)pip): the fork's VALUE is a
  # struct, so the cast does not compile. The target is a struct pointer, or a typedef of one.
  # The functions passed as the first argument of rb_protect(...) anywhere in the input: a rb_protect callback takes its data as
  # one VALUE (a pointer carried in it, when the caller passes the address of a struct)
  def protect_callback_name?(name)
    @protect_cb_names ||= begin
      names = Set.new
      @files.each_value do |f|
        # rb_protect's callback and rb_rescue2's body callback both take their data as one VALUE
        f['masked'].to_enum(:scan, /rb_(?:protect|rescue2?)\s*\(\s*([A-Za-z_]\w*)/).each { names << Regexp.last_match(1) }
      end
      names
    end
    @protect_cb_names.include?(name)
  end

  # the pointer typedef names of the input: typedef struct X *T;  and  typedef struct { ... } *T;
  def pointer_typedef_names
    @ptr_typedef_names ||= begin
      set = Set.new
      @files.each_value do |f|
        f['masked'].to_enum(:scan, /typedef\s+[^;{}]*\*\s*([A-Za-z_]\w*)\s*;|\}\s*\*\s*([A-Za-z_]\w*)\s*;/).each do
          set << (Regexp.last_match(1) || Regexp.last_match(2))
        end
      end
      set
    end
  end

  def value_struct_pointer_cast_pass
    ptr_typedefs = pointer_typedef_names
    @files.each_key do |rel|
      mv = @files[rel]['masked']
      fs_values = file_scope_value_names(rel)
      # a struct pointer carried in a VALUE: (VALUE)pi, where pi is declared as a struct pointer (CRuby passes such a pointer as
      # the data of rb_protect, rb_ensure, rb_hash_foreach)
      ptr_names = Set.new
      # a void * is a pointer too (a callback's context, carried in a VALUE by CRuby: GetParser((VALUE)ctx, ...))
      ptr_re = ptr_typedefs.empty? ? /(?:struct\s+[A-Za-z_]\w*|void)\s*\*+\s*([A-Za-z_]\w*)/ :
               /(?:struct\s+[A-Za-z_]\w*|void)\s*\*+\s*([A-Za-z_]\w*)|\b(?:#{ptr_typedefs.to_a.map { |t| Regexp.escape(t) }.join('|')})\b\s*\**\s*([A-Za-z_]\w*)/
      mv.to_enum(:scan, ptr_re).each { ptr_names << (Regexp.last_match(1) || Regexp.last_match(2)) }
      # any statement-level declaration of a pointer (Holder *h;, const char *s = ...): a pointer whatever its type's name
      decl_ptr_kw = %w[return else case goto sizeof do typedef VALUE mrb_value].freeze
      mv.to_enum(:scan, /(?:\A|[;{}(,])[ \t\n]*(?:const\s+)?([A-Za-z_]\w*)[ \t\n]*\*+[ \t\n]*([A-Za-z_]\w*)[ \t\n]*(?=[;=,)\[])/).each do
        m = Regexp.last_match
        ptr_names << m[2] unless decl_ptr_kw.include?(m[1])
      end
      mv.to_enum(:scan, /\(\s*(?:VALUE|mrb_value)\s*\)\s*([A-Za-z_]\w*)(?=\s*(?:[;,)\-.\[]|\z))/).each do
        m = Regexp.last_match
        nm = m[1]
        next unless ptr_names.include?(nm) && !local_value_at?(rel, m.begin(1), nm) && !fs_values.include?(nm)
        next if in_dead_init(rel, m.begin(1))
        # the cast's VALUE token is already renamed to mrb_value (the type mapping): that rename is replaced with the whole cast
        items = @edits[rel].overlapping(m.begin(0), m.end(1))
        next unless items.all? { |a, b, t| t == 'mrb_value' && a >= m.begin(0) && b <= m.begin(1) }
        @edits[rel].drop(items)
        # a pointer carried in a VALUE is a CPTR object in the fork: (VALUE)pi is mrb_cptr_value(mrb, pi) (the GC roots of a VALUE
        # that stores it are the converter's, as for any VALUE field)
        @edits[rel].add(m.begin(0), m.begin(1), "mrb_cptr_value(#{mrb_tok(rel, m.begin(0))}, ")
        @edits[rel].add(m.end(1), m.end(1), ')')
        rewrite(rel, m.begin(0), nm, "mrb_cptr_value(mrb, #{nm})", 'a pointer cast to VALUE is a CPTR object (mrb_cptr_value): the VALUE holds the address, and a VALUE stored in a C struct must be rooted')
      end
      mv.to_enum(:scan, /\(\s*(?:struct\s+[A-Za-z_]\w*\s*\*+|([A-Za-z_]\w*))\s*\)\s*([A-Za-z_]\w*)(?=\s*(?:[;,)\-.\[]|\z))/).each do
        m = Regexp.last_match
        target = m[1]
        next if target && !ptr_typedefs.include?(target)
        nm = m[2]
        next unless (local_value_at?(rel, m.begin(2), nm) || fs_values.include?(nm)) && !@class_vars.include?(nm)
        next if in_dead_init(rel, m.begin(2))
        next if @edits[rel].overlaps(m.begin(2), m.begin(2) + 1)
        # the third parameter of a rb_hash_foreach callback is the pointer it was given (the threading makes it void *): a cast of it is
        # a cast of a pointer, as yajl's yajl_encode_part_hash_i casts its iterator
        fnh = enclosing_func(rel, m.begin(2))
        next if fnh && (@hash_cb_names || Set.new).include?(fnh['name']) &&
                (fnh['params'] || '').split(',')[2].to_s.split.last.to_s.delete('*') == nm
        # the data of a rb_protect callback is the pointer it was given: the sole parameter, read back from the CPTR value
        # (nfcx_ptr_value at the call; the last pass inserts mrb_cptr at the cast)
        next if fnh && m[0].include?('*') && protect_callback_name?(fnh['name']) && fnh['params'].to_s.split(',').size == 1 &&
                fnh['params'].to_s.split.last.to_s.delete('*') == nm
        # a cast to a pointer typedef ((ParseInfo)x) is mapped by value_to_pointer_cast_pass (mrb_cptr of the VALUE), which runs last
      end
    end
  end

  # A VALUE local that CRuby uses only as a C integer (date's jd, t, nth: jd = m_jd(dat) stores an int in the VALUE, and
  # c_jd_to_civil(jd, ...) reads the word back as an int). The fork's VALUE is a struct with no integer form, so the local is
  # declared mrb_int instead, when every use of it is an integer use: a declaration or assignment from an integer (a literal, a
  # call with an integer return, or a cast to an integer type), a cast to an integer type, an argument at an integer parameter of
  # a function with one prototype, or a logical not. Any other use (a VALUE call, a return, an address, arithmetic on objects,
  # a comparison) keeps the local a VALUE, and its refusals stand. Only function-body locals are retyped, never parameters or
  # file-scope variables. The retyped set is computed before the passes, so value_names_of does not list those names.
  def int_local_retype_scan
    @int_locals = Set.new
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      stmts = value_decl_statements(masked)
      stmts.each do |st, kw_end, decls|
        fn = enclosing_func(rel, st)
        next unless fn && fn.key?('brace') && fn.key?('body_end')
        next if in_dead_init(rel, st) || @edits[rel].overlaps(st, kw_end)
        next if decls.empty? || decls.any? { |d| d[:name].nil? || d[:ptr] || d[:fn] }
        body_s = fn['brace']
        body_e = fn['body_end']
        next unless decls.all? { |d| d[:start] > body_s && d[:start] < body_e }
        names = decls.map { |d| d[:name] }
        # a type qualifier is not a declarator name (VALUE const v = f(): the parser reads const as the name)
        next if names.any? { |n| %w[const volatile restrict register static].include?(n) }
        next unless names.uniq.size == names.size
        next if names.any? { |n| names.count(n) > 1 }
        ok = names.all? { |n| int_local_uses_ok?(rel, masked, fn, n, decls) }
        next unless ok
        @edits[rel].add(st, kw_end, 'mrb_int')
        names.each { |n| @int_locals << [rel, body_s, n] }
        decls.each { |d| (@int_decl_pos ||= Set.new) << [rel, d[:start]] }
        rewrite(rel, st, 'VALUE', 'mrb_int', 'a VALUE local that CRuby uses only as a C integer (its word is the integer) is an mrb_int local: every use is an integer use')
      end
    end
  end

  INT_TYPE_WORDS = /\A(?:(?:unsigned|signed|const)\s+)*(?:u?int(?:\d+_t)?|u?long(?:\s+long)?|short|char|size_t|ssize_t|off_t|time_t|st_index_t|st_data_t|ID|uintptr_t|intptr_t|mrb_int)\z/

  def int_type_text?(t)
    return false if t.nil? || t.include?('*') || t.include?('[')
    INT_TYPE_WORDS.match?(t.to_s.strip.gsub(/\s+/, ' '))
  end

  def int_local_uses_ok?(rel, masked, fn, name, decls)
    body = masked[fn['brace']...fn['body_end']]
    decl_starts = decls.map { |d| d[:start] }.to_set
    re = /(?<![#{WC}.>])#{Regexp.escape(name)}(?![#{WC}])/
    uses = []
    body.to_enum(:scan, re).each { uses << (fn['brace'] + Regexp.last_match.begin(0)) }
    return false if uses.empty?
    uses.all? do |p|
      if decl_starts.include?(p)
        init = decl_initializer(masked, p + name.size)
        init.nil? || int_rhs?(init)
      elsif masked[p + name.size..] =~ /\A\s*=(?!=)/
        int_rhs?(assign_rhs(masked, p + name.size))
      elsif masked[0...p] =~ /\(\s*(?:[A-Za-z_]\w*\s*)+\)\s*\z/ && (ct = masked[0...p][/\(\s*((?:[A-Za-z_]\w*\s*)+)\)\s*\z/, 1]) && int_type_text?(ct) && masked[p + name.size..].match?(/\A\s*(?:[;,)\-+*\/<>=&|?:]|\z)/)
        true
      elsif masked[0...p] =~ /!\s*\z/ && masked[0...p] !~ /!=\s*\z/ && masked[p + name.size..].match?(/\A\s*(?:[;)&|?]|\z)/)
        true
      else
        int_arg_use?(rel, masked, p)
      end
    end
  end

  # the initializer after a declarator's name (VALUE jd = e, ...): the text up to the next ',' or ';' at depth 0, or nil
  def decl_initializer(masked, i)
    return nil unless masked[i..] =~ /\A\s*=(?!=)/
    assign_rhs(masked, i)
  end

  # the right-hand side of the assignment whose '=' follows position i: the text to the ';' or ',' at depth 0
  def assign_rhs(masked, i)
    j = masked.index('=', i) + 1
    depth = 0
    k = j
    while k < masked.length
      c = masked[k]
      if c == '(' || c == '[' then depth += 1
      elsif c == ')' || c == ']'
        break if depth.zero?
        depth -= 1
      elsif depth.zero? && (c == ';' || c == ',' || c == '{' || c == '}')
        break
      end
      k += 1
    end
    masked[j...k].strip
  end

  # a right-hand side that is an integer: a literal, or one call with an integer return (f(...) and nothing after it)
  def int_rhs?(t)
    return false if t.nil?
    s = t.strip
    return true if s.match?(/\A\(\s*(?:int|long|unsigned\s+int|unsigned\s+long|size_t|st_index_t)\s*\)\s*/) && int_rhs?(s.sub(/\A\(\s*[a-z_ ]+\s*\)\s*/, ''))
    return true if s.match?(/\A-?\d+[uUlL]*\z/)
    m = /\A([A-Za-z_]\w*)\s*\(/.match(s)
    return false unless m && s.end_with?(')')
    depth = 0
    s[m[0].size - 1..].each_char.with_index do |c, i|
      depth += 1 if c == '('
      depth -= 1 if c == ')'
      return false if depth.zero? && i < s[m[0].size - 1..].size - 1
    end
    defs = (@defs[m[1]] || [])
    !defs.empty? && defs.all? { |d| int_type_text?(d['ret'].to_s.strip) }
  end

  # the use at p is an argument of a call (name(...)) at a parameter with an integer type: the call has one prototype
  def int_arg_use?(rel, masked, p)
    depth = 0
    commas = 0
    i = p - 1
    while i >= 0
      c = masked[i]
      if c == ')' || c == ']' then depth += 1
      elsif c == '(' || c == '['
        return false if c == '['
        break if depth.zero?
        depth -= 1
      elsif c == ';' || c == '{' || c == '}' then return false
      elsif c == ',' && depth.zero? then commas += 1
      end
      i -= 1
    end
    return false if i < 0
    fname = masked[0...i][/([A-Za-z_]\w*)\s*\z/, 1]
    return false unless fname && !@entries[fname] && !define_at(rel, i)
    defs = (@defs[fname] || [])
    plists = defs.map { |d| (d['params'] || '').split(',', -1).map { |x| py_strip(x) } }.uniq
    return false unless plists.size == 1
    ptype = plists[0][commas]
    return false if ptype.nil? || ptype == 'void'
    toks = ptype.split
    toks.pop if toks.size >= 2 && toks.last.match?(/\A[A-Za-z_]\w*\z/)
    int_type_text?(toks.join(' '))
  end

  # A VALUE variable passed to a converted function whose parameter is not a VALUE, a pointer or a struct (an sid_t key, an
  # ID, an integer): CRuby passes the VALUE's word, and the fork's VALUE is a struct with no integer form of it
  def value_as_integer_arg_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      fs_values = file_scope_value_names(rel)
      masked.to_enum(:scan, /(?<![#{WC}>.])([A-Za-z_]\w*)\s*\(/).each do
        m = Regexp.last_match
        name = m[1]
        next if @entries[name] || @defs[name].nil? || @defs[name].empty?
        next if define_at(rel, m.begin(1))
        plists = @defs[name].map { |d| (d['params'] || '').split(',', -1).map { |p| py_strip(p) } }.uniq
        next unless plists.size == 1
        ptypes = plists[0]
        open_pos = m.end(0) - 1
        close_pos = match_close(masked, open_pos)
        next if close_pos < 0
        split_args(masked, open_pos, close_pos).each_with_index do |(s, e), i|
          ptype = ptypes[i]
          next if ptype.nil? || ptype.empty? || ptype == 'void'
          next if ptype.match?(/VALUE|mrb_value|\*|\[|\.\.\./)
          arg = masked[s...e].to_s.strip
          next unless arg.match?(/\A[A-Za-z_]\w*\z/)
          next unless (local_value_at?(rel, s, arg) || fs_values.include?(arg)) && !@class_vars.include?(arg)
          next if @edits[rel].overlaps(s, s + 1)
          if ptype.match?(/\bsid_t\b/)
            # an sid_t key is an identity key (oj's cache is keyed by the object): the VALUE's word, read through the union
            # (value.p, the same bits as value.i, value.f and value.sym: C's union reads), as an integer
            ed = @edits[rel]
            ed.drop(ed.overlapping(s, e))
            ed.add(s, e, "nfcx_value_word(#{arg})")
            rewrite(rel, s, arg, "nfcx_value_word(#{arg})", "a VALUE passed as an sid_t key: its word (the union's bits, the object's identity for a heap object) is the key")
            fn_v = enclosing_func(rel, s)
            at = define_at(rel, s) ? define_at(rel, s)[1] : (fn_v && fn_v['hstart'])
            if at
              @prelude_done ||= Set.new
              unless @prelude_done.include?([rel, 'nfcx_value_word'])
                @prelude_done << [rel, 'nfcx_value_word']
                ed.add(at, at, "static unsigned long long nfcx_value_word(mrb_value v) {\n  return (unsigned long long)(uintptr_t)v.value.p;\n}\n")
              end
            end
            next
          end
          refuse(rel, s, arg, "stuck point (VALUE as integer): #{arg} is a VALUE, a struct in the fork (include/mruby/boxing_no.h), passed as #{name}'s #{ptype} parameter, which takes the VALUE's word in CRuby; the fork has no integer form of it")
        end
      end
    end
  end

  # A relational comparison (<, >, <=, >=) of two VALUE expressions orders them by address (CRuby's class tables are searched
  # by VALUE). The fork's VALUE is a struct with no order: a stuck point, recorded with its reason.
  # == and != between two VALUEs compare the words in CRuby (identity: the same object, or the same immediate). The fork's VALUE is a
  # struct, so the comparison is mrb_value_identical(a, b) (src/object.c: the identity mrb_obj_eq uses), and != is its negation. A
  # plain struct == does not compile; both operands must be VALUE operands (value_operand?), as for the ordering comparisons.
  def value_identity_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /(?<![<>=!])(==|!=)(?!=)/).each do
        m = Regexp.last_match
        op_s, op_e = m.begin(1), m.end(1)
        next if in_dead_init(rel, op_s)
        next if masked[op_s - 1] == '#' || masked[[op_s - 8, 0].max...op_s].to_s.include?('#')
        fn = enclosing_func(rel, op_s)
        next unless fn
        value_names = value_names_of(fn) | all_file_scope_value_names
        l_start, l_text = left_operand(masked, op_s)
        r_end, r_text = right_operand(masked, op_e)
        next if l_text.nil? || r_text.nil? || l_text.empty? || r_text.empty?
        next unless value_operand?(l_text, value_names, value_field_names, rel, op_s) && value_operand?(r_text, value_names, value_field_names, rel, op_s)
        next if @edits[rel].touches_strictly?(op_s)
        l_end = op_s
        l_end -= 1 while l_end > 0 && masked[l_end - 1] =~ /\s/
        r_start = op_e
        r_start += 1 while r_start < masked.length && masked[r_start] =~ /\s/
        next if r_start > r_end || l_start >= l_end
        next if @edits[rel].overlaps(l_start, l_end) || @edits[rel].overlaps(r_start, r_end) || @edits[rel].overlaps(op_s, op_e)
        ed = @edits[rel]
        neg = m[1] == '!='
        ed.add(l_start, l_start, neg ? '!mrb_value_identical(' : 'mrb_value_identical(')
        ed.add(l_end, r_start, ', ')
        ed.add(r_end, r_end, ')')
        rewrite(rel, op_s, m[1], neg ? '!mrb_value_identical' : 'mrb_value_identical',
                'a VALUE comparison is identity (mrb_value_identical, the identity mrb_obj_eq uses): the same object or the same immediate')
      end
    end
  end

  # switch (TYPE(x)) with case labels of a data-object type (T_RATIONAL, T_REGEXP): such an object is told apart from the other
  # data objects by a type key (nfcx_type_key_<kind>: the kind's constant for the object, else the tag), and each label is that key.
  # A Rational is the mruby-rational data object (a class test); a Regexp is the mruby-onig-regexp data object (its data type).
  # The labels were refused in process and their refusal markers are removed here; the subject's TYPE is the key, not its tag.
  # A switch with labels of two such kinds is not rewritten (its labels stay refused): one key function per switch.
  SWITCH_KEY_KINDS = {
    'T_RATIONAL' => { 'const' => 'NFCX_TT_RATIONAL', 'fn' => 'nfcx_type_key_rational', 'gem' => 'mruby-rational' },
    'T_REGEXP' => { 'const' => 'NFCX_TT_REGEXP', 'fn' => 'nfcx_type_key_regexp', 'gem' => 'mruby-onig-regexp' }
  }.freeze

  def value_rational_switch_pass
    @switch_key_kind ||= {}
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /(?<![#{WC}])(T_RATIONAL|T_REGEXP)(?![#{WC}])/).each do
        m = Regexp.last_match
        kind = m[1]
        info = SWITCH_KEY_KINDS[kind]
        lab = m.begin(0)
        lab_e = m.end(0)
        before = masked[0...lab].to_s
        next unless before.match?(/(?<![#{WC}])case[ \t\n]+\z/)
        nx = next_nonspace(masked, lab_e)
        next unless nx >= 0 && masked[nx] == ':'
        # the innermost switch whose body holds the label
        sw = nil
        masked.to_enum(:scan, /(?<![#{WC}])switch[ \t]*\(/).each do
          sm = Regexp.last_match
          op = sm.end(0) - 1
          cl = match_close(masked, op)
          next if cl < 0 || cl > lab
          br = next_nonspace(masked, cl + 1)
          next unless br >= 0 && masked[br] == '{' && match_close(masked, br) > lab
          sw = [op, cl] if sw.nil? || op > sw[0]
        end
        next if sw.nil?
        subj = masked[(sw[0] + 1)...sw[1]].to_s.strip
        # the subject is TYPE(x) or rb_type(x) (the same type read: rb_type maps to mrb_type)
        sj = subj.match(/\A(TYPE|rb_type)[ \t]*\(/)
        next unless sj
        tp = masked.index(sj[1], sw[0] + 1)
        next if tp.nil? || tp >= sw[1]
        tlen = sj[1].length
        top = masked.index('(', tp)
        tc = match_close(masked, top)
        next if tc < 0 || tc >= sw[1]
        fn = enclosing_func(rel, lab)
        # the state token of this position (the parameter, or the file-scope state of a global-state helper: mrb_tok)
        next unless fn
        # one key function per switch: a switch already keyed by another kind keeps this label refused
        sw_kind = (@switch_key_kind[[rel, sw[0]]] ||= kind)
        next unless sw_kind == kind
        ed = @edits[rel]
        if @switch_key_kind[[rel, sw[0], :subject]].nil?
          @switch_key_kind[[rel, sw[0], :subject]] = true
          # the switch subject: TYPE(x) becomes the kind's key function (nfcx_type_key_<kind>(mrb, (x)))
          ed.drop(ed.overlapping(tp, tp + tlen))
          ed.add(tp, tp + tlen, "#{info['fn']}(#{mrb_tok(rel, tp)}, ")
          ed.add(tc + 1, tc + 1, ')')
        end
        # the label: the key of the kind; the refusal and its marker go
        ed.drop(ed.at_point(lab).select { |_a, _b, t| t.to_s.include?("REFUSED: #{kind}") })
        @refusals.reject! { |r| r['file'] == rel && r['api'] == kind && r['pos'] == lab }
        ed.drop(ed.overlapping(lab, lab_e))
        ed.add(lab, lab_e, info['const'])
        (@gem_deps ||= Set.new) << info['gem']
        rewrite(rel, lab, kind, info['const'], "a #{kind} label: the switch is on #{info['fn']}, which tells that data object (#{info['gem']}) from other data")
        # the helper, once per file and kind, before the enclosing function
        at = define_at(rel, lab) ? define_at(rel, lab)[1] : (fn['hstart'] || nil)
        next unless at
        @prelude_done ||= Set.new
        next if @prelude_done.include?([rel, info['fn']])
        @prelude_done << [rel, info['fn']]
        ed.add(at, at, switch_key_helper(kind, info))
      end
    end
  end

  # the key function of a data-object kind: its constant, and the test that tells the object (the state is taken, not used, for a
  # Regexp, whose test is the gem's data type)
  def switch_key_helper(kind, info)
    if kind == 'T_RATIONAL'
      "#define #{info['const']} (MRB_TT_MAXDEFINE + 1)\n" \
      "static int #{info['fn']}(mrb_state *mrb, mrb_value v) {\n" \
      "  if (mrb_type(v) == MRB_TT_DATA && mrb_class_defined(mrb, \"Rational\") &&\n" \
      "      mrb_obj_is_kind_of(mrb, v, mrb_class_get(mrb, \"Rational\"))) return #{info['const']};\n" \
      "  return (int)mrb_type(v);\n}\n"
    else
      "#include <mruby/onigmo.h>\n" \
      "#define #{info['const']} (MRB_TT_MAXDEFINE + 2)\n" \
      "static int #{info['fn']}(mrb_state *mrb, mrb_value v) {\n" \
      "  (void)mrb;\n" \
      "  if (mruby_onig_regexp_is(v)) return #{info['const']};\n" \
      "  return (int)mrb_type(v);\n}\n"
    end
  end

  # a VALUE-returning call that is an operand of && or || (or !) in an if or while condition: mrb_test of the call, as the call
  # that is the whole condition is (value_truth_call_pass). The call's own insertion points must be free (an earlier pass may
  # have wrapped it already).
  def value_condition_operand_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /(?<![#{WC}])([A-Za-z_]\w*)[ \t\n]*\(/).each do
        m = Regexp.last_match
        nm = m[1]
        next if %w[if while for switch return sizeof].include?(nm)
        defs = (@defs[nm] || []).reject { |x| x['proto'] }
        next unless (defs.any? && defs.all? { |x| x['ret'].to_s.strip == 'VALUE' }) || funcall_macro?(rel, nm)
        st = m.begin(1)
        cl = match_close(masked, m.end(0) - 1)
        next if cl < 0
        pre = prev_nonspace(masked, st - 1)
        post = next_nonspace(masked, cl + 1)
        next unless pre >= 0 && post >= 0
        next unless '(&|!'.include?(masked[pre]) && ')&|'.include?(masked[post])
        # a call that is the whole parenthesised condition (if (f(x)): '(' and ')') is not an operand: the if's own truth
        # test (value_truth_call_pass, value_if_truth_stuck_pass) is the one wrap
        next if masked[pre] == '(' && masked[post] == ')'
        ch, owner = innermost_open(masked, st)
        next unless ch == '(' && %w[if while].include?(owner)
        ed = @edits[rel]
        next if ed.at_point(st).any? || ed.at_point(cl + 1).any? || ed.overlaps(st, st + 1) || ed.overlaps(cl + 1, cl + 2)
        ed.add(st, st, 'mrb_test(')
        ed.add(cl + 1, cl + 1, ')')
        rewrite(rel, st, nm, "mrb_test(#{nm}(...))", TRUTH_TEST_CAVEAT)
      end
    end
  end

  def value_order_stuck_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /(?<![<>=!])(<=|>=|<|>)(?![<>=])/).each do
        m = Regexp.last_match
        op_s, op_e = m.begin(1), m.end(1)
        next if in_dead_init(rel, op_s)
        next if masked[op_s - 1] == '#' || masked[[op_s - 8, 0].max...op_s].to_s.include?('#')
        fn = enclosing_func(rel, op_s)
        next unless fn
        value_names = value_names_of(fn) | all_file_scope_value_names
        l_start, l_text = left_operand(masked, op_s)
        r_end, r_text = right_operand(masked, op_e)
        next if l_text.nil? || r_text.nil? || l_text.empty? || r_text.empty?
        next unless value_operand?(l_text, value_names, value_field_names, rel, op_s) && value_operand?(r_text, value_names, value_field_names, rel, op_s)
        next if @edits[rel].touches_strictly?(op_s)
        # ordered by address: each operand is its object address (mrb_value_addr, include/mruby/value.h). CRuby's tables that are
        # searched by VALUE are built and searched with this same order, so the search is consistent (the order is not CRuby's
        # value of an address, which nothing observes). The operands are the spans of the comparison.
        l_end = op_s
        l_end -= 1 while l_end > 0 && masked[l_end - 1] =~ /\s/
        r_start = op_e
        r_start += 1 while r_start < masked.length && masked[r_start] =~ /\s/
        next if r_start > r_end || l_start >= l_end
        next if @edits[rel].overlaps(l_start, l_end) || @edits[rel].overlaps(r_start, r_end)
        ed = @edits[rel]
        ed.add(l_start, l_start, 'mrb_value_addr(')
        ed.add(l_end, l_end, ')')
        ed.add(r_start, r_start, 'mrb_value_addr(')
        ed.add(r_end, r_end, ')')
        rewrite(rel, op_s, m[1], m[1], 'a VALUE is ordered by its object address (mrb_value_addr): the converted table is sorted and searched in the same order')
      end
    end
  end

  # A call returning a VALUE (rb_funcall and its family, mrb_funcall_argv) used as a truth value beside && or || is
  # tested as CRuby tests it: mrb_test(...) (nil and false are false, everything else true)
  def value_truth_call_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      # an operand after && or ||, or the first operand of an if or while condition
      masked.to_enum(:scan, /(?<![#{WC}])((?:&&|\|\|)[ \t\n]*|\b(?:if|while)[ \t\n]*\([ \t\n]*|![ \t\n]*\([ \t\n]*)(?=[A-Za-z_])/).each do
        m = Regexp.last_match
        rs = m.end(0)
        cm = masked[rs..].to_s.match(/\A([A-Za-z_]\w*)[ \t\n]*\(/)
        next unless cm
        ent = @entries[cm[1]]
        # a macro whose body is a funcall (date's f_ge_p: #define f_ge_p(x,y) rb_funcall(...)) is a funcall too
        macro_funcall = @files[rel]['text'].match?(/^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(cm[1])}\s*\([^)]*\)\s*(?:mrb_funcall|rb_funcall)/)
        next unless macro_funcall || (ent.is_a?(Hash) && (ent['mruby'].to_s.start_with?('mrb_funcall') || ent['template'].to_s.start_with?('mrb_funcall') || ent['handler'] == 'funcall'))
        open = rs + cm[0].length - 1
        close = match_close(masked, open)
        next if close < 0
        next if in_dead_init(rel, rs)
        # the call is a whole truth operand: what follows it ends the operand (a comparison or arithmetic on it is not a truth test)
        nxt_t = next_nonspace(masked, close + 1)
        next unless nxt_t >= 0 && (masked[nxt_t] == ')' || masked[nxt_t] == ';' || masked[nxt_t] == '?' || masked[nxt_t] == ',' ||
                                   masked[nxt_t, 2] == '&&' || masked[nxt_t, 2] == '||')
        next if @edits[rel].touches_strictly?(rs) || @edits[rel].touches_strictly?(close + 1)
        @edits[rel].add(rs, rs, 'mrb_test(')
        @edits[rel].add(close + 1, close + 1, ')')
      end
    end
  end

  # a VALUE funcall as the condition of ?: (date's f_ge_p(n, 69) ? 19 : 20): CRuby tests the word, and a boolean result is
  # exact under mrb_test (nil and false are false). Same funcall criteria as value_truth_call_pass; the call ends at the ?.
  def value_ternary_truth_pass
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      masked.to_enum(:scan, /(?<![#{WC}.>])([A-Za-z_]\w*)[ \t\n]*\(/).each do
        m = Regexp.last_match
        name = m[1]
        ent = @entries[name]
        macro_funcall = @files[rel]['text'].match?(/^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(name)}\s*\([^)]*\)\s*(?:mrb_funcall|rb_funcall)/)
        # a funcall macro, a funcall entry, or a converted function returning VALUE (date's f_ge_p helper)
        next unless macro_funcall || value_call_name?(name) || (ent.is_a?(Hash) && (ent['mruby'].to_s.start_with?('mrb_funcall') || ent['template'].to_s.start_with?('mrb_funcall') || ent['handler'] == 'funcall'))
        open = m.end(0) - 1
        close = match_close(masked, open)
        next if close < 0
        q = next_nonspace(masked, close + 1)
        next unless q >= 0 && masked[q] == '?'
        next if in_dead_init(rel, m.begin(0))
        next if @edits[rel].touches_strictly?(m.begin(0)) || @edits[rel].touches_strictly?(close + 1)
        @edits[rel].add(m.begin(0), m.begin(0), 'mrb_test(')
        @edits[rel].add(close + 1, close + 1, ')')
      end
    end
  end

  # the template uses mrb_class_ptr($k) on argument k (the argument is a VALUE there)
  def out_tmpl_uses_class_ptr?(tmpl, k)
    tmpl.to_s.include?("mrb_class_ptr($#{k})")
  end

  # the parameters of a function declared with a type other than VALUE or mrb_value (char *json, int n)
  def non_value_param_names(fn)
    (fn['params'] || '').to_s.split(',').each_with_object(Set.new) do |p, acc|
      q = py_strip(p)
      next if q.empty? || q.match?(/\b(?:VALUE|mrb_value)\b/) || q == 'void'
      acc << $1 if q =~ /([A-Za-z_]\w*)\s*\z/
    end
  end

  def value_compare_wrap_pass
    cmp_re = /(?<![=!<>])(==|!=)(?!=)/
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      text = @files[rel]['text']
      vfields = value_field_names
      masked.to_enum(:scan, cmp_re).each do
        m = Regexp.last_match
        op = m[1]
        op_s, op_e = m.begin(1), m.end(1)
        next if in_dead_init(rel, op_s)
        # the operator must not be inside an edit already (the equality pass rewrote this comparison, or another pass did)
        next if @edits[rel].overlaps(op_s, op_e)
        # a comparison in a macro body has no enclosing function: its operands are the macro's parameters and the file's VALUE names
        fn = enclosing_func(rel, op_s)
        next unless fn || define_at(rel, op_s)
        value_names = (fn ? value_names_of(fn) : Set.new) | all_file_scope_value_names
        l_start, l_text = left_operand(masked, op_s)
        r_end, r_text = right_operand(masked, op_e)
        next if l_text.nil? || r_text.nil? || l_text.empty? || r_text.empty?
        # a parameter of this function that is not a VALUE (char *json) shadows a file-scope VALUE of the same name
        value_names -= non_value_param_names(fn) if fn
        # a comparison with a definite VALUE (a Q constant or an mrb_*_value call) compares VALUEs: the other operand is one too
        # (CRuby compares VALUEs with ==; a member whose name is declared differently in other structs is not judged by name)
        strong = ->(t) { t.strip.match?(/\AQ(?:nil|true|false|undef)\z/) || t.strip.match?(/\Amrb_\w*_value\s*\(/) ||
                         (t.strip.match?(/\A[A-Za-z_]\w*\z/) && (e_s = @entries[t.strip]).is_a?(Hash) && e_s['kind'] == 'expr' &&
                          e_s['mruby'].to_s.match?(CLASS_EXPR_RE)) }
        # a dereference of a VALUE pointer (VALUE *argv, mrb_value *p) is a VALUE
        value_ptr = fn ? value_pointer_names(fn) : Set.new
        value_names = value_names | value_ptr.map { |n| "*#{n}" }
        # a literal 0 beside a VALUE is CRuby's Qfalse (the equality pass's rule): it becomes mrb_false_value()
        zero_l = l_text.strip == '0'
        zero_r = r_text.strip == '0'
        if zero_l || zero_r
          other = zero_l ? r_text : l_text
          next if fn && non_value_param_names(fn).include?(other.strip)
          next unless value_operand?(other, value_names, vfields, rel, op_s) || strong.call(other)
          zero_s, zero_e = zero_l ? [l_start, l_start + 1] : [r_end - 1, r_end]
          @edits[rel].add(zero_s, zero_e, 'mrb_false_value()') unless @edits[rel].touches_strictly?(zero_s)
        else
        next unless (value_operand?(l_text, value_names, vfields, rel, op_s) || strong.call(r_text)) &&
                    (value_operand?(r_text, value_names, vfields, rel, op_s) || strong.call(l_text))
        end
        # the insertions must not fall strictly inside another edit
        next if [l_start, r_end].any? { |q| @edits[rel].touches_strictly?(q) }
        @edits[rel].add(l_start, l_start, (op == '!=' ? '!' : '') + 'mrb_value_identical(')
        @edits[rel].add(op_s, op_e, ', ')
        @edits[rel].add(r_end, r_end, ')')
      end
    end
  end

  # the left operand of an operator at pos: [start, text] of the maximal expression ending before pos (balanced groups,
  # identifiers, member and address/deref prefixes; stops at a lower-precedence token or an unmatched open)
  def left_operand(masked, pos)
    i = prev_nonspace(masked, pos - 1)
    return [pos, nil] if i < 0
    start = nil
    loop do
      break if i < 0
      c = masked[i]
      if c == ')' || c == ']'
        open = c == ')' ? '(' : '['
        depth = 0
        k = i
        while k >= 0
          if masked[k] == c then depth += 1
          elsif masked[k] == open
            depth -= 1
            break if depth.zero?
          end
          k -= 1
        end
        return [pos, nil] if k < 0
        start = k
        i = prev_nonspace(masked, k - 1)
        # a call's name (or a cast's type) before the group is part of the operand
        if i >= 0 && masked[i] =~ /[#{WC}]/
          j = i
          j -= 1 while j >= 0 && masked[j] =~ /[#{WC}]/
          start = j + 1
          i = prev_nonspace(masked, j)
        end
      elsif masked[i] =~ /[#{WC}]/
        j = i
        j -= 1 while j >= 0 && masked[j] =~ /[#{WC}]/
        start = j + 1
        i = j
      else
        break
      end
      # a member or pointer access before the operand continues it
      k = i
      k -= 1 while k >= 0 && masked[k] =~ /\s/
      if k >= 1 && (masked[k - 1, 2] == '->' || masked[k] == '.')
        i = k - (masked[k] == '.' ? 1 : 2)
        i = prev_nonspace(masked, i)
        next
      end
      break
    end
    return [pos, nil] if start.nil?
    # a unary prefix (*x, &x, !x) before a plain operand is part of it when the operand is a deref
    st = start
    j = prev_nonspace(masked, st - 1)
    st = j if j >= 0 && masked[j] == '*' && (j == 0 || masked[j - 1] !~ /[#{WC})\]]/)
    [st, masked[st...pos].to_s.strip.sub(/\s*\z/, '')]
  end

  # the right operand of an operator ending at pos: [end, text] of the expression starting after pos (stops at a lower-precedence token)
  def right_operand(masked, pos)
    i = next_nonspace(masked, pos)
    return [pos, nil] if i < 0
    st = i
    depth = 0
    k = i
    while k < masked.length
      c = masked[k]
      if c == '(' || c == '[' then depth += 1
      elsif c == ')' || c == ']'
        break if depth.zero?
        depth -= 1
      elsif depth.zero?
        break if c =~ /[;,?:{}]/ || masked[k, 2] == '&&' || masked[k, 2] == '||' || masked[k, 2] == '==' || masked[k, 2] == '!=' || (c == '=' && masked[k + 1] != '=' && masked[k - 1] !~ /[=!<>]/)
      end
      k += 1
    end
    e = k
    e -= 1 while e > st && masked[e - 1] =~ /\s/
    [e, masked[st...e]]
  end

  # a VALUE operand: a VALUE name, a VALUE member, an *_value(...) call, a Q constant, a converted function that returns VALUE, or a
  # parenthesized assignment to a VALUE name. A literal 0 is left to the equality pass (CRuby's Qfalse).
  # a #define whose body is a funcall (rb_funcall or mrb_funcall...) in this file
  def funcall_macro?(rel, name)
    # (a macro whose body is a symbol of an ID, ID2SYM(...), is a VALUE too: the symbol is a VALUE in CRuby)
    @files[rel]['text'].match?(/^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(name)}\s*\([^)]*\)\s*(?:mrb_funcall|rb_funcall|ID2SYM)/)
  end

  # a function-like or object-like macro of any file of the gem whose body casts to VALUE (or is an mrb_value): its uses are VALUEs
  def value_macro?(name)
    @value_macro_cache ||= {}
    return @value_macro_cache[name] if @value_macro_cache.key?(name)
    @value_macro_cache[name] = @files.any? do |frel, f|
      next false unless f['masked']
      define_spans(frel).any? { |n, a, b| n == name && f['masked'][a..b].to_s.match?(/\(\s*VALUE\s*\)|\bmrb_value\b/) }
    end
  end

  def value_operand?(t, value_names, vfields, rel, pos)
    t = t.strip
    return true if t.match?(/\AQ(?:nil|true|false|undef)\z/)
    return true if t.match?(/\A[A-Za-z_]\w*\z/) && value_names.include?(t)
    return true if t.match?(/\A\*\s*[A-Za-z_]\w*\z/) && value_names.include?(t.delete(' \t'))
    return true if t.match?(/\A[A-Za-z_]\w*\z/) && @class_vars.include?(t)
    # a macro whose body is a VALUE cast (msgpack's NO_MAPPED_STRING is ((VALUE)0)) is a VALUE operand
    return true if t.match?(/\A[A-Za-z_]\w*\z/) && value_macro?(t)
    # a class constant (rb_cObject, mrb->object_class) outside a class argument is its VALUE (mrb_obj_value)
    if t.match?(/\A[A-Za-z_]\w*\z/) && (e = @entries[t]).is_a?(Hash) && e['kind'] == 'expr' && e['mruby'].to_s.match?(CLASS_EXPR_RE)
      return true
    end
    return true if t.match?(/(?:->|\.)[A-Za-z_]\w*\z/) && vfields.include?(t[/([A-Za-z_]\w*)\z/])
    return true if t.match?(/\A[A-Za-z_]\w*\s*\(/) && t.match?(/_value\s*\(/) && t.start_with?('mrb_')
    # a funcall of the fork returns a VALUE (mrb_funcall_argv(...) == mrb_fixnum_value(1))
    return true if t.match?(/\Amrb_funcall\w*\s*\(/)
    # a CRuby funcall (rb_funcall(...)) of the original is the same VALUE-returning call
    # a macro whose body is a funcall (date's f_denominator: #define f_denominator(x) rb_funcall(x, ...)) is a VALUE call too
    if (fm = t.match(/\A([A-Za-z_]\w*)\s*\(/)) && funcall_macro?(rel, fm[1])
      return true
    end
    return true if t.match?(/\Arb_funcall\w*\s*\(/)
    if (cm = t.match(/\A([A-Za-z_]\w*)\s*\(/))
      defs = (@defs[cm[1]] || []).reject { |x| x['proto'] }
      return true if defs.any? && defs.all? { |x| x['ret'].to_s.strip == 'VALUE' }
      # a mapped CRuby API call whose result is a VALUE (its template wraps a data or class object in mrb_obj_value)
      ent = @entries[cm[1]]
      # (a template that is a funcall of the fork, rb_rational_den: mrb_funcall_argv(...), yields a VALUE too)
      return true if ent.is_a?(Hash) && (ent['template'].to_s.start_with?('mrb_obj_value(', 'mrb_funcall') || ent['mruby'].to_s.end_with?('_value'))
    end
    if (am = t.match(/\A\(\s*([A-Za-z_]\w*)\s*=/))
      # the assigned call's result decides: a converted function that returns a non-VALUE (a Leaf pointer, an int) is not one
      rhs_call = t[am.end(0)..].to_s.match(/\A\s*([A-Za-z_]\w*)\s*\(/)
      if rhs_call && (rdefs = (@defs[rhs_call[1]] || []).reject { |x| x['proto'] }).any? &&
         rdefs.none? { |x| x['ret'].to_s.strip == 'VALUE' }
        return false
      end
      return true if value_names.include?(am[1])
    end
    false
  end

  def value_equality_pass
    qconst = /\AQ(?:nil|true|false|undef)\z/
    with_state = (@threaded_cands || Set.new) | (@valid_reg_names || Set.new)
    vfields = value_field_names
    @files.each_key do |rel|
      masked = @files[rel]['masked']
      operand = '[A-Za-z_]\w*(?:(?:->|\.)[A-Za-z_]\w*)*'
      # the right operand may be the literal 0 (CRuby's Qfalse is the zero word, so 0 compared with a VALUE is Qfalse)
      masked.to_enum(:scan, /(?<![#{WC}.>])(#{operand})[ \t\n]*(==|!=)[ \t\n]*(#{operand}|0(?![\w.]))(?![#{WC}(])/).each do
        m = Regexp.last_match
        a, op, b = m[1], m[2], m[3]
        s0, e0 = m.begin(0), m.end(0)
        next if qconst.match?(b) && (@q_done || Set.new).include?(m.begin(3))
        fn = enclosing_func(rel, s0)
        # a comparison in the body of a global macro (its expansions have the state, through the global name) is a value
        # comparison too: its VALUE names are the macro body's own declarations
        mac = fn.nil? ? define_at(rel, s0) : nil
        if fn.nil?
          next unless mac && ((@global_macro_spans || {})[rel] || []).any? { |x, _z| x == mac[1] }
        end
        value_names = fn ? value_names_of(fn) : macro_value_names(rel, mac)
        # a parameter of this function declared as a non-VALUE (char *json) is not a VALUE, whatever a class variable has the name
        nvp = fn ? non_value_param_names(fn) : Set.new
        is_value = lambda do |x|
          next true if qconst.match?(x) || x == '0'
          next false if x.match?(/\A[A-Za-z_]\w*\z/) && nvp.include?(x)
          # a tracked class variable is a VALUE (its mrb_obj_value wrap, made by the identifier pass)
          next true if x.match?(/\A[A-Za-z_]\w*\z/) && @class_vars.include?(x) && !value_names.include?(x)
          next value_names.include?(x) if x.match?(/\A[A-Za-z_]\w*\z/)
          # a member path is VALUE when its last member is declared VALUE in every struct that declares that name
          x.match?(/(?:->|\.)([A-Za-z_]\w*)\z/) && vfields.include?(x[/([A-Za-z_]\w*)\z/])
        end
        ok_a = is_value.call(a)
        ok_b = is_value.call(b)
        next unless ok_a && ok_b
        # a function without the mruby state compares identity with mrb_value_identical (the fork's stateless test)
        stateless = fn ? !with_state.include?(fn['name']) : false
        conv = ->(x) { x == '0' ? 'mrb_false_value()' : (qconst.match?(x) ? @entries[x]['mruby'] : (@class_vars.include?(x) && !value_names.include?(x) ? "mrb_obj_value(#{x})" : x)) }
        # the only edits allowed inside the comparison are the rewrites of its own Q-constant operands (Qundef becomes
        # mrb_undef_value()); the comparison replaces them with the same text, so they are dropped
        if @edits[rel].overlaps(s0, e0)
          operand_spans = []
          operand_spans << [m.begin(1), m.end(1), a] if qconst.match?(a) || (@class_vars.include?(a) && !value_names.include?(a))
          operand_spans << [m.begin(3), m.end(3), b] if qconst.match?(b) || b == '0' || (@class_vars.include?(b) && !value_names.include?(b))
          inner = @edits[rel].overlapping(s0, e0)
          own = inner.select do |x, y, t|
            operand_spans.any? { |os, oe, name| x >= os && y <= oe && t == conv.call(name) }
          end
          unless own.size == inner.size
            refuse(rel, s0, op, 'VALUE comparison inside a rewritten span (not supported)')
            next
          end
          @edits[rel].drop(own)
        end
        expr = stateless ? "mrb_value_identical(#{conv.call(a)}, #{conv.call(b)})" : "mrb_obj_equal(#{mrb_tok(rel, s0)}, #{conv.call(a)}, #{conv.call(b)})"
        expr = "!#{expr}" if op == '!='
        @edits[rel].add(s0, e0, expr)
      end
    end
  end

  # a return type with leading words that are object-like macros defined in the input as a storage class (VP_EXPORT is
  # #define VP_EXPORT static): those words are storage, not the type, so VP_EXPORT VALUE is VALUE
  def value_ret_after_storage_macros(d)
    words = d['ret'].to_s.split
    storage_macro = lambda do |w|
      @files.values.any? { |f| f['masked'].match?(/^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(w)}[ \t]+(?:static|extern|inline)\b/) }
    end
    words.shift while !words.empty? && storage_macro.call(words.first)
    words.join(' ')
  end

  # the file-scope variables the input defines (a line starting at column 0 with a declaration and '=' or ';'): the gem's own
  # names, not CRuby's (rb_redcarpet_method_names is a static array of the gem)
  def local_file_scope_names
    @local_file_scope_names ||= begin
      names = Set.new
      @files.each_value do |f|
        f['masked'].to_enum(:scan, /^(?:static|const|extern|volatile|unsigned|signed|struct|[A-Za-z_]\w*)(?:[ \t]+[A-Za-z_*][\w*]*)*[ \t\n*]+\*?[ \t]*([A-Za-z_]\w*)[ \t]*(?:\[[^\]\n]*\][ \t]*)*[=;]/).each do
          names << Regexp.last_match[1]
        end
      end
      names
    end
  end

  # the enumerators the input defines (enum { RUBY_VAL = 3, ... }): a name the gem defines is not a CRuby name, and the
  # enum stays in the output (its header is kept)
  def local_enumerators
    @local_enumerators ||= begin
      names = Set.new
      @files.each_value do |f|
        f['masked'].to_enum(:scan, /\benum\b[^{};]*\{([^{}]*)\}/).each do
          body = Regexp.last_match[1]
          body.split(',').each do |item|
            m = /\A\s*([A-Za-z_]\w*)/.match(item)
            names << m[1] if m
          end
        end
      end
      names
    end
  end

  # the member names declared VALUE in every struct of the input that declares them (a name declared with another type
  # anywhere is not VALUE: its comparison stays as it is)
  # whether the member chain path (base first, its fields after) of an if condition is a VALUE: resolved through the base's declared
  # struct type (struct T *base), member by member, so a field name declared VALUE in one struct and as a pointer or function
  # pointer in another is decided by its struct. nil when the chain does not resolve: the name set (vfields) decides then.
  def if_field_value?(rel, pos, path, vfields)
    fn = enclosing_func(rel, pos)
    tag = nil
    if fn
      masked = @files[rel]['masked']
      region = (fn['params'].to_s + "\n" + masked[fn['brace']...fn['body_end']].to_s)
      mm = region.match(/struct\s+(\w+)\s*\*\s*#{Regexp.escape(path[0])}\b/)
      tag = mm && mm[1]
    end
    r = nil
    if tag
      (1...path.length).each do |i|
        t = struct_member_type(tag, path[i])
        break if t.nil?
        if i == path.length - 1
          r = (t == :value)
        elsif t.is_a?(Array)
          tag = t[1]
        else
          break
        end
      end
    end
    return r unless r.nil?
    vfields.include?(path.last)
  end

  # the type of a member of struct tag: :value, [:struct, tag] for a struct value member, :other for any other member, nil when
  # the struct or the member is not found
  def struct_member_type(tag, field)
    @struct_bodies ||= {}
    body = (@struct_bodies[tag] ||= begin
      found = nil
      @files.each_value do |f|
        masked = f['masked']
        masked.to_enum(:scan, /struct[ \t\n]+#{Regexp.escape(tag)}[ \t\n]*\{/).each do
          mm = Regexp.last_match
          bc = match_close(masked, mm.end(0) - 1)
          found ||= masked[mm.end(0)...bc].to_s if bc > 0
        end
        break if found
      end
      found
    end)
    return nil unless body
    decl = top_level_decls(body).find do |d|
      d.match?(/\(\s*\*\s*#{Regexp.escape(field)}\s*\)/) || d.match?(/\b#{Regexp.escape(field)}\s*(?:\[[^\]]*\])?\s*\z/)
    end
    return nil unless decl
    return :other if decl.match?(/\(\s*\*\s*#{Regexp.escape(field)}\s*\)/) || decl.include?('*')
    return :value if decl.strip.match?(/\AVALUE\s+#{Regexp.escape(field)}\s*(?:\[[^\]]*\])?\z/)
    sm = decl.strip.match(/\Astruct[ \t\n]+(\w+)[ \t\n]+#{Regexp.escape(field)}\b/)
    return [:struct, sm[1]] if sm
    :other
  end

  # the declarations of a struct or union body at its top level (a nested body's ';' does not end the outer declaration)
  def top_level_decls(body)
    out = []
    cur = +''
    depth = 0
    body.each_char do |c|
      depth += 1 if c == '{'
      if c == ';' && depth == 0
        out << cur
        cur = +''
        next
      end
      cur << c if depth == 0
      depth -= 1 if c == '}'
    end
    out
  end

  def value_field_names
    return @value_fields if @value_fields
    value = Set.new
    other = Set.new
    @files.each_value do |f|
      masked = f['masked']
      # struct and union bodies: a union member is a field too (a name declared as a non-VALUE member anywhere is not a VALUE field)
      # (balanced: a body may hold a nested struct, whose braces are not the outer body's end; the outer body's declarations are
      # its top-level ones)
      masked.to_enum(:scan, /(?:struct|union)[ \t\n]*[A-Za-z_]?\w*[ \t\n]*\{/).each do
        bo = Regexp.last_match.end(0) - 1
        bc = match_close(masked, bo)
        next if bc < 0
        top_level_decls(masked[(bo + 1)...bc].to_s).each do |decl|
          # a function-pointer member (void (*name)(...)) is not a VALUE: its name is a non-VALUE field
          if (fp = decl.match(/\(\s*\*\s*([A-Za-z_]\w*)\s*\)/))
            other << fp[1]
            next
          end
          m = /\A\s*((?:(?:const|volatile|unsigned|signed|static)\s+)*[A-Za-z_]\w*(?:\s*\*)?)\s*\*?\s*([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\s*\z/.match(decl)
          next unless m
          if m[1].strip == 'VALUE' && !decl.include?('*')
            value << m[2]
          else
            other << m[2]
          end
        end
      end
    end
    @value_fields = value - other
  end

  # the names declared VALUE (not pointers) in a function: its parameters and its local declarations
  def value_names_of(fn)
    names = Set.new
    (fn['params'] || '').to_s.split(',').each do |p|
      m = /\bVALUE\s+([A-Za-z_]\w*)\s*\z/.match(p.strip)
      names << m[1] if m
    end
    if fn.key?('brace') && fn.key?('body_end')
      body = psl(@files[fn['file']]['masked'], fn['brace'], fn['body_end'] + 1)
      body.scan(/\bVALUE\s+([A-Za-z_]\w*)\s*[;=,)]/) { |m| names << m[0] }
      # every declarator of a VALUE declaration list in the body (VALUE a, b, c;): the statements are parsed once per file
      @vdecl_cache ||= {}
      stmts = (@vdecl_cache[fn['file']] ||= value_decl_statements(@files[fn['file']]['masked']))
      stmts.each do |_st, _kw, decls|
        decls.each do |d|
          next unless d[:name] && !d[:ptr] && !d[:fn] && d[:start] > fn['brace'] && d[:start] < fn['body_end']
          names << d[:name]
        end
      end
    end
    names.reject! { |n| @int_locals&.include?([fn['file'], fn['brace'], n]) } if fn.key?('brace')
    names
  end

  # The state a use inside function or macro position pos gets: the mrb parameter, or the file-scope global for a
  # global-state helper or a global macro body.
  def mrb_tok(rel, pos)
    fd = enclosing_func(rel, pos)
    return @global_name if fd && @global_helpers && @global_helpers.include?(fd['name'])
    return @global_name if in_global_macro?(rel, pos)
    # with the gem's Init, a function that has no state parameter reads the global (set by Init)
    if fd && (@init_defs || []).any? && !((@threaded_cands || Set.new) | (@valid_reg_names || Set.new) |
                                          (@init_defs || []).map { |d| d['name'] }.to_set).include?(fd['name'])
      return @global_name
    end
    'mrb'
  end

  def in_global_macro?(rel, pos)
    ((@global_macro_spans || {})[rel] || []).any? { |a, b| a < pos && pos < b }
  end

  # A registered method or Init with a global-state user saves the previous value on entry and restores it on each
  # return, so a nested state (a method that runs Ruby code in another state) sees its own state again afterwards.
  # The return expression is evaluated before the restore. A VALUE function that falls off its end is undefined in C
  # already, so it gets no restore; Init (void) gets one before its closing brace.
  def wrap_returns(rel, d, void)
    ed = @edits[rel]
    masked, text = @files[rel]['masked'], @files[rel]['text']
    g = @global_name
    finditer(/(?<![#{WC}])return(?![#{WC}])/, masked).each do |m|
      rs = m.begin(0)
      re = m.end(0)
      next if rs <= d['brace'] || rs >= d['body_end']
      depth = 0
      k = re
      semi = nil
      while k < masked.length
        ch = masked[k]
        if '([{'.include?(ch)
          depth += 1
        elsif ')]}'.include?(ch)
          depth -= 1
        elsif ch == ';' && depth == 0
          semi = k
          break
        end
        k += 1
      end
      next unless semi
      expr = py_strip(psl(text, re, semi))
      if expr.empty?
        ed.add(rs, rs, "{ #{g} = nfcx_bc2_old; ")
        ed.add(semi + 1, semi + 1, ' }')
      else
        ed.add(rs, re, '{ mrb_value nfcx_bc2_ret = (')
        ed.add(semi, semi + 1, "); #{g} = nfcx_bc2_old; return nfcx_bc2_ret; }")
      end
    end
    ed.add(d['body_end'], d['body_end'], " #{g} = nfcx_bc2_old; ") if void
  end

  # ---- stage 3: per-file rewrite -----------------------------------------
  def variadic_params(d)
    # (argc, argv, self) parameter names of a variadic (argc -1) method definition, or nil.
    # mruby calls every method as f(mrb, self) and hands the arguments over through mrb_get_args, so
    # the converted function reads them back with the "*" format into locals of the original names.
    params = d['params'].split(',', -1).map { |p| py_strip(p) }
    return nil unless params.size == 3
    m_argc = /\Aint#{SS1}([A-Za-z_][#{WC}]*)\z/.match(params[0])
    m_argv = /\AVALUE#{SS}\*#{SS}([A-Za-z_][#{WC}]*)\z/.match(params[1])
    m_self = /\AVALUE#{SS1}([A-Za-z_][#{WC}]*)\z/.match(params[2])
    return nil unless m_argc && m_argv && m_self
    [m_argc[1], m_argv[1], m_self[1]]
  end

  def param_names(d)
    names = Set.new
    d['params'].split(',', -1).each do |p|
      m = /([A-Za-z_][#{WC}]*)#{SS}(?:\[[^\]]*\]#{SS})*\z/.match(py_strip(p))
      names << m[1] if m
    end
    names
  end

  # returns [hdr, prologue, err]
  # the storage class of a declaration: its keywords, and the storage a leading object-like macro expands to (VP_EXPORT is
  # static): "static " or ""
  def storage_of(d)
    words = d['ret'].to_s.split
    macro_storage = []
    while !words.empty? && storage_macro_word(words.first)
      macro_storage << storage_macro_word(words.shift)
    end
    st = d['storage'].to_s
    st = "#{st.strip} " unless st.strip.empty?
    st + (macro_storage.empty? ? '' : macro_storage.join(' ') + ' ')
  end

  def storage_macro_word(w)
    @files.each_value do |f|
      m = f['masked'].match(/^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(w)}[ \t]+((?:static|extern|inline))\b/)
      return m[1] if m
    end
    nil
  end

  def registered_header(d)
    regs = @regs.select { |r| r['error'].nil? && r['func'] == d['name'] }
    n = regs[0]['argc']
    # the block is fetched by the wrapper when the body yields (rb_yield: the template names nfcx_block)
    yields = false
    if d['brace'] && d['body_end'] && @files[d['file']]
      yields = @files[d['file']]['masked'][d['brace']..d['body_end']].to_s.match?(/\b(?:rb_yield|RETURN_ENUMERATOR)\s*\(/)
    end
    return [nil, nil, "registered method must return VALUE (found #{py_repr(d['ret'])})"] if value_ret_after_storage_macros(d) != 'VALUE'
    if n == -1
      p = variadic_params(d)
      if p.nil?
        return [nil, nil, 'variadic registered method must take (int argc, VALUE *argv, VALUE self)' \
                          " (found #{py_repr(py_strip(d['params']))})"]
      end
      argc_n, argv_n, self_n = p
      hdr = "#{storage_of(d)}mrb_value #{d['name']}(mrb_state *mrb, mrb_value #{self_n})"
      # a yielding variadic method fetches the block too ("&": nil when there is none), as a fixed-arity one does
      if yields
        prologue = "\n  mrb_int nfcx_argc;\n  mrb_value *#{argv_n};\n  mrb_value nfcx_block;\n" \
                   "  mrb_get_args(mrb, \"*&\", &#{argv_n}, &nfcx_argc, &nfcx_block);\n  int #{argc_n} = (int)nfcx_argc;"
      else
        prologue = "\n  mrb_int nfcx_argc;\n  mrb_value *#{argv_n};\n  mrb_get_args(mrb, \"*\", &#{argv_n}, &nfcx_argc);" \
                   "\n  int #{argc_n} = (int)nfcx_argc;"
      end
      return [hdr, prologue, nil]
    end
    params = d['params'].split(',', -1).map { |p| py_strip(p) }
    if params.size != n + 1
      return [nil, nil, "registered method has #{params.size} parameters, arity #{n} needs #{n + 1}"]
    end
    names = []
    params.each do |p|
      mm = /\AVALUE#{SS1}([A-Za-z_][#{WC}]*)\z/.match(p)
      return [nil, nil, "parameter #{py_repr(p)} is not a plain VALUE"] unless mm
      names << mm[1]
    end
    hdr = "#{storage_of(d)}mrb_value #{d['name']}(mrb_state *mrb, mrb_value #{names[0]})"
    prologue = ''
    if yields
      # the block is the last argument of mrb_get_args: "&" takes it as a Proc value (nil when there is none)
      fmt = 'o' * n + '&'
      decl = n > 0 ? "mrb_value #{names[1..].join(', ')}, nfcx_block;" : 'mrb_value nfcx_block;'
      ptrs = (names[1..].map { |x| '&' + x } + ['&nfcx_block']).join(', ')
      prologue = "\n  #{decl}\n  mrb_get_args(mrb, \"#{fmt}\", #{ptrs});"
    elsif n > 0
      prologue = "\n  mrb_value #{names[1..].join(', ')};\n  mrb_get_args(mrb, \"#{'o' * n}\", #{names[1..].map { |x| '&' + x }.join(', ')});"
    end
    [hdr, prologue, nil]
  end

  # A CRuby #include that api_map.json maps (its "includes" key): the mruby headers it becomes, one per line, quoted or
  # angle-bracketed. "comment" follows a quoted include; "config_macro" (when the input's text uses it) is defined by
  # the converter, as CRuby's extconf would define it; "caveat" is recorded with the rewrite.
  def map_include(rel, m, ent, masked, ed)
    heads = ent['headers']
    repl = heads.map do |h|
      line = ent['quoted'] ? "#include \"#{h}\"" : "#include <#{h}>"
      line += "  /* #{ent['comment']} */" if ent['comment'] && ent['quoted']
      line
    end.join("\n")
    ed.add(m.begin(0), m.end(0), repl)
    cm = ent['config_macro']
    if cm && masked.include?(cm)
      # CRuby's extconf sets this macro; the code it guards is in the input, so the converter defines it.
      ed.add(0, 0, "#define #{cm} 1  /* set by the converter: #{ent['config_comment']} */\n")
      rewrite(rel, 0, cm, 'defined by converter', 'extconf config macro set on')
    end
    rewrite(rel, m.begin(0), m[0], repl.gsub("\n", ' | '), ent['caveat'])
  end

  def process(rel)
    f = @files[rel]
    text, masked, ed = f['text'], f['masked'], @edits[rel]
    # 1. includes (directives only; masked check skips commented-out ones)
    finditer(INC_RE, text).each do |m|
      next if masked[m.begin(0)] != '#'
      inc = m[1]
      # a directive that is rewritten here replaces its whole text. An edit already inside that text is dropped, since the
      # rewrite covers it: check_refs marks an identifier of the header name (ruby/encoding.h has the name encoding) as a
      # direct use of a registered method called encoding, and that marker would otherwise overlap this rewrite (apply
      # raises on any overlap, so only inputs that already failed are changed)
      if @includes.key?(inc) || DROP_INCLUDES.key?(inc) || inc == 'ruby/encoding.h'
        ed.drop(ed.overlapping(m.begin(0), m.end(0)))
      end
      if @includes.key?(inc)
        map_include(rel, m, @includes[inc], masked, ed)
      elsif DROP_INCLUDES.key?(inc)
        reason = DROP_INCLUDES[inc]
        ed.add(m.begin(0), m.end(0), "/* BC2CPP-MRBGEM dropped: #include <#{inc}> (#{reason}) */")
        @warnings << { 'file' => rel, 'line' => line_of(text, m.begin(0)), 'api' => "#include <#{inc}>", 'reason' => reason }
        warn "warning: #{rel}:#{line_of(text, m.begin(0))} dropped #include <#{inc}> (#{reason})"
      else
        if inc == 'ruby/encoding.h'
          # the fork's C encoding API (mrbgems/mruby-encoding, include/mruby/encoding.h) declares rb_encoding and the functions
          ed.add(m.begin(0), m.end(0), "#include <mruby/encoding.h>")
        elsif inc == 'ruby/io.h'
          refuse(rel, m.begin(0), "#include <#{inc}>", 'stuck point (IO): ruby/io.h declares the CRuby IO struct (rb_io_t) and its API; the fork has no binding for that struct (mruby-io has its own, different one) (accepted stuck point)')
        elsif inc == 'ruby/version.h'
          refuse(rel, m.begin(0), "#include <#{inc}>", 'stuck point (CRuby version): ruby/version.h gives the CRuby version (RUBY_API_VERSION_CODE, RUBY_VERSION), which the code uses to choose its paths; mruby has no such number, so the version to emulate is a decision (accepted stuck point)')
        else
          if inc.start_with?('ruby/internal/') || inc == 'ruby/atomic.h'
            refuse(rel, m.begin(0), "#include <#{inc}>", "stuck point (CRuby internal header): #{inc} is CRuby's internal API (its feature tests, static assertions and atomics), which has no form in the converted subset")
          else
            refuse(rel, m.begin(0), "#include <#{inc}>", 'CRuby header not in the supported subset')
          end
        end
      end
    end
    # 1b. a quoted include that names a header outside the extension directory ("../json.h": the converter reads only the
    # extension root, so the header is not in the output tree). The compile check stops at the first such include, so the
    # refusal is recorded here, at conversion time, for every such include in the file.
    finditer(/#[ \t]*include[ \t]*"([^"\n]+)"/, text).each do |m|
      next if masked[m.begin(0)] != '#'
      inc = m[1]
      next if include_in_tree?(rel, inc)
      next unless include_key(rel, inc).split('/').first == '..'
      refuse(rel, m.begin(0), "#include \"#{inc}\"",
             "include outside the extension directory: #{inc} (the converter reads only the extension root; the header is not in the output)")
    end
    # 2. function headers
    init_name = @init_defs.empty? ? nil : @init_defs[0]['name']
    @decls.each do |d|
      next if d['file'] != rel
      name = d['name']
      if @split_names.include?(name)
        split_decl(rel, d)
        next
      end
      hdr, pro, err = nil, '', nil
      # Only a function with a surviving registration gets the method signature. A refused registration
      # (e.g. no definition in the input) leaves its prototype as is; the refusal is already recorded.
      if @valid_reg_names.include?(name)
        hdr, pro, err = registered_header(d)
        pro = '' if d['proto']
      elsif d['name'] == (@init_defs.empty? ? nil : @init_defs[0]['name']) && !d['proto']
        hdr = "void mrb_#{@funcname}_gem_init(mrb_state *mrb)"
      elsif @helper_names.include?(name)
        ptxt = fnptr_param_text(name, py_strip(d['params']))
tail = ['', 'void'].include?(ptxt) ? '' : ', ' + map_types(ptxt, @types)
if (@hash_cb_names || Set.new).include?(name)
  # a rb_hash_foreach callback: its third (VALUE) parameter is the pointer it was given (void *)
  ps = ptxt.split(',').map(&:strip)
  vcb = (@hash_value_cbs || {})[name]
  tail = ', ' + [map_types(ps[0], @types), map_types(ps[1], @types), vcb ? "void *nfcx_data_#{vcb}" : 'void *' + ps[2].split.last].join(', ')
end
        hdr = "#{d['storage']}#{map_types(d['ret'], @types)} #{name}(mrb_state *mrb#{tail})"
      end
      if err
        refuse(rel, d['hstart'], name, err)
        next
      end
      next if hdr.nil?
      if d['proto']
        ed.add(d['hstart'], d['hend'], hdr)
      else
        # a registered method or Init of a gem that uses the global state saves and restores it (wrap_returns)
        if @global_wrap && (@valid_reg_names.include?(name) || name == init_name)
          g = @global_name
          pro = "\n  mrb_state *nfcx_bc2_old = #{g};\n  if (nfcx_bc2_old != NULL && nfcx_bc2_old != mrb) abort(); /* nested mruby state */\n  #{g} = mrb;" + pro
          wrap_returns(rel, d, name == init_name && !@valid_reg_names.include?(name))
        end
        ed.add(d['hstart'], d['hend'], hdr + ' ')
        ed.add(d['brace'] + 1, d['brace'] + 1, pro) unless pro.empty?
        rewrite(rel, d['hstart'], "#{d['name']}(...)", hdr)
      end
    end
    # 3. class variable declarations become struct RClass *
    # A VALUE parameter that has a class variable's name is an ordinary parameter (it shadows the class
    # variable in its function) and is left alone.
    # A VALUE declaration statement (VALUE a, b = f(x), c;) with a tracked class variable among its declarators: the class
    # declarators get a * (struct RClass *name), a leading VALUE becomes struct RClass when its declarator is a class, and a
    # change of type between two declarators is a ';' with the new type in place of the comma. The initializers keep their
    # text, so their calls are converted by the passes that own them. A declarator that is a VALUE parameter shadows the
    # class variable and stays VALUE.
    value_decl_statements(masked).each do |st, kw_end, decls|
      next if decls.none? { |d| d[:name] && @class_vars.include?(d[:name]) && !is_param(rel, d[:start], d[:name]) }
      next if decls.any? { |d| d[:name].nil? || d[:fn] }
      cls = decls.map { |d| d[:name] && @class_vars.include?(d[:name]) && !is_param(rel, d[:start], d[:name]) && owns_class_var?(rel, d[:start], d[:name]) }
      next if decls.zip(cls).any? { |d, c| c && d[:ptr] }
      ed.add(st, kw_end, 'struct RClass') if cls[0]
      decls.each_with_index do |d, i|
        ed.add(d[:start], d[:start], '*') if cls[i]
        next if i == 0
        if cls[i] != cls[i - 1]
          ed.add(d[:comma], d[:comma] + 1, cls[i] ? '; struct RClass' : '; mrb_value')
        end
      end
      decls.each_with_index do |d, i|
        next unless cls[i]
        @decl_name_pos << [rel, d[:start]]
        rewrite(rel, d[:start], "VALUE #{d[:name]}", "struct RClass *#{d[:name]}")
      end
    end
    # 4. helper call sites get the mrb argument
    header_spans = @decls.select { |d| d['file'] == rel }.map { |d| [d['hstart'], d['hend']] }
    # an object-like alias of a threaded helper (#define NewX helper) is called as the helper: its calls get the argument too
    alias_names = @files.values.flat_map { |f| f['text'].scan(/^[ \t]*#[ \t]*define[ \t]+([A-Za-z_]\w*)[ \t]+([A-Za-z_]\w*)[ \t]*$/) }
                        .select { |a, t| @helper_names.include?(t) && !@entries.key?(a) }.map(&:first)
    (@helper_names.to_a + alias_names).uniq.sort.each do |name|
      (@occ[name] || []).each do |orel, s, e|
        next if orel != rel || header_spans.any? { |a, b| a <= s && s < b }
        # a use in the text of an inactive definition (its #if is false in this build) stays as it is
        next if ((@excluded_spans || {})[rel] || []).any? { |a, z| a < s && s < z }
        next if masked[e..].to_s.match?(/\A[ \t\n]*\([^()]*\)[ \t\n]*\{/)
        po = next_nonspace(masked, e)
        next if po < 0 || masked[po] != '('
        pa = next_nonspace(masked, po + 1)
        t = mrb_tok(rel, s)
        # an alias call inside another rewritten span is that span's business (it is not threaded here)
        next if !@helper_names.include?(name) && @edits[rel].touches?(po + 1)
        ed.add(po + 1, po + 1, masked[pa] == ')' ? t : "#{t}, ")
        # a direct call of a VALUE-data callback passes its VALUE data by address (the callback reads it back)
        if (@hash_value_cbs || {}).key?(name)
          cargs = split_args(masked, po, close_of = match_close(masked, po))
          if cargs.size == 3
            a3, b3 = cargs[2]
            id3 = psl(@files[rel]['text'], a3, b3).strip
            qv = { 'Qnil' => 'mrb_nil_value()', 'Qtrue' => 'mrb_true_value()', 'Qfalse' => 'mrb_false_value()' }[id3]
            if qv
              # a Q constant has no address: a compound literal holds its value for the call
              ed.add(a3, b3, "(void *)&(mrb_value[]){#{qv}}")
            elsif id3.match?(/\A[A-Za-z_][#{WC}]*\z/)
              ed.add(a3, b3, "(void *)&#{id3}")
            end
          end
        end
      end
    end
    # 4b. a direct call of a split registered method calls its impl (the mrb argument, if any, is added above). A
    # use inside a registration is the wrapper's name, and stays.
    @split_names.to_a.sort.each do |name|
      (@occ[name] || []).each do |orel, s, _e|
        next if orel != rel || header_spans.any? { |a, b| a <= s && s < b }
        next if @regs.any? { |r| r['error'].nil? && r['file'] == rel && r['open'] <= s && s <= r['close'] }
        # a member access or a struct or union field named like the method is not a call of it
        mk = @files[rel]['masked']
        next if is_member(mk, s)
        ob = enclosing_open_brace(mk, s)
        next if ob && mk[[ob - 60, 0].max...ob].to_s.match?(/\b(?:struct|union)[ \t\n]*[A-Za-z_]?\w*[ \t\n]*\z/)
        ed.add(s, s + name.length, split_impl_name(name))
        rewrite(rel, s, name, split_impl_name(name))
      end
    end
# NORETURN( ) wrappers (noreturn_mask): the two tokens are removed; the declaration inside stays
(@files[rel]['noreturn'] || []).each do |start, open, close|
  # a prototype rewritten as a whole already lacks the opening token; when its rewrite also covers the closing parenthesis, the
  # closing token is not removed again (an overlap); otherwise the rewrite keeps the original ')' and it is removed here
  ed.add(start, open + 1, '') unless noreturn_in_rewritten_decl?(rel, start)
  ed.add(close, close + 1, '') unless ed.overlapping(close, close + 1).any?
end
    edit_fnptr_fields(rel)
    # 4c. a rb_data_type_t initializer is CRuby's {name, {dmark, dfree, dsize}, parent, data, flags}; mruby's
    # mrb_data_type is {name, dfree, mark} (the fork's mark hook). The whole initializer is one edit, so the identifiers
    # inside it are not converted again (the identifier pass skips overlapping ranges). The mark and free functions must
    # be threaded (they take (mrb, data)); the flags are dropped (RUBY_TYPED_* are 0 in mruby, with a caveat).
    dtype_decls.select { |drel, _dm, _di| drel == rel }.each do |drel, m, info|
      # a refused initializer keeps CRuby's members, which mruby's struct does not have, so each one fails the compile check
      # again. It is replaced by a stub that keeps the name and has NULL callbacks; the refusal given is the reason.
      stub = lambda do |why|
        refuse(rel, m.begin(0), 'rb_data_type_t', why)
        open = m.end(0) - 1
        close = match_close(@files[rel]['masked'], open)
        lit = @files[rel]['text'][open..close][/"(?:[^"\\\n]|\\.)*"/]
        ed.add(open, close + 1, "{ #{lit || 'NULL'}, NULL, NULL }")
      end
      if info['error']
        stub.call(info['error'])
        next
      end
      # mrb_free is mruby's library free, already (mrb, data): it needs no threading
      cbs = [info['mark'], info['free']].reject { |n| n == 'NULL' || n == '0' || n == 'mrb_free' }
      unless cbs.all? { |n| @threaded_cands.include?(n) }
        unthreaded = cbs.reject { |n| @threaded_cands.include?(n) }
        if unthreaded.all? { |n| openssl_guarded_definition?(n) }
          stub.call("stuck point (OpenSSL): the mark or free function #{unthreaded.join(', ')} is compiled only with OpenSSL, which mruby has no binding for (accepted stuck point)")
        else
          stub.call("the mark or free function #{unthreaded.join(', ')} is not threaded (it does not take the mruby state; see that function's own refusal)")
        end
        next
      end
      (@dtype_mark_names ||= Set.new) << info['mark'] unless info['mark'] == '0' || info['mark'] == 'NULL'
      mark = info['mark'] == '0' ? 'NULL' : info['mark']
      free = info['free'] == '0' ? 'NULL' : info['free']
      ed.add(m.begin(0), m.begin(0) + 'rb_data_type_t'.length, 'mrb_data_type')
      ed.add(info['open'], info['close'] + 1, "{ #{info['name']}, #{free}, #{mark} }")
      rewrite(rel, m.begin(0), 'rb_data_type_t', 'mrb_data_type',
              'the initializer is reordered to mruby\'s {name, dfree, mark}; RUBY_TYPED_* flags are dropped (0 in mruby)')
    end
    # 5. identifier pass. Local names: functions the input defines (a prototype alone does not count: it may declare a
    # CRuby API), class variables and the macros the input defines (scan_local_macros).
    local_syms = Set.new(@defs.keys) | @class_vars | @local_macros | local_enumerators | local_file_scope_names | local_macro_arg_names
    body_spans = @defs.values.flatten.select { |d| d['file'] == rel }.map { |d| [d['brace'], d['body_end']] }
    # text-inactive branches (#if 0, a #ifdef of a name this build defines or the gem #defines) are excluded like dead definitions
    text_inactive_spans(rel).each do |a, z|
      (@excluded_spans ||= {})[rel] ||= []
      @excluded_spans[rel] << [a, z]
    end
    # A prototype of a name whose api_map entry says decl_drop (the fork provides the function under another name, which the
    # calls use): the declaration is removed, the names inside it are not converted
    @decls.each do |d|
      next unless d['file'] == rel && d['proto'] && (@entries[d['name']] || {})['decl_drop']
      semi = masked.index(';', d['pc'] + 1)
      next if semi.nil?
      ed.add(d['hstart'], semi + 1, "/* BC2CPP-MRBGEM: prototype of #{d['name']} removed: the calls use the fork's function */")
      rewrite(rel, d['hstart'], d['name'], '(prototype removed)', 'the prototype is replaced by the fork function the calls use')
    end
    # A macro with no use anywhere in the gem (no occurrence outside its own #define) is dead text: its CRuby body is not
    # converted, so the #define is kept under #if 0 and its names are not refused. A macro used in any file is not dead.
    # a name built by pasting (s##_trunc with s = jd makes jd_trunc) is a use of the macro it names
    paste_suffixes = (@paste_suffixes ||= @files.values.inject(Set.new) do |acc, f|
      acc | f['masked'].scan(/##\s*([A-Za-z_]\w*)/).flatten.to_set
    end)
    unused_spans = define_spans(rel).select do |mname, a, b|
      (@occ[mname] || []).none? { |r, os, _oe| !(r == rel && a <= os && os < b) } &&
        paste_suffixes.none? { |sfx| mname.end_with?(sfx) }
    end.map { |_n, a, b| [a, b] }
    unused_spans.each do |a, b|
      ed.add(a, a, "#if 0  /* BC2CPP-MRBGEM: unused macro (no use in the gem): its CRuby body is not converted */\n")
      ed.add(b, b, "\n#endif")
    end
    finditer(IDENT_RE, masked).each do |m|
      s, e = m.begin(0), m.end(0)
      name = m[0]
      next if is_member(masked, s) || ed.overlaps(s, e)
      # the name a #define or #undef names is the macro's own name, not a use (an api_map name with an expr entry keeps it)
      lstart = masked.rindex("\n", s - 1) || -1
      next if masked[(lstart + 1)...s].to_s.match?(/\A[ \t]*#[ \t]*(?:define|undef)[ \t]+\z/)
      next if unused_spans.any? { |a, b| a <= s && s < b }
      # a name in inactive code (#if 0, an excluded branch, a dead definition) is not compiled: it is left as written
      next if ((@excluded_spans || {})[rel] || []).any? { |a, z| a < s && s < z }
      # a name in a conditional directive (#if, #ifdef, #ifndef, #elif, or defined(...)) is a feature test, not a use: it stays
      # as written, and the preprocessor of the mruby build answers it (mruby defines none of CRuby's feature macros)
      next if pp_conditional_at?(masked, s)
      # TYPE(v) == T_NIL (or !=) is a nil test: mruby has no nil type tag (nil and false share MRB_TT_FALSE), so the whole
      # comparison is rewritten to mrb_nil_p, and the T_NIL token inside that edit is not refused
      if name == 'TYPE' && (tn = /\A\(\s*([A-Za-z_][#{WC}]*)\s*\)\s*(==|!=)\s*(T_NIL|T_FALSE)(?![#{WC}])/.match(masked[e..(e + 80)].to_s)) &&
         !@entries.key?(tn[1]) && !@class_vars.include?(tn[1])
        neg = tn[2] == '!=' ? '!' : ''
        pred = tn[3] == 'T_NIL' ? 'mrb_nil_p' : 'mrb_false_p'
        new_text = "#{neg}#{pred}(#{tn[1]})"
        ed.add(s, e + tn.end(0), new_text)
        rewrite(rel, s, 'TYPE', new_text, "TYPE(v) == #{tn[3]} is a value test: nil and false share MRB_TT_FALSE, so #{pred} (which checks the value) is used")
        next
      end
      next if @local_var_occ.include?([rel, s])
      # switch (TYPE(x)) with case T_NIL / T_FALSE labels: nil is a value test, so the switch is on
      # (mrb_nil_p(x) ? 1000 : mrb_type(x)) (1000 stands for nil; no other tag is 1000) and the labels follow:
      # case T_NIL: is case 1000:, case T_FALSE: is case MRB_TT_FALSE: (false only, nil is routed to 1000)
      if %w[TYPE rb_type].include?(name) && (sh = masked[[s - 40, 0].max...s].to_s =~ /switch\s*\(\s*\z/) &&
         (tm = /\A\(\s*([A-Za-z_][#{WC}]*(?:(?:->|\.)[A-Za-z_][#{WC}]*)*)\s*\)/.match(masked[e..(e + 40)].to_s)) && !@entries.key?(tm[1]) &&
         !@class_vars.include?(tm[1])
        rest = masked[(e + tm.end(0))..(e + tm.end(0) + 12)].to_s
        if rest.match?(/\A\s*\)/)
          new_text = "(mrb_nil_p(#{tm[1]}) ? 1000 : mrb_type(#{tm[1]}))"
          ed.add(s, e + tm.end(0), new_text)
          rewrite(rel, s, name, new_text, 'switch (TYPE(v)): nil is routed to case 1000, so the cases below test values')
          next
        end
      end
      if %w[T_NIL T_FALSE].include?(name) && masked[[s - 6, 0].max...s].to_s =~ /case\s+\z/
        open = enclosing_open_brace(masked, s)
        head = open ? masked[[open - 120, 0].max...open].to_s : ''
        if open && head.match?(/switch\s*\(\s*(?:TYPE|rb_type)\(\s*[A-Za-z_][#{WC}]*(?:(?:->|\.)[A-Za-z_][#{WC}]*)*\s*\)\s*\)\s*\z/)
          repl = name == 'T_NIL' ? '1000 /* nil */' : 'MRB_TT_FALSE /* false only: nil is case 1000 */'
          ed.add(s, e, repl)
          rewrite(rel, s, name, repl, 'a case label of a switch on TYPE(v): nil is the value test in case 1000')
          next
        end
      end
      # RETURN_ENUMERATOR(obj, argc, argv) in a registered method: when no block is given, the method returns the enumerator
      # of its own name (to_enum(:name, *args), the Ruby-level Kernel#to_enum of mruby-enumerator)
      if name == 'RETURN_ENUMERATOR' && !@entries.key?(name) && (op = next_nonspace(masked, e)) >= 0 && masked[op] == '('
        cpe = match_close(masked, op)
        eargs = cpe > 0 ? split_args(masked, op, cpe) : []
        fne = enclosing_func(rel, s)
        rec_e = fne && @regs.find { |r| r['error'].nil? && r['func'] == fne['name'] && r['name'] }
        if eargs.size == 3 && rec_e && statement_call(rel, s, cpe)
          obj_t, argc_t, argv_t = eargs.map { |a| psl(text, a[0], a[1]).strip }
          tk = mrb_tok(rel, s)
          repl = "if (mrb_nil_p(nfcx_block)) { mrb_value nfcx_ea[(#{argc_t}) + 1]; " \
                 "nfcx_ea[0] = mrb_symbol_value(mrb_intern_cstr(#{tk}, \"#{rec_e['name']}\")); " \
                 "for (int nfcx_i = 0; nfcx_i < (#{argc_t}); nfcx_i++) nfcx_ea[nfcx_i + 1] = (#{argv_t})[nfcx_i]; " \
                 "return mrb_funcall_argv(#{tk}, #{obj_t}, mrb_intern_cstr(#{tk}, \"to_enum\"), (#{argc_t}) + 1, nfcx_ea); }"
          after_semi = next_nonspace(masked, cpe + 1)
          ed.add(s, after_semi + 1, repl)
          rewrite(rel, s, name, 'if (mrb_nil_p(nfcx_block)) return to_enum(:' + rec_e['name'] + ', ...)',
                  'no block: the method returns its enumerator (Kernel#to_enum of mruby-enumerator, as RETURN_ENUMERATOR)')
          next
        end
      end
      entry = @entries[name]
      # the name in the prototype that decl_drop removes is not a use (the calls are converted)
      next if entry && entry['decl_drop'] && @decls.any? { |d| d['name'] == name && d['proto'] && d['file'] == rel &&
                                                              d['hstart'] <= s && s < d['hend'] }
      # a VALUE local of the enclosing macro body or function named like an API entry (yajl's rb_encoder) is that local, not
      # the API: it is not a use of the entry (a call of it is still the API)
      if entry && !psl(masked, e, e + 1).match?(/\A\(/)
        dl = define_at(rel, s)
        fl = enclosing_func(rel, s)
        local_v = dl ? macro_value_names(rel, dl).include?(name) : (fl && value_names_of(fl).include?(name))
        next if local_v
      end
      if !entry.nil?
        excluded = (@excluded_spans || {})[rel]&.any? { |a, z| a < s && s < z }
        next if excluded && entry['needs_mrb']
        if entry['needs_mrb'] && body_spans.none? { |a, b| a < s && s < b } && !in_global_macro?(rel, s)
          dm = define_at(rel, s)
          if dm && alloc_reach.include?(dm[0])
            refuse(rel, s, name, 'stuck point (per-class allocator): the macro is expanded in a per-class allocator, which has no state argument in the fork (accepted stuck point)')
          else
            refuse(rel, s, name, 'needs the mruby state, which is not in scope at file scope')
          end
          next
        end
        # a name inside a comparison this pass has already rewritten as a whole (T_STRUCT != rb_type(x)) is not converted again
        next if ((@claimed_spans || {})[rel] || []).any? { |a, z| a <= s && s < z }
        map_entry(rel, s, e, name, entry)
      elsif @types.key?(name)
        # an ID declaration: `ID x` or `ID *x` (the spaces around the * are optional; the match is on the text after the type)
        # a cast to ID, (ID)x, is an mrb_sym cast as well
        id_cast = name == 'ID' && (pc = prev_nonspace(masked, s - 1)) >= 0 && masked[pc] == '(' && psl(masked, e, e + 40) =~ /\A[#{WSP}]*\)/
        next if name == 'ID' && !id_cast && !(psl(masked, e, e + 40) =~ /\A[#{WSP}]*(?:[A-Za-z_]|\*[#{WSP}]*[A-Za-z_])/)
        # a declaration of ID variables that are all assigned ID2SYM(...) holds a symbol VALUE (CRuby keeps it in an ID-typed
        # variable): it is an mrb_value, as ID2SYM is mrb_symbol_value
        if name == 'ID' && symbol_value_decl?(rel, e)
          ed.add(s, e, 'mrb_value')
          rewrite(rel, s, name, 'mrb_value', 'an ID variable assigned ID2SYM holds a symbol value: mrb_value')
          next
        end
        ed.add(s, e, @types[name])
        rewrite(rel, s, name, @types[name])
      elsif (name == 'T_RATIONAL' || name == 'T_COMPLEX') && (cc_t = call_context(masked, s)) && cc_t[0] == 'RB_TYPE_P'
        # the type argument of an RB_TYPE_P that is rewritten to a class test (or refused with its own reason): not a use here
        next
      elsif UNKNOWN_RE.match?(name) && !local_syms.include?(name) && !local_value_at?(rel, s, name) && !input_declared_names.include?(name) &&
            !(@local_tags.include?(name) && psl(masked, [s - 40, 0].max, s).match?(/\b(?:struct|union|enum)[ \t\n]+\z/))
        # a CRuby type tag the fork cannot test has its recorded reason (type_check_refused), not a generic one
        if name == 'T_STRUCT' && (cmp = psl(masked, e, [e + 200, masked.length].min).match(/\A[ \t\n]*(!=|==)[ \t\n]*rb_type\(([^()]+)\)/))
          # T_STRUCT compared with the type of an object: the Struct class test (the mruby-struct gem; CRuby's T_STRUCT is Struct
          # and its subclasses, which kind_of covers). The whole comparison is one rewrite, so rb_type's own name is not converted.
          st_end = e + cmp[0].length
          obj_expr = cmp[2].strip
          if obj_expr.match?(/\A[A-Za-z_][#{WC}]*(?:\s*(?:->|\.)\s*[A-Za-z_][#{WC}]*)*\z/)
            neg = cmp[1] == '!=' ? '!' : ''
            new = "#{neg}mrb_obj_is_kind_of(#{mrb_tok(rel, s)}, #{obj_expr}, mrb_class_get(#{mrb_tok(rel, s)}, \"Struct\"))"
            (@gem_deps ||= Set.new) << 'mruby-struct'
            ed.add(s, st_end, new)
            (@claimed_spans ||= {})[rel] ||= []
            (@claimed_spans[rel]) << [s, st_end]
            rewrite(rel, s, name, new, 'a Struct test by class (the mruby-struct gem): T_STRUCT compared with rb_type of an object')
            next
          end
        end
        stored_key = name.sub(/\ARUBY_/, '')
        if ($stored_tags || {}).key?(stored_key) && !psl(masked, [s - 40, 0].max, s).match?(/\b(?:struct|union|enum)[ \t\n]+\z/)
          # a tag the build configuration names as stored (--stored-tag NAME=VALUE; CRuby's RUBY_ alias too): the file keeps it
          # as an integer tag
          val = $stored_tags[stored_key]
          ed.add(s, e, val)
          rewrite(rel, s, name, val, "a stored tag (--stored-tag): the file keeps #{stored_key} as the integer tag #{val}, not a VALUE type test")
          next
        end
        refuse(rel, s, name, @type_check_refused[name] || @unmapped_reasons[name] || 'no entry in api_map.json')
      elsif @class_vars.include?(name)
        next if @decl_name_pos.include?([rel, s]) || is_param(rel, s, name)
        # a macro's parameter list (#define NAME(a, b)) names parameters, not class variables
        ls_m = masked.rindex("\n", s - 1)
        ls_m = ls_m ? ls_m + 1 : 0
        mp = masked[ls_m...s].to_s.match(/\A[ \t]*#[ \t]*define[ \t]+[A-Za-z_]\w*\(([^)]*)\z/)
        next if mp
        # inside a function-like macro whose parameter has this name, the name is the parameter (in the body too)
        dm_p = define_at(rel, s)
        if dm_p
          dl_s = masked.rindex("\n", dm_p[1]) ; dl_s = dl_s ? dl_s + 1 : 0
          dl = masked[dl_s...(masked.index("\n", dm_p[1]) || masked.length)].to_s
          dl_m = dl.match(/\A[ \t]*#[ \t]*define[ \t]+[A-Za-z_]\w*\(([^)]*)\)/)
          next if dl_m && dl_m[1].split(',').map(&:strip).include?(name)
        end
        # a struct or union field declaration named like a class variable is a field (not a use of the class variable)
        ob_f = enclosing_open_brace(masked, s)
        next if ob_f && masked[[ob_f - 60, 0].max...ob_f].to_s.match?(/\b(?:struct|union)[ \t\n]*[A-Za-z_]?\w*[ \t\n]*\z/) &&
                enclosing_func(rel, s).nil?
        # a local or parameter of this name in the enclosing function shadows the class variable: not a use of it
        fn_here = enclosing_func(rel, s)
        next if fn_here && local_shadows_class_var?(name, fn_here)
        nx = next_nonspace(masked, e)
        next if nx >= 0 && masked[nx] == '=' && psl(masked, nx + 1, nx + 2) != '='
        callee, idx = call_context(masked, s)
        next if callee && (@special_pos[callee] || []).include?(idx)
        # the address of an owned class variable (struct RClass *) is an RClass **, which no mruby call takes as a GC root
        pv = prev_nonspace(masked, s - 1)
        if pv >= 0 && masked[pv] == '&' && !(pv > 0 && masked[pv - 1] == '&') && owns_class_var?(rel, s, name)
          # the class value is rooted by mrb_gc_register once the variable is set (a class is a constant, so it is rooted by
          # its constant even before that); the registration call becomes a guarded statement
          span = gc_root_call_span(masked, pv, e)
          fnq = enclosing_func(rel, s)
          dpre = define_at(rel, s)
          at = dpre ? dpre[1] : (fnq && fnq['hstart'])
          if span && at
            # the address is passed as a void *, with the size of the variable: the helper roots a struct RClass * by its class
            # value (when it is set) and an mrb_value while it is not nil, so the statement compiles whichever type the
            # variable has (the converter's declaration and its assignment sites do not always agree)
            @prelude_done ||= Set.new
            unless @prelude_done.include?([rel, 'nfcx_gc_root_addr'])
              @prelude_done << [rel, 'nfcx_gc_root_addr']
              ed.add(at, at, GC_ROOT_ADDR_PRELUDE + "\n")
            end
            @edits[rel].drop(@edits[rel].overlapping(span[0], span[1]))
            ed.add(span[0], s, 'nfcx_gc_root_addr(mrb, (void *)&')
            ed.add(e, span[1], ", sizeof(#{name}))")
            rewrite(rel, s, name, "nfcx_gc_root_addr(mrb, (void *)&#{name}, sizeof(#{name}))",
                    'the address of a class variable is rooted by the prelude helper: a class by its class value (when set), a value while it is not nil')
            next
          end
          refuse(rel, s, name, 'stuck point (GC root): the address of an owned class variable (struct RClass *) is taken as a GC root, which needs an mrb_value holder (the variable would change type)')
          next
        end
        # rb_raise's class is an RClass * for mrb_raisef: an owned class variable is one already; a class variable whose
        # value is not a class definition (rb_const_get) is an mrb_value, and its class pointer is taken
        if callee == 'rb_raise' && idx == 0
          next if owns_class_var?(rel, s, name)
          ed.add(s, e, "mrb_class_ptr(#{name})")
          rewrite(rel, s, name, "mrb_class_ptr(#{name})")
          next
        end
        # the address of an unowned class variable (a VALUE) is the address of the VALUE itself (&mrb_obj_value(x) is not an lvalue)
        pv_c = prev_nonspace(masked, s - 1)
        if pv_c >= 0 && masked[pv_c] == '&' && !(pv_c > 0 && masked[pv_c - 1] == '&')
          next
        end
        # an unowned class variable is a VALUE already (no wrap); an owned one is a class pointer, wrapped as a VALUE
        next unless owns_class_var?(rel, s, name)
        ed.add(s, e, "mrb_obj_value(#{name})")
        rewrite(rel, s, name, "mrb_obj_value(#{name})")
      end
    end
    # 5b. a VALUE is a struct in the fork (the default boxing, include/mruby/boxing_no.h): a cast of a VALUE name to a pointer
    # type, and a (VALUE) cast of an address, have no mruby form (the converted code does not compile)
    mv = @files[rel]['masked']
    fs_values = file_scope_value_names(rel)
    mv.to_enum(:scan, /\(\s*(?:void|char|unsigned\s+char|const\s+char|VALUE)\s*\*\s*\)\s*([A-Za-z_]\w*)/).each do
      m = Regexp.last_match
      nm = m[1]
      next unless (local_value_at?(rel, m.begin(1), nm) || fs_values.include?(nm)) && !@class_vars.include?(nm)
      # the third parameter of a rb_hash_foreach callback is the void * it was given (the threading above), not a VALUE
      fnv = enclosing_func(rel, m.begin(1))
      next if fnv && (@hash_cb_names || Set.new).include?(fnv['name']) &&
              (fnv['params'] || '').split(',')[2].to_s.split.last.to_s.delete('*') == nm
      # the sole parameter of a rb_protect or rb_rescue2 callback is the pointer it was given (the last pass reads it with mrb_cptr)
      next if fnv && m[0].include?('*') && protect_callback_name?(fnv['name']) && fnv['params'].to_s.split(',').size == 1 &&
              fnv['params'].to_s.split.last.to_s.delete('*') == nm
      next if @edits[rel].overlaps(m.begin(1), m.begin(1) + 1)
      # a single-word pointer type (void, char, VALUE) is mapped by value_to_pointer_cast_pass (mrb_cptr of the VALUE), which runs last
      next if m[0].match?(/\(\s*(?:void|char|VALUE)\s*\*\s*\)/)
      refuse(rel, m.begin(1), nm, "stuck point (VALUE as pointer): #{nm} is a VALUE, a struct in the fork (include/mruby/boxing_no.h), and a cast of it to a pointer has no mruby form")
    end
    # assert(v) on a VALUE (a local, parameter or VALUE struct member) is a truth test that the fork's VALUE struct has no
    # exact form for (the converter does not weaken it to a nil test; see the assert decision in the history)
    vfields = value_field_names
    mv.to_enum(:scan, /(?<![#{WC}])assert\s*\(\s*([A-Za-z_]\w*)(?:\s*->\s*([A-Za-z_]\w*))?\s*\)/).each do
      m = Regexp.last_match
      base, field = m[1], m[2]
      is_value = field ? if_field_value?(rel, m.begin(1), [base, field], vfields) : (local_value_at?(rel, m.begin(1), base) || fs_values.include?(base)) && !@class_vars.include?(base)
      next unless is_value
      next if @edits[rel].overlaps(m.begin(0), m.begin(0) + 1)
      refuse(rel, m.begin(0), 'assert', "stuck point (VALUE truth test): assert(#{field ? "#{base}->#{field}" : base}) tests a VALUE, a struct in the fork (include/mruby/boxing_no.h), and no exact truth test of it is expressed")
    end
    mv.to_enum(:scan, /\(\s*VALUE\s*\)\s*&\s*[A-Za-z_]\w*/).each do
      m = Regexp.last_match
      next if in_dead_init(rel, m.begin(0))
      # a cast an earlier pass already converted (a call argument mapped to its CPTR value) is left alone, as before
      next if @edits[rel].overlaps(m.begin(0), m.begin(0) + 1)
      # (VALUE)&x: the address of x carried in a VALUE is a CPTR value (mrb_cptr_value), as for (VALUE)pi
      items = @edits[rel].overlapping(m.begin(0), m.end(0))
      unless items.all? { |a, b, t| t == 'mrb_value' && a >= m.begin(0) && b <= m.begin(0) + 7 }
        refuse(rel, m.begin(0), 'VALUE', 'stuck point (VALUE as pointer): a pointer is cast to VALUE, which is a struct in the fork (include/mruby/boxing_no.h) and cannot hold an address')
        next
      end
      @edits[rel].drop(items)
      addr = m[0][/&\s*([A-Za-z_]\w*)\z/, 1]
      @edits[rel].add(m.begin(0), m.end(0), "mrb_cptr_value(#{mrb_tok(rel, m.begin(0))}, &#{addr})")
      rewrite(rel, m.begin(0), addr, "mrb_cptr_value(mrb, &#{addr})", 'the address of a struct carried in a VALUE is a CPTR value (mrb_cptr_value): a VALUE stored in a C struct must be rooted')
    end
    # 6. mrb name clash in files that get the mrb parameter
    if @decls.any? { |d| d['file'] == rel && @needs.include?(d['name']) }
      mm = /(?<![#{WC}])mrb(?![#{WC}])/.match(masked)
      refuse(rel, mm.begin(0), 'mrb', 'source already uses the identifier mrb (clashes with the state parameter)') if mm
    end
  end

  # The VALUE declaration statements of a masked text: [start of VALUE, end of VALUE, declarators], where a declarator is
  # {start:, name:, ptr:, fn:, comma:} (comma: the position of the comma before it, nil for the first). A statement ends
  # at its ';' at depth 0; a '{', '}' or unbalanced ')' first means it is not a declaration (a parameter list, a body).
  def value_decl_statements(masked)
    out = []
    masked.to_enum(:scan, /(?<![#{WC}])VALUE(?![#{WC}])/).each do
      st = Regexp.last_match.begin(0)
      kw_end = Regexp.last_match.end(0)
      # the words before the type, with preprocessor lines blanked (they are not statements)
      # (the whole text before the type, so a statement that follows a long run of preprocessor lines is still found)
      ctx = masked[0...st].gsub(/^[ \t]*#[^\n]*/) { |x| ' ' * x.length }
      next unless ctx.match?(/(?:\A|[;{}])\s*(?:(?:static|const|extern|register|volatile)\s+)*\z/)
      depth = 0
      i = kw_end
      semi = nil
      while i < masked.length
        c = masked[i]
        if c == '(' || c == '[' then depth += 1
        elsif c == ')' || c == ']'
          depth -= 1
          break if depth < 0
        elsif depth.zero? && (c == '{' || c == '}')
          break
        elsif depth.zero? && c == ';'
          semi = i
          break
        end
        i += 1
      end
      next unless semi
      # split the declarators at the commas of depth 0
      pieces = []
      depth = 0
      from = kw_end
      commas = []
      (from...semi).each do |j|
        c = masked[j]
        if c == '(' || c == '[' then depth += 1
        elsif c == ')' || c == ']' then depth -= 1
        elsif c == ',' && depth.zero?
          commas << j
        end
      end
      bounds = [from] + commas.map { |j| j + 1 } 
      ends = commas + [semi]
      bounds.each_with_index do |b, k|
        seg = masked[b...ends[k]]
        lead = seg[/\A\s*/].size
        nm = seg[/\A\s*([A-Za-z_][#{WC}]*)/, 1]
        after = seg[lead + nm.to_s.size..].to_s if nm
        pieces << { start: b + lead, name: nm, ptr: seg.lstrip.start_with?('*'),
                    fn: !nm.nil? && after.to_s.match?(/\A\s*\(/), comma: k.zero? ? nil : commas[k - 1] }
      end
      out << [st, kw_end, pieces]
    end
    out
  end

  # the variable of a file-scope initializer that contains position s (NAME = { ... } or NAME[] = { ... }), or nil
  def file_scope_table_at(rel, s)
    @table_spans ||= {}
    spans = (@table_spans[rel] ||= begin
      masked = @files[rel]['masked']
      out = []
      masked.to_enum(:scan, /(?<![#{WC}])([#{WC}]+)(?:[ \t\n]*\[[^\]\n]*\])?[ \t\n]*=[ \t\n]*\{/).each do
        m = Regexp.last_match
        open = m.end(0) - 1
        close = match_close(masked, open)
        next if close < 0
        out << [m[1], open, close]
      end
      out
    end)
    hit = spans.find { |_n, a, b| a < s && s < b }
    return nil unless hit
    fn = enclosing_func(rel, s)
    return nil if fn
    hit[0]
  end

  # every use of the table is inside its own initializer or in a registered method or Init function
  def table_used_in_methods?(tbl, rel, s)
    mo = method_only_functions
    (@occ[tbl] || []).all? do |orel, os, _oe|
      # a type name (struct tbl) is not a use of the table
      next true if @files[orel]['masked'][[os - 12, 0].max...os].to_s.match?(/\b(?:struct|union|enum)[ \t\n]+\z/)
      # a member of that name (x.tbl, x->tbl) is a field, not the table
      next true if @files[orel]['masked'][[os - 3, 0].max...os].to_s.match?(/(?:\.|->)[ \t\n]*\z/)
      # a parameter or local of the enclosing function with that name shadows the table there
      ef = enclosing_func(orel, os)
      next true if ef && shadowed_in?(tbl, ef)
      # a declaration of that name (a parameter of a prototype: `T *tbl`, `T tbl`) is not a use: a use follows no type name
      pv = prev_nonspace(@files[orel]['masked'], os - 1)
      if pv >= 0
        pw = @files[orel]['masked'][0..pv][/([A-Za-z_]\w*)\z/, 1]
        next true if @files[orel]['masked'][pv] == '*' || (pw && !%w[return case else do sizeof].include?(pw))
      end
      # the table's own declaration: a file-scope occurrence that opens its initializer
      if enclosing_func(orel, os).nil? && @files[orel]['masked'][_oe..].to_s.match?(/\A(?:[ \t\n]*\[[^\]\n]*\])?[ \t\n]*=[ \t\n]*\{/)
        next true
      end
      f = enclosing_func(orel, os)
      f && mo.include?(f['name'])
    end
  end

  # The functions that run only inside a registered method or Init (their dynamic extent has the global state): the
  # registered methods and Init, and every function all of whose uses are in such functions (a use at file scope, such as
  # an entry of a function-pointer table, is not in one, so the function is not in the set). A fixpoint.
  def method_only_functions
    @method_only ||= begin
      set = Set.new(@valid_reg_names.to_a + (@init_defs || []).map { |d| d['name'] })
      names = @defs.keys
      changed = true
      while changed
        changed = false
        names.each do |n|
          next if set.include?(n)
          uses = (@occ[n] || []).reject do |orel, os, _oe|
            # a definition header or a prototype in the text (name (params) { or name (params) ;) is not a use
            @files[orel]['masked'][_oe..].to_s.match?(/\A[ \t\n]*\((?:[^()]|\([^()]*\))*\)[ \t\n]*[{;]/)
          end
          next if uses.empty?
          if uses.all? { |orel, os, _oe| (f = enclosing_func(orel, os)) && set.include?(f['name']) }
            set << n
            changed = true
          end
        end
      end
      set
    end
  end

  # A format string (the adjacent literals of one argument, span [a, b)) with PRIsVALUE: "%"PRIsVALUE becomes "%S" (a VALUE
  # printed with to_s), and "%+"PRIsVALUE becomes "%!"S" (the fork's inspect flag). The token is replaced; adjacent literals
  # concatenate. Returns false when a PRIsVALUE is in another form (refused by the caller).
  def prsvalue_edits(rel, a, b)
    text = @files[rel]['text']
    ed = @edits[rel]
    fmt = psl(text, a, b)
    ok = true
    fmt.to_enum(:scan, /PRIsVALUE/).each do
      pm = Regexp.last_match
      prefix = fmt[[pm.begin(0) - 6, 0].max...pm.begin(0)]
      tok = a + pm.begin(0)
      if prefix.match?(/%"\s*\z/)
        ed.add(tok, tok + 'PRIsVALUE'.length, '"S"')
      elsif prefix.match?(/%\+"\s*\z/)
        plus = tok - (prefix.length - prefix.rindex('+'))
        ed.add(plus, plus + 1, '!')
        ed.add(tok, tok + 'PRIsVALUE'.length, '"S"')
      else
        ok = false
      end
    end
    # mruby's formatter reads %l as a C string and a size_t, not an integer: CRuby's %ld and %lu are %d and %u here
    # (strscan's inspect formats the position with %ld; the arguments after it were read from the wrong places)
    fmt.to_enum(:scan, /%l([du])/).each do
      lm = Regexp.last_match
      ltok = a + lm.begin(0) + 1
      ed.add(ltok, ltok + 1, '')
    end
    ok
  end

  # The open parenthesis of the innermost call around pos, or nil.
  def call_open_pos(masked, pos)
    depth = 0
    k = pos - 1
    while k >= 0
      ch = masked[k]
      if ')]}'.include?(ch)
        depth += 1
      elsif '([{'.include?(ch)
        return k if depth.zero? && ch == '('
        return nil if depth.zero?
        depth -= 1
      end
      k -= 1
    end
    nil
  end

  # A pointer passed as an argument of a file-scope macro (SUBS(str, pat, cb)) escapes only if the macro does: the macro's
  # body calls a function with that parameter in a position that does not keep it (non_retaining?). The callee's
  # callback record must be ok (threaded for it), as in non_retaining_use?.
  def macro_arg_nonretaining?(rel, pos, macro)
    masked = @files[rel]['masked']
    return false unless @files.values.any? { |f| f['masked'].match?(/^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(macro)}\(/) }
    k = call_open_pos(masked, pos)
    return false if k.nil?
    close = match_close(masked, k)
    return false if close <= 0
    idx = split_args(masked, k, close).index { |a, b| a <= pos && pos < b }
    return false if idx.nil?
    dm = nil
    @files.each do |drel, f|
      m = /^[ \t]*#[ \t]*define[ \t]+#{Regexp.escape(macro)}\(([^)]*)\)/.match(f['masked'])
      if m
        dm = [drel, m, f['masked']]
        break
      end
    end
    return false unless dm
    _drel, m, dmasked = dm
    pname = m[1].split(',').map(&:strip)[idx]
    return false if pname.nil?
    body_end = logical_line_end(dmasked, m.end(0))
    body = dmasked[m.end(0)...body_end].to_s
    body.to_enum(:scan, /([A-Za-z_]\w*)[ \t\n\\]*\(/).each do
      cm = Regexp.last_match
      g = cm[1]
      next unless @defs.key?(g)
      copen = cm.end(0) - 1
      cclose = match_close(body, copen)
      next if cclose <= 0
      split_args(body, copen, cclose).each_with_index do |(a, b), kk|
        next unless body[a...b].strip == pname
        ok_rec = (@fnptr_recs || []).any? { |r| r[:ok] && r[:owner] == g && r[:pidx] == kk }
        return true if ok_rec && non_retaining?(g, kk)
      end
    end
    false
  end

  def is_param(rel, pos, name)
    # True if name at pos is a parameter of the function (its header, or its body) that encloses pos.
    # A parameter shadows a file-scope class variable of the same name, so it must not be rewritten.
    @decls.each do |d|
      next if d['file'] != rel
      return param_names(d).include?(name) if d['hstart'] <= pos && pos < d['hend']
      return true if d.key?('body_end') && d['brace'] < pos && pos < d['body_end'] && param_names(d).include?(name)
    end
    false
  end

  # words that can precede an expression (return x uses x; it does not declare it)
  DECL_NON_TYPE_WORDS = Set.new(%w[return else goto case typedef sizeof do new delete throw struct union enum]).freeze

  # The names the input declares as a variable or a struct/union field, in every file: an identifier after a type name (or after
  # a *), followed by ; , = [ : or ), outside a preprocessor line. A prototype (the name followed by "(") declares nothing here,
  # since it may declare a CRuby API. A ruby_ name the input declares is the input's own (a struct field such as pg's ruby_sd),
  # so a use of it is not an unknown-API refusal.
  def input_declared_names
    @input_declared_names ||= begin
      names = Set.new
      @files.each_value do |f|
        masked = f['masked']
        masked.to_enum(:scan, /(?<![#{WC}$])([A-Za-z_][#{WC}]*)(?:[ \t\r\n]+|[ \t\r\n]*\*[ \t\r\n]*)([A-Za-z_][#{WC}]*)[ \t\r\n]*(?=[;,=\[:)])/).each do
          m = Regexp.last_match
          next if DECL_NON_TYPE_WORDS.include?(m[1])
          ls = masked.rindex("\n", m.begin(0))
          next if masked[(ls ? ls + 1 : 0)...m.begin(0)].match?(/\A[ \t]*#/)
          names << m[2]
        end
      end
      names
    end
  end

  # a VALUE local of the enclosing macro body or function (VALUE a, b; in it), not a CRuby name
  def local_value_at?(rel, s, name)
    dl = define_at(rel, s)
    return macro_value_names(rel, dl).include?(name) if dl
    fl = enclosing_func(rel, s)
    return false unless fl
    # a body declaration in scope at s decides the type (a block's long t and a later block's VALUE t are two locals)
    t = local_decl_type_at(rel, s, name)
    return t == 'VALUE' if t
    !!value_names_of(fl).include?(name)
  end

  # mruby.h's exception-class macros (E_ARGUMENT_ERROR and the rest): the class each names
  MRB_E_EXC_CLASSES = { 'E_RUNTIME_ERROR' => 'RuntimeError', 'E_TYPE_ERROR' => 'TypeError', 'E_ARGUMENT_ERROR' => 'ArgumentError', 'E_INDEX_ERROR' => 'IndexError', 'E_RANGE_ERROR' => 'RangeError', 'E_ZERODIV_ERROR' => 'ZeroDivisionError', 'E_NAME_ERROR' => 'NameError', 'E_NOMETHOD_ERROR' => 'NoMethodError', 'E_SCRIPT_ERROR' => 'ScriptError', 'E_SYNTAX_ERROR' => 'SyntaxError', 'E_LOCALJUMP_ERROR' => 'LocalJumpError', 'E_REGEXP_ERROR' => 'RegexpError', 'E_FROZEN_ERROR' => 'FrozenError', 'E_NOTIMP_ERROR' => 'NotImplementedError', 'E_FLOATDOMAIN_ERROR' => 'FloatDomainError', 'E_KEY_ERROR' => 'KeyError', 'E_FIBER_ERROR' => 'FiberError' }.freeze

  LOCAL_DECL_KEYWORDS = %w[return else goto case typedef sizeof do].freeze

  # The declared type of the local name in effect at pos, by block scope: the latest declaration in the function body whose
  # block encloses pos and comes before it. nil when no body declaration of name is in scope (a parameter, or not a local).
  def local_decl_type_at(rel, pos, name)
    fn = enclosing_func(rel, pos)
    return nil unless fn && fn.key?('brace') && fn.key?('body_end')
    @local_decls ||= {}
    cands = (@local_decls[[rel, fn['brace'], name]] ||= local_decl_candidates(rel, fn, name))
    best = nil
    cands.each do |dpos, type, bs, be|
      next unless bs < pos && pos < be && dpos < pos
      best = [dpos, type] if best.nil? || dpos > best[0]
    end
    best && best[1]
  end

  # the declarations of name in a function body: [name position, declared type, block start, block end]
  def local_decl_candidates(rel, fn, name)
    masked = @files[rel]['masked']
    base = fn['brace']
    out = []
    re = /((?:(?:const|volatile|static|unsigned|signed|register)\s+)*[A-Za-z_]\w*(?:\s*\*)*)\s+#{Regexp.escape(name)}(?![#{WC}])\s*(?=[;=,)\[])/
    masked[base...fn['body_end']].to_enum(:scan, re).each do
      m = Regexp.last_match
      type = m[1].strip.gsub(/\s+/, ' ')
      first = type.split.reject { |w| %w[const volatile static unsigned signed register].include?(w) }.first.to_s
      next if LOCAL_DECL_KEYWORDS.include?(first)
      dpos = base + m.begin(0) + m[0].rindex(name)
      type = 'mrb_int' if @int_decl_pos&.include?([rel, dpos])
      before = masked[0...m.begin(0) + base].rstrip[-1]
      next unless before.nil? || [';', '{', '}', '(', ','].include?(before)
      bs, be = block_span(masked, dpos, fn)
      out << [dpos, type, bs, be]
    end
    # a later declarator of a declaration (const char *s1, *s2;): its type is the statement's base type, a pointer when it has a *
    comma_re = /,[ \t\n]*((?:\*[ \t\n]*)*)#{Regexp.escape(name)}(?![#{WC}])[ \t\n]*(?=[;=,)\[])/
    masked[base...fn['body_end']].to_enum(:scan, comma_re).each do
      m = Regexp.last_match
      comma = base + m.begin(0)
      st = comma
      st -= 1 while st > base && !";{}(".include?(masked[st - 1])
      head = masked[st...comma].to_s.strip
      hm = head.match(/\A((?:(?:const|volatile|static|unsigned|signed|register)\s+)*[A-Za-z_]\w*)/)
      next unless hm
      first = hm[1].split.reject { |w| %w[const volatile static unsigned signed register].include?(w) }.first.to_s
      next if first.empty? || LOCAL_DECL_KEYWORDS.include?(first)
      type = m[1].to_s.include?('*') ? "#{first} *" : first
      dpos = base + m.begin(0) + m[0].rindex(name)
      type = 'mrb_int' if @int_decl_pos&.include?([rel, dpos])
      bs, be = block_span(masked, dpos, fn)
      out << [dpos, type, bs, be]
    end
    out
  end

  # the block that encloses position d: its '{' and matching '}' (the function body when d is at its top level)
  def block_span(masked, d, fn)
    depth = 0
    i = d - 1
    bs = fn['brace']
    while i > fn['brace']
      c = masked[i]
      if c == '}' then depth += 1
      elsif c == '{'
        if depth.zero?
          bs = i
          break
        end
        depth -= 1
      end
      i -= 1
    end
    depth = 0
    j = bs + 1
    be = fn['body_end']
    while j < fn['body_end']
      c = masked[j]
      if c == '{' then depth += 1
      elsif c == '}'
        if depth.zero?
          be = j
          break
        end
        depth -= 1
      end
      j += 1
    end
    [bs, be]
  end

  def map_entry(rel, s, e, name, entry)
    masked = @files[rel]['masked']
    ed = @edits[rel]
    kind = entry['kind']
    nxt = next_nonspace(masked, e)
    called = nxt >= 0 && masked[nxt] == '('
    case kind
    when 'refuse'
      refuse(rel, s, name, entry['reason'])
    when 'special'
      special(rel, s, e, name, entry, nxt, called)
    when 'drop'
      # Declaration with no effect in mruby: the call is removed and a warning is printed and recorded.
      # The name in a #define line is the macro's own definition, not a use: nothing to drop.
      return if psl(@files[rel]['text'], [s - 12, 0].max, s) =~ /#[ \t]*(?:define|ifn?def|undef)[ \t]+\z/
      unless called
        refuse(rel, s, name, 'used without a call; cannot drop it')
        return
      end
      close = pyfind(masked, ')', nxt)
      stop = close + 1
      semi = next_nonspace(masked, stop)
      stop = semi + 1 if semi >= 0 && masked[semi] == ';'
      ed.add(s, stop, "/* BC2CPP-MRBGEM dropped: #{name} (#{entry['reason']}) */")
      line = line_of(@files[rel]['text'], s)
      @warnings << { 'file' => rel, 'line' => line, 'api' => name, 'reason' => entry['reason'] }
      warn "warning: #{rel}:#{line} dropped #{name} (#{entry['reason']})"
    when 'template'
      # a fixed expression over the call's arguments (api_map.json "template"): $0, $1, ... are the argument texts and
      # $m is the mruby state. Only plain identifiers and integer literals are substituted, and none is a class variable.
      unless called
        # rb_yield as the function of rb_protect (rb_protect(rb_yield, Qnil, &state)): a file-scope wrapper yields with
        # the data as the argument, and the callback slot takes it (the wrapper reads the block as a helper does)
        open_p, callee_p = innermost_open(masked, s)
        prev_p = prev_nonspace(masked, s - 1)
        fnp = enclosing_func(rel, s)
        if name == 'rb_yield' && open_p == '(' && callee_p == 'rb_protect' && prev_p >= 0 && masked[prev_p] == '(' && fnp && fnp['hstart']
          unless @block_arg_files.include?(rel)
            @block_arg_files << rel
            ed.add(fnp['hstart'], fnp['hstart'],
                   "static mrb_value nfcx_block_arg(mrb_state *mrb)\n{\n  mrb_value nfcx_b;\n  mrb_get_args(mrb, \"&\", &nfcx_b);\n  return nfcx_b;\n}\n\n")
          end
          unless @yield_cb_files.include?(rel)
            @yield_cb_files << rel
            ed.add(fnp['hstart'], fnp['hstart'],
                   "static mrb_value nfcx_yield_cb(mrb_state *mrb, mrb_value data)\n{\n  return mrb_yield(mrb, nfcx_block_arg(mrb), data);\n}\n\n")
          end
          ed.add(s, e, 'nfcx_yield_cb')
          rewrite(rel, s, name, 'nfcx_yield_cb', 'the callback of rb_protect: yields to the block of the calling method (a file-scope wrapper)')
          return
        end
        refuse(rel, s, name, 'used without a call; cannot map it')
        return
      end
      cp = match_close(masked, nxt)   # the matching parenthesis: an argument may hold calls
      args = cp > 0 ? split_args(masked, nxt, cp) : []
      # a macro's line continuation inside an argument (the backslash at a line end) is not part of the argument's text
      texts = args.map { |a, b| psl(@files[rel]['text'], a, b).gsub(/[ \t]*\\\n[ \t]*/, ' ').strip }
      if texts.size != entry['arity']
        refuse(rel, s, name, "expected #{entry['arity']} arguments, found #{texts.size}")
        return
      end
      # CLASS_OF(x) in a class-only argument position (rb_undef_method's class) is the RClass * itself: CRuby's class pointer, not
      # the VALUE the template wraps for an expression use
      if name == 'CLASS_OF'
        cc_c, ci_c = call_context(masked, s)
        if cc_c && (@special_pos[cc_c] || []).include?(ci_c)
          entry = entry.merge('template' => 'mrb_class($m, $0)')
        end
      end
      # a template that wraps its class result in mrb_obj_value (rb_obj_class) in a class-only argument position is the class
      # pointer itself (rb_class2name's argument is an RClass *): the wrap is dropped
      if entry['template'].to_s.start_with?('mrb_obj_value(') && entry['template'].to_s.end_with?(')')
        cc_w, ci_w = call_context(masked, s)
        if cc_w && (@special_pos[cc_w] || []).include?(ci_w)
          entry = entry.merge('template' => entry['template'][14...-1])
        end
      end
      # a template that needs a file-scope helper (api_map "prelude": its definition text, "prelude_name": its name) gets it once
      # per file, before the enclosing function (as nfcx_block_arg is)
      # a template that needs a gem at run time declares it (api_map gem_dep): the converted gem depends on it
      (@gem_deps ||= Set.new) << entry['gem_dep'] if entry['gem_dep']
      if entry['prelude']
        # a call in a function: the helper goes before that function; a call in a macro body: before the #define (file scope)
        dpre = define_at(rel, s)
        fnq = enclosing_func(rel, s)
        at = if dpre then dpre[1]
             elsif fnq && fnq['hstart'] then fnq['hstart']
             end
        unless at
          refuse(rel, s, name, 'the helper this call needs has no place before it (not in a function or a macro)')
          return
        end
        @prelude_done ||= Set.new
        unless @prelude_done.include?([rel, entry['prelude_name']])
          @prelude_done << [rel, entry['prelude_name']]
          ed.add(at, at, entry['prelude'] + "\n")
        end
      end
      class_args = entry['class_args'] || []
      str_args = entry['str_args'] || []
      value_class_arg = lambda do |t, at|
        fnc = enclosing_func(rel, at)
        vn = fnc ? value_names_of(fnc) : Set.new
        vf = value_field_names
        (t.match?(/\A[A-Za-z_]\w*\z/) && (vn.include?(t) || @files.keys.any? { |fr| file_scope_value_names(fr).include?(t) }) && !@class_vars.include?(t)) ||
          (t.match?(/(?:->|\.)[A-Za-z_]\w*\z/) && vf.include?(t[/([A-Za-z_]\w*)\z/])) ||
          # an element of a VALUE array (rb_class_inherited_p(args[0], key): a class read from the array)
          (t.match?(/\A[A-Za-z_]\w*\s*\[[^\[\]]*\]\z/) && (vn.include?(t[/\A([A-Za-z_]\w*)/, 1]) || vn.include?("*#{t[/\A([A-Za-z_]\w*)/, 1]}") ||
            (fnc && value_pointer_names(fnc).include?(t[/\A([A-Za-z_]\w*)/, 1]))))
      end
      # rb_yield needs the block of the method, which only a registered method's wrapper fetches (registered_header)
      # in a helper (a function with the mruby state), the block is read from the current call frame, as the wrapper does:
      # nfcx_block_arg (one per file, placed before the helper) runs mrb_get_args with "&" (the frame's block slot)
      if entry['requires_block']
        fnb = enclosing_func(rel, s)
        if fnb && @valid_reg_names.include?(fnb['name'])
          nil
        elsif fnb && fnb['hstart']
          unless @block_arg_files.include?(rel)
            @block_arg_files << rel
            ed.add(fnb['hstart'], fnb['hstart'],
                   "static mrb_value nfcx_block_arg(mrb_state *mrb)\n{\n  mrb_value nfcx_b;\n  mrb_get_args(mrb, \"&\", &nfcx_b);\n  return nfcx_b;\n}\n\n")
          end
          entry = entry.merge('template' => entry['template'].sub('nfcx_block', 'nfcx_block_arg($m)'))
        else
          refuse(rel, s, name, 'rb_yield is supported only in a function body (no block is in scope at file scope)')
          return
        end
      end
      # a template whose arguments each appear once, in order, and some argument is a call or another complex expression:
      # only the text between the arguments is rewritten (head, the separators, and tail); the arguments stay in place and
      # the identifier pass converts their own names and calls (NUM2LL(rb_funcall2(...)) keeps its inner call converted)
      tmpl = entry['template']
      order = tmpl.scan(/\$(\d+)(?!\d)/).flatten.map(&:to_i)
      # an encoding (or any argument the template drops) is removed with the text between the used arguments: a dropped
      # argument is a plain name or a pure encoding getter, so no rewrite is lost
      dropped = entry['ignored_args'] || []
      if !dropped.empty? && entry['template_cond'].nil? && class_args.empty? && str_args.empty? &&
         texts.none? { |t| t.match?(/\Arb_intern\(/) } && texts.each_with_index.all? { |t, i| !dropped.include?(i) || t.match?(/\A(?:(?:[A-Za-z_][#{WC}]*(?:\s*(?:->|\.)\s*[A-Za-z_][#{WC}]*)*)|rb_utf8_encoding\(\)|rb_ascii8bit_encoding\(\)|rb_usascii_encoding\(\))\z/) } &&
         order == (0...args.size).reject { |i| dropped.include?(i) }
        used_args = order.map { |i| args[i] }
        pieces = tmpl.split(/(\$\d+(?!\d))/, -1)
        literal = ->(x) { x.gsub('$m', mrb_tok(rel, s)) }
        lits = pieces.each_slice(2).map { |lit, _| literal.call(lit.to_s) }
        if pieces.count { |x| x.match?(/\A\$\d+\z/) } == used_args.size && !used_args.empty?
          spans = [[s, used_args[0][0]]] + used_args.each_cons(2).map { |(_, b1), (a2, _)| [b1, a2] } + [[used_args[-1][1], cp + 1]]
          if spans.any? { |a, b| ed.overlaps(a, b) }
            refuse(rel, s, name, 'the call overlaps a rewritten span (not supported)')
            return
          end
          ed.add(s, used_args[0][0], lits[0])
          used_args.each_cons(2).with_index { |((_, b1), (a2, _)), j| ed.add(b1, a2, lits[j + 1]) }
          ed.add(used_args[-1][1], cp + 1, lits[used_args.size])
          rewrite(rel, s, name, tmpl.gsub(/\$\d+/, '\u2026').gsub('$m', mrb_tok(rel, s)), entry['caveat'])
          return
        end
      end
      # (an argument with a special form, a string literal or rb_intern, is substituted by the general path below)
      # (a class argument that is a mapped CRuby class constant, rb_cX, is its class expression as it stands: no unwrapping)
      consts_only = class_args.all? { |i| texts[i].to_s.match?(/\Arb_c[A-Z]\w*\z/) }
      if entry['template_cond'].nil? && (class_args.empty? || consts_only) && (entry['ignored_args'] || []).empty? && str_args.empty? &&
         texts.none? { |t| t.match?(/\Arb_intern\(/) } &&
         order == (0...entry['arity']).to_a && texts.any? { |t| !t.match?(/\A&?[#{WC}\s.\->]+\z/) }
