        args = cp > 0 ? split_args(masked, nxt, cp) : []
        if args.size != entry['append_arity']
          refuse(rel, s, name, "expected #{entry['append_arity']} arguments, found #{args.size}")
          return
        end
        ed.add(cp, cp, ', ' + entry['append_args'].join(', '))
      end
      if entry['wrap_arg']
        # text around one argument (a conversion such as mrb_symbol(x)): only insertions at its two ends, so the
        # argument's own conversion stays exactly as it is
        w = entry['wrap_arg']
        cp = pyfind(masked, ')', nxt)
        args = cp > 0 ? split_args(masked, nxt, cp) : []
        if args.size <= w['index']
          refuse(rel, s, name, "expected at least #{w['index'] + 1} arguments, found #{args.size}")
          return
        end
        a, b = args[w['index']]
        ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ") if entry['wrap_mrb']
        ed.add(a, a, w['prefix'])
        ed.add(b, b, w['suffix'])
      end
      if entry['intern_arg']
        # a C name argument (a string literal) becomes the symbol mruby takes: mrb_intern_cstr(mrb, "name")
        cp = pyfind(masked, ')', nxt)
        args = cp > 0 ? split_args(masked, nxt, cp) : []
        k = entry['intern_arg']
        lit = args.size > k ? psl(@files[rel]['text'], args[k][0], args[k][1]) : ''
        unless lit.match?(/\A"[^"\\\n]*"\z/)
          refuse(rel, s, name, "argument #{k + 1} is not a string literal (mruby takes a symbol; only a literal name is rewritten)")
          return
        end
        ed.add(args[k][0], args[k][1], "mrb_intern_cstr(#{mrb_tok(rel, s)}, #{lit})")
      end
      ed.add(s, e, entry['mruby'])
      if entry['inject_mrb']
        pa = next_nonspace(masked, nxt + 1)
        t = mrb_tok(rel, s)
        ed.add(nxt + 1, nxt + 1, masked[pa] == ')' ? t : "#{t}, ")
      end
      rewrite(rel, s, name, entry['mruby'], entry['caveat'])
    when 'macro'
      if entry['mruby'] != name
        ed.add(s, e, entry['mruby'])
        rewrite(rel, s, name, entry['mruby'])
      end
    when 'strip'
      # A macro whose only effect is a compiler hint (RB_LIKELY): the name becomes entry['mruby'] and the
      # argument stays in place, so the call form is kept and the hint is dropped.
      unless called
        refuse(rel, s, name, 'used without a call; cannot map it')
        return
      end
      ed.add(s, e, entry['mruby'])
      rewrite(rel, s, name, entry['mruby'], entry['caveat'])
    when 'expr'
      if called
        refuse(rel, s, name, 'expression mapping used in call form')
        return
      end
      # a Q constant that labels a case of a switch (on a VALUE): the switch is on nfcx_q_key of its subject (1 nil, 2 true,
      # 3 false, 0 other), and the label is that integer. The switch keeps its structure (fall-through, default).
      if %w[Qnil Qtrue Qfalse].include?(name) && masked[0...s].match?(/(?<![#{WC}])case[ \t\n]+\z/) &&
         next_nonspace(masked, e) >= 0 && masked[next_nonspace(masked, e)] == ':'
        sw = nil
        masked.to_enum(:scan, /(?<![#{WC}])switch[ \t\n]*\(/).each do
          m = Regexp.last_match
          op = m.end(0) - 1
          cl = match_close(masked, op)
          next if cl < 0 || cl > s
          br = next_nonspace(masked, cl + 1)
          next unless br >= 0 && masked[br] == '{' && match_close(masked, br) > s
          sw = [op, cl] if sw.nil? || op > sw[0]
        end
        if sw
          tok_q = mrb_tok(rel, s)
          @switch_keyed ||= Set.new
          unless @switch_keyed.include?([rel, sw[0]])
            @switch_keyed << [rel, sw[0]]
            ed.add(sw[0] + 1, sw[0] + 1, "nfcx_q_key(#{tok_q}, ")
            ed.add(sw[1], sw[1], ')')
          end
          fnk = enclosing_func(rel, s)
          at_k = define_at(rel, s) ? define_at(rel, s)[1] : (fnk && fnk['hstart'])
          @prelude_done ||= Set.new
          unless !at_k || @prelude_done.include?([rel, 'nfcx_q_key'])
            @prelude_done << [rel, 'nfcx_q_key']
            ed.add(at_k, at_k, "static int nfcx_q_key(mrb_state *mrb, mrb_value v) {\n" \
                               "  if (mrb_nil_p(v)) return 1;\n  if (mrb_true_p(v)) return 2;\n  if (mrb_false_p(v)) return 3;\n  return 0;\n}\n")
          end
          key = { 'Qnil' => 1, 'Qtrue' => 2, 'Qfalse' => 3 }[name]
          ed.add(s, e, key.to_s)
          rewrite(rel, s, name, key.to_s, 'a case label of a switch on a VALUE: the switch is on the key of its subject (nfcx_q_key)')
          return
        end
      end
      # a class expression (RClass *: mrb->object_class, mrb_class_get(...)) used as a plain value is its VALUE
      # an expression that names the state (mrb->object_class) names the state of this context (the global, in a global-state helper)
      # an mruby exception-class macro (E_ARGUMENT_ERROR: mrb_exc_get(mrb, "ArgumentError") over the variable mrb) names the state of
      # this context: mrb_exc_get of that state (a function with only a global state has no mrb to name)
      text = if (ecls = MRB_E_EXC_CLASSES[entry['mruby']]) && mrb_tok(rel, s) != 'mrb'
               "mrb_exc_get(#{mrb_tok(rel, s)}, \"#{ecls}\")"
             else
               entry['mruby'].gsub(/\bmrb->/) { "#{mrb_tok(rel, s)}->" }
             end
      # not in a class argument of a call: that position takes the RClass * itself (mrb_define_method(mrb, mrb->object_class, ...))
      callee_c, idx_c = call_context(masked, s)
      class_pos = callee_c && ((@special_pos[callee_c] || []).include?(idx_c) ||
                               ((@entries[callee_c] || {})['class_args'] || []).include?(idx_c))
      # the right side of an assignment to an owned class variable (struct RClass *) is the class itself, not its VALUE
      eq = prev_nonspace(masked, s - 1)
      owned_target = false
      if eq >= 0 && masked[eq] == '=' && !(eq > 0 && '=!<>+-*/%&|^'.include?(masked[eq - 1]))
        lhs = masked[0...eq].match(/([A-Za-z_]\w*)#{SS}\z/)
        owned_target = lhs && @class_vars.include?(lhs[1]) && owns_class_var?(rel, s, lhs[1])
      end
      text = "mrb_obj_value(#{text})" if !class_pos && !owned_target && entry['mruby'].match?(CLASS_EXPR_RE)
      # a file-scope initializer (static VALUE X = Qnil;) is not a constant expression in C (mrb_nil_value is a function): the
      # initializer is removed, and the variable is set at the start of Init (the file's Init function)
      fs_init = if %w[Qnil Qtrue Qfalse].include?(name) && enclosing_func(rel, s).nil?
                  eq = prev_nonspace(masked, s - 1)
                  var = eq >= 0 && masked[eq] == '=' ? masked[0...eq].match(/([A-Za-z_]\w*)\s*\z/) : nil
                  # a member assigned in a macro ((s)->regex = Qnil) is not a declaration's initializer
                  var = nil if var && masked[0...eq].match?(/(?:->|\.)\s*#{Regexp.escape(var[1])}\s*\z/)
                  init_d = @init_defs.find { |d| d['file'] == rel && d['brace'] }
                  [eq, var && var[1], init_d] if var && init_d && (@init_rel == rel)
                end
      # Qfalse (0) and Qtrue returned from a function whose result is an integer (int, bool): the integer, as CRuby's (0 / truthy)
      if %w[Qfalse Qtrue].include?(name) && (fr_i = enclosing_func(rel, s)) && fr_i['ret'].to_s.split.any? { |t| %w[int bool long unsigned].include?(t) }
        ret_pre = masked[[s - 12, 0].max...s].to_s
        if ret_pre.match?(/\breturn[ \t\n]*\z/)
          lit = name == 'Qfalse' ? '0' : '1'
          ed.add(s, e, lit)
          rewrite(rel, s, name, lit, 'a Q constant returned from an integer function: CRuby\'s Qfalse is 0 (Qtrue a nonzero truth value)')
          return
        end
      end
      # a static local initialized with a Q constant (static VALUE pat = Qnil;) needs a constant initializer too: the compound
      # literal with the fork's bits (mrb_nil_value() is a function call, not a constant)
      if %w[Qnil Qtrue Qfalse Qundef].include?(name) && enclosing_func(rel, s) &&
         masked[[s - 80, 0].max...s].to_s.match?(/\bstatic\s+(?:const\s+)?(?:VALUE|mrb_value)\s+[A-Za-z_]\w*\s*=\s*\z/)
        static_lit = { 'Qnil' => '((mrb_value){.value.i = 0, .tt = MRB_TT_FALSE})',
                       'Qtrue' => '((mrb_value){.value.i = 1, .tt = MRB_TT_TRUE})',
                       'Qfalse' => '((mrb_value){.value.i = 1, .tt = MRB_TT_FALSE})',
                       'Qundef' => '((mrb_value){.value.i = 0, .tt = MRB_TT_UNDEF})' }[name]
        ed.add(s, e, static_lit)
        rewrite(rel, s, name, static_lit, 'a static local initialized with a Q constant: a constant compound literal (the fork\'s bits)')
        return
      end
      # a Q constant in a file-scope initializer (a table entry) is a constant compound literal with the same bits as the
      # fork's value (nil: value 0; true and false: value 1, the tag tells them apart): mrb_nil_value() is not a constant
      if %w[Qnil Qtrue Qfalse Qundef].include?(name) && !fs_init && enclosing_func(rel, s).nil? && define_at(rel, s).nil? &&
         (masked[[s - 60, 0].max...s].to_s.match?(/struct\s+RClass\s*\*\s*([A-Za-z_]\w*)\s*=\s*\z/) ||
          (decl_v = masked[[s - 60, 0].max...s].to_s.match(/\bVALUE\s+([A-Za-z_]\w*)\s*=\s*\z/)) && @class_vars.include?(decl_v[1]) && owns_class_var?(rel, s, decl_v[1]))
        # an owned class variable (struct RClass *) starts as a null class pointer (the Q value is not a class)
        ed.add(s, e, '0')
        rewrite(rel, s, name, '0', 'an owned class variable (struct RClass *) initialized with a Q value: the null class pointer')
        return
      end
      # (inside a macro, a Q constant of a brace initializer is the same constant: a table entry from a macro, f(N) { ..., Qnil })
      in_init_brace = !define_at(rel, s).nil? && masked[[s - 160, 0].max...s].to_s.match?(/=\s*\{[^;]*\z/)
      if %w[Qnil Qtrue Qfalse Qundef].include?(name) && !fs_init && enclosing_func(rel, s).nil? && (define_at(rel, s).nil? || in_init_brace)
        const_lit = { 'Qnil' => '((mrb_value){.value.i = 0, .tt = MRB_TT_FALSE})',
                      'Qtrue' => '((mrb_value){.value.i = 1, .tt = MRB_TT_TRUE})',
                      'Qfalse' => '((mrb_value){.value.i = 1, .tt = MRB_TT_FALSE})',
                      'Qundef' => '((mrb_value){.value.i = 0, .tt = MRB_TT_UNDEF})' }[name]
        ed.add(s, e, const_lit)
        rewrite(rel, s, name, const_lit, 'a file-scope Q constant as a constant value (the fork\'s nil, true or false bits)')
        return
      end
      if fs_init
        eq, var_name, init_d = fs_init
        ed.add(eq, e, '')
        # an owned class variable (struct RClass *) is set to the null class pointer, as its declaration's Q value is
        rhs_fs = @class_vars.include?(var_name) && owns_class_var?(rel, s, var_name) ? '0' : entry['mruby']
        ed.add(init_d['brace'] + 1, init_d['brace'] + 1, "\n  #{var_name} = #{rhs_fs};")
        rewrite(rel, s, name, "#{var_name} = #{rhs_fs} (in Init)", 'a file-scope initializer is set at the start of Init (not a constant in C)')
        return
      end
      # nil, true and false compare by identity in CRuby (x == Qnil); mruby values are structs, so the comparison is a test
      # through a one-argument helper (the value is evaluated once) defined before the enclosing function
      # Q on the left of == or != with a call on the right (Qtrue == rb_obj_is_kind_of(...)): the helper test of the call
      if %w[Qnil Qtrue Qfalse].include?(name) && (rhs = q_left_call(masked, e))
        ops_l, call_end, neg_l = rhs
        fnl = enclosing_func(rel, s)
        if fnl && fnl['hstart']
          hname_l = { 'Qnil' => 'nfcx_is_nil', 'Qtrue' => 'nfcx_is_true', 'Qfalse' => 'nfcx_is_false' }[name]
          ptest_l = { 'Qnil' => 'mrb_nil_p', 'Qtrue' => 'mrb_true_p', 'Qfalse' => 'mrb_false_p' }[name]
          @q_helpers[rel] ||= Set.new
          unless @q_helpers[rel].include?(hname_l)
            @q_helpers[rel] << hname_l
            ed.add(fnl['hstart'], fnl['hstart'], "static mrb_bool #{hname_l}(mrb_value v) { return #{ptest_l}(v); }\n")
          end
          call_start = next_nonspace(masked, ops_l + 2)
          ed.add(s, call_start, "#{neg_l ? '!' : ''}#{hname_l}(")
          ed.add(call_end, call_end, ')')
          rewrite(rel, s, name, "#{hname_l}(...)", 'a comparison of nil, true or false with a call: the helper test of the call result')
          return
        end
      end
      if %w[Qnil Qtrue Qfalse].include?(name) && (cmp = q_comparison(rel, s, masked))
        ops, lhs_start, neg = cmp
        fnq = enclosing_func(rel, s)
        if fnq && fnq['hstart']
          hname = { 'Qnil' => 'nfcx_is_nil', 'Qtrue' => 'nfcx_is_true', 'Qfalse' => 'nfcx_is_false' }[name]
          ptest = { 'Qnil' => 'mrb_nil_p', 'Qtrue' => 'mrb_true_p', 'Qfalse' => 'mrb_false_p' }[name]
          @q_helpers[rel] ||= Set.new
          unless @q_helpers[rel].include?(hname)
            @q_helpers[rel] << hname
            ed.add(fnq['hstart'], fnq['hstart'],
                   "static mrb_bool #{hname}(mrb_value v) { return #{ptest}(v); }\n")
          end
          ed.add(lhs_start, lhs_start, "#{neg ? '!' : ''}#{hname}(")
          ed.add(ops, e, ')')
          (@q_done ||= Set.new) << s   # the comparison is rewritten here: value_equality_pass leaves it
          rewrite(rel, s, name, "#{hname}(…)", 'a comparison with nil, true or false (==, !=) is the helper test of the left operand')
          return
        end
      end
      ed.add(s, e, text)
      rewrite(rel, s, name, text)
    else
      refuse(rel, s, name, "unknown kind #{py_repr(kind)} in api_map.json")
    end
  end

  # rb_struct_define(name, m1, ..., NULL) and rb_struct_new(klass, v1, ..., vn) of the mruby-struct gem: the variadic helper
  # nfcx_struct_va (once per file, before the enclosing function) defines the class with Struct.new (the member symbols; a name
  # is the Struct constant) and rb_struct_new calls klass.new with as many values as klass.members has
  STRUCT_VA_PRELUDE = <<~'C'.chomp
    /* BC2CPP-MRBGEM: the mruby-struct gem's Struct: rb_struct_define and rb_struct_new (variadic) */
    #include <stdarg.h>
    static mrb_value
    nfcx_struct_define(mrb_state *mrb, const char *name, ...)
    {
      va_list ap;
      mrb_value argv[64];
      int n = 0;
      const char *m;
      mrb_value st = mrb_obj_value(mrb_class_get(mrb, "Struct"));
      mrb_value cls;
      va_start(ap, name);
      while (n < 64 && (m = va_arg(ap, const char *)) != NULL) {
        argv[n++] = mrb_symbol_value(mrb_intern_cstr(mrb, m));
      }
      va_end(ap);
      cls = mrb_funcall_argv(mrb, st, mrb_intern_cstr(mrb, "new"), n, argv);
      if (name) mrb_const_set(mrb, st, mrb_intern_cstr(mrb, name), cls);
      return cls;
    }
    static mrb_value
    nfcx_struct_new(mrb_state *mrb, mrb_value klass, ...)
    {
      va_list ap;
      mrb_value members = mrb_funcall_argv(mrb, klass, mrb_intern_cstr(mrb, "members"), 0, NULL);
      mrb_int n = RARRAY_LEN(members), i;
      mrb_value argv[64];
      va_start(ap, klass);
      for (i = 0; i < n && i < 64; i++) argv[i] = va_arg(ap, mrb_value);
      va_end(ap);
      return mrb_funcall_argv(mrb, klass, mrb_intern_cstr(mrb, "new"), (mrb_int)i, argv);
    }
  C

  # onig_foreach_name(reg, cb, arg) -> (nfcx_onig_mrb = mrb, onig_foreach_name(reg, nfcx_tramp_cb, arg)): the trampoline calls cb with
  # the state first, and cb takes mrb (it is threaded like a helper: see onig_foreach_calls)
  def onig_foreach_special(rel, s, nxt, called)
    unless called
      refuse(rel, s, 'onig_foreach_name', 'used without a call')
      return
    end
    rec = (@onig_calls || []).find { |c| c[:rel] == rel && c[:call] == s }
    if rec.nil?
      refuse(rel, s, 'onig_foreach_name', 'the callback is not a static function of this file with no other use (not supported)')
      return
    end
    fn = enclosing_func(rel, s)
    dpre = define_at(rel, s)
    at = dpre ? dpre[1] : (fn && fn['hstart'])
    unless at
      refuse(rel, s, 'onig_foreach_name', 'the trampoline this call needs has no place before it (not in a function or a macro)')
      return
    end
    cb = rec[:cb]
    tramp = "nfcx_tramp_#{cb}"
    ed = @edits[rel]
    @prelude_done ||= Set.new
    unless @prelude_done.include?([rel, 'nfcx_onig'])
      @prelude_done << [rel, 'nfcx_onig']
      ed.add(at, at, "static mrb_state *nfcx_onig_mrb;\n")
    end
    unless @prelude_done.include?([rel, tramp])
      @prelude_done << [rel, tramp]
      ed.add(at, at, "static int #{tramp}(const OnigUChar *name, const OnigUChar *name_end, int back_num, int *back_refs, " \
                     "OnigRegex regex, void *arg) {\n  return #{cb}(nfcx_onig_mrb, name, name_end, back_num, back_refs, regex, arg);\n}\n")
    end
    ed.drop(ed.overlapping(rec[:cb_pos], rec[:cb_pos] + cb.length))
    ed.add(rec[:cb_pos], rec[:cb_pos] + cb.length, tramp)
    ed.drop(ed.overlapping(s, s + 'onig_foreach_name'.length))
    ed.add(s, s + 'onig_foreach_name'.length, "(nfcx_onig_mrb = #{mrb_tok(rel, s)}, onig_foreach_name")
    ed.add(rec[:close] + 1, rec[:close] + 1, ')')
    rewrite(rel, s, 'onig_foreach_name', "(nfcx_onig_mrb = mrb, onig_foreach_name(..., #{tramp}, ...))",
            'the callback takes the mruby state (threaded like a helper); the trampoline passes it, and the state is stored for the call')
  end

  def struct_variadic_special(rel, s, nxt, called, name)
    unless called
      refuse(rel, s, name, 'used without a call')
      return
    end
    masked = @files[rel]['masked']
    cp = match_close(masked, nxt)
    if cp < 0
      refuse(rel, s, name, 'the call is not closed')
      return
    end
    fn = enclosing_func(rel, s)
    dpre = define_at(rel, s)
    at = dpre ? dpre[1] : (fn && fn['hstart'])
    unless at
      refuse(rel, s, name, 'the helper this call needs has no place before it (not in a function or a macro)')
      return
    end
    ed = @edits[rel]
    @prelude_done ||= Set.new
    unless @prelude_done.include?([rel, 'nfcx_struct_va'])
      @prelude_done << [rel, 'nfcx_struct_va']
      ed.add(at, at, STRUCT_VA_PRELUDE + "\n")
    end
    helper = name == 'rb_struct_define' ? 'nfcx_struct_define' : 'nfcx_struct_new'
    ed.add(s, s + name.length, helper)
    ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
    (@gem_deps ||= Set.new) << 'mruby-struct'
    rewrite(rel, s, name, "#{helper}(mrb, ...)", 'a Struct of the mruby-struct gem (Struct.new of the member symbols, or klass.new with the members count of values)')
  end

  # rb_ary_new3(n, a1..an) -> mrb_ary_new_from_values(mrb, n, (mrb_value[]){a1..an}): the count is a literal and the values
  # stay in place (the identifier pass converts them); the head and the closing paren are rewritten
  def ary_new3_special(rel, s, nxt, called)
    masked = @files[rel]['masked']
    text = @files[rel]['text']
    ed = @edits[rel]
    unless called
      refuse(rel, s, 'rb_ary_new3', 'used without a call')
      return
    end
    cp = match_close(masked, nxt)
    args = cp > 0 ? split_args(masked, nxt, cp) : []
    n_text = args.empty? ? '' : psl(text, args[0][0], args[0][1]).strip
    # rb_ary_new3(__VA_ARGS__) in a variadic macro: the count and the values come from each expansion, so the call is the
    # variadic helper nfcx_ary_new3(mrb, n, values...), defined once before the macro (its count is the first argument)
    if n_text == '__VA_ARGS__' && (dpre = define_at(rel, s))
      unless (@prelude_done ||= Set.new).include?([rel, 'nfcx_ary_new3'])
        @prelude_done << [rel, 'nfcx_ary_new3']
        ed.add(dpre[1], dpre[1], "#include <stdarg.h>\n" \
          "static mrb_value nfcx_ary_new3(mrb_state *mrb, int n, ...) {\n" \
          "  mrb_value ary = mrb_ary_new_capa(mrb, n);\n" \
          "  va_list ap; int i;\n  va_start(ap, n);\n" \
          "  for (i = 0; i < n; i++) mrb_ary_push(mrb, ary, va_arg(ap, mrb_value));\n" \
          "  va_end(ap);\n  return ary;\n}\n")
      end
      ed.add(s, s + 'rb_ary_new3'.length, 'nfcx_ary_new3')
      ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
      rewrite(rel, s, 'rb_ary_new3', 'nfcx_ary_new3(mrb, __VA_ARGS__)', 'the count and values come from the expansion (a variadic helper)')
      return
    end
    unless n_text.match?(/\A\d+\z/) && args.size == 1 + n_text.to_i
      refuse(rel, s, 'rb_ary_new3', 'the count must be an integer literal that matches the values (not supported)')
      return
    end
    n = n_text.to_i
    tok = mrb_tok(rel, s)
    spans = [[s, nxt + 1]]
    spans << [args[0][0], args[1][0]] if n.positive?
    spans << [cp, cp + 1]
    if spans.any? { |a, b| ed.overlaps(a, b) }
      refuse(rel, s, 'rb_ary_new3', 'the call overlaps a rewritten span (not supported)')
      return
    end
    if n.zero?
      ed.add(s, cp + 1, "mrb_ary_new_from_values(#{tok}, 0, NULL)")
    else
      ed.add(s, nxt + 1, "mrb_ary_new_from_values(#{tok}, #{n}, (mrb_value[]){")
      ed.add(args[0][0], args[1][0], '')
      ed.add(cp, cp + 1, '})')
    end
    rewrite(rel, s, 'rb_ary_new3', "mrb_ary_new_from_values(#{tok}, #{n}, ...)",
            'the values are the arguments of rb_ary_new3, in an mrb_value array (mrb_ary_new_from_values)')
  end

  # rb_funcall(recv, ID, n, a1..an) -> mrb_funcall_argv(mrb, recv, name, n, (mrb_value[]){a1..an}), with the name from
  # rb_intern("lit") or a character ID ('*'). Only the call's head, its ID and count and its closing paren are rewritten:
  # the receiver and the arguments stay in place, so the identifier pass converts them as it does everywhere else.
  # Data_Make_Struct(klass, type, mark, free, ptr) -> a static mrb_data_type (threaded callbacks) and
  # mrb_data_object_alloc of a zeroed struct: ptr = (type *)mrb_calloc(...). The static type is declared before the
  # function that holds the call (its callbacks must be declared before it, so they must be defined earlier).
  def data_make_special(rel, s, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    unless called
      refuse(rel, s, 'Data_Make_Struct', 'used without a call')
      return
    end
    cp = match_close(masked, nxt)
    args = cp > 0 ? split_args(masked, nxt, cp) : []
    texts = args.map { |a, b| psl(text, a, b).strip }
    unless args.size == 5
      refuse(rel, s, 'Data_Make_Struct', 'Data_Make_Struct takes five arguments')
      return
    end
    klass, type, mk, fr, ptr = texts
    fn = enclosing_func(rel, s)
    unless fn && (@valid_reg_names.include?(fn['name']) || (@needs || Set.new).include?(fn['name']))
      refuse(rel, s, 'Data_Make_Struct', 'the call is in a function that does not have the mruby state')
      return
    end
    unless ptr.match?(/\A[A-Za-z_][#{WC}]*\z/) && klass.match?(/\A[A-Za-z_][#{WC}]*(?:(?:->|\.)[A-Za-z_][#{WC}]*)*\z/) &&
           type.match?(/\A(?:struct[ \t]+)?[A-Za-z_][#{WC}]*\z/) &&
           [mk, fr].all? { |x| x.match?(/\A[A-Za-z_][#{WC}]*\z/) || x == 'NULL' || x == '0' }
      refuse(rel, s, 'Data_Make_Struct', 'the arguments are not plain names (klass, type, callbacks, pointer)')
      return
    end
    # the callbacks must be defined before the function that holds the static type
    [mk, fr].each do |x|
      next if x == 'NULL' || x == '0'
      dd = (@defs[x] || []).reject { |y| y['proto'] }
      unless dd.size == 1 && dd[0]['file'] == rel && dd[0]['hstart'] < fn['hstart']
        refuse(rel, s, 'Data_Make_Struct', "callback #{x} is not defined in this file before the function that makes the object")
        return
      end
    end
    @dm_counter = (@dm_counter || 0) + 1
    dt = "nfcx_dt_#{@dm_counter}"
    free_c = fr == '0' ? 'NULL' : fr
    mark_c = mk == '0' ? 'NULL' : mk
    ed.add(fn['hstart'], fn['hstart'], "static const mrb_data_type #{dt} = { #{texts[1].inspect.gsub('"', '"')}, #{free_c}, #{mark_c} };\n")
    tok = mrb_tok(rel, s)
    tname = type.sub(/\Astruct[ \t]+/, '')
    cls = @class_vars.include?(klass) ? klass : "mrb_class_ptr(#{klass})"
    new = "mrb_obj_value(mrb_data_object_alloc(#{tok}, #{cls}, (#{ptr} = (#{type} *)mrb_calloc(#{tok}, 1, sizeof(#{type}))), &#{dt}))"
    ed.add(s, cp + 1, new)
    rewrite(rel, s, 'Data_Make_Struct', new, 'the struct is zeroed (mrb_calloc, as Data_Make_Struct); its type is a static mrb_data_type with the threaded callbacks')
  end

  def funcall_special(rel, s, nxt, called)
    masked = @files[rel]['masked']
    text = @files[rel]['text']
    ed = @edits[rel]
    unless called
      refuse(rel, s, 'rb_funcall', 'used without a call')
      return
    end
    cp = match_close(masked, nxt)
    args = cp > 0 ? split_args(masked, nxt, cp) : []
    if args.size < 3
      refuse(rel, s, 'rb_funcall', 'rb_funcall needs a receiver, an ID and a count')
      return
    end
    id_text = psl(text, args[1][0], args[1][1]).strip
    n_text = psl(text, args[2][0], args[2][1]).strip
    # rb_funcall(recv, id, __VA_ARGS__) in a variadic macro: the count and the arguments come from each expansion, so the call is
    # the variadic helper nfcx_funcall_va(mrb, recv, id, n, args...), defined once before the macro (up to 16 arguments)
    if n_text == '__VA_ARGS__' && args.size == 3 && (dpre = define_at(rel, s))
      unless (@prelude_done ||= Set.new).include?([rel, 'nfcx_funcall_va'])
        @prelude_done << [rel, 'nfcx_funcall_va']
        ed.add(dpre[1], dpre[1], "#include <stdarg.h>\n" \
          "static mrb_value nfcx_funcall_va(mrb_state *mrb, mrb_value recv, mrb_sym mid, int n, ...) {\n" \
          "  mrb_value argv[16]; va_list ap; int i;\n" \
          "  if (n < 0 || n > 16) mrb_raise(mrb, E_ARGUMENT_ERROR, \"too many arguments\");\n" \
          "  va_start(ap, n);\n  for (i = 0; i < n; i++) argv[i] = va_arg(ap, mrb_value);\n" \
          "  va_end(ap);\n  return mrb_funcall_argv(mrb, recv, mid, n, argv);\n}\n")
      end
      ed.add(s, s + 'rb_funcall'.length, 'nfcx_funcall_va')
      ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
      rewrite(rel, s, 'rb_funcall', 'nfcx_funcall_va(mrb, recv, mid, n, args...)', 'the count and the arguments come from the expansion (a variadic helper)')
      return
    end
    unless n_text.match?(/\A\d+\z/) && args.size == 3 + n_text.to_i
      refuse(rel, s, 'rb_funcall', 'the argument count must be an integer literal that matches the arguments')
      return
    end
    name =
      if (m = /\Arb_intern\(\s*"([^"\\]+)"\s*\)\z/.match(id_text)) then m[1]
      elsif (m = /\A'([^'\\])'\z/.match(id_text)) then m[1]
      end
      name ||= @id_literals[id_text] if id_text.match?(/\A[#{WC}]+\z/)
    # SYM2ID(x) with x a Symbol value (a method name held at run time): the ID is that symbol (mrb_symbol), as in CRuby
    sym_m = name.nil? && /\ASYM2ID\(\s*([A-Za-z_][#{WC}]*)\s*\)\z/.match(id_text)
    # an ID that is a variable, a pointer or array element, or a member (ID i; ID *idp; odd->attrs[k]) is already a symbol: every
    # ID declaration is an mrb_sym (the type map), so the expression is passed unchanged
    id_var = name.nil? && !sym_m && id_text.match?(/\A\*?\s*[A-Za-z_]\w*(?:(?:->|\.)[A-Za-z_]\w*|\[[^\]]*\])*\z/) &&
             !@entries.key?(id_text.delete('*').strip)
    if name.nil? && !sym_m && !id_var
      refuse(rel, s, 'rb_funcall', "the ID #{id_text} is not rb_intern of a string literal or a character (not supported)")
      return
    end
    tok = mrb_tok(rel, s)
    id_expr = sym_m ? "mrb_symbol(#{sym_m[1]})" : (id_var ? id_text : "mrb_intern_cstr(#{tok}, \"#{name}\")")
    n = n_text.to_i
    spans = [[s, nxt + 1], [args[1][0], n.zero? ? args[2][1] : args[3][0]]]
    spans << [cp, cp + 1] if n.positive?
    if spans.any? { |a, b| ed.overlaps(a, b) }
      refuse(rel, s, 'rb_funcall', 'the call overlaps a rewritten span (not supported)')
      return
    end
    ed.add(s, nxt + 1, "mrb_funcall_argv(#{tok}, ")
    if n.zero?
      ed.add(args[1][0], args[2][1], "#{id_expr}, 0, NULL")
    else
      ed.add(args[1][0], args[3][0], "#{id_expr}, #{n}, (mrb_value[]){")
      ed.add(cp, cp + 1, '})')
    end
    rewrite(rel, s, 'rb_funcall', "mrb_funcall_argv(#{tok}, ..., #{id_expr}, #{n}, ...)",
            sym_m ? 'the method name is the Symbol value of the SYM2ID argument (mrb_symbol)' \
                  : id_var ? 'the method name is an ID already converted to a symbol (mrb_sym), passed unchanged' \
                  : 'the receiver and arguments are unchanged; the method name is an interned C string (mrb_funcall_argv)')
  end

  # RB_ALLOCV_N(type, v, n) in a declaration `T *p = RB_ALLOCV_N(type, v, n);` is mrb_malloc of n elements; RB_ALLOCV_END(v) is
  # the mrb_free of p. The pair must be in one function with no return or goto between (else the buffer would leak: stuck).
  def allocv_n_special(rel, s, nxt, called)
    masked = @files[rel]['masked']
    ed = @edits[rel]
    unless called
      refuse(rel, s, 'RB_ALLOCV_N', 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    text = @files[rel]['text']
    fn = enclosing_func(rel, s)
    before = masked[[s - 160, 0].max...s].to_s
    decl = before.match(/([A-Za-z_]\w*)[ \t\n]*\*[ \t\n]*([A-Za-z_]\w*)[ \t\n]*=[ \t\n]*\z/)
    # an assignment to a pointer declared earlier (buf = ALLOCV_N(char, v, n);): the element type is the macro's first argument
    assign = decl.nil? && args.size == 3 ? before.match(/\b([A-Za-z_]\w*)[ \t\n]*=[ \t\n]*\z/) : nil
    if args.size != 3 || fn.nil? || (decl.nil? && assign.nil?)
      refuse(rel, s, 'RB_ALLOCV_N', 'stuck point (temporary buffer): RB_ALLOCV_N is used other than as a pointer declaration or an assignment (p = RB_ALLOCV_N(...)) in a function, so its free has no mruby form here')
      return
    end
    if decl
      type = decl[1]
      ptr = decl[2]
    else
      type = psl(text, args[0][0], args[0][1]).strip
      ptr = assign[1]
    end
    v = psl(text, args[1][0], args[1][1]).strip
    n = psl(text, args[2][0], args[2][1]).strip
    unless v.match?(/\A[A-Za-z_]\w*\z/)
      refuse(rel, s, 'RB_ALLOCV_N', 'stuck point (temporary buffer): the VALUE holder of RB_ALLOCV_N is not a plain name')
      return
    end
    (@allocv ||= {})[[rel, v]] = { pos: s, ptr: ptr, fn: fn['name'], type: type }
    ed.add(s, close + 1, "(#{type} *)mrb_malloc(#{mrb_tok(rel, s)}, sizeof(#{type}) * (#{n}))")
    rewrite(rel, s, 'RB_ALLOCV_N', "(#{type} *)mrb_malloc(...)", 'a temporary buffer: mrb_malloc, freed by RB_ALLOCV_END of the same VALUE; mrb_malloc raises (longjmp) on exhaustion, which leaks the buffer as CRuby\'s ALLOCV would not')
  end

  def allocv_end_special(rel, s, nxt, called)
    masked = @files[rel]['masked']
    ed = @edits[rel]
    close = called ? match_close(masked, nxt) : -1
    args = close > 0 ? split_args(masked, nxt, close) : []
    rec = nil
    if args.size == 1
      v = psl(@files[rel]['text'], args[0][0], args[0][1]).strip
      rec = (@allocv || {})[[rel, v]]
    end
    fn = enclosing_func(rel, s)
    if rec.nil? || fn.nil? || rec[:fn] != fn['name'] || rec[:pos] >= s
      refuse(rel, s, 'RB_ALLOCV_END', 'stuck point (temporary buffer): RB_ALLOCV_END has no RB_ALLOCV_N of its VALUE before it in the same function')
      return
    end
    between = masked[rec[:pos]...s].to_s
    if between.match?(/\b(?:return|goto)\b/)
      refuse(rel, s, 'RB_ALLOCV_END', 'stuck point (temporary buffer): a return or goto between RB_ALLOCV_N and RB_ALLOCV_END would leak the buffer')
      return
    end
    ed.add(s, close + 1, "mrb_free(#{mrb_tok(rel, s)}, #{rec[:ptr]})")
    rewrite(rel, s, 'RB_ALLOCV_END', "mrb_free(..., #{rec[:ptr]})", 'the temporary buffer is freed (mrb_free)')
  end

  def special(rel, s, e, name, entry, nxt, called)
    masked = @files[rel]['masked']
    text = @files[rel]['text']
    ed = @edits[rel]
    if name == 'Data_Make_Struct'
      data_make_special(rel, s, nxt, called)
      return
    end
    if name == 'rb_funcall'
      funcall_special(rel, s, nxt, called)
      return
    end
    if %w[RB_ALLOCV_N ALLOCV_N].include?(name)
      allocv_n_special(rel, s, nxt, called)
      return
    end
    if %w[RB_ALLOCV_END ALLOCV_END].include?(name)
      allocv_end_special(rel, s, nxt, called)
      return
    end
    if name == 'rb_ary_new3'
      ary_new3_special(rel, s, nxt, called)
      return
    end
    if name == 'onig_foreach_name'
      onig_foreach_special(rel, s, nxt, called)
      return
    end
    if %w[rb_struct_define rb_struct_new].include?(name)
      struct_variadic_special(rel, s, nxt, called, name)
      return
    end
    if name == 'RB_GC_GUARD'
      fn = enclosing_func(rel, s)
      if !called || fn.nil? || !@needs.include?(fn['name'])
        refuse(rel, s, name, 'GC guard outside a function that has an mrb_state in scope')
        return
      end
      close = pyfind(masked, ')', nxt)
      arg = py_strip(psl(text, nxt + 1, close))
      # a variable, or a member path of one (a.bigdecimal, p->value): the guarded value is the member
      if close < 0 || !/\A[A-Za-z_][#{WC}]*(?:(?:\.|->)[A-Za-z_][#{WC}]*)*\z/.match?(arg)
        refuse(rel, s, name, 'GC guard argument is not a variable or a member path')
        return
      end
      ed.add(s, close + 1, "mrb_gc_protect(#{mrb_tok(rel, s)}, #{arg})")
      rewrite(rel, s, name, "mrb_gc_protect(mrb, #{arg})",
              'keeps the value rooted until the arena is restored (fine within the call; use mrb_gc_register to outlive it)')
      return
    end
    case name
    when 'rb_define_method', 'rb_define_private_method', 'rb_define_singleton_method', 'rb_define_module_function', 'rb_define_global_function'
      rec = @reg_by_call[[rel, s]]
      if rec.nil? || !called || nxt != rec['open']
        refuse(rel, s, name, 'used without a registration call')
        return
      end
      if rec['error']
        refuse(rel, s, name, rec['error'])
        return
      end
      tgt = rec['target']
      if name == 'rb_define_global_function'
        # the Kernel module: a private instance method and a module function, as CRuby's global function
        tgt = 'mrb->kernel_module'
      # CLASS_OF(cls) of a tracked class is its singleton class (CRuby creates it with the class): the target becomes
      # mrb_class_ptr(mrb_singleton_class(...)); the identifier pass skips the CLASS_OF token inside that edit
      elsif (co = /\ACLASS_OF\(\s*([A-Za-z_]\w*)\s*\)\z/.match(tgt)) && @class_vars.include?(co[1])
        tgt_new = "mrb_class_ptr(mrb_singleton_class(#{mrb_tok(rel, s)}, mrb_obj_value(#{co[1]})))"
        ed.add(*rec['target_span'], tgt_new)
        tgt = tgt_new
      # a VALUE name of the function (a class value, unwrapped with mrb_class_ptr), or a VALUE struct member
      elsif (rfn = enclosing_func(rel, s)) && (value_names_of(rfn).include?(tgt) && !@class_vars.include?(tgt) || is_param(rel, s, tgt)) &&
            tgt.match?(/\A[A-Za-z_][#{WC}]*\z/)
        tgt_new = "mrb_class_ptr(#{tgt})"
        ed.add(*rec['target_span'], tgt_new)
        tgt = tgt_new
      # a tracked class variable, or a CRuby class constant with a mruby class expression (rb_cString -> mrb->string_class)
      elsif !@class_vars.include?(tgt) && tgt != 'rb_cObject' && !class_expr_ok.call(tgt)
        refuse(rel, s, name, "target #{py_repr(tgt)} is not a tracked class or module variable")
        return
      end
      new = { 'rb_define_method' => 'mrb_define_method', 'rb_define_private_method' => 'mrb_define_method',
              'rb_define_singleton_method' => 'mrb_define_class_method',
              'rb_define_module_function' => 'mrb_define_module_function',
              'rb_define_global_function' => 'mrb_define_module_function' }[name]
      ed.add(s, e, new)
      if name == 'rb_define_global_function'
        ed.add(rec['name_span'][0], rec['name_span'][0], "#{mrb_tok(rel, s)}, #{tgt}, ")
      else
        ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
      end
      fs, fe = rec['func_span']
      ed.add(fs, fe, rec['func'])
      as_, ae = rec['argc_span']
      aspec =
        if rec['argc'] == -1
          'MRB_ARGS_ANY()' # the function reads its arguments itself (see variadic_params)
        elsif rec['argc'] == 0
          'MRB_ARGS_NONE()'
        else
          "MRB_ARGS_REQ(#{rec['argc']})"
        end
      ed.add(as_, ae, aspec)
      rewrite(rel, s, name, "#{new}(mrb, #{tgt}, \"#{rec['name']}\", #{rec['func']}, #{aspec})")
    when 'rb_scan_args'
      scan_args(rel, s, e, nxt, called)
    when 'RB_TYPE_P'
      type_p(rel, s, e, nxt, called)
    when 'Check_Type', 'rb_check_type'
      check_type(rel, s, e, name, nxt, called)
    when 'rb_gc_start'
      gc_start(rel, s, e, nxt, called)
    when 'rb_gc_writebarrier'
      gc_writebarrier(rel, s, e, nxt, called)
    when 'rb_define_const'
      define_const(rel, s, e, nxt, called)
    when 'rb_const_get'
      const_get(rel, s, e, nxt, called)
    when 'rb_require'
      require_call(rel, s, e, nxt, called)
    when 'rb_raise', 'rb_enc_raise'
      unless called
        refuse(rel, s, name, 'used without a call')
        return
      end
      cp = match_close(masked, nxt)
      args = cp > 0 ? split_args(masked, nxt, cp) : []
      # rb_enc_raise(enc, exc, fmt, ...): the encoding of the message is not kept (the fork's messages are not tagged), so the
      # encoding argument is dropped and the rest is a rb_raise
      if name == 'rb_enc_raise'
        if args.size < 3
          refuse(rel, s, name, 'rb_enc_raise needs an encoding, an exception class and a format string')
          return
        end
        ed.add(args[0][0], args[1][0], '')
        args = args[1..-1]
      end
      if args.size < 2
        refuse(rel, s, name, 'rb_raise needs an exception class and a format string')
        return
      end
      fmt = psl(text, args[1][0], args[1][1])
      if fmt.include?('PRIsVALUE') && !prsvalue_edits(rel, args[1][0], args[1][1])
        refuse(rel, s, name, 'PRIsVALUE format (VALUE to string) not supported in this position (only "%"PRIsVALUE and "%+"PRIsVALUE)')
        return
      end
      # a VALUE class (a VALUE name or member, not a tracked class variable) is unwrapped: mrb_raisef takes an RClass *
      cls_t = psl(text, args[0][0], args[0][1]).strip
      # (a tracked class variable that is not owned is an mrb_value too: its class pointer is taken)
      if (@class_vars.include?(cls_t) && !owns_class_var?(rel, args[0][0], cls_t)) || !@class_vars.include?(cls_t) && (cls_t.match?(/\A[A-Za-z_]\w*\z/) && (value_names_of(enclosing_func(rel, s) || {}).include?(cls_t) || @files.keys.any? { |fr| file_scope_value_names(fr).include?(cls_t) }) ||
                                       cls_t.match?(/(?:->|\.)[A-Za-z_]\w*\z/) && value_field_names.include?(cls_t[/([A-Za-z_]\w*)\z/]))
        ed.add(args[0][0], args[0][1], "mrb_class_ptr(#{cls_t})")
      end
      ed.add(s, e, 'mrb_raisef')
      ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
      if (cm_r = cls_t.match(/\A([A-Za-z_]\w*)\s*\(/)) && value_call_name?(cm_r[1])
        # a call whose result is a VALUE (rb_const_get_at(...), a converted function returning VALUE): the call's own rewrites
        # stay, and the class pointer of its result is taken around it (after the state argument, which precedes it)
        ed.add(args[0][0], args[0][0], 'mrb_class_ptr(')
        ed.add(args[0][1], args[0][1], ')')
      end
      rewrite(rel, s, name, 'mrb_raisef')
    else
      refuse(rel, s, name, 'unknown special handler')
    end
  end

  # rb_const_get(klass, id) -> mrb_const_get(mrb, klass, id). Both take the receiver as a VALUE and the name as
  # an ID (mrb_sym); rb_cObject is passed as its VALUE. Differences, recorded as a caveat: a module receiver
  # does not fall back to Object in mruby (CRuby does), and there is no autoload.
  # rb_require("feature") -> rb_require(mrb, "feature") (the fork's require, mrbgems/mruby-require). A literal feature is
  # required at run time, and when api_map.json "require_gems" says which built gem provides it, that gem is a dependency of
  # the converted gem (mrbgem.rake), so the build includes it. A feature with no entry is required as written: the build must
  # provide it, or the require raises LoadError (WARNINGS.txt says so). A name that is not a literal cannot be checked.
  def require_call(rel, s, e, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    unless called
      refuse(rel, s, 'rb_require', 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    if args.size != 1
      refuse(rel, s, 'rb_require', 'rb_require takes a feature name')
      return
    end
    a0, a1 = args[0]
    lit = psl(text, a0, a1)
    m = /\A"([^"\\]*)"\z/.match(lit)
    unless m
      refuse(rel, s, 'rb_require', 'stuck point (require): the feature name is not a literal, so the build cannot tell which gem provides it')
      return
    end
    feature = m[1]
    gem = @require_gems[feature]
    if gem
      (@gem_deps ||= Set.new) << gem
    else
      (@warnings ||= []) << { 'file' => rel, 'line' => line_of(text, s), 'api' => 'rb_require',
                              'reason' => "feature '#{feature}' has no providing gem in api_map.json require_gems: it must be provided by a built gem" }
    end
    ed.add(nxt + 1, nxt + 1, 'mrb, ')
    rewrite(rel, s, 'rb_require', 'rb_require', "the fork's require (mrbgems/mruby-require): feature '#{feature}'#{gem ? " is provided by #{gem}" : ''}")
  end

  # The runtime dependencies named by the gem's own gemspec (<gem root>/*.gemspec, the root above ext/<name>): the names of
  # add_runtime_dependency and add_dependency calls (development dependencies are not runtime).
  def gemspec_runtime_deps
    root = File.dirname(File.dirname(@cext_dir))
    deps = []
    Dir.glob(File.join(root, '*.gemspec')).sort.each do |gs|
      File.readlines(gs, encoding: 'UTF-8').each do |line|
        line = line.scrub
        next if line =~ /development/
        m = /\badd_(?:runtime_)?dependency\s*\(?\s*['"]([^'"]+)['"]/.match(line)
        deps << m[1] if m
      end
    end
    deps.uniq
  end

  def const_get(rel, s, e, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    unless called
      refuse(rel, s, 'rb_const_get', 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    if args.size != 2
      refuse(rel, s, 'rb_const_get', 'rb_const_get takes a class and an ID')
      return
    end
    ed.add(s, e, 'mrb_const_get')
    ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
    ed.add(args[0][0], args[0][1], "mrb_obj_value(#{mrb_tok(rel, s)}->object_class)") if psl(text, args[0][0], args[0][1]) == 'rb_cObject'
    rewrite(rel, s, 'rb_const_get', 'mrb_const_get(mrb, klass, id)',
            'a module receiver does not fall back to Object as CRuby does; no autoload')
  end

  # rb_define_const(klass, "NAME", value) -> mrb_define_const(mrb, klass, "NAME", value). The receiver must be
  # a tracked class or module variable (a struct RClass *) or rb_cObject, as mrb_define_const takes a class
  # pointer. mruby stores the constant without CRuby's 'already initialized' warning on redefinition.
  def define_const(rel, s, e, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    unless called
      refuse(rel, s, 'rb_define_const', 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    if args.size != 3
      refuse(rel, s, 'rb_define_const', 'rb_define_const takes a class, a name and a value')
      return
    end
    tgt = psl(text, args[0][0], args[0][1])
    # a VALUE parameter is a module or class the caller holds (msgpack's *_module_init(VALUE mMessagePack)): its class pointer is read
    value_param = is_param(rel, args[0][0], tgt) && (fe = enclosing_func(rel, s)) && value_names_of(fe).include?(tgt)
    unless tgt == 'rb_cObject' || (@class_vars.include?(tgt) && !is_param(rel, args[0][0], tgt)) || class_expr_ok.call(tgt) || value_param
      refuse(rel, s, 'rb_define_const', "target #{py_repr(tgt)} is not a tracked class or module variable")
      return
    end
    ed.add(s, e, 'mrb_define_const')
    ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
    # a VALUE parameter as the receiver: its class pointer (the mrb_class_ptr of a VALUE class, as the class arguments are)
    if value_param
      ed.add(args[0][0], args[0][0], 'mrb_class_ptr(')
      ed.add(args[0][1], args[0][1], ')')
    end
    rewrite(rel, s, 'rb_define_const', "mrb_define_const(mrb, #{tgt}, ...)",
            'an existing constant is replaced without CRuby\'s "already initialized" warning')
  end

  # rb_scan_args(argc, argv, FMT, &v...) in a variadic method, as a statement, with FMT of the form
  # "<lead><opt>" (no rest, keyword or block parts) -> mrb_get_args(mrb, "o|o", &v...). mrb_get_args reads
  # the same stack the method was called with, and its arity check is the one rb_scan_args makes. Optional
  # outputs are set to nil first, because mrb_get_args leaves a missing optional argument unwritten.
  # Functions that are not registered variadic methods but read rb_scan_args on their own (argc, argv) parameters: a helper
  # called with an argv array (the registered method's arguments, or NULL with argc 0). Name => [argc, argv, self] names.
  def argv_scan_helpers
    @argv_scan_helpers ||= begin
      out = {}
      @files.each do |rel, f|
        masked, text = f['masked'], f['text']
        finditer(/(?<![#{WC}$.>])rb_scan_args#{SS}\(/, masked).each do |m|
          s = m.begin(0)
          open = m.end(0) - 1
          close = match_close(masked, open)
          next if close < 0
          args = split_args(masked, open, close).map { |a, b| psl(text, a, b).strip }
          next if args.size < 3
          fn = enclosing_func(rel, s)
          next if fn.nil? || @variadic.key?(fn['name'])
          plist = fn['params'].to_s.split(',', -1).map { |x| x.strip[/([A-Za-z_][#{WC}]*)\s*\z/, 1] }
          next unless plist.size >= 2 && plist[0] == args[0] && plist[1] == args[1]
          out[fn['name']] = plist[0, 3]
        end
      end
      out
    end
  end

  # the function of a macro body's expansions, when every expansion is a variadic method with the same argc and argv names
  # (the macro's rb_scan_args then reads its arguments as each of them does): nil otherwise
  def macro_expansion_fn(rel, s)
    dm = define_at(rel, s)
    return nil unless dm
    fns = (@occ[dm[0]] || []).reject { |orel, os, _oe| define_at(orel, os) }.map { |orel, os, _oe| enclosing_func(orel, os) }
    return nil if fns.empty? || fns.any?(&:nil?)
    return nil unless fns.all? { |f| @variadic.key?(f['name']) }
    return nil unless fns.map { |f| @variadic[f['name']] }.uniq.size == 1
    fns.first
  end

  def scan_args(rel, s, e, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    fn = enclosing_func(rel, s) || (called ? macro_expansion_fn(rel, s) : nil)
    argv_helper = called && fn && !@variadic.key?(fn['name']) && argv_scan_helpers.key?(fn['name'])
    if !called || fn.nil? || (!@variadic.key?(fn['name']) && !argv_helper)
      refuse(rel, s, 'rb_scan_args', 'only supported directly in a variadic method (argc -1)')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    if args.size < 3
      refuse(rel, s, 'rb_scan_args', 'rb_scan_args needs argc, argv and a format string')
      return
    end
    argc_n, argv_n, self_n = argv_helper ? argv_scan_helpers[fn['name']] : @variadic[fn['name']]
    if psl(text, args[0][0], args[0][1]) != argc_n || psl(text, args[1][0], args[1][1]) != argv_n
      refuse(rel, s, 'rb_scan_args', 'rb_scan_args is not called on the argc and argv of its method')
      return
    end
    # the format: <lead><optional> [*] [:] [&] (required, optional, rest, keyword, block: CRuby's order; no post parts)
    fm = /\A"([0-9])([0-9]?)(\*?)(:?)(&?)"\z/.match(psl(text, args[2][0], args[2][1]))
    unless fm
      refuse(rel, s, 'rb_scan_args',
             "format #{psl(text, args[2][0], args[2][1])} not supported " \
             '(only "<lead><optional>[*][:][&]": no post-rest parts)')
      return
    end
    lead = fm[1].to_i
    opt = (fm[2].empty? ? 0 : fm[2].to_i)
    rest = !fm[3].empty?
    kw = !fm[4].empty?
    blk = !fm[5].empty?
    nout = lead + opt + (rest ? 1 : 0) + (kw ? 1 : 0) + (blk ? 1 : 0)
    outs = args[3..] || []
    if outs.size != nout
      refuse(rel, s, 'rb_scan_args', "format needs #{nout} output pointer(s), call gives #{outs.size}")
      return
    end
    names = []
    outs.each do |a, b|
      # a NULL output is an argument the caller discards: a dummy VALUE takes it (declared at the start of the function)
      if psl(text, a, b).strip == 'NULL'
        dummy = "nfcx_skip#{a}"
        ed.add(fn['brace'] + 1, fn['brace'] + 1, " mrb_value #{dummy}; ")
        names << dummy
        next
      end
      om = /\A&#{SS}([A-Za-z_][#{WC}]*)\z/.match(psl(text, a, b))
      if !om || @class_vars.include?(om[1]) || [argc_n, argv_n, self_n].include?(om[1])
        refuse(rel, s, 'rb_scan_args', "output #{py_repr(psl(text, a, b))} is not a plain local variable")
        return
      end
      names << om[1]
    end
    prev = prev_nonspace(masked, s - 1)
    after = next_nonspace(masked, close + 1)
    # the value is used only in the form (nil-initialised outputs, mrb_get_args(...)): mrb_get_args returns the number of
    # arguments it consumed, which is the argument count here (no rest part, and extra arguments are an error). A used value
    # with a keyword part, or with a rest part, takes a statement expression (GNU C, which the mruby build accepts).
    used = (prev >= 0 && !";{}".include?(masked[prev])) || after < 0 || masked[after] != ';'
    fmt = 'o' * lead + (opt > 0 ? '|' + 'o' * opt : '') + (rest ? '*' : '') + (kw ? ':' : '') + (blk ? '&' : '')
    # a split method's implementation takes its arguments as an argv array (mrb_value *), not from the mruby frame:
    # its lead and optional outputs are read from argv, the argc check raises as mrb_get_args does, and the value is argc
    if @split_names.include?(fn['name']) || argv_helper
      if rest
        refuse(rel, s, 'rb_scan_args', 'a split method reads its arguments from an argv array: rest parts are not supported there')
        return
      end
      # a block part is the block of the frame the call runs in (CRuby's rb_scan_args "&" reads the same slot): nfcx_block_arg
      # reads it, as the helper's rb_yield does (one definition per file, before the function)
      blk_assign = ''
      if blk
        unless @block_arg_files.include?(rel)
          @block_arg_files << rel
          ed.add(fn['hstart'], fn['hstart'],
                 "static mrb_value nfcx_block_arg(mrb_state *mrb)\n{\n  mrb_value nfcx_b;\n  mrb_get_args(mrb, \"&\", &nfcx_b);\n  return nfcx_b;\n}\n\n")
        end
        blk_assign = "#{names[-1]} = nfcx_block_arg(#{mrb_tok(rel, s)}); "
      end
      # a keyword part takes the trailing Hash when there are more arguments than positional outputs (CRuby 3 keywords);
      # an empty Hash is nil, as in the frame form. The count returned excludes the keyword Hash.
      kw_pre = kw ? "#{names[lead + opt]} = mrb_nil_value(); if (nfcx_ac > #{lead + opt} && mrb_hash_p(#{argv_n}[nfcx_ac - 1])) { #{names[lead + opt]} = #{argv_n}[--nfcx_ac]; } " \
                  "#{names[lead + opt]} = (mrb_hash_p(#{names[lead + opt]}) && mrb_hash_size(#{mrb_tok(rel, s)}, #{names[lead + opt]}) ? #{names[lead + opt]} : mrb_nil_value()); " : ''
      assigns = (0...(lead + opt)).map { |i| "#{names[i]} = (#{i} < nfcx_ac) ? #{argv_n}[#{i}] : mrb_nil_value(); " }.join
      ed.add(s, close + 1, "({ int nfcx_ac = #{argc_n}; #{kw_pre}if (nfcx_ac < #{lead} || nfcx_ac > #{lead + opt}) " \
                           "mrb_argnum_error(#{mrb_tok(rel, s)}, nfcx_ac, #{lead}, #{lead + opt}); #{assigns}#{blk_assign}nfcx_ac; })")
      rewrite(rel, s, 'rb_scan_args', "argv form of mrb_get_args(\"#{fmt}\", ...)",
              'the arguments come from the argv array of the split method; the argc check raises ArgumentError as CRuby does')
      return
    end
    # the outputs in mruby's order: the positional ones, then the rest (its array is built from the pointer and length),
    # the keyword hash (an empty table takes every keyword; CRuby gives nil when there are none), the block
    pos_names = names[0, lead + opt]
    rest_name = rest ? names[lead + opt] : nil
    kw_name = kw ? names[lead + opt + (rest ? 1 : 0)] : nil
    blk_name = blk ? names[-1] : nil
    pre = pos_names[lead..].to_a.map { |n| "#{n} = mrb_nil_value(), " }.join
    pre += "#{kw_name} = mrb_nil_value(), " if kw
    callargs = ['mrb', "\"#{fmt}\""] + pos_names.map { |n| '&' + n }
    callargs += ['&nfcx_ra', '&nfcx_rn'] if rest
    callargs << "(const mrb_kwargs[]){{0, NULL, NULL, 0, &#{kw_name}}}" if kw
    callargs << "&#{blk_name}" if blk
    callargs = callargs.join(', ')
    normalise = kw ? "#{kw_name} = (mrb_hash_size(mrb, #{kw_name}) ? #{kw_name} : mrb_nil_value()); " : ''
    if rest || (used && kw)
      stmts = pos_names[lead..].to_a.map { |n| "#{n} = mrb_nil_value(); " }.join
      stmts += "#{kw_name} = mrb_nil_value(); " if kw
      stmts += "mrb_value *nfcx_ra; mrb_int nfcx_rn; " if rest
      rest_build = rest ? "#{rest_name} = mrb_ary_new_from_values(#{mrb_tok(rel, s)}, nfcx_rn, nfcx_ra); " : ''
      ed.add(s, close + 1, "({ #{stmts}mrb_int nfcx_n = mrb_get_args(#{callargs}); #{rest_build}#{normalise}nfcx_n; })")
    else
      tail = kw ? ", #{kw_name} = (mrb_hash_size(mrb, #{kw_name}) ? #{kw_name} : mrb_nil_value()), (void)0" : ''
      ed.add(s, close + 1, "(#{pre}mrb_get_args(#{callargs})#{tail})")
    end
    rewrite(rel, s, 'rb_scan_args', "mrb_get_args(mrb, \"#{fmt}\", ...)",
            'optional outputs are set to nil first (as rb_scan_args does); mruby arity errors are ArgumentError as in CRuby; ' \
            'a rest part is an array built from mruby\'s argument pointer and length; a keyword part takes the trailing Hash; ' \
            'a block part is the block (nil when there is none)')
  end

  # True if the call whose name starts at s and whose ')' is at close is a whole statement: the value is
  # discarded. It must follow a statement boundary, a closed condition or do/else, and be followed by ';'.
  def statement_call(rel, s, close)
    masked = @files[rel]['masked']
    prev = prev_nonspace(masked, s - 1)
    after = next_nonspace(masked, close + 1)
    return false if after < 0 || masked[after] != ';'
    return true if prev < 0 || ";{})".include?(masked[prev])
    # the previous nonblank text is a preprocessor line (#endif, #else, ...): a statement starts after it
    pl = masked.rindex("\n", prev) || -1
    return true if masked[(pl + 1)..prev].to_s.match?(/\A[ \t]*#/)
    # after a case label or default: (a statement starts there)
    return true if masked[prev] == ':' && !(psl(masked, [prev - 120, 0].max, prev + 1) =~ /(?:\bcase\b[^;{}]*|\bdefault)#{SS}:\z/).nil?
    !(psl(masked, 0, s) =~ /(?<![#{WC}])(?:else|do)#{SS}\z/).nil?
  end

  # rb_gc_start() as a statement -> mrb_full_gc(mrb). CRuby returns nil; mruby returns void, so a use of the
  # value is refused. mrb_full_gc does nothing while gc.disabled is set or during an iteration (src/gc.c:1442).
  def gc_start(rel, s, _e, nxt, called)
    masked, text = @files[rel]['masked'], @files[rel]['text']
    unless called
      refuse(rel, s, 'rb_gc_start', 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    if close < 0 || !py_strip(psl(text, nxt + 1, close)).empty?
      refuse(rel, s, 'rb_gc_start', 'rb_gc_start takes no arguments')
      return
    end
    unless statement_call(rel, s, close)
      refuse(rel, s, 'rb_gc_start', 'the return value of rb_gc_start (nil) is used; mruby has no equivalent')
      return
    end
    @edits[rel].add(s, close + 1, "mrb_full_gc(#{mrb_tok(rel, s)})")
    rewrite(rel, s, 'rb_gc_start', 'mrb_full_gc(mrb)',
            'mrb_full_gc does nothing while gc.disabled is set or an object iteration is running; no collection is forced then')
  end

  # RB_TYPE_P(obj, T_X) -> (mrb_type(obj) == MRB_TT_X), where T_X is a T_ name whose api_map entry is an exact
  # MRB_TT_ type with no caveat (T_DATA, T_FIXNUM, T_NIL and the like are refused). obj must be a plain local: the
  # whole call is replaced, so a nested mapped name would not be rewritten.
  def type_p(rel, s, _e, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    unless called
      refuse(rel, s, 'RB_TYPE_P', 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    if args.size != 2
      refuse(rel, s, 'RB_TYPE_P', 'RB_TYPE_P takes an object and a T_ type')
      return
    end
    obj = psl(text, args[0][0], args[0][1])
    tname = psl(text, args[1][0], args[1][1])
    # a class variable name is an object only when no local of the function shadows it (then the local is the object)
    if !/\A[A-Za-z_][#{WC}]*\z/.match?(obj) || @entries.key?(obj) || @types.key?(obj) ||
       (@class_vars.include?(obj) && !shadowed_local?(rel, obj, s)) || obj == 'mrb'
      refuse(rel, s, 'RB_TYPE_P', "object #{py_repr(obj)} is not a plain local variable (nested names would not be mapped)")
      return
    end
    # classes and modules: CRuby's T_CLASS includes singleton classes (mruby's MRB_TT_SCLASS), and T_MODULE is MRB_TT_MODULE
    type_expr = { 'T_CLASS' => "(mrb_type(OBJ) == MRB_TT_CLASS || mrb_type(OBJ) == MRB_TT_SCLASS)", 'T_MODULE' => 'mrb_module_p(OBJ)' }[tname.sub(/\ARUBY_/, '')]
    if type_expr
      new = type_expr.gsub('OBJ', obj)
      ed.add(s, close + 1, new)
      rewrite(rel, s, 'RB_TYPE_P', new, 'a class test: singleton classes are CRuby T_CLASS and mruby MRB_TT_SCLASS')
      return
    end
    # nil and false share mruby's MRB_TT_FALSE tag, so their tests are the value predicates: CRuby's RB_TYPE_P(v, T_NIL)
    # is true only for nil, and RB_TYPE_P(v, T_FALSE) only for false (Qfalse)
    # T_RATIONAL: the fork's rational gem makes Rational objects as data (no exact tag), but CRuby's Rational class has no
    # subclasses, so the class test is the match. It needs the mruby state, which only a function that has it can pass.
    # T_RATIONAL and T_COMPLEX: the classes of the mruby-rational and mruby-complex gems (data objects, no subclasses in CRuby),
    # so the test is the class test; the gem is a dependency of the generated mrbgem (only when such a test is emitted)
    class_gem = { 'T_RATIONAL' => ['Rational', 'mruby-rational'], 'T_COMPLEX' => ['Complex', 'mruby-complex'], 'T_STRUCT' => ['Struct', 'mruby-struct'] }[tname.sub(/\ARUBY_/, '')]
    if class_gem
      cls_name, gem_name = class_gem
      fnr = enclosing_func(rel, s)
      unless fnr && ((@valid_reg_names || Set.new).include?(fnr['name']) || (@needs || Set.new).include?(fnr['name']))
        refuse(rel, s, 'RB_TYPE_P', "#{tname} needs the mruby state (the #{cls_name} class test), which this function does not have")
        return
      end
      new = "mrb_obj_is_kind_of(#{mrb_tok(rel, s)}, #{obj}, mrb_class_get(#{mrb_tok(rel, s)}, \"#{cls_name}\"))"
      ed.add(s, close + 1, new)
      (@gem_deps ||= Set.new) << gem_name
      rewrite(rel, s, 'RB_TYPE_P', new, "a #{cls_name} test by class (the #{gem_name} gem; CRuby #{cls_name} has no subclasses)")
      return
    end
    pred = { 'T_NIL' => 'mrb_nil_p', 'T_FALSE' => 'mrb_false_p' }[tname.sub(/\ARUBY_/, '')]
    if pred
      new = "#{pred}(#{obj})"
      ed.add(s, close + 1, new)
      rewrite(rel, s, 'RB_TYPE_P', new, 'nil and false are told apart by value (mrb_nil_p, mrb_false_p), not by tag')
      return
    end
    if tname.sub(/\ARUBY_/, '') == 'T_REGEXP'
      # a Regexp is a data object of the mruby-onig-regexp gem: its data type is the gem's (mruby/onigmo.h, mruby_onig_regexp_is)
      new = "mruby_onig_regexp_is(#{obj})"
      ed.add(s, close + 1, new)
      rewrite(rel, s, 'RB_TYPE_P', new, 'a Regexp is the mruby-onig-regexp gem\'s data object (its data type), not a tag')
      return
    end
    ent = @entries[tname]
    # an entry with a caveat is accepted when its type_check says the caveat is the accepted form (T_FIXNUM: the weaker Integer check)
    if ent.nil? || ent.empty? || ent['kind'] != 'expr' || !(ent['mruby'] || '').start_with?('MRB_TT_') ||
       (ent.key?('caveat') && ent['type_check'] != 'caveat')
      if tname == 'T_BIGNUM'
        refuse(rel, s, 'RB_TYPE_P', 'stuck point (Bignum): the fork has no Bignum. No MRB_TT_BIGINT tag exists (include/mruby/value.h:106-131) and no mrbgem defines a big-integer class, so no tag or class test can select CRuby\'s T_BIGNUM values')
      elsif tname == 'T_REGEXP'
        refuse(rel, s, 'RB_TYPE_P', 'stuck point (Regexp): the fork has no Regexp class (no regexp mrbgem, and no Onigmo engine under mrbgems), so no class test can select CRuby\'s T_REGEXP values')
      else
        refuse(rel, s, 'RB_TYPE_P', "#{tname} has no exact mruby type to compare with")
      end
      return
    end
    new = "(mrb_type(#{obj}) == #{ent['mruby']})"
    ed.add(s, close + 1, new)
    rewrite(rel, s, 'RB_TYPE_P', new)
  end

  # Check_Type(v, T_X) and rb_check_type(v, T_X) -> mrb_check_type(mrb, v, MRB_TT_X). Only the name and the type
  # argument are edited, so the value argument is left to the identifier pass (it may be any expression). The type
  # argument must be a literal T_ identifier: CRuby's int values differ from mruby's enum, so a variable is refused.
  # The name must have type_check "exact" or "caveat" in api_map.json; the others are refused with type_check_refused.
  def check_type(rel, s, e, name, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    unless called
      refuse(rel, s, name, 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    if args.size != 2
      refuse(rel, s, name, "#{name} takes a value and a T_ type")
      return
    end
    ts, te = args[1]
    tname = psl(text, ts, te)
    unless /\A(?:RUBY_)?T_[A-Z]+\z/.match?(tname)
      refuse(rel, s, name, 'type argument is not a literal T_ constant')
      return
    end
    # T_CLASS: mruby's MRB_TT_CLASS and MRB_TT_SCLASS (a singleton class, CRuby's T_CLASS); T_MODULE: MRB_TT_MODULE. The
    # object is evaluated twice in the test, so it must be a plain name.
    cls_tags = { 'T_CLASS' => 'MRB_TT_CLASS || mrb_type(OBJ) == MRB_TT_SCLASS', 'T_MODULE' => 'MRB_TT_MODULE' }[tname.sub(/\ARUBY_/, '')]
    if cls_tags
      obj = psl(text, args[0][0], args[0][1]).strip
      unless obj.match?(/\A[A-Za-z_][#{WC}]*\z/)
        refuse(rel, s, name, 'the object of a class check is not a plain name (it is evaluated twice)')
        return
      end
      test = "mrb_type(#{obj}) == #{cls_tags.gsub('OBJ', obj)}"
      new = "(#{test} ? (void)0 : mrb_raise(#{mrb_tok(rel, s)}, E_TYPE_ERROR, \"wrong argument type (expected Class or Module)\"))"
      ed.add(s, close + 1, new)
      rewrite(rel, s, name, new, 'a class or module check by tag (singleton classes are CRuby T_CLASS and mruby MRB_TT_SCLASS); the message is generic')
      return
    end
    # Check_Type(x, T_RATIONAL / T_COMPLEX): the class test of the gem's class, raising TypeError as CRuby does (the gem is a dependency)
    class_gem_c = { 'T_RATIONAL' => ['Rational', 'mruby-rational'], 'T_COMPLEX' => ['Complex', 'mruby-complex'], 'T_STRUCT' => ['Struct', 'mruby-struct'] }[tname.sub(/\ARUBY_/, '')]
    if class_gem_c
      cls_name, gem_name = class_gem_c
      fnc = enclosing_func(rel, s)
      obj_c = psl(text, args[0][0], args[0][1]).strip
      unless fnc && ((@valid_reg_names || Set.new).include?(fnc['name']) || (@needs || Set.new).include?(fnc['name'])) &&
             obj_c.match?(/\A[A-Za-z_][#{WC}]*\z/)
        refuse(rel, s, name, "#{tname} needs the mruby state and a plain object (the #{cls_name} class test)")
        return
      end
      tok_c = mrb_tok(rel, s)
      new_c = "(mrb_obj_is_kind_of(#{tok_c}, #{obj_c}, mrb_class_get(#{tok_c}, \"#{cls_name}\")) ? (void)0 : " \
              "mrb_raise(#{tok_c}, E_TYPE_ERROR, \"wrong argument type (expected #{cls_name})\"))"
      ed.add(s, close + 1, new_c)
      (@gem_deps ||= Set.new) << gem_name
      rewrite(rel, s, name, new_c, "a #{cls_name} check by class (the #{gem_name} gem); the message is generic")
      return
    end
    ent = @entries[tname]
    if !@type_check_refused[tname].nil? || ent.nil? || !%w[exact caveat].include?(ent['type_check']) ||
       !(ent['mruby'] || '').start_with?('MRB_TT_')
      reason = @type_check_refused[tname] || "#{tname} has no exact mruby type test in the supported subset"
      refuse(rel, s, name, reason)
      # keep the T_ name as written: the identifier pass must not map it inside a refused call
      ed.add(ts, te, tname)
      return
    end
    obj = psl(text, args[0][0], args[0][1])
    to = "mrb_check_type(mrb, #{obj}, #{ent['mruby']})"
    ed.add(s, e, 'mrb_check_type')
    ed.add(nxt + 1, nxt + 1, "#{mrb_tok(rel, s)}, ")
    ed.add(ts, te, ent['mruby'])
    rewrite(rel, s, name, to, ent['caveat'])
  end

  # rb_gc_writebarrier(old, young) as a statement -> an immediate-guarded mrb_field_write_barrier_value. The
  # arguments are plain locals: they are used more than once, and an edit inside them would overlap. CRuby's
  # `old` is never a special constant (RB_OBJ_WRITE only calls this for heap owners), so the guard is a no-op there.
  def gc_writebarrier(rel, s, _e, nxt, called)
    masked, text, ed = @files[rel]['masked'], @files[rel]['text'], @edits[rel]
    unless called
      refuse(rel, s, 'rb_gc_writebarrier', 'used without a call')
      return
    end
    close = match_close(masked, nxt)
    args = close > 0 ? split_args(masked, nxt, close) : []
    if args.size != 2
      refuse(rel, s, 'rb_gc_writebarrier', 'rb_gc_writebarrier takes an owner and a referenced value')
      return
    end
    names = []
    args.each do |a, b|
      t = psl(text, a, b)
      if !/\A[A-Za-z_][#{WC}]*\z/.match?(t) || @entries.key?(t) || @types.key?(t) ||
         @class_vars.include?(t) || t == 'mrb'
        refuse(rel, s, 'rb_gc_writebarrier', "argument #{py_repr(t)} is not a plain local variable (it is used twice)")
        return
      end
      names << t
    end
    unless statement_call(rel, s, close)
      refuse(rel, s, 'rb_gc_writebarrier', 'the return value of rb_gc_writebarrier is used (it is void)')
      return
    end
    old, young = names
    new = "do { if (!mrb_immediate_p(#{old})) mrb_field_write_barrier_value(#{mrb_tok(rel, s)}, mrb_basic_ptr(#{old}), #{young}); } while (0)"
    ed.add(s, close + 1, new)
    rewrite(rel, s, 'rb_gc_writebarrier', new,
            'mruby keeps the write barrier only for a heap owner; it does not make C-held storage a GC root ' \
            '(there is no mark callback, see rb_gc_mark)')
  end

  # ---- stage 4: write ----------------------------------------------------
  # Compiles each converted source with gcc -fsyntax-only against the mruby headers (NFCX_MRUBY_INCLUDE, colon-separated).
  # A compile error becomes a refusal at its output line, so the gem is marked not buildable. The converter's own
  # refusals do not see every wrong conversion (a CRuby VALUE compared with == has no mruby form in the output).
  # names of the functions (source) that have a stuck-point refusal in rel
  def stuck_function_names(rel)
    names = Set.new
    text = @files[rel]['text']
    @refusals.each do |r|
      next unless r['file'] == rel && r['reason'].to_s.match?(/stuck point/)
      off = text.lines.take(r['line'].to_i - 1).sum(&:length)
      fn = enclosing_func(rel, off)
      names << fn['name'] if fn
    end
    names
  end

  # the name of the function whose definition header is the last column-0 header above output line l (1-based), or nil
  def output_function_name(lines, l)
    (l - 1).downto(0) do |i|
      m = /\A(?:static |inline |extern )*[A-Za-z_][\w \*]*?\b([A-Za-z_]\w*)[ \t]*\([^;]*\)[ \t]*\{/.match(lines[i].to_s)
      return m[1] if m
    end
    nil
  end

  def verify_compile(src_dir, inc_dir)
    incs = ENV['NFCX_MRUBY_INCLUDE'].split(':').reject(&:empty?)
    @files.each do |rel, f|
      next unless f['kind'] == 'src'
      path = File.join(src_dir, rel)
      # a C++ source (.cc) is checked as C++ (g++): the mruby headers are extern "C" and the converted classes are C++
      args = [(rel.end_with?('.cc') ? 'g++' : 'gcc'), '-fsyntax-only', '-w', '-include', 'stddef.h', '-I', src_dir, '-I', inc_dir]
      # the build's defines (the --define options: the names the build defines, as extconf would set them)
      (@defines || []).each { |d| args << "-D#{d}" }
      # the fork's build defines MRB_USE_BIGINT for every object (mrbgems/mruby-bigint/mrbgem.rake): the bigint helpers are declared
      args << '-DMRB_USE_BIGINT'
      incs.each { |d| args += ['-I', d] }
      args << path
      _o, err, _st = Open3.capture3(*args)
      out_lines = File.exist?(path) ? File.readlines(path, encoding: 'UTF-8').map { |x| x.scrub } : []
      stuck_fns = stuck_function_names(rel)
      header_seen = Set.new
      err.each_line do |ln|
        # an error reported in a fork header (the converted code misuses an mruby header: gcc reports the header's line, and the
        # call site is the file's own 'In function' context) is a compile error of this file, recorded once per header line
        hm = ln.chomp.match(/\A(\/[^:]*\/mruby\/[^:]*):(\d+):\d+: (?:fatal )?error: (.+)\z/)
        if hm && hm[1] != path
          next if header_seen.include?([hm[1], hm[2]])
          header_seen << [hm[1], hm[2]]
          @refusals << { 'file' => rel, 'line' => 0, 'api' => 'compile check',
                         'reason' => "compile error in the fork header #{File.basename(hm[1])}:#{hm[2]} (the converted code's use of it): #{hm[3].strip}" }
          next
        end
        m = ln.chomp.match(/\A#{Regexp.escape(path)}:(\d+):\d+: (?:fatal )?error: (.+)\z/)
        next unless m
        # a compile error inside a function that has a stuck-point refusal is that stuck point's cascade: the stuck call
        # is left as written, so the compiler reports its uses (the stuck point is counted once, under its own reason)
        fn_out = output_function_name(out_lines, m[1].to_i)
        # a CRuby type tag the fork cannot test (T_RATIONAL, T_BIGNUM) is its own open or stuck group, not a cascade
        tag_err = m[2].match?(/'T_[A-Z_]+'|\bCheck_Type\b/)
        if fn_out && stuck_fns.include?(fn_out) && !tag_err && m[2].strip != 'ruby/encoding.h: No such file or directory'
          @refusals << { 'file' => rel, 'line' => m[1].to_i, 'api' => 'compile check',
                         'reason' => "stuck point (cascade in #{fn_out}): the converted code does not compile here because of a stuck " \
                                     "point in the same function (#{m[2].strip})" }
          next
        end
        # an error on a line that holds a refused use (a macro body, or an expression the refusal marked): the marked use is the
        # stuck point, and the error is its cascade
        line_txt = out_lines[m[1].to_i - 1].to_s
        if line_txt.match?(/BC2CPP-MRBGEM (?:REFUSED|stub)/)
          @refusals << { 'file' => rel, 'line' => m[1].to_i, 'api' => 'compile check',
                         'reason' => "stuck point (cascade of a refused use on the same line): the converted line does not compile " \
                                     "because of its refused use (#{m[2].strip})" }
          # the refused use is the stuck point (recorded, and stubbed or kept NOT BUILDABLE on its own): this line is its cascade
          (@stubbed ||= Set.new) << [rel, m[1].to_i]
          next
        end
        # the include of ruby/encoding.h is kept in the output (its api is the accepted Encoding stuck point); the fork has no
        # such header, and gcc stops at the fatal error, so the rest of the file is not checked
        # an undeclared CRuby type tag that is a stuck decision (Rational, Complex: a gem; Bignum: no bignum): the tag's own
        # stuck point is the reason, not a cascade
        if (tm = m[2].strip.match(/\A'(T_RATIONAL|T_COMPLEX|T_BIGNUM|T_FIXNUM)' undeclared/))
          why = tm[1] == 'T_BIGNUM' || tm[1] == 'T_FIXNUM' ? 'the bignum decision (no bignum in the fork)' : 'the gem decision (mruby-rational or mruby-complex in the build)'
          @refusals << { 'file' => rel, 'line' => m[1].to_i, 'api' => 'compile check',
                         'reason' => "stuck point (#{tm[1]}): the converted code uses #{tm[1]}, a tag the fork does not have; it is #{why} (accepted stuck point)" }
          next
        end
        # bcrypt's #else branch defines crypt_r for libcs without it; a glibc host declares crypt_r in crypt.h with another
        # signature, and the gem gates its own branch on _LIBC (defined only while glibc is built): a target conflict
        if m[2].strip.start_with?("conflicting types for 'crypt_r'")
          @refusals << { 'file' => rel, 'line' => m[1].to_i, 'api' => 'compile check',
                         'reason' => 'stuck point (target): the gem defines crypt_r in its #else branch for libcs without it; glibc declares ' \
                                     'crypt_r in crypt.h with another signature, and the gem gates its glibc branch on _LIBC, which is ' \
                                     'defined only while glibc is built (accepted stuck point)' }
          next
        end
        # the CRuby version and IO headers, kept as the stuck include they are, stop gcc the same way
        if ['ruby/version.h', 'ruby/io.h'].any? { |h| m[2].strip == "#{h}: No such file or directory" }
          hdr = m[2].strip.split(':').first
          @refusals << { 'file' => rel, 'line' => m[1].to_i, 'api' => 'compile check',
                         'reason' => "stuck point (#{hdr == 'ruby/io.h' ? 'IO' : 'CRuby version'}): the converted code keeps #include <#{hdr}>, " \
                                     'which the fork does not have (accepted stuck point); the compile check stops at this include' }
          next
        end
        if m[2].strip == 'ruby/encoding.h: No such file or directory'
          @refusals << { 'file' => rel, 'line' => m[1].to_i, 'api' => 'compile check',
                         'reason' => 'stuck point (Encoding): the converted code keeps #include <ruby/encoding.h>, which the fork ' \
                                     'does not have (accepted stuck point); the compile check stops at this include' }
          next
        end
        @refusals << { 'file' => rel, 'line' => m[1].to_i, 'api' => 'compile check',
                       'reason' => "the converted code does not compile: #{m[2].strip}" }
      end
    end
  end

  # Stub policy (option A): a function whose body holds a refused (stuck) use has its body replaced by a stub that raises
  # NotImplementedError when it runs, so the gem compiles and loads; the function is then not a source of NOT BUILDABLE.
  # Each refusal line in a stubbed body is recorded in @stubbed; the refusals elsewhere (file scope, headers, the gem) remain.
  # the statement holding position pos, as [start, end) of masked text, when it is a plain statement (a call, not a control
  # statement, a block or an assignment); nil otherwise
  def stmt_span(masked, pos, allow_assign: false)
    # the position is inside the statement's own parentheses (an argument), so the statement boundaries are the ; { } characters
    st = nil
    k = pos - 1
    while k >= 0
      if masked[k] == ';' || masked[k] == '{' || masked[k] == '}'
        st = k + 1
        break
      end
      k -= 1
    end
    return nil if st.nil?
    e = nil
    k = pos
    while k < masked.length
      c = masked[k]
      return nil if c == '{' || c == '}'
      if c == ';'
        e = k + 1
        break
      end
      k += 1
    end
    return nil if e.nil?
    # a preprocessor line (#if, #endif) between the boundary and the statement is not part of the statement: the span starts after it
    dir = masked[st...pos].to_s.scan(/^[ \t]*#[^\n]*\n/).last
    if dir
      st = st + masked[st...pos].to_s.rindex(dir) + dir.length
    end
    text = masked[st...e].to_s.strip
    return nil if text.match?(/\A(?:if|else|for|while|do|return|switch|case|goto)\b/)
    return nil if !allow_assign && text.match?(/(?<![=!<>])=(?!=)/)
    [st, e]
  end

  # The init-like functions: the gem's Init_<name> entry point, and a *_module_init helper that Init calls (msgpack's
  # MessagePack_Packer_module_init defines the class and its methods). A refused plain statement in one is dropped, as in Init,
  # so the rest of the function (its definitions) stays; a whole-function stub would leave the class undefined.
  def init_like_name?(name)
    n = name.to_s
    n.start_with?('Init_') || n.match?(/_module_init\z/)
  end

  def stub_refused_functions
    @stubbed = Set.new
    @refusals.group_by { |r| r['file'] }.each do |rel, refs|
      next unless @files[rel]
      text = @files[rel]['text']
      # Init: a refused statement is dropped (the decision of the user: a deliberate no-op, noted in REFUSALS.txt); a stub
      # there would make the gem raise at load. A refusal whose statement is not a plain call statement stays unstubbed.
      masked = @files[rel]['masked']
      init_defs = @defs.values.flatten.select { |d| d['file'] == rel && !d['proto'] && d['brace'] && d['body_end'] && init_like_name?(d['name']) }
      # a refusal in a #define body (a macro whose expansion refuses) is handled at each use of the macro: a use inside Init
      # is a statement dropped there, a use inside a function stubs that function (the uses are the refused uses)
      refs = refs.dup
      # a use of a refused macro inside another macro's body is a use of that macro too: the chain is followed to the functions
      # (or Init statements) that expand it
      work = refs.select { |r| r['pos'] && define_at(rel, r['pos']) }
      seen_macros = Set.new
      until work.empty?
        r = work.shift
        dl = define_at(rel, r['pos'])
        name, da, db = dl[0], dl[1], dl[2]
        # every refusal in a macro body is handled by its uses (the first refusal of a macro expands them; the others are the same)
        @stubbed << [rel, r['line']]
        next if seen_macros.include?(name)
        seen_macros << name
        uses = (@occ[name] || []).reject { |rr, os, _oe| rr == rel && da <= os && os < db }
        next if uses.empty?
        uses.each do |rr, os, _oe|
          next unless rr == rel
          rec = r.merge('line' => line_of(text, os), 'pos' => os, 'api' => name)
          if define_at(rel, os)
            work << rec
          else
            refs << rec
          end
        end
        @stubbed << [rel, r['line']]
        (@dropped_inits ||= Set.new) << [rel, r['line']] if uses.all? { |rr, os, _oe| rr == rel && init_defs.any? { |d| os >= d['brace'] && os <= d['body_end'] } }
      end
      init_defs.each do |d|
        l1 = line_of(text, d['hstart'] || d['brace'])
        l2 = line_of(text, d['body_end'])
        refs.select { |r| r['line'] >= l1 && r['line'] <= l2 && r['pos'] }.each do |r|
          span = stmt_span(masked, r["pos"], allow_assign: true)
          next unless span
          s0, e0 = span
          next if @edits[rel].overlapping(s0, e0).any? { |a, b, _| a < d['brace'] || b > d['body_end'] + 1 }
          @edits[rel].drop(@edits[rel].overlapping(s0, e0))
          @edits[rel].add(s0, e0, "/* BC2CPP-MRBGEM dropped in Init (#{r['api']}): #{r['reason'].to_s.sub(/\A[^:]*: /, '')[0, 160]} */")
          @stubbed << [rel, r['line']]
          @dropped_inits = (@dropped_inits || Set.new) << [rel, r['line']]
        end
      end
      # the Init function is not stubbed: a stub there would make the gem raise at load and register no method
      defs = @defs.values.flatten.select do |d|
        d['file'] == rel && !d['proto'] && d['brace'] && d['body_end'] && !init_like_name?(d['name'])
      end
      defs.each do |d|
        l1 = line_of(text, d['hstart'] || d['brace'])
        l2 = line_of(text, d['body_end'])
        hit = refs.select { |r| r['line'] >= l1 && r['line'] <= l2 }
        next if hit.empty?
        # the function's output has the state parameter when the conversion adds it (@needs) or the source has one
        # a global-state helper (or a method-scope function) keeps its signature and reads the global, whatever @needs says
        global_fn = (@global_helpers || Set.new).include?(d['name']) || ($method_scope_fns || []).include?(d['name'])
        # the output has the state parameter when the source has it, or an edit inserts it into the parameter list
        added_mrb = @edits[rel].overlapping(d['po'], d['po'] + 2).any? { |_a, _b, t| t.to_s.include?('mrb_state') }
        has_mrb = !global_fn && (d['params'].to_s.match?(/\bmrb_state\b/) || added_mrb)
        # a per-class allocator without a state (its registration, rb_define_alloc_func, is dropped in Init): nothing calls it,
        # so its body returns a zero value (no state to raise with), noted as the dropped allocator
        if !has_mrb && !@global_wrap && hit.all? { |r| r['reason'].to_s.include?('per-class allocator') }
          ret = d['ret'].to_s.strip
          zero = if ret.split.last == 'void' && !ret.include?('*') then '' elsif ret.match?(/\bVALUE\b|\bmrb_value\b/) then ' return mrb_nil_value();'
                 elsif ret.include?('*') then ' return NULL;' else " return (#{ret}){0};" end
          inside = @edits[rel].overlapping(d['brace'] + 1, d['body_end'])
          @edits[rel].drop(inside)
          @edits[rel].add(d['brace'] + 1, d['body_end'], " /* BC2CPP-MRBGEM dropped: the per-class allocator is unreachable (rb_define_alloc_func was dropped in Init) */#{zero} ")
          hit.each { |r| @stubbed << [rel, r['line']]; (@dropped_inits ||= Set.new) << [rel, r['line']] }
          next
        end
        next unless has_mrb || @global_wrap
        target = has_mrb ? 'mrb' : @global_name
        ret = d['ret'].to_s.strip
        ret_stmt = if ret.split.last == 'void' && !ret.include?('*') then ''
                   elsif ret.match?(/\bVALUE\b|\bmrb_value\b/) then ' return mrb_nil_value();'
                   elsif ret.include?('*') then ' return NULL;'
                   else " return (#{ret}){0};"
                   end
        msg = "stuck point (see REFUSALS.txt): #{d['name']} uses a CRuby feature the fork has no form of"
        # a void GC callback (a dfree or a mark function: strscan_free, strscan_mark) runs inside the collector, where a raise
        # aborts the process (mrb_close): its stub does nothing, and the refused part of the body is noted in REFUSALS.txt
        if d['name'].to_s.match?(/_(?:free|mark)\z/) && ret.split.last == 'void'
          stub = " /* BC2CPP-MRBGEM stub: refused code (a GC callback: no effect, the refused part is noted in REFUSALS.txt) */ "
        else
          stub = " /* BC2CPP-MRBGEM stub: refused code */ mrb_raise(#{target}, mrb_exc_get(#{target}, \"NotImplementedError\"), \"#{msg}\");#{ret_stmt} "
        end
        inside = @edits[rel].overlapping(d['brace'] + 1, d['body_end'])
        @edits[rel].drop(inside)
        @edits[rel].add(d['brace'] + 1, d['body_end'], stub)
        hit.each { |r| @stubbed << [rel, r['line']] }
        (@stub_fns ||= Set.new) << d['name']
      end
    end
    drop_init_calls_to_stubs
  end

  # A call from an Init function to a stubbed function is a statement Init must not run: the stub raises, and at load time the
  # raise aborts the gem (oj's Init called oj_string_writer_init, a stub). The statement is dropped, as a refused statement in Init
  # is, and recorded in REFUSALS.txt as dropped in Init.
  def drop_init_calls_to_stubs
    names = (@stub_fns || Set.new).dup
    return if names.empty?
    # a function that calls a stub reaches it too (bigdecimal's BigDecimal_literal calls the stubbed f_BigDecimal_impl): its call
    # from Init would raise at load, so the closure of the callers of stubs is dropped from Init as well (its own body is not changed)
    loop do
      grew = false
      @defs.values.flatten.each do |d|
        # an init-like function is not stubbed (its refused statements are dropped), so calling it does not raise
        next if d['proto'] || !d['brace'] || !d['body_end'] || names.include?(d['name']) || init_like_name?(d['name'])
        next unless @files[d['file']]
        body = @files[d['file']]['masked'][d['brace']..d['body_end']]
        next unless names.any? { |n| body.match?(/\b#{Regexp.escape(n)}\s*\(/) }
        names << d['name']
        grew = true
      end
      # a function-like macro whose body reaches a stub is a name too: its uses in Init are dropped (bigdecimal's
      # BIGDECIMAL_LITERAL expands to BigDecimal_literal, which reaches the stub f_BigDecimal_impl)
      @files.each_key do |frel|
        define_spans(frel).each do |mname, ma, mb|
          next if names.include?(mname)
          mbody = @files[frel]['masked'][ma..mb]
          next unless names.any? { |n| mbody.match?(/\b#{Regexp.escape(n)}\s*\(/) }
          names << mname
          grew = true
        end
      end
      break unless grew
    end
    @files.each do |rel, f|
      next unless @edits[rel]
      masked = f['masked']
      text = f['text']
      inits = @defs.values.flatten.select { |d| d['file'] == rel && !d['proto'] && d['brace'] && d['body_end'] && init_like_name?(d['name']) }
      inits.each do |d|
        names.each do |n|
          positions = []
          masked.scan(/\b#{Regexp.escape(n)}\s*\(/) { positions << $~.begin(0) }
          positions.each do |pos|
            next unless pos > d['brace'] && pos < d['body_end']
            span = stmt_span(masked, pos)
            next unless span
            s0, e0 = span
            next if @edits[rel].overlapping(s0, e0).any? { |a, b, _| a < d['brace'] || b > d['body_end'] + 1 }
            @edits[rel].drop(@edits[rel].overlapping(s0, e0))
            direct = (@stub_fns || Set.new).include?(n)
            how = direct ? 'calls the stubbed function' : 'calls a function that reaches a stub'
            @edits[rel].add(s0, e0, "/* BC2CPP-MRBGEM dropped in Init (#{n}): #{how} #{n} (a stuck point, see REFUSALS.txt) */")
            line = line_of(text, pos)
            why = direct ? "#{n} is stubbed (its refusal is above)" : "#{n} calls a stubbed function (its body reaches the stub)"
            @refusals << { 'file' => rel, 'line' => line, 'api' => n, 'reason' => "stuck point: #{why}; called from Init, the stub would raise at load", 'pos' => pos }
            @stubbed << [rel, line]
            (@dropped_inits ||= Set.new) << [rel, line]
          end
        end
      end
    end
  end

  def write_outputs
    src_dir = File.join(@out_dir, 'src')
    inc_dir = File.join(@out_dir, 'include')
    FileUtils.mkdir_p(src_dir)
    FileUtils.mkdir_p(inc_dir)
    stub_refused_functions
    # a refusal of a stuck type or include that the placeholder prelude covers is stubbed too: the declaration compiles
    @refusals.each do |r|
      next unless r['api'] && PLACEHOLDER_APIS.include?(r['api'])
      next unless @files[r['file']] && needs_placeholder_prelude?(@files[r['file']])
      (@stubbed ||= Set.new) << [r['file'], r['line']]
    end
    outputs = {}
    @files.each { |rel, f| outputs[rel] = @edits[rel].apply(f['text']) }
    # the helpers of the gem's sources (api_map nfcx_ptr_value, nfcx_ptr_of, nfcx_int_value, nfcx_int_of) are written where a call's
    # text is copied (a rescue's data arguments), not expanded by a template: their mruby forms are written here
    @files.each_key do |rel|
      # a macro's last line continuation written after the closing argument ("... \)" at a line end): a backslash that
      # does not continue into a line is a stray in C, and the closing parenthesis is what the macro body ends with
      outputs[rel] = outputs[rel].gsub(/ \\\)$/, ')')
      outputs[rel] = outputs[rel].gsub(/\bnfcx_ptr_value\(/, 'mrb_cptr_value(mrb, ')
                                 .gsub(/\bnfcx_ptr_of\(/, 'mrb_cptr(')
                                 .gsub(/\bnfcx_int_value\(/, 'mrb_fixnum_value(')
                                 .gsub(/\bnfcx_int_of\(/, 'mrb_fixnum(')
    end
    @files.each { |rel, f| outputs[rel] = id_value_casts(outputs[rel]) if f['kind'] == 'src' }
    @files.each { |rel, _f| outputs[rel] = macro_paste_mrb(outputs[rel]) }
    # Onigmo's types in declarations (a struct field of OnigRegion, a UChar pointer): the fork has no regexp engine, so these are
    # placeholder types for the declarations only. Every use of an Onigmo function or constant is refused, so the code that
    # reads these types is a stub: the placeholders are never used to compute a result.
    @files.each do |rel, f|
      next unless needs_placeholder_prelude?(f)
      prelude = ONIG_STUCK_TYPES_PRELUDE
      # a file that includes POSIX <regex.h> has its own regex_t (struct re_pattern_buffer): no placeholder for that name
      prelude = prelude.sub(/^typedef void \*regex_t;\n/, '') if f['text'].match?(/#\s*include\s*<regex\.h>/)
      outputs[rel] = prelude + outputs[rel]
    end
    # a function without the state parameter reads the gem's state global: a literal mrb-> (from a template's class argument)
    # in its body names that global (the global-state functions are the ones that have no mrb parameter)
    if @global_wrap
      @files.each do |rel, f|
        if f['kind'] == 'src'
          outputs[rel] = global_mrb_arrows(outputs[rel], @global_name)
        end
        # a header's macro that generates a stateless function (DEFINE_DELEGATED_FUNCTION in safe.h) names the global too
        outputs[rel] = global_macro_arrows(outputs[rel], @global_name)
      end
    end
    # a converted source that uses mruby names includes the mruby headers itself (gem_init.c has its own include)
    prelude_headers = %w[mruby.h mruby/array.h mruby/class.h mruby/data.h mruby/error.h mruby/hash.h
                         mruby/numeric.h mruby/range.h mruby/string.h mruby/variable.h]
    # a header that names the state or the mruby API (a converted prototype or callback type) needs the mruby headers before it
    mrb_header_names = @files.keys.select { |r| @files[r]['kind'] != 'src' && outputs[r].to_s.match?(/\bmrb_|\bmrb_state\b/) }
                             .map { |r| File.basename(r) }
    # <math.h> came with CRuby's ruby.h (signbit, isnan, INFINITY, ...): a source that uses its names includes it
    # the l and f suffixes are the long double and float variants (powl, sqrtf, ...)
    math_names = /(?<![\w$])(?:signbit|isnan|isinf|isfinite|fabs|floor|ceil|pow|sqrt|NAN|INFINITY|HUGE_VAL)[fl]?(?![\w$])/
    @files.each do |rel, f|
      next unless f['kind'] == 'src'
      next if outputs[rel].to_s.match?(/#\s*include\s*[<"]math\.h[>"]/)
      next unless outputs[rel].to_s.match?(math_names)
      outputs[rel] = "#include <math.h>\n" + outputs[rel]
    end
    # <string.h> came with CRuby's ruby.h too (memcpy, strlen, ...): a source that uses its names includes it
    string_names = /(?<![\w$])(?:memcpy|memmove|memset|memcmp|memchr|strlen|strnlen|strcmp|strncmp|strcpy|strncpy|strchr|strrchr|strstr|strdup|strndup)(?![\w$])/
    @files.each do |rel, f|
      next unless f['kind'] == 'src'
      next if outputs[rel].to_s.match?(/#\s*include\s*[<"]string\.h[>"]/)
      next unless outputs[rel].to_s.match?(string_names)
      outputs[rel] = "#include <string.h>\n" + outputs[rel]
    end
    # CRuby's ruby.h included <unistd.h> (read, write, close, ...): a source that calls one of those includes it. The call
    # pattern needs the open parenthesis, so a variable named read is not a match.
    posix_calls = /(?<![\w$.>])(?:read|write|close|lseek|dup2?|getpid|isatty|unlink|sleep|usleep|getcwd|access)\s*\(/
    @files.each do |rel, f|
      next if outputs[rel].to_s.match?(/#\s*include\s*[<"]unistd\.h[>"]/)
      next unless outputs[rel].to_s.match?(posix_calls)
      outputs[rel] = "#include <unistd.h>\n" + outputs[rel]
    end
    # <stdlib.h> came with CRuby's ruby.h too (abort, strtoul, malloc, ...): a source that calls one of those includes it
    stdlib_calls = /(?<![\w$.>])(?:abort|exit|malloc|calloc|realloc|free|atoi|atol|strtol|strtoul|strtod|strtoll|strtoull|getenv|qsort|bsearch|rand|srand|abs|labs)\s*\(/
    @files.each do |rel, f|
      next if outputs[rel].to_s.match?(/#\s*include\s*[<"]stdlib\.h[>"]/)
      next unless outputs[rel].to_s.match?(stdlib_calls)
      outputs[rel] = "#include <stdlib.h>\n" + outputs[rel]
    end
    # rb_require is the mruby-require API (mruby/require.h): a source that calls it includes that header
    @files.each do |rel, f|
      next if outputs[rel].to_s.match?(/#\s*include\s*[<"]mruby\/require\.h[>"]/)
      next unless outputs[rel].to_s.match?(/(?<![\w$])rb_require\s*\(/)
      outputs[rel] = "#include <mruby/require.h>\n" + outputs[rel]
    end
    # the encoding API (rb_encoding, rb_enc_*, rb_str_conv_enc, rb_usascii_encoding, ...) is declared by the fork's mruby/encoding.h:
    # a source or header that uses its names includes it, and needs mruby-encoding on the build path. Without the declaration C takes the call
    # as implicit int, which is the 'incompatible type' error in the compile check.
    enc_names = /(?<![\w$])(?:rb_enc\w*|rb_encoding|rb_utf8_\w+|rb_usascii_\w+|rb_ascii8bit_\w+|rb_str_conv_enc|rb_str_export_to_enc|rb_default_\w*_encoding)(?![\w$])/
    @files.each do |rel, f|
      next if outputs[rel].to_s.match?(/#\s*include\s*[<"]mruby\/encoding\.h[>"]/)
      next unless outputs[rel].to_s.match?(enc_names)
      outputs[rel] = "#include <mruby/encoding.h>\n" + outputs[rel]
      (@gem_deps ||= Set.new) << 'mruby-encoding'
    end
    @files.each do |rel, f|
      next unless f['kind'] == 'src'
      t = outputs[rel]
      quoted = t.scan(/#\s*include\s*"([^"]+)"/).flatten.map { |h| File.basename(h) }
      next unless t.match?(/\bmrb_|\bmrb_state\b/) || quoted.any? { |h| mrb_header_names.include?(h) }
      # each header the file does not include yet (the API map adds some of them itself)
      missing = prelude_headers.reject { |h| t.match?(/#\s*include\s*[<"]#{Regexp.escape(h)}[>"]/) }
      # mruby.h first: the other mruby headers need its types (and the include guards make a repeat harmless)
      missing = ['mruby.h'] + missing.reject { |h| h == 'mruby.h' } unless missing.empty?
      outputs[rel] = missing.map { |h| "#include <#{h}>\n" }.join + t unless missing.empty?
    end
    if @global_wrap
      # the global state (check_refs): defined once, in the file of Init; declared before any other text in the others.
      # Declared as struct mrb_state so the prefix needs no include (the typedef is the same type).
      @files.each do |rel, _f|
        pre = "extern struct mrb_state *#{@global_name};\n"
        # 0, not NULL: the definition is placed before the file's includes (NULL may not be declared yet)
        pre += "struct mrb_state *#{@global_name} = 0;\n" if rel == @init_rel
        outputs[rel] = pre + outputs[rel]
      end
    end
    @files.each do |rel, f|
      dest = File.join(f['kind'] == 'src' ? src_dir : inc_dir, rel)
      write_bytes(dest, outputs[rel])
    end
    # the thread header the sources include is written first, so the compile check finds it
    write_bytes(File.join(inc_dir, 'nfcx_uv_thread.h'), $thread_sync ? NFCX_SYNC_THREAD_H : NFCX_UV_THREAD_H) if uses_uv_thread?
    verify_compile(src_dir, inc_dir) if ENV['NFCX_MRUBY_INCLUDE']
    write_bytes(File.join(inc_dir, 'nfcx_uv_thread.h'), $thread_sync ? NFCX_SYNC_THREAD_H : NFCX_UV_THREAD_H) if uses_uv_thread?
    fn = @funcname
    init_file = @init_rel
    gem_init = []
    unstubbed = @refusals.reject { |r| (@stubbed || Set.new).include?([r['file'], r['line']]) }
    gem_init << '#error "BC2CPP-MRBGEM: NOT BUILDABLE, see REFUSALS.txt"' unless unstubbed.empty?
    gem_init += [
      "/* Generated by convert_mrbgem.rb from ext/#{@name}. */",
      '#include <mruby.h>',
      '',
      init_file ? "/* mrb_#{fn}_gem_init is defined in src/#{init_file} (the converted Init_ function). */" :
        "void\nmrb_#{fn}_gem_init(mrb_state *mrb)  /* no Init_ function: see REFUSALS.txt */\n{\n  (void)mrb;\n}",
      '',
      'void',
      "mrb_#{fn}_gem_final(mrb_state *mrb)",
      '{',
      '  (void)mrb;',
      '}',
      '',
    ]
    write_bytes(File.join(src_dir, 'gem_init.c'), gem_init.join("\n"))
    status = if @refusals.empty? then 'no refusals (NOT compiled or tested)'
             elsif unstubbed.empty? then 'STUBBED (every refused use is in a stub that raises NotImplementedError, or was dropped as a no-op in Init: see [dropped in Init])'
             else 'NOT BUILDABLE'
             end
    rake = ["# Generated by convert_mrbgem.rb from CRuby ext/#{@name}. Fill in the TODO fields."]
    unless unstubbed.empty?
      rake << "raise \"BC2CPP-MRBGEM: #{@name} is NOT BUILDABLE (#{unstubbed.size} refusal(s) outside stubs); see REFUSALS.txt\""
    end
    rake += [
      '',
      "MRuby::Gem::Specification.new('#{@name}') do |spec|",
      "  spec.license = 'TODO'",
      "  spec.author  = 'TODO'",
      "  spec.summary = 'converted from CRuby ext/#{@name}'",
    ]
    rake << "  spec.add_dependency 'mruby-uv'  # thread model: nfcx_uv_thread.h" if uses_uv_thread? && !$thread_sync
    (@defines || []).each { |d| rake << "  spec.cc.defines << '#{d}'  # a build define (--define): the guard branches it selects are the ones built" }
    (@gem_deps || Set.new).to_a.sort.each { |g| rake << "  spec.add_dependency '#{g}'  # a class test in the converted code" }
    # runtime dependencies from the gem's own metadata (its *.gemspec, in the gem root above ext/): a dependency that a built
    # gem provides (api_map.json require_gems) is added; any other is recorded in WARNINGS.txt
    gemspec_runtime_deps.each do |dep|
      gem = @require_gems[dep]
      if gem
        rake << "  spec.add_dependency '#{gem}'  # runtime dependency #{dep} (gemspec metadata)" unless (@gem_deps || Set.new).include?(gem)
      else
        (@warnings ||= []) << { 'file' => File.basename(@cext_dir), 'line' => 0, 'api' => 'gemspec',
                                'reason' => "runtime dependency '#{dep}' has no providing gem in api_map.json require_gems" }
      end
    end
    rake += ['end', '']
    write_bytes(File.join(@out_dir, 'mrbgem.rake'), rake.join("\n"))
    lines = ["BC2CPP-MRBGEM refusals for ext/#{@name}",
             "STATUS: #{status} (#{@refusals.size} refusal(s))", '']
    @refusals.each do |r|
      tag = if (@dropped_inits || Set.new).include?([r['file'], r['line']]) then ' [dropped in Init: a no-op, noted]'
            elsif (@stubbed || Set.new).include?([r['file'], r['line']]) then ' [stubbed]'
            else ' [NOT stubbed]'
            end
      lines << "#{r['file']}:#{r['line']}  #{r['api']}  #{r['reason']}#{tag}"
    end
    write_bytes(File.join(@out_dir, 'REFUSALS.txt'), lines.join("\n") + "\n")
    unless @warnings.empty?
      body = @warnings.map { |w| "#{w['file']}:#{w['line']}  #{w['api']}  dropped: #{w['reason']}\n" }.join
      write_bytes(File.join(@out_dir, 'WARNINGS.txt'), body)
    end
    marker = File.join(@out_dir, 'NOT_BUILDABLE')
    if !@refusals.empty?
      write_bytes(marker, "#{@refusals.size} refusal(s); see REFUSALS.txt\n")
    elsif File.exist?(marker)
      File.delete(marker)
    end
    log = { 'gem' => @name, 'funcname' => fn, 'init_file' => init_file, 'scanner' => @scanner,
            'rewrites' => @rewrites, 'refusals' => @refusals,
            'ignored' => @ignored.map { |a, b| { 'file' => a, 'why' => b } },
            'helpers_threaded' => @helper_names.to_a.sort,
            'registered' => @regs.map { |r| { 'name' => r['name'], 'c_func' => r['func'], 'argc' => r['argc'],
                                              'target' => r['target'], 'error' => r['error'] } } }
    log['scanner_reason'] = @scanner_reason if @scanner_reason
    log['scanner_fallback'] = @scanner_fallback unless @scanner_fallback.empty?
    write_bytes(File.join(@out_dir, 'conversion_log.json'), py_json(log, 0))
    [@rewrites.size, @refusals.size]
  end

  def run
    choose_scanner
    load
    scan_local_macros
    # the inactive text of each file (its #if branches the build decides) is known before the uses are collected: a use in
    # inactive text is not a use (its helper and its prototype)
    @files.each_key do |rel|
      text_inactive_spans(rel).each do |a, z|
        (@excluded_spans ||= {})[rel] ||= []
        @excluded_spans[rel] << [a, z]
      end
    end
    scan
    build_occurrences
    scan_local_names
    int_local_retype_scan
    compute_splits
    compute_needs
    check_refs
    @files.keys.sort.each { |rel| process(rel) }
    value_rational_switch_pass
    value_equality_pass
    value_compare_wrap_pass
    owned_class_assign_pass
    value_truth_call_pass
    value_ternary_truth_pass
    value_condition_operand_pass
    value_order_stuck_pass
    value_identity_pass
    value_as_integer_arg_pass
    value_struct_pointer_cast_pass
    value_cast_integer_stuck_pass
    value_cast_zero_pass
    value_zero_init_pass
    onig_engine_stuck_pass
    id_return_pass
    id_arg_of_value_pass
    value_not_stuck_pass
    value_if_truth_stuck_pass
    value_pointer_array_stuck_pass
    encoding_pointer_assign_pass
    header_prototype_types_pass
    value_zero_assign_pass
    integer_return_pass
    # last: a (T *)v cast that the passes above did not cover (the ensure and protect data are theirs)
    value_to_pointer_cast_pass
    @dead_inits.each do |d|
      @edits[d['file']].add(d['hstart'], d['hstart'],
                            "#if 0  /* BC2CPP-MRBGEM: not the extension entry; CRuby never calls it */\n")
      @edits[d['file']].add(d['body_end'] + 1, d['body_end'] + 1, "\n#endif\n")
    end
    n_rw, n_ref = write_outputs
    puts "converted #{@name}: #{n_rw} rewrite(s), #{n_ref} refusal(s), " \
         "#{@regs.count { |r| r['error'].nil? }} registered method(s) -> #{@out_dir}"
    @refusals.empty? ? 0 : 2
  end
end

def main(argv)
  args = argv.dup
  name = nil
  scanner = 'auto'
  defines = []
  undefines = []
  while args.first&.start_with?('--')
    opt = args.shift
    if opt == '--name' && !args.empty?
      name = args.shift
    elsif opt == '--scanner' && %w[auto libclang regex].include?(args.first)
      scanner = args.shift
    elsif opt == '--define' && !args.empty?
      defines << args.shift
    elsif opt == '--undefine' && !args.empty?
      undefines << args.shift
    elsif opt == '--exclude' && !args.empty?
      ($excluded_files ||= Set.new) << args.shift
    elsif opt == '--replace' && !args.empty? && args.first.include?('=')
      ($replaces ||= []) << args.shift.split('=', 2).map { |t| t.gsub('\\n', "\n") }
    elsif opt == '--thread-sync'
      $thread_sync = true
    elsif opt == '--rename' && !args.empty? && args.first.include?('=')
      ($renames ||= []) << args.shift.split('=', 2)
    elsif opt == '--method-scope-fn' && !args.empty?
      ($method_scope_fns ||= Set.new) << args.shift
    elsif opt == '--stored-tag' && !args.empty? && args.first.include?('=')
      tag_name, tag_value = args.shift.split('=', 2)
      ($stored_tags ||= {})[tag_name] = tag_value
    else
      args = nil
      break
    end
  end
  if args.nil? || args.size != 2
    warn 'usage: convert_mrbgem.rb [--name GEM] [--scanner auto|libclang|regex] [--define NAME[=VALUE]]... [--undefine NAME]... [--exclude FILE]... [--rename OLD=NEW]... [--thread-sync] [--replace OLD=NEW]... ' \
         '[--stored-tag NAME=VALUE]... <cext_dir> <out_dir>'
    return 1
  end
  Converter.new(args[0], args[1], name, scanner, defines, undefines).run
end

exit(main(ARGV)) if $PROGRAM_NAME == __FILE__
